insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_dd_1', 'side', '뒷이야기·남문 수로 선착', '등심 세 번', '흰 밤이 걷혔는데도 선착 등지기 차랑은 등심을 하루 세 번 손질한다. 선착 야영소 선반에 새 물건이 들어오던 날, 차랑의 세 번 손질을 아침부터 밤까지 함께 따라간다.', 'deungdo_landing', 50, '{mdq_17}'::text[], null, 1500, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:deungdo", "stage": 1}'::jsonb where quest_id = 'ep_dd_1';
delete from public.world_quest_steps where quest_id = 'ep_dd_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_1', 1, '하나', '하나', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "남문 수로 선착 돌계단을 따라 등 기둥 여섯이 서 있었다. 아침 안개 속에서 젊은 등지기 하나가 사다리에 올라 맨 아래 기둥의 등갓을 열고 있었다."}, {"s": null, "t": "등지기는 허리춤에서 작은 심지 가위를 꺼내 탄 심지 끝을 싹둑 잘라 냈다. 그러고는 기둥에 칼끝으로 금 하나를 그었다."}, {"s": "q:ug_charang", "t": "하나. ……아, 조사원님이시네요. 선착 등지기 차랑이에요. 손에 기름이 묻어서 인사는 이렇게만 할게요."}, {"s": null, "t": "차랑이 기름 묻은 손을 바지에 쓱쓱 닦고 고개를 꾸벅 숙였다. 기둥에는 칼로 그은 금이 빽빽했다. 금은 기둥 한쪽을 다 덮고 다른 쪽으로 넘어가 있었다."}, {"s": null, "t": "물길 쪽에서 철썩철썩 노 젓는 소리가 났다. 수향 뱃사람 삿대가 짐을 가득 실은 거룻배를 말뚝에 댔다. 삿대가 노를 지팡이처럼 짚고 뭍으로 뛰어내렸다."}, {"s": "q:sx_md_satdae", "t": "차랑, 또 세냐? 밤이 돌아온 지가 언젠데 아직도 하루 세 번이야! 조사원님, 이 등지기 좀 말려 주세요."}, {"s": null, "t": "차랑은 대꾸하지 않고 가위를 허리춤에 꽂았다. 사다리를 내려와 삿대의 거룻배를 들여다보았다."}, {"s": "q:ug_charang", "t": "오늘 짐은 뭐예요?"}, {"s": null, "t": "삿대가 상자 뚜껑을 열어 보이며 어깨를 으쓱했다."}, {"s": "q:sx_md_satdae", "t": "야영소 선반에 올릴 거요. 대환단, 천령 감로. 선반 물건이 네 가지에서 여섯 가지로 는대요. 흰 밤 나루 살리는 데 조사원님들이 물건을 줄줄이 넘겨 주셔서, 봉인고 쪽에서 이런 것도 실어 보낸대요."}, {"s": null, "t": "야영소 천막 앞에서 흑련 문지기 막쇠가 칼집째 쥔 칼로 땅을 짚고 서 있었다. 막쇠는 새 선반 앞을 떠나지 않고 지나가는 사람마다 노려보았다."}, {"s": "q:sx_md_maksoe", "t": "비싼 약이야. 손대지 마."}, {"s": null, "t": "차랑이 막쇠 쪽을 보고 작게 웃었다. 그러고는 위쪽 기둥의 등을 올려다보았다. 등갓 종이가 군데군데 찢어져 있었다."}, {"s": "q:ug_charang", "t": "좋은 약은 들어왔는데 등갓 바를 종이는 안 들어왔네요. 선착 등갓은 꺼진 관아 터의 바랜 등롱 종이로 발라요. 글자는 하얗게 바랬어도 결이 질겨서 밤바람에도 안 찢어지거든요."}, {"s": null, "t": "나는 차랑에게 왜 아직도 하루 세 번 손질을 하느냐고 물었다. 차랑이 가위 손잡이를 만지작거리다가 웃음으로 얼버무렸다."}, {"s": "q:ug_charang", "t": "그건 세 번째 손질 때 말씀드릴게요. 그 전에 종이부터요. 관아 터에서 네 장만 모아다 주시겠어요? 두 번째 손질은 한낮이에요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_1', 2, '둘', '꺼진 관아 터에서 바랜 등롱 종이을(를) 모은다', '{"at": ["deungdo_landing"], "tasks": [{"t": "gather", "items": ["bleached_lantern_paper"], "r": ["dark_yamen"], "n": 4}]}'::jsonb, '[{"s": null, "t": "바랜 등롱 종이를 들고 돌아오니 해가 머리 위에 있었다. 차랑은 사다리 아래에서 풀 그릇을 저으며 나를 기다리고 있었다."}, {"s": "q:ug_charang", "t": "딱 맞춰 오셨어요. 이제 둘이에요."}, {"s": null, "t": "야영소 선반 앞에는 아침에 들어온 대환단을 구경하러 온 조사원들이 몰려 있었다. 막쇠가 그 앞에서 칼집으로 땅을 짚고 한 사람씩 노려보았다."}, {"s": null, "t": "대환단 한 병이 팔려 나가자 막쇠의 어깨가 조금 내려갔다. 지킬 물건이 하나 줄었다는 얼굴이었다."}, {"s": null, "t": "차랑이 사다리에 올라 심지를 자르고 기둥에 금을 하나 더 그었다. 내가 건넨 종이 두 장을 받아 찢어진 등갓에 펴 발랐다. 바랜 종이에 한낮 햇빛이 비치자 등갓이 우윳빛으로 환해졌다."}, {"s": null, "t": "맨 위 두 기둥에만 등이 없었다. 쇠고리만 덩그러니 달려 있었다."}, {"s": "q:ug_charang", "t": "저 두 자리는 비워 뒀어요. 흰 밤이 계단 맨 위에서 시작됐거든요. 거기 등을 달면 금방 바래서 소용이 없었어요."}, {"s": "q:ug_charang", "t": "이제는 밤이 와요. 밤에 수로로 들어오는 배는 계단 맨 위가 안 보이면 헤매요. 저기에 명등을 달고 싶어요. 명등은 멀리까지 비치니까요."}, {"s": null, "t": "삿대가 거룻배 밧줄을 감다 말고 고개를 들었다. 이마에 혹이 하나 볼록 솟아 있었다."}, {"s": "q:sx_md_satdae", "t": "그러고 보니 요즘 밤배가 늘었어요. 어젯밤엔 저도 계단 찾다가 말뚝에 이마를 박았다니까요."}, {"s": null, "t": "삿대가 혹을 문지르며 히죽 웃었다. 차랑이 그 혹을 보고 입술을 깨물며 웃음을 참았다."}, {"s": null, "t": "천막 앞의 막쇠가 칼집 끝으로 땅을 톡 치고 이쪽을 보았다."}, {"s": "q:sx_md_maksoe", "t": "명등은 심지가 따로 있어야 해. 꺼진 등롱에서 나온 심지. 아무 실로는 안 탄다."}, {"s": null, "t": "차랑이 막쇠 쪽으로 고개를 꾸벅 숙이고 내 쪽으로 돌아섰다."}, {"s": "q:ug_charang", "t": "막쇠 님 말이 맞아요. 명등 심지에 끊긴 등 기름을 붓고, 남은 바랜 종이로 갓을 해야 해요. 명등 등롱 두 개만 지어 주세요. 세 번째 손질은 해 진 뒤예요. 그때 달면 돼요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_1', 3, '셋', '명등 등롱을(를) 만든다, 명등 등롱을(를) 넘긴다', '{"at": ["deungdo_landing"], "tasks": [{"t": "craft", "items": ["myeongdeung_lamp"], "n": 2}], "give": {"myeongdeung_lamp": 2}}'::jsonb, '[{"s": null, "t": "해가 지고 선착에 밤이 내렸다. 돌계단 아래 물길이 검푸르게 출렁였고, 수로 저편에서 노 젓는 소리가 멀리까지 퍼져 왔다."}, {"s": null, "t": "차랑이 내가 지어 온 명등 등롱 둘을 받아 맨 위 기둥 쇠고리에 하나씩 걸었다. 심지에 불이 붙자 노란 불빛이 계단을 타고 물길까지 길게 내려갔다."}, {"s": null, "t": "차랑은 아래 기둥부터 차례로 심지를 다듬으며 올라왔다. 마지막 기둥에 칼끝을 대고 금 하나를 그었다."}, {"s": "q:ug_charang", "t": "셋. 오늘 하루가 갔어요."}, {"s": null, "t": "차랑이 사다리에 걸터앉아 기둥의 금들을 손끝으로 쓸었다. 금 사이사이에 작은 점도 찍혀 있었다."}, {"s": "q:ug_charang", "t": "흰 밤일 때도 선착은 바깥 하늘을 따랐어요. 그런데 계단 위로 올라가신 분들은 안쪽에서 날을 잃어버리셨죠. 해도 달도 없었으니까요."}, {"s": "q:ug_charang", "t": "그분들이 나오시면 계단 맨 아래에서 꼭 물으셨어요. 오늘이 며칠이냐고요. 그래서 하루에 세 번, 아침이랑 한낮이랑 저녁에 등을 다듬고 금을 그었어요. 누가 물으시면 바로 대답해 드리려고요."}, {"s": null, "t": "차랑이 금 옆의 점 하나를 짚었다. 손가락 끝이 조금 떨렸다."}, {"s": "q:ug_charang", "t": "점은 그날 나오신 분이 계셨다는 표시예요. 조사원님도 몇 번 물으셨어요. 기억 안 나시죠? 다들 기억 못 하세요. 흰 밤에서 나오면 몸이 날을 잊으니까요."}, {"s": null, "t": "나는 기억나지 않았다. 다만 계단 맨 아래에서 누군가 날짜를 대 주던 목소리만 어렴풋했다."}, {"s": null, "t": "차랑이 가위를 허리춤에 꽂으며 고개를 숙였다. 목소리가 작아졌다."}, {"s": "q:ug_charang", "t": "이제는 아무도 안 물으세요. 밤이 돌아왔으니 다들 날을 아시죠. 그게 좋은 건데…… 저는 아직도 세 번을 다듬어야 하루가 간 것 같아요."}, {"s": null, "t": "나는 사다리 아래에서 일부러 오늘이 며칠이냐고 물었다. 차랑이 눈을 동그랗게 떴다가 소리 내어 웃었다. 웃음소리가 물길을 따라 멀리 퍼져 나갔다."}, {"s": "q:ug_charang", "t": "오늘은요, 선착 맨 위에 명등 두 개가 처음 켜진 날이에요. 그렇게 대답할게요. 날짜보다 그게 낫잖아요."}, {"s": null, "t": "천막 앞에서 막쇠가 칼집째 쥔 칼에 턱을 괴고 불빛을 올려다보고 있었다. 막쇠는 우리 쪽을 보지 않은 채 한마디 던졌다."}, {"s": "q:sx_md_maksoe", "t": "……물으면 대답해 주는 놈이 있는 데가 고을이지. 근데 여긴 명부에 고을로 안 올라 있다더라."}, {"s": null, "t": "차랑이 막쇠를 돌아보았다. 그러고는 나를 보며 고개를 끄덕였다."}, {"s": "q:ug_charang", "t": "안 그래도 삿대가 그 일로 정청에 가 보겠대요. 지름길이 열리면요. 그날은 제가 금을 하나 더 그을래요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_dd_2', 'side', '뒷이야기·남문 수로 선착', '선착에서 정청까지', '남문 수로 선착에서 본부 정청까지 지름길이 났다. 삿대가 선착과 쉼막 사람들 명단을 들고 첫 배를 띄우고, 청파가 노를 함께 잡는다. 명등청 명부에 선착을 고을로 올리려면 삿대의 진짜 이름이 필요하다.', 'deungdo_landing', 50, '{mdq_17,ep_dd_1}'::text[], null, 1501, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:deungdo", "stage": 2}'::jsonb where quest_id = 'ep_dd_2';
delete from public.world_quest_steps where quest_id = 'ep_dd_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_2', 1, '첫 배', '첫 배', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "그사이 봉인고 아래 수로 어귀에 새 이정표가 섰다. 「본부 정청 — 순라 길」. 선착 사람들은 그 길을 지름길이라고 불렀다."}, {"s": null, "t": "선착 말뚝 아래에서 삿대가 거룻배 바닥을 물걸레로 박박 닦고 있었다. 뱃머리에서 「세 걸음」이라고 적힌 등롱이 흔들렸다."}, {"s": "q:sx_md_satdae", "t": "조사원님! 오늘 첫 배 뜹니다. 정청까지 노정패 한 닢 안 내고 가는 첫 배요!"}, {"s": null, "t": "삿대 옆에는 청파가 쪼그려 앉아 밧줄을 사리고 있었다. 청파가 나를 보고 반갑게 손을 흔들다가 쿨럭쿨럭 쇳소리 기침을 했다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님! 구름나루에서 손님 태워 왔다가 삿대한테 붙잡혔어요. 첫 배는 둘이 저어야 한대요. 수향 법이래요."}, {"s": null, "t": "삿대가 걸레를 내던지고 노를 짚으며 청파 앞에 섰다."}, {"s": "q:sx_md_satdae", "t": "법은 무슨. 너 노 젓는 거 좀 보려고 그러지. 잠수꾼이 뱃사공 됐다며."}, {"s": null, "t": "쉼막 맏이 함박이 큰 보자기를 이고 돌계단을 내려왔다. 함박은 보자기를 삿대 품에 안기고 종이 한 뭉치를 그 위에 얹었다."}, {"s": "q:sx_md_hambak", "t": "아이고, 늦을 뻔했네. 이게 선착하고 쉼막 사람들 명단이야. 명등청 가서 「사는 고을 — 남문 수로 선착」으로 올려 달라고 해. 그래야 동짓밤에 여기서 부를 이름도 생기지."}, {"s": null, "t": "삿대가 명단을 넘겨 보다가 얼굴을 찡그렸다. 맨 위에 「삿대」라고 적혀 있었다."}, {"s": "q:sx_md_satdae", "t": "맏이님, 이거 다 호칭이잖아요. 「삿대」, 「옹심」, 「함박」."}, {"s": null, "t": "함박이 큰 손바닥으로 제 이마를 탁 쳤다."}, {"s": "q:sx_md_hambak", "t": "아이고, 그렇네. 명부엔 진짜 이름을 적어야 한다던데. 가서 대면 되지 뭐. 쉼막 사람들 이름은 내가 따로 적어 보낼게. 너도 진짜 이름 있잖아."}, {"s": null, "t": "삿대가 갑자기 입을 꾹 다물었다. 청파가 밧줄을 사리다 말고 삿대를 올려다보더니 키득거렸다."}, {"s": "q:sn_cheongpa", "t": "있죠. 있어요. 저는 알아요."}, {"s": null, "t": "삿대가 청파의 뒤통수를 노 끝으로 톡 쳤다. 그러고는 헛기침을 하며 나를 돌아보았다."}, {"s": "q:sx_md_satdae", "t": "그 얘긴 정청 가서 하고요! 조사원님, 뱃길이 반나절이에요. 가면서 먹을 물고기 좀 낚아 주세요. 정청 서리님들 갖다 드릴 것도요. 물길에서 세 번만 던지면 돼요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_2', 2, '기름종이', '남문 수로 선착에서 낚시를 한다', '{"at": ["deungdo_landing"], "tasks": [{"t": "fish", "r": ["deungdo_landing"], "n": 3}]}'::jsonb, '[{"s": null, "t": "낚은 물고기를 바구니에 담아 오자 삿대가 뱃전에 걸쳐 둔 석쇠에 두 마리를 올렸다. 지글지글 기름 떨어지는 소리에 청파가 침을 꼴깍 삼켰다."}, {"s": null, "t": "삿대가 구운 물고기 하나를 청파에게 내밀었다. 청파는 생선을 받아 후후 불면서도 눈은 배 바닥의 보자기에 가 있었다."}, {"s": "q:sn_cheongpa", "t": "그 명단 젖으면 안 돼요. 기름종이로 한 번 더 싸요. 물속에서 건진 종이는 다 그렇게 쌌어요."}, {"s": null, "t": "놀리려고 입을 열던 삿대가 청파의 손을 보고 입을 다물었다. 청파가 생선을 쥐지 않은 손으로 저도 모르게 제 목을 감싸고 있었다."}, {"s": "q:sx_md_satdae", "t": "……너 물에서 그런 것까지 건졌구나. 그래, 두 겹 싸자."}, {"s": null, "t": "삿대가 명단을 기름종이로 한 겹 더 쌌다. 그러고는 노를 짚고 일어서 수로 저편을 가리켰다."}, {"s": "q:sx_md_satdae", "t": "봉인고 아래 돌계단에서 배를 대고 순라 길로 걸어가요. 옥사 담장 끼고, 순라청 지나서, 정청 뒷문. 예전엔 노정패를 두 닢씩 내고 하루를 갔는데, 이젠 반나절이면 된대요."}, {"s": null, "t": "청파가 생선 가시를 바르다 말고 고개를 갸웃했다."}, {"s": "q:sn_cheongpa", "t": "그 길 누가 다졌어요? 순라 길은 풀이 무릎까지 났다던데."}, {"s": null, "t": "삿대가 노 끝으로 선착 야영소 쪽을 가리켰다. 천막 앞에 물건 상자가 높다랗게 쌓여 있었다."}, {"s": "q:sx_md_satdae", "t": "저 상자 다 봐. 조사원님들이 흰 밤 나루 살리라고 넘긴 거야. 그걸로 봉인고 쪽 일꾼들 품삯 주고 길을 다졌대."}, {"s": null, "t": "청파가 상자 더미를 한참 보다가 쇳소리 기침을 했다. 기침이 가라앉자 청파가 나를 보았다."}, {"s": "q:sn_cheongpa", "t": "정청 서리님들은 밤새 명부 쓰신대요. 명단 들이밀면서 빈손이면 좀 그렇잖아요. {이름} 님, 밤빛 차 두 봉만 지어 가요. 차 한 잔 드리면 서리님들이 덜 귀찮아하실 거예요."}, {"s": null, "t": "삿대가 노 끝으로 뱃전을 탕 쳤다."}, {"s": "q:sx_md_satdae", "t": "그럼 출발! 우린 배로 먼저 갑니다. 조사원님은 차 지어서 정청 뒷문에서 만나요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_2', 3, '사는 고을', '야행국 본부 정청에 간다, 밤빛 차을(를) 만든다, 밤빛 차을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "travel", "r": ["hq_yard"], "n": 1}, {"t": "craft", "items": ["night_tea"], "n": 2}], "give": {"night_tea": 2}}'::jsonb, '[{"s": null, "t": "순라 길 끝 정청 뒷문에 닿았을 때 삿대와 청파는 벌써 마루 끝에 앉아 있었다. 청파의 바짓단이 물길 이슬에 젖어 있었다. 둘은 노정패 한 닢도 안 냈다며 손바닥을 짝 마주쳤다."}, {"s": null, "t": "명등청 대청 옆방에서 서리 문수가 명부 더미에 파묻혀 있다가 우리를 보고 벌떡 일어났다. 볼에 먹이 한 줄 묻어 있었다."}, {"s": "q:dh_munsu", "t": "조사원님! 아, 차예요? 차 맞죠? 저 사흘째 맹물만 마셨거든요."}, {"s": null, "t": "문수가 밤빛 차를 받아 한 모금 마시고 눈을 감았다. 그러고는 삿대가 내민 명단을 펼쳤다. 펼치자마자 이마를 짚었다."}, {"s": "q:dh_munsu", "t": "「삿대」, 「옹심」, 「함박」…… 이거 다 호칭이거든요. 명부는 이름하고 태어난 해하고 사는 고을이에요. 호칭으로 적으면 동짓밤에 불러도 안 닿거든요."}, {"s": null, "t": "삿대가 마루 끝에서 몸을 배배 꼬았다. 청파가 옆에서 팔꿈치로 삿대를 쿡 찔렀다."}, {"s": "q:sn_cheongpa", "t": "대요, 얼른. 쉼막 사람들 이름은 맏이님이 따로 보낸대요. 여기선 하나만 대면 돼요."}, {"s": null, "t": "삿대가 한참 노를 만지작거리다 문수에게만 들리게 무언가를 웅얼거렸다. 문수가 붓을 든 채 눈을 끔뻑였다."}, {"s": "q:dh_munsu", "t": "네? 다시 한번요. 잘 안 들렸거든요."}, {"s": null, "t": "삿대가 얼굴이 시뻘게진 채 마루를 쾅 치고 일어섰다."}, {"s": "q:sx_md_satdae", "t": "미르요! 미르! 할머니가 용처럼 배를 지키라고 지어 주셨어요! 됐어요?"}, {"s": null, "t": "대청 쪽에서 붓을 닦던 서리 몇이 고개를 쏙 내밀었다. 청파가 마루에 엎어져 웃다가 기침을 터뜨렸다. 웃음과 기침이 한데 섞여 한참 이어졌다."}, {"s": null, "t": "문수가 웃음을 꾹 참으며 명부 새 줄에 붓을 댔다. 「미르 · 사는 고을 — 남문 수로 선착」. 문수가 그 줄 끝 빈 네모에 테를 두르고 삿대를 올려다보았다."}, {"s": "q:dh_munsu", "t": "부르는 이 칸은요? 이건 남이 적어야 하거든요."}, {"s": null, "t": "청파가 웃음을 그치고 마루에서 일어났다. 기침 끝의 쉰 목소리였지만 대답은 또렷했다."}, {"s": "q:sn_cheongpa", "t": "제가 적을게요. 같은 나루에서 자랐으니까요."}, {"s": null, "t": "청파가 그 칸에 제 이름을 적고 엄지를 꾹 눌렀다. 마침 해가 넘어가 대청 마당에 어스름이 깔렸다. 청파가 삿대를 보며 「미르」 하고 한 번 불렀다."}, {"s": null, "t": "청파의 입김이 흩어지지 않고 금빛 실로 엉겨 삿대의 가슴께에 닿았다. 삿대가 제 가슴을 손바닥으로 덮고 한동안 움직이지 않았다."}, {"s": "q:sx_md_satdae", "t": "……따뜻하네. 할머니 돌아가시고 그 이름 부른 사람은 처음이에요. 다들 삿대, 삿대 하니까."}, {"s": null, "t": "문수가 코를 훌쩍이며 명부를 덮으려다 명단 맨 끝 줄을 다시 들여다보았다."}, {"s": "q:dh_munsu", "t": "그런데 쉼막 명단 끝에 「밥은 다 제가 먹여요 — 함박」이라고 적힌 줄이 있거든요. 이것도 명부에 올려요?"}, {"s": null, "t": "삿대가 그 줄을 보고 한숨을 푹 쉬었다."}, {"s": "q:sx_md_satdae", "t": "맏이님 버릇이에요. 쉼막 쌀독이 또 바닥났을걸요. 그건 명부 말고 조사원님한테 맡기세요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_dd_3', 'side', '뒷이야기·남문 수로 선착', '쉼막의 창고', '선착과 쉼막에 창고가 서고 물건 서신도 오가게 되었다. 쉼막 맏이 함박이 오는 사람마다 밥을 퍼 주다 쉼막 쌀독을 바닥냈다. 옹심과 함께 쉼막 살림을 다시 채우며, 함박이 흰 밤 동안 왜 그렇게 퍼 주었는지 듣는다.', 'deungdo_landing', 50, '{mdq_17,ep_dd_2}'::text[], null, 1502, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:deungdo", "stage": 3}'::jsonb where quest_id = 'ep_dd_3';
delete from public.world_quest_steps where quest_id = 'ep_dd_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_3', 1, '주먹밥 광주리', '주먹밥 광주리', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "그사이 선착 야영소 천막 뒤에 「창고」 패를 단 판잣집이 섰다. 쉼막에도 같은 창고가 났고, 서신으로 물건을 주고받는 곳도 함께 생겼다."}, {"s": null, "t": "돌계단 아래에서 함박이 커다란 광주리를 끼고, 오가는 사람마다 주먹밥을 하나씩 쥐여 주고 있었다. 함박은 나를 보자마자 주먹밥 두 개를 내 손에 얹었다."}, {"s": "q:sx_md_hambak", "t": "아이고, 조사원님. 마침 잘 오셨어요. 먹고 가요. 아니, 들고 가요. 아니, 둘 다 해요."}, {"s": null, "t": "주먹밥을 받은 조사원들이 계단에 걸터앉아 우물우물 먹었다. 선착 야영소에 갓 들어온 장사꾼들도 영문도 모른 채 주먹밥을 받아 들었다."}, {"s": null, "t": "함박이 장사꾼 하나의 손에 주먹밥을 하나 더 얹으며 껄껄 웃었다."}, {"s": "q:sx_md_hambak", "t": "처음 오셨죠? 등도에 처음 오면 다들 배고픈 줄을 몰라요. 그러니까 먹어 둬요."}, {"s": null, "t": "함박 뒤에서 옹심이 빈 쌀 자루를 들고 서 있었다. 옹심은 내 손의 주먹밥을 보더니 고개를 깊이 숙였다. 그러고는 함박 몰래 나를 천막 그늘로 데려갔다."}, {"s": "q:sx_md_ongsim", "t": "조사원님, 송구한 부탁이 있어요. 저 주먹밥이 쉼막 쌀독의 마지막 쌀이에요. 맏이님이 오늘 아침에 남은 쌀을 다 쪄서 들고 나오셨어요."}, {"s": null, "t": "옹심이 빈 자루를 펼쳐 보였다. 자루 바닥에 쌀알 몇 톨이 굴러다녔다."}, {"s": "q:sx_md_ongsim", "t": "오늘 저녁 쉼막 뱃사람들 먹을 게 없어요. 맏이님은 늘 이러세요. 쉼막에 들어오는 쌀보다 퍼 주는 쌀이 많아요. 창고가 생겼으니 이제 쌓아 두자고 말씀드려도 웃기만 하세요."}, {"s": null, "t": "광주리를 든 함박이 우리 쪽을 돌아보고 손을 흔들었다. 광주리는 벌써 반이 비어 있었다."}, {"s": "q:sx_md_hambak", "t": "옹심아, 또 조사원님 붙잡고 내 흉보지? 다 들려!"}, {"s": null, "t": "옹심이 함박을 향해 꾸벅 고개를 숙여 보이고 다시 나를 보았다. 목소리를 한층 낮췄다."}, {"s": "q:sx_md_ongsim", "t": "창고는 조사원님들이 이 나루에 물건을 보태 주셔서 생긴 거예요. 그걸 비워 두면 그분들께 면목이 없잖아요."}, {"s": "q:sx_md_ongsim", "t": "오늘 저녁만이라도 국 끓일 거리를 마련하고 싶어요. 빙어 맑은국이면 쉼막 솥 하나를 채워요. 네 그릇만 지어 주시면 제가 쉼막까지 같이 들고 갈게요. 맏이님이 퍼 주시기 전에 창고에 먼저 넣으려고요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_3', 2, '쌀독 앞에서', '빙어 맑은국을(를) 만든다, 빙어 맑은국을(를) 넘긴다', '{"at": ["lamp_rest"], "tasks": [{"t": "craft", "items": ["smelt_clear_soup"], "n": 4}], "give": {"smelt_clear_soup": 4}}'::jsonb, '[{"s": null, "t": "빙어 맑은국 단지를 들고 무관 거리를 지나 쉼막에 닿았다. 쉼막 한가운데 등 하나가 늘 그렇듯 켜져 있었고, 그 둘레 처마 밑에 새 창고 문이 달려 있었다."}, {"s": null, "t": "옹심이 국 단지를 받아 창고 시렁에 올리려는 순간, 뒤따라 들어온 함박이 단지를 덥석 낚아챘다."}, {"s": "q:sx_md_hambak", "t": "아이고, 국을 왜 창고에 넣어! 식으면 맛없어. 저기 기둥 밑에 앉은 사람들 줘야지."}, {"s": null, "t": "쉼막 기둥 밑에는 무관 거리에서 막 돌아온 조사원 몇이 지친 얼굴로 앉아 있었다. 옹심이 단지 끝을 붙잡고 놓지 않았다."}, {"s": null, "t": "늘 고개부터 숙이던 옹심이 처음으로 고개를 들고 함박을 똑바로 보았다."}, {"s": "q:sx_md_ongsim", "t": "맏이님. 오늘 저녁 우리 뱃사람들 먹을 게 이것뿐이에요. 다 퍼 주시면 내일은 맏이님이 굶으세요."}, {"s": null, "t": "함박이 단지를 쥔 채 멈칫했다. 쉼막 안이 조용해졌다. 등불이 흔들리며 두 사람의 얼굴에 저녁 빛깔을 드리웠다."}, {"s": null, "t": "함박은 단지를 내려놓고 쌀독 옆에 털썩 주저앉았다. 큰 손으로 빈 쌀독 테두리를 쓸었다."}, {"s": "q:sx_md_hambak", "t": "……옹심아, 흰 밤 때 생각나? 거기선 배가 안 고팠잖아. 냄새도 없고, 춥지도 덥지도 않고."}, {"s": null, "t": "옹심이 천천히 고개를 끄덕였다. 함박의 목소리가 낮아졌다."}, {"s": "q:sx_md_hambak", "t": "그래서 다들 먹는 걸 잊었어. 우리 막내 뱃사람 하나는 사흘을 안 먹고 수로 끝에 앉아 있다가 픽 쓰러졌지. 배고픈 줄을 몰랐대."}, {"s": "q:sx_md_hambak", "t": "그 뒤로 나는 누가 오기만 하면 밥부터 쥐여 줬어. 배가 안 고프다고 해도 쥐여 줬어. 안 쥐여 주면 또 누가 쓰러질 것 같아서."}, {"s": null, "t": "함박의 큰 손이 쌀독 테두리 위에서 멈췄다. 그 손이 조금 떨렸다."}, {"s": "q:sx_md_hambak", "t": "이제 밤이 돌아와서 다들 배고픈 줄 아는데, 내 손은 아직 그걸 몰라."}, {"s": null, "t": "옹심이 함박 곁에 무릎을 꿇고 앉았다. 고개를 숙이는 대신 함박의 손등에 제 손을 얹었다."}, {"s": "q:sx_md_ongsim", "t": "그러니까 창고에 넣자는 거예요, 맏이님. 쌀독이 차 있어야 맏이님이 내일도 퍼 주시죠. 맏이님 손 탓이 아니에요. 쌀 탓이에요."}, {"s": null, "t": "함박이 옹심을 한참 보다가 코를 훌쩍이며 웃었다. 그러고는 나를 올려다보았다."}, {"s": "q:sx_md_hambak", "t": "조사원님, 그럼 창고부터 채워 봅시다. 쉼막 등 기름도 바닥이에요. 옹심이 늘 얻으러 다니던 붉은 사당 골목 곳간 기름 있잖아요. 그거 세 단지만 채워다 주세요. 기름은 창고에 넣고, 국은…… 반만 퍼 줄게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_3', 3, '반만', '붉은 사당 골목에서 끊긴 등 기름을(를) 모은다, 끊긴 등 기름을(를) 넘긴다', '{"at": ["lamp_rest"], "tasks": [{"t": "gather", "items": ["severed_lamp_oil"], "r": ["red_shrine_lane"], "n": 3}], "give": {"severed_lamp_oil": 3}}'::jsonb, '[{"s": null, "t": "끊긴 등 기름 단지를 들고 쉼막에 돌아오니 창고 시렁에 쌀자루 셋이 나란히 놓여 있었다. 옹심이 시렁 앞에서 장부를 펴고 붓으로 한 줄씩 적고 있었다."}, {"s": "q:sx_md_ongsim", "t": "조사원님, 오셨어요. 쌀이 들어왔어요. 구름나루에 사시는 맏이님 동생분이 서신으로 부쳐 주셨어요. 창고가 생겨서 이제 쉼막에서도 물건 서신을 받을 수 있거든요."}, {"s": null, "t": "함박이 서신 종이를 들고 등불 아래 앉아 있었다. 큰 글씨로 꾹꾹 눌러 쓴 서신이었다. 함박은 종이를 읽다가 웃고, 또 읽다가 웃었다."}, {"s": "q:sx_md_hambak", "t": "동생이 「언니는 또 다 퍼 줬지」 이래요. 안 봐도 안대요. 그래서 세 자루를 보냈대요. 한 자루는 퍼 주고, 한 자루는 넣어 두고, 한 자루는 언니 먹으라고."}, {"s": null, "t": "옹심이 장부에 「쌀 셋 — 퍼 줄 것 하나, 넣어 둘 것 하나, 맏이님 몫 하나」라고 적었다. 옹심은 내가 가져온 기름 단지도 창고 맨 아래 칸에 넣고 「쉼막 등」이라는 패를 붙였다."}, {"s": null, "t": "함박이 서신을 접어 품에 넣고 일어섰다. 쌀자루 하나를 번쩍 들었다가 옹심의 눈길을 보고 도로 내려놓았다. 이번에는 바가지로 반만 떠서 솥에 부었다."}, {"s": "q:sx_md_hambak", "t": "봐, 반만. 반만 펐어."}, {"s": null, "t": "옹심이 장부를 덮으며 고개를 깊이 숙였다. 이번 고갯짓에는 웃음이 섞여 있었다."}, {"s": "q:sx_md_ongsim", "t": "고맙습니다, 맏이님."}, {"s": null, "t": "저녁이 되자 쉼막 솥에서 보글보글 국 끓는 냄새가 퍼졌다. 기둥 밑에 앉은 조사원들과 뱃사람들이 그릇을 들고 줄을 섰다. 함박은 그릇마다 국을 담다가 내 그릇에만 빙어 한 마리를 몰래 더 얹었다."}, {"s": "q:sx_md_hambak", "t": "쉿. 이건 퍼 준 게 아니라 고마워서 준 거예요. 장부에 적으면 안 돼요."}, {"s": null, "t": "옹심은 다 보았지만 장부를 펴지 않았다. 대신 함박에게 동생한테 답장을 쓰자고 붓을 내밀었다."}, {"s": null, "t": "함박이 붓을 받아 들고 큰 글씨로 한 줄을 적었다. 「쌀 잘 받음. 반만 펐음.」 함박은 잠깐 생각하더니 창고에서 밤빛 차 두 봉을 꺼내 서신에 끼웠다."}, {"s": "q:sx_md_hambak", "t": "이건 보내는 거니까 퍼 주는 거 아니야. 동생이 밤에 바느질하느라 늘 눈이 침침하대."}, {"s": null, "t": "옹심이 그 서신을 서신 받는 곳에 꽂으며 나를 돌아보았다. 등불 아래 옹심의 얼굴이 처음으로 느긋해 보였다."}, {"s": "q:sx_md_ongsim", "t": "조사원님, 창고에 쌀이 차니까 쉼막 사람들이 장을 열자고 해요. 선착에 거래소랑 마구간이 생기면요. 일흔 해 동안 등도엔 장이 한 번도 안 섰대요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_dd_4', 'side', '뒷이야기·남문 수로 선착', '등도 첫 장', '선착에 거래소 천막과 마구간, 조사원 의뢰 게시판이 섰다. 옹심이 일흔 해 만의 등도 첫 장을 열자고 나서고, 쉼막 장꾼들이 지나갈 무관 거리를 치운 뒤 옛 나루 저자에서 값 나무패를 떼어 온다.', 'deungdo_landing', 50, '{mdq_17,ep_dd_3}'::text[], null, 1503, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:deungdo", "stage": 4}'::jsonb where quest_id = 'ep_dd_4';
delete from public.world_quest_steps where quest_id = 'ep_dd_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_4', 1, '장 서는 날', '장 서는 날', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "그사이 선착 야영소 옆에 거래소 천막이 섰다. 돌계단 아래 말뚝에는 나귀 한 마리가 매였고, 천막 기둥에는 조사원 의뢰 게시판이 걸렸다."}, {"s": null, "t": "나귀는 말뚝 옆에 세워 둔 삿대의 노 자루를 우물우물 씹고 있었다. 게시판에는 「쉼막 등 기름 구함 — 고개 숙여 부탁드립니다. 옹심」이라고 적힌 첫 쪽지 한 장이 붙어 있었다."}, {"s": null, "t": "말뚝 아래에서 삿대가 나귀 입에서 노 자루를 빼내려고 낑낑댔다. 나귀는 노를 문 채 꿈쩍도 하지 않았다."}, {"s": "q:sx_md_satdae", "t": "이 녀석이 마구간 첫 손님이라더니 내 노부터 맛을 보네! 조사원님, 마구간에 짚 좀 넉넉히 넣으라고 해 주세요!"}, {"s": null, "t": "게시판 앞에서 옹심이 쪽지 모서리를 꼭꼭 눌러 붙이고 있었다. 옹심은 나를 보자 손을 거두고 허리를 숙였다."}, {"s": "q:sx_md_ongsim", "t": "조사원님, 오셨어요. 오늘 장을 세우려고요. 거래소가 서고 나귀도 들어왔으니 장날이 있어야죠. 수향에서는 장이 서야 고을이라고 해요."}, {"s": null, "t": "옹심이 선착 돌계단 위쪽, 꺼진 관아 터로 이어지는 길을 가리켰다. 손끝이 조금 머뭇거렸다."}, {"s": "q:sx_md_ongsim", "t": "쉼막 장꾼들은 짐을 지고 무관 거리를 넘어와야 해요. 그런데 무관 거리에 아직 요괴들이 돌아요. 장꾼들이 거기서 짐을 버리고 돌아간 적도 있어요."}, {"s": null, "t": "천막 앞에서 막쇠가 칼집째 쥔 칼로 땅을 짚고 서 있었다. 막쇠가 거래소 천막을 턱으로 가리켰다."}, {"s": "q:sx_md_maksoe", "t": "장 서면 내가 천막 지킨다. 흑련은 장 지키는 일은 잘해. 길은 네가 치워."}, {"s": null, "t": "등 기둥 사다리 위에서 차랑이 아침 손질을 하다 말고 고개를 내밀었다."}, {"s": "q:ug_charang", "t": "하나. 조사원님, 장꾼들이 오면 저녁에 계단 등을 다 켤게요. 불이 켜져야 장 보는 맛이 나잖아요."}, {"s": null, "t": "차랑이 사다리 위에서 심지 가위를 흔들어 보이고 다음 기둥으로 옮겨 갔다."}, {"s": null, "t": "옹심이 막쇠와 차랑에게 차례로 고개를 숙이고 다시 나를 보았다."}, {"s": "q:sx_md_ongsim", "t": "무관 거리 요괴를 좀 쫓아 주세요. 여덟만 쓰러뜨려 주시면 장꾼들이 지나갈 틈이 생길 거예요. 장꾼들은 쉼막에서 짐을 싸 놓고 기다리고 있어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_4', 2, '값 나무패', '무관 거리의 요괴를 물리친다', '{"at": ["lamp_rest"], "tasks": [{"t": "win", "r": ["martial_row"], "n": 8}]}'::jsonb, '[{"s": null, "t": "무관 거리를 지나 쉼막에 닿으니 장꾼들이 짐을 지고 줄지어 서 있었다. 함박이 광주리를 이고 맨 앞에 서서 손을 흔들었다."}, {"s": "q:sx_md_hambak", "t": "아이고, 조사원님이 길을 치우셨대! 다들 가자!"}, {"s": null, "t": "옹심이 그 줄 앞을 막아서며 고개를 숙였다."}, {"s": "q:sx_md_ongsim", "t": "맏이님, 잠깐만요. 좌판에 값을 걸 나무패가 없어요. 장꾼들 물건마다 값을 적어 걸어야 손님이 다투지 않아요."}, {"s": null, "t": "함박이 이마를 탁 쳤다. 그러다 무언가 생각난 듯 쉼막 서쪽, 옛 나루 저자 쪽 하늘을 가리켰다."}, {"s": "q:sx_md_hambak", "t": "옛 나루 저자 좌판마다 값 나무패가 꽂혀 있잖아. 일흔 해 전 등도 장꾼들이 꽂아 둔 거. 그걸 떼어다 쓰면 어때? 글자 위에 새로 적으면 되지."}, {"s": null, "t": "옹심이 한참 생각하다 고개를 저었다."}, {"s": "q:sx_md_ongsim", "t": "위에 새로 적으면 안 돼요. 그분들 값이잖아요. 뒷면에 적어요. 앞면은 그대로 두고요. 그래야 일흔 해 전 장꾼들도 이 장에 같이 서는 거예요."}, {"s": null, "t": "함박이 옹심을 오래 보다가 큰 손으로 옹심의 어깨를 철썩 쳤다. 옹심이 앞으로 휘청했다."}, {"s": "q:sx_md_hambak", "t": "우리 옹심이 언제 이렇게 컸어."}, {"s": null, "t": "옹심이 자세를 바로 하고 나를 돌아보았다. 귀 끝이 발갰다."}, {"s": "q:sx_md_ongsim", "t": "저자 좌판이 백 개가 넘어요. 마른 물길 위로 배들이 얹혀 있어서 하루로는 다 못 돌아요. 조사원님, 며칠 묵으실 셈으로 저자에 다녀와 주시겠어요? 좌판 깔 뱃판도 같이 거둬 오시면 좋고요."}, {"s": null, "t": "장꾼들 사이에서 누군가 볼멘소리를 했다. 오늘 장 서는 줄 알고 새벽부터 짐을 쌌다는 소리였다. 함박이 그쪽을 돌아보며 광주리를 내려놓았다."}, {"s": "q:sx_md_hambak", "t": "기다리는 동안 내가 주먹밥 쥐여 줄게. 반만. 반만 쥐여 줄게."}, {"s": null, "t": "옹심이 그 말을 듣고 함박 쪽으로 고개를 숙였다. 이번에는 웃음을 참느라 어깨가 들썩였다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_4', 3, '일흔 해 만의 장', '옛 나루 저자에 원정을 다녀온다', '{"at": ["deungdo_landing"], "tasks": [{"t": "expedition", "r": ["old_ferry_market"], "n": 1}]}'::jsonb, '[{"s": null, "t": "원정에서 돌아오니 선착 돌계단 아래가 사람으로 북적였다. 장꾼들이 뱃판을 깔아 좌판을 만들었고, 좌판마다 옛 값 나무패가 꽂혀 있었다. 앞면에는 바랜 옛 값이, 뒷면에는 새 값이 적혀 있었다."}, {"s": null, "t": "맨 앞 좌판에서 함박이 솥을 걸고 생선을 쪘다. 함박 좌판의 나무패 앞면에는 「잉어 한 마리 · 세 푼」이 흐릿하게 남아 있었다."}, {"s": null, "t": "수로 쪽에서 철썩철썩 노 소리가 들렸다. 청파가 구름나루 장꾼들을 가득 태운 배를 말뚝에 댔다. 장꾼들이 우르르 내리자 청파가 뱃전에 기대 쿨럭쿨럭 기침을 했다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님! 구름나루에서 등도에 장 선다니까 다들 따라오겠대요. 지름길 덕에 반나절이에요. 뱃삯은 안 받았어요. 이제 값 안 받고 나르기로 했으니까요."}, {"s": null, "t": "거래소 천막 앞에서는 막쇠가 칼집째 쥔 칼을 세워 들고 꼿꼿이 서 있었다. 장꾼 하나가 값을 두고 언성을 높이자 막쇠가 그쪽을 한 번 노려보았다. 소리가 쏙 들어갔다."}, {"s": "q:sx_md_maksoe", "t": "장에서 싸우면 장이 아니야. 셈은 천막 안에서 해."}, {"s": null, "t": "옹심이 거래소 천막 안에서 장부를 펴 놓고 값이 오갈 때마다 한 줄씩 적었다. 손님이 물건을 사 갈 때마다 옹심은 고개를 깊이 숙였고, 손님들도 덩달아 고개를 숙였다."}, {"s": null, "t": "천막 안은 금세 고개 숙이는 사람들로 가득해졌다. 함박이 좌판에서 그 모습을 보고 배를 잡고 웃었다."}, {"s": "q:sx_md_hambak", "t": "아이고, 저기는 장이 아니라 절간이네! 옹심아, 고개 좀 그만 숙여!"}, {"s": null, "t": "해가 기울자 차랑이 사다리를 들고 돌계단을 올랐다. 차랑은 등 기둥마다 심지를 다듬어 불을 붙였다. 마지막으로 맨 위 명등 둘이 환하게 켜졌다."}, {"s": "q:ug_charang", "t": "셋. 오늘은 등도에 장이 선 날이에요. 누가 물으시면 그렇게 대답할 거예요."}, {"s": null, "t": "장이 파할 무렵 옹심이 장부 맨 끝에 붓을 댔다. 「등도 첫 장 — 손님 많음. 값은 다 맞음. 싸움 없음.」 옹심이 붓을 내려놓고 나를 향해 허리를 숙였다."}, {"s": "q:sx_md_ongsim", "t": "거래소도, 나귀도, 저 게시판도 조사원님들이 이 나루에 넘겨 주신 물건으로 들였어요. 오늘 장꾼들이 다들 그 얘기를 했어요. 그분들한테도 꼭 전해 주세요."}, {"s": null, "t": "천막 앞의 막쇠는 장꾼들이 다 돌아갈 때까지 칼을 놓지 않았다. 차랑이 사다리를 내려오며 그 모습을 보고 작게 웃었다."}, {"s": "q:ug_charang", "t": "막쇠 님은 서 계실 땐 늘 칼을 쥐고 계세요. 낙성 날엔 계단마다 등을 달 건데, 그날은 두 손이 다 필요할 텐데요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_dd_5', 'side', '뒷이야기·남문 수로 선착', '살아난 나루', '흰 밤 나루 살리기가 끝나는 날. 선착 돌계단마다 명등을 달려면 두 손이 필요한데, 막쇠는 칼을 놓지 못한다. 막쇠의 칼에는 흑련 사람 누구도 모르는 사연이 있다.', 'deungdo_landing', 50, '{mdq_17,ep_dd_4}'::text[], null, 1504, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:deungdo", "stage": 5}'::jsonb where quest_id = 'ep_dd_5';
delete from public.world_quest_steps where quest_id = 'ep_dd_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_5', 1, '손이 하나 모자라', '손이 하나 모자라', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "그사이 선착 야영소 대장간 화덕에 쇠가 제대로 달궈지기 시작했다. 바깥 대장간과 같은 값으로 연장을 고쳐 준다는 말에 조사원들이 줄을 섰다."}, {"s": null, "t": "돌계단에서는 차랑이 사다리를 옮겨 가며 쇠고리를 박고 있었다. 기둥 여섯만이 아니라 계단 한 칸 한 칸 양쪽에 새 고리가 반짝였다."}, {"s": "q:ug_charang", "t": "조사원님! 오늘 낙성이에요. 계단마다 명등을 달 거예요. 수로에서 올라오는 사람이 맨 아래부터 맨 위까지 불빛을 밟고 오게요."}, {"s": null, "t": "차랑이 사다리를 붙잡고 천막 쪽을 돌아보았다. 막쇠가 한 손엔 칼을, 한 손엔 등롱 하나를 들고 쇠고리 앞에서 낑낑대고 있었다. 등롱을 걸려면 고리를 벌려야 하는데 손이 하나 모자랐다."}, {"s": null, "t": "거룻배에서 등롱 상자를 나르던 삿대가 그 모습을 보고 노를 짚은 채 깔깔 웃었다."}, {"s": "q:sx_md_satdae", "t": "막쇠 님, 칼 좀 내려놓으세요! 그 칼 누가 훔쳐 간다고요!"}, {"s": null, "t": "막쇠가 삿대를 노려보았다. 그러고는 등롱을 내려놓고 나를 천막 뒤로 데려갔다. 칼을 쥔 손등에 핏줄이 불끈 서 있었다."}, {"s": "q:sx_md_maksoe", "t": "……너만 알아라. 이 칼, 안 뽑혀."}, {"s": null, "t": "막쇠가 칼자루를 잡고 힘을 주었다. 칼집과 칼자루 사이가 벌건 녹으로 엉겨 붙어 꿈쩍도 하지 않았다."}, {"s": "q:sx_md_maksoe", "t": "장부고 문 지키는 열 해 동안 한 번도 안 뽑았어. 문지기 칼은 뽑으면 지는 거라고 배웠거든. 그랬더니 녹이 슬어서 이제는 뽑고 싶어도 안 뽑혀."}, {"s": "q:sx_md_maksoe", "t": "칼 안 뽑히는 문지기가 무슨 문지기냐. 그래서 놓지를 못했어. 놓으면 누가 집어 들다 알아챌까 봐."}, {"s": "q:sx_md_maksoe", "t": "회에는 절대 말하지 마. 같은 회 사람한테 들키는 게 제일 창피해. 두례가 알면 장부고 끝까지 소문낸다.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": "q:sx_md_maksoe", "t": "흑련엔 절대 말하지 마. 두례가 알면 장부고 끝까지 소문낸다.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": null, "t": "막쇠가 칼을 품에 끌어안듯 쥐었다. 대장간 화덕 쪽을 흘끔 보았다가 고개를 저었다."}, {"s": "q:sx_md_maksoe", "t": "대장간에 맡기면 다들 보잖아. 네가 몰래 좀 고쳐 줘. 장비 고치는 도구 있잖아. 그거 하나만 지어 와."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_5', 2, '녹', '장비 수리 도구을(를) 만든다, 장비 수리 도구을(를) 넘긴다', '{"at": ["deungdo_landing"], "tasks": [{"t": "craft", "items": ["repair_kit"], "n": 1}], "give": {"repair_kit": 1}}'::jsonb, '[{"s": null, "t": "해 질 무렵, 사람들이 돌계단에 등롱을 거는 사이 막쇠와 나는 천막 뒤 화로 앞에 앉았다. 내가 장비 수리 도구를 건네자 막쇠가 주위를 한 번 둘러보았다."}, {"s": null, "t": "나는 칼집 이음새에 기름을 먹이고 녹을 조금씩 긁어냈다. 사각사각 소리가 날 때마다 막쇠가 움찔움찔 천막 쪽을 돌아보았다."}, {"s": "q:sx_md_maksoe", "t": "조용히 긁어. 소리가 커."}, {"s": null, "t": "마지막 녹 덩이가 툭 떨어지자 칼자루가 헐거워졌다. 막쇠가 숨을 들이쉬고 칼을 천천히 뽑았다. 스르릉 소리와 함께 칼날이 화롯불을 받아 번쩍였다."}, {"s": null, "t": "막쇠는 칼날을 한참 내려다보았다. 열 해 만에 처음 보는 제 칼이었다. 막쇠가 칼날에 비친 제 얼굴을 보고 코를 찡그렸다."}, {"s": "q:sx_md_maksoe", "t": "……생각보다 별거 아니네. 이걸 열 해를 쥐고 있었어."}, {"s": null, "t": "나는 칼날에는 녹이 한 점도 없다고 했다. 칼집이 녹을 다 받아 낸 덕이었다."}, {"s": null, "t": "막쇠가 칼을 도로 칼집에 넣었다. 이번에는 칼집이 부드럽게 칼을 삼켰다. 막쇠는 칼을 쥔 채 한동안 일어나지 않았다."}, {"s": "q:sx_md_maksoe", "t": "장부고 문 지킬 땐 칼이 있어야 사람들이 맡긴 이름을 믿고 갔어. 근데 여긴 맡긴 이름이 없잖아. 다들 제 이름 달고 장 보고, 배 타고 다니지."}, {"s": null, "t": "천막 너머 돌계단에서 차랑이 사다리 위에 선 채 이쪽으로 손나팔을 만들었다."}, {"s": "q:ug_charang", "t": "조사원님! 명등이 모자라요! 계단 맨 위 두 칸이 비었어요!"}, {"s": null, "t": "막쇠가 그 소리에 칼을 쥔 손을 내려다보았다. 그러고는 나를 보고 턱짓을 했다."}, {"s": "q:sx_md_maksoe", "t": "명등 두 개 더 지어 와. 맨 위 두 개는 내가 건다. 두 손으로."}, {"s": null, "t": "막쇠가 화로 불을 덮어 끄고 천막 기둥에 등을 기댔다. 칼은 무릎 위에 가로로 눕혀 두었다."}, {"s": "q:sx_md_maksoe", "t": "다 지어 오면 깨워. 낙성은 한밤에 한대. 나도 좀 쉬어야겠다. 열 해 쥔 칼 내려놓을 생각을 하니까 기운이 다 빠져."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_dd_5', 3, '불빛을 밟고', '명등 등롱을(를) 만든다, 남문 수로 선착에서 쉰다, 명등 등롱을(를) 넘긴다', '{"at": ["deungdo_landing"], "tasks": [{"t": "craft", "items": ["myeongdeung_lamp"], "n": 2}, {"t": "rest", "r": ["deungdo_landing"], "n": 1}], "give": {"myeongdeung_lamp": 2}}'::jsonb, '[{"s": null, "t": "한밤이 되자 선착에 사람들이 모여들었다. 쉼막에서는 함박과 옹심이 장꾼들을 이끌고 왔고, 수로로는 청파의 배가 구름나루 사람들을 싣고 들어왔다."}, {"s": null, "t": "막쇠가 내가 지어 온 명등 둘을 받아 들고 돌계단 맨 위로 올라갔다. 사람들이 숨을 죽이고 막쇠를 올려다보았다."}, {"s": null, "t": "막쇠는 쇠고리 앞에서 잠깐 멈췄다. 그러고는 허리에서 칼을 풀어 칼집째 계단 위에 가만히 내려놓았다."}, {"s": null, "t": "막쇠가 두 손으로 고리를 벌리고 명등 둘을 하나씩 걸었다. 걸고 나서도 칼 쪽으로는 손을 뻗지 않았다."}, {"s": null, "t": "차랑이 맨 아래 칸부터 차례로 심지에 불을 붙이며 올라왔다. 등이 하나 켜질 때마다 돌계단 한 칸이 노랗게 밝아졌다. 맨 위 두 등이 켜지자 계단 전체가 물길 위에 불빛 사다리처럼 비쳤다."}, {"s": null, "t": "쉼막 사람들이 와 하고 환호했다. 함박이 광주리를 내려놓고 큰 손으로 손뼉을 짝짝 쳤다."}, {"s": "q:sx_md_hambak", "t": "아이고, 곱기도 해라! 우리 쉼막 처마엔 등을 일곱 달았어요. 맹약 마당 자리마다 하나씩요. 오늘 밤엔 쉼막 쪽 하늘도 환할 거예요."}, {"s": null, "t": "뱃전에 서 있던 청파가 계단을 올려다보며 쿨럭쿨럭 기침을 했다. 기침이 멎자 청파가 두 손을 입가에 모았다."}, {"s": "q:sn_cheongpa", "t": "막쇠 님! 칼 내려놓으셨어요? 처음 봐요!"}, {"s": null, "t": "계단 맨 위의 막쇠가 칼 쪽을 내려다보았다. 칼은 계단에 놓인 채 불빛을 받고 있었다. 막쇠는 칼을 다시 집어 들지 않고 퉁명스럽게 소리쳤다."}, {"s": "q:sx_md_maksoe", "t": "시끄러. 오늘은 등 거는 날이야. 칼 쥐는 날 아니고."}, {"s": null, "t": "말뚝 옆에서 삿대가 노를 짚고 서서 휘파람을 불었다. 나귀가 그 소리에 놀라 히힝 울자 사람들이 한꺼번에 웃음을 터뜨렸다."}, {"s": null, "t": "옹심이 장꾼들 손에 낙성 떡을 하나씩 나눠 주었다. 떡을 건넬 때마다 옹심은 고개를 깊이 숙였다."}, {"s": "q:sx_md_ongsim", "t": "여기까지 온 건 조사원님들이 이 나루에 보태 주신 물건 덕이에요. 대장간 수리 값도, 선반에 되파는 값도 이제 바깥이랑 같대요. 조사원님 별채도 여기서 고치실 수 있고요."}, {"s": null, "t": "차랑이 사다리에서 내려와 맨 아래 기둥에 칼끝으로 금 하나를 그었다. 그러고는 그 옆에 처음으로 작은 동그라미 하나를 그렸다."}, {"s": "q:ug_charang", "t": "넷이에요. 오늘은 세 번으로는 모자라서요. 이 동그라미는 선착이 고을이 된 날이에요."}, {"s": null, "t": "나는 계단 맨 위로 올라가 막쇠 곁에 섰다. 막쇠는 칼을 발치에 둔 채 두 손을 허리 뒤로 맞잡고 불빛 아래 물길을 내려다보고 있었다."}, {"s": "q:sx_md_maksoe", "t": "조사원. 칼 얘기 말이야. 이젠 해도 돼. 녹은 네가 긁었으니까, 소문도 네가 내."}, {"s": null, "t": "물길을 따라 불빛이 길게 흔들렸다. 수로 저편 끝까지 사람들 웃음소리가 퍼져 나갔고, 그 소리는 이제 세 걸음 밖에서도 또렷하게 들렸다."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_gw_1', 'side', '뒷이야기·반요촌', '장날 좌판 둘', '반요촌 장날에 바깥 물건을 파는 좌판이 둘 더 선다. 날마다 문패만 고치던 촌장 묵호가 망치를 내려놓고 장 구경을 하고, 상쇠는 「맞이하는 노래」의 첫 소절을 짓는다.', 'banyo_village', 50, '{mdq_17}'::text[], null, 1505, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:gwiheo", "stage": 1}'::jsonb where quest_id = 'ep_gw_1';
delete from public.world_quest_steps where quest_id = 'ep_gw_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_1', 1, '재가 내리는 좌판', '재가 내리는 좌판', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 한가운데 빈터에 장이 서 있었다. 비늘을 이은 지붕 아래 좌판마다 등불이 걸렸고, 사람들 손등과 목덜미의 비늘이 그 불빛에 반짝였다."}, {"s": null, "t": "빈터 맨 끝에 새로 짠 좌판 둘이 놓여 있었다. 한쪽 좌판에는 회춘단 병이, 다른 쪽 좌판에는 월광 정수 병이 키를 맞춰 늘어서 있었다. 섬에서 나지 않는 바깥 약이었다."}, {"s": null, "t": "좌판 앞에서 상쇠가 두 팔을 벌리고 목청을 돋우었다."}, {"s": "q:sx_sangsoe", "t": "자, 보시오, 보시오! 바깥 약이 왔어! 섬에 들어온 뒤로 처음 보는 거야! 한 번 보고 두 번 보고 세 번 보면… 마루야, 세 번 보면 뭐더라?"}, {"s": null, "t": "상쇠 곁에서 약병을 세던 마루가 고개도 들지 않고 대꾸했다."}, {"s": "q:sx_maru", "t": "사야죠. 아저씨가 아까 그렇게 외우셨잖아요."}, {"s": null, "t": "마루가 갈퀴처럼 갈라진 손가락으로 약병 수를 세며 대꾸했다. 사람들이 좌판 둘레에 둥글게 모여 병 하나하나를 신기한 듯 들여다보았다."}, {"s": null, "t": "좌판에서 조금 떨어진 문간에 촌장 묵호가 쪼그려 앉아 있었다. 한 손에 망치를 쥔 채였다. 문패에 박다 만 못이 반쯤 튀어나와 있었는데, 노인의 눈은 문패가 아니라 장터 쪽에 가 있었다."}, {"s": null, "t": "나는 묵호 곁으로 가서 오늘은 문패를 안 고치느냐고 물었다. 묵호가 그제야 손에 든 망치를 내려다보았다."}, {"s": "q:g_mukho", "t": "아, {이름}. 왔구먼. …허허, 고치던 중이었네. 저걸 보느라 손이 멈췄어."}, {"s": "q:g_mukho", "t": "바깥 조사원들이 우리 사업에 식칼이며 바늘이며 망치며 메기 약선을 넘겨주었다더군. 상점이 그 몫으로 바깥 약을 바꿔 들였다네. 섬에서 바깥 물건 좌판이 서는 건 처음일세."}, {"s": null, "t": "그때 갈대숲 쪽에서 바람이 불어왔다. 잿빛 갈대 끝에서 재 같은 꽃가루가 풀풀 날려 좌판 위로 내려앉았다. 약병 마개와 종이 꼬리표가 금세 뿌옇게 덮였다."}, {"s": null, "t": "바느질 아낙 솔래가 좌판으로 달려와 앞치마로 병을 훔쳤다."}, {"s": "q:sx_sollae", "t": "어쩌나, 어쩌나. 바깥 약 꼬리표에 재가 앉으면 글씨가 안 보여. 그럼 무슨 약인지 몰라서 아무도 못 사 가잖아."}, {"s": "q:sx_sollae", "t": "차양을 쳐야겠어. 갈대숲에서 거둔 걸로 엮으면 재도 막고 바람도 막아. 조사원, 갈대숲에서 쓸 만한 걸 좀 거둬 와 줄래? 갈대 영사든 수향 갈대든 부적목이든, 손에 잡히는 대로. 내가 엮을게."}, {"s": null, "t": "상쇠가 솔래 뒤에서 고개를 내밀었다."}, {"s": "q:sx_sangsoe", "t": "넉넉히 거둬 와! 좌판이 둘이니까 차양도 둘이야! 둘이면… 마루야, 둘이면 몇 번 거둬야 하냐?"}, {"s": null, "t": "마루가 한숨을 쉬며 손가락 넷을 펴 보였다."}, {"s": "q:sx_maru", "t": "네 번이요. 차양 하나에 두 번씩요. …아저씨, 손가락 그만 접으세요. 네 번이라니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_1', 2, '이름값과 전', '잿빛 갈대숲에서 채집한다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "r": ["ash_reeds"], "n": 4}]}'::jsonb, '[{"s": null, "t": "갈대숲에서 거둔 것을 내려놓자 솔래가 무릎을 꿇고 앉아 갈대 영사를 꼬기 시작했다. 바늘이 휙휙 오갈 때마다 차양 한 폭이 늘어났다. 바깥에서 들어온 무월 비단 바늘이었다."}, {"s": "q:sx_sollae", "t": "이 바늘 좀 봐. 바깥 조사원들이 넘겨준 거라더라. 예전 조개 바늘은 세 땀에 한 번씩 부러졌는데, 이건 백 땀을 떠도 멀쩡해."}, {"s": null, "t": "좌판 앞에서는 상쇠와 마루가 서로 마주 보고 팔짱을 끼고 있었다."}, {"s": "q:sx_sangsoe", "t": "값은 이름값이야. 반요촌 장날은 다 이름값이잖아. 판 사람 이름을 한 번 불러 주면 물건 하나."}, {"s": null, "t": "마루가 팔짱을 풀지 않고 고개를 갸웃했다."}, {"s": "q:sx_maru", "t": "그럼 이 약은 누구 이름을 불러요? 이건 바깥에서 왔어요. 만든 사람도 넘겨준 사람도 여기 없잖아요."}, {"s": null, "t": "상쇠가 잠깐 눈을 굴리다가 손뼉을 쳤다."}, {"s": "q:sx_sangsoe", "t": "…바깥 사람 이름을 부르면 되지!"}, {"s": null, "t": "마루가 상쇠를 빤히 올려다보았다."}, {"s": "q:sx_maru", "t": "바깥 사람 이름을 아무도 몰라요."}, {"s": null, "t": "상쇠가 입을 딱 벌렸다가 다물었다. 상쇠가 나를 돌아보았다. 볼에 돋은 요문이 등불에 번들거렸다."}, {"s": "q:sx_sangsoe", "t": "조사원, 네 이름 불러도 돼?"}, {"s": null, "t": "나는 이 약을 넘긴 조사원은 여럿이라 내 이름 하나로는 셈이 안 맞는다고 했다. 마루가 그 말에 손뼉을 짝 쳤다."}, {"s": "q:sx_maru", "t": "맞아요. 그러니까 바깥 물건은 전으로 받아요. 바깥에서도 전으로 샀으니까요. 대신 덤으로, 좌판 앞에 선 사람 이름을 불러 줘요. 사는 사람이 파는 사람 이름을 부르고, 파는 사람이 사는 사람 이름을 부르고요."}, {"s": null, "t": "상쇠가 눈을 번쩍 뜨고 마루의 어깨를 붙잡았다."}, {"s": "q:sx_sangsoe", "t": "덤이 이름이라고? …그거 좋다! 그럼 손님이 많아질수록 이름이 많이 불리겠네!"}, {"s": null, "t": "묵호가 망치를 무릎에 내려놓고 그 말을 듣고 있다가 허허 웃었다."}, {"s": "q:g_mukho", "t": "바깥 장에서는 물건이 덤이고 섬 장에서는 이름이 덤이구먼. 좋네. 그리 하게."}, {"s": null, "t": "상쇠가 좌판 앞을 서성이며 무엇을 중얼거렸다. 박자를 맞추듯 손바닥으로 허벅지를 툭툭 쳤다."}, {"s": "q:sx_sangsoe", "t": "바깥 물건 왔구나, 좌판 둘이 더 섰구나…. 이거 노래 첫 소절이야. 맞이하는 노래. 섬에는 배웅 노래밖에 없잖아. 내가 하나 짓는 중이거든."}, {"s": null, "t": "마루가 차양 끝을 붙잡은 채 쯧 혀를 찼다."}, {"s": "q:sx_maru", "t": "아까는 「좌판 셋이 더 섰구나」였어요. 둘이에요, 아저씨."}, {"s": null, "t": "상쇠가 못 들은 척 헛기침을 하고 나를 보았다."}, {"s": "q:sx_sangsoe", "t": "차양만 있으면 좌판이 심심해. 맨 앞에 노리개를 걸어야 손님이 오지. 세 갈래 술을 단 삼작 노리개 두 개만 엮어 줘. 좌판마다 하나씩. 노래도 노리개 걸고 나서 마저 부를 거야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_1', 3, '문패를 잊은 아침', '삼작 노리개을(를) 만든다, 삼작 노리개을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["n5_luck"], "n": 2}], "give": {"n5_luck": 2}}'::jsonb, '[{"s": null, "t": "상쇠가 삼작 노리개를 두 좌판 차양 끝에 하나씩 걸었다. 세 갈래 술 끝에 반요 비늘을 꿴 노리개가 바람에 짤랑짤랑 흔들렸다. 차양 아래로는 재가 들이치지 않아 약병 꼬리표가 또렷했다."}, {"s": null, "t": "첫 손님은 단이였다. 단이는 등에 멘 약 상자를 고쳐 메고 회춘단 좌판 앞에 섰다. 손바닥에 전 몇 닢이 쥐여 있었다."}, {"s": "q:g_dani", "t": "회춘단 하나 주세요. 어제 갈대 베다 손 벤 새암 아주머니 드릴 거예요. …그리고 덤이요."}, {"s": null, "t": "단이가 좌판 너머 상쇠를 올려다보며 그의 섬 이름을 또박또박 불렀다. 상쇠가 화들짝 놀라 대답하고는, 병을 건네며 단이의 이름을 큰 소리로 불렀다. 단이가 병을 두 손으로 받아 들고 배시시 웃었다."}, {"s": null, "t": "그 뒤로 줄이 생겼다. 사는 사람과 파는 사람이 서로 이름을 주고받을 때마다 좌판 앞이 와글와글 시끄러워졌다. 마루는 좌판 귀퉁이에 앉아 팔린 병과 불린 이름을 나란히 셈했다."}, {"s": "q:sx_maru", "t": "병 일곱, 이름 열넷이요. 아저씨가 혼잣말로 아저씨 이름 부른 건 이번엔 안 셀게요."}, {"s": null, "t": "상쇠가 얼굴이 벌게져서 손사래를 쳤다."}, {"s": "q:sx_sangsoe", "t": "세어 줘!"}, {"s": null, "t": "줄 맨 끝에 묵호가 서 있었다. 노인은 월광 정수 한 병을 사고, 판 사람의 이름을 천천히 또박또박 불렀다. 그러다 묵호가 병을 든 채 갑자기 걸음을 멈췄다."}, {"s": "q:g_mukho", "t": "…이런."}, {"s": null, "t": "묵호가 제 집 문간 쪽으로 돌아섰다. 걸음이 바빴다. 나는 그 뒤를 따라갔다. 문간 문패 앞에 선 노인이 위 칸의 바깥 이름을 손가락으로 짚었다."}, {"s": "q:g_mukho", "t": "오늘 아침에 이걸 안 짚었네. 섬에 들어온 뒤로 하루도 안 빼고 짚었는데. 장 구경하느라 잊어버렸어."}, {"s": null, "t": "노인의 손가락이 위 칸 첫 글자 위에서 멈췄다. 한동안 아무 말이 없었다. 나는 노인 곁에 서서 기다렸다."}, {"s": "q:g_mukho", "t": "…있네. 아직 읽히네, 오늘도."}, {"s": null, "t": "묵호가 허허 웃었다. 웃음 끝이 조금 떨렸다. 노인은 문패에서 손을 떼고 장터 쪽을 돌아보았다."}, {"s": "q:g_mukho", "t": "{이름}, 이상하지. 이름을 안 짚은 아침이 이렇게 가볍구먼. 날마다 오늘은 몇 글자가 남았나, 그것만 셈하고 살았는데 말일세."}, {"s": null, "t": "장터 쪽에서 상쇠의 목소리가 크게 울렸다. 첫 소절이었다. 「바깥 물건 왔구나, 좌판 둘이 더 섰구나.」 마루가 곁에서 「둘이요, 이번엔 맞았어요」 하고 외쳤다."}, {"s": null, "t": "묵호는 문패에 박다 만 못을 마저 박지 않고 망치를 허리춤에 꽂았다. 노인은 월광 정수 병을 품에 넣고 다시 장터 쪽으로 걸어갔다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_gw_2', 'side', '뒷이야기·반요촌', '바깥으로 가는 뱃길', '반요촌과 십삼문 암시장을 잇는 지름길이 열린다. 십삼문의 소금 장수 짠물댁이 섬 장날에 오겠다는 서신을 보내고, 섬 밖으로 나갈 수 없는 길잡이 여울이 바깥 손님을 맞으러 섬 끝 말뚝까지 배를 몬다.', 'banyo_village', 50, '{mdq_17,ep_gw_1}'::text[], null, 1506, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:gwiheo", "stage": 2}'::jsonb where quest_id = 'ep_gw_2';
delete from public.world_quest_steps where quest_id = 'ep_gw_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_2', 1, '섬 끝 말뚝', '섬 끝 말뚝', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "그사이 반요촌 장날에는 바깥 약 좌판 둘이 늘 섰다. 상쇠의 맞이하는 노래는 아직 첫 소절에서 더 나가지 못했다."}, {"s": null, "t": "선창에 내려가니 여울이 거룻배 뱃머리에 서서 물길 위 말뚝마다 작은 등을 달고 있었다. 검은 물길을 따라 등불이 점점이 이어져 봉연 쪽 어둠 속으로 사라졌다."}, {"s": "q:g_yeoul", "t": "왔네. 사업 둘째 단계가 찼어. 섬에서 십삼문까지 지름길이 났어. 지맥의 뿌리랑 봉연을 지나는 길. 바깥 조사원들이 넘겨준 증류기며 각인도며 짚신 덕이야. 이제 오가는 데 운임도 안 들고 시간도 덜 걸려."}, {"s": null, "t": "여울은 등 하나를 말뚝에 걸고 손목의 비늘을 문질렀다. 푸른 비늘이 등불에 차갑게 반짝였다."}, {"s": "q:g_yeoul", "t": "길이 났으면 길잡이가 있어야지. 그래서 등을 다는 중이야."}, {"s": null, "t": "선창 위에서 상쇠가 종이 한 장을 흔들며 뛰어 내려왔다. 그 뒤를 단이가 약 상자를 덜컹거리며 따라왔다."}, {"s": "q:sx_sangsoe", "t": "서신이야, 서신! 바깥에서 왔어! 십삼문 밀수 부두 소금 장수래. 우리 장날에 소금을 팔러 오겠대!"}, {"s": null, "t": "상쇠가 내민 서신을 여울이 받아 펼쳤다. 여울이 한 줄씩 읽어 내려가다가 끝에서 눈썹을 찌푸렸다."}, {"s": "q:g_yeoul", "t": "「길은 났다지만 봉연 물길은 무섭소. 먹손이 기어 나온다는 소문도 있고, 섬 사람은 비늘이 돋았다지 않소. 누가 데리러 와 주면 가겠소. 밑지는 장사지만.」 …짠물댁이래."}, {"s": null, "t": "상쇠가 여울의 소매를 붙잡고 흔들었다."}, {"s": "q:sx_sangsoe", "t": "데리러 가 줘, 여울! 네가 길잡이잖아!"}, {"s": null, "t": "여울이 서신을 접어 품에 넣었다. 여울은 물길 끝 어둠을 한참 바라보다가 고개를 저었다."}, {"s": "q:g_yeoul", "t": "나는 못 가. 요기 탄 몸은 섬 밖으로 못 나가. 저기 마지막 등 단 말뚝 보여? 섬 끝 말뚝이야. 거기까지가 섬이야. 나는 거기까지밖에 못 가."}, {"s": null, "t": "여울이 나를 보았다. 짧게 끊어 말하던 목소리가 조금 낮아졌다."}, {"s": "q:g_yeoul", "t": "그러니까 네가 십삼문까지 가서 그 사람을 데려와. 섬 끝 말뚝까지만. 거기서부터는 내가 배로 맞을게."}, {"s": null, "t": "단이가 여울 곁으로 다가와 내 소매를 잡아당겼다."}, {"s": "q:g_dani", "t": "{이름} 님, 십삼문에 바다 있죠? 부두요. 거기서 물고기 한 마리만 낚아 와 주세요. 바다 물고기요."}, {"s": null, "t": "나는 바다 물고기는 왜냐고 물었다. 단이가 약 상자 끈을 두 손으로 꼭 쥐었다."}, {"s": "q:g_dani", "t": "바다 냄새 맡아 보고 싶어서요. 엄마가 상자 뚜껑에 써 놨어요. 비늘 없는 아이는 바깥으로도 섬으로도 갈 데가 없다고요. 그래서 저는 아직 말뚝 너머로 한 번도 안 가 봤어요. …냄새라도 먼저 맡아 보고 싶어요."}, {"s": null, "t": "여울이 단이의 머리에 손을 얹었다가 금방 거두었다."}, {"s": "q:g_yeoul", "t": "낚아다 줘. 부두에서 세 번쯤 던지면 걸릴 거야. 저 애 소원이야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_2', 2, '소금 장수', '십삼문 암시장에 간다, 십삼문 암시장에서 낚시를 한다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "travel", "r": ["hidden_bazaar"], "n": 1}, {"t": "fish", "r": ["hidden_bazaar"], "n": 3}]}'::jsonb, '[{"s": null, "t": "십삼문 밀수 부두에는 짠 바람이 불었다. 갈매기가 끼룩끼룩 울며 돛대 위를 맴돌았고, 부두 판자마다 소금기가 하얗게 말라붙어 있었다. 나는 낚은 바다 물고기를 젖은 갈대에 싸서 바구니에 담았다."}, {"s": null, "t": "부두 끝 창고 앞에서 허리에 소금 자루를 찬 아낙 하나가 항아리를 지게에 얹고 있었다. 내 허리춤의 인장을 보자 아낙이 지게를 내려놓고 두 손을 허리에 짚었다."}, {"s": "q:sx_ep_jjanmul", "t": "섬에서 보낸 사람이오? 아니, 조사원이네. 섬 사람이 직접 올 줄 알았는데."}, {"s": null, "t": "나는 섬 사람은 섬 끝 말뚝 밖으로 나올 수 없어서 내가 왔다고 했다. 짠물댁이 눈을 끔뻑이다가 쯧 혀를 찼다."}, {"s": "q:sx_ep_jjanmul", "t": "그것도 모르고 데리러 오라 했네. 미안하게 됐소. 나는 서른 해를 이 부두에서 소금만 팔았지. 섬은 지도에 없는 데라고만 알았어. 사업 소식 듣고서야 거기도 장이 선다는 걸 알았소."}, {"s": "q:sx_ep_jjanmul", "t": "섬에는 소금이 귀하다며. 바닷물이 안 닿는 데라. 소금 없이 밥을 어떻게 먹나 싶어서, 그 생각만 하니까 잠이 안 오더라고. 밑지는 장사인 줄 알면서도 가겠다고 한 거요."}, {"s": null, "t": "짠물댁이 항아리 뚜껑을 열어 보였다. 굵은 소금이 가득했고, 옆 항아리에는 말린 미역과 조개젓이 들어 있었다."}, {"s": null, "t": "짠물댁이 소금 한 줌을 집어 내 손바닥에 털어 주었다. 굵은 알갱이가 손금 사이로 서걱서걱 굴렀다."}, {"s": "q:sx_ep_jjanmul", "t": "맛보시오. 이게 십삼문 소금이야. 섬 사람들이 이 맛을 잊었으면 다시 알려 줘야지."}, {"s": null, "t": "나는 소금 한 알을 혀끝에 대 보았다. 짠맛 뒤에 단맛이 살짝 돌았다. 나는 바구니의 바다 물고기를 보여 주며, 섬에 바다 냄새를 맡고 싶어 하는 아이가 있다고 했다."}, {"s": "q:sx_ep_jjanmul", "t": "바다 냄새를? 허, 그 섬엔 바다 냄새도 없나. …그 물고기는 젖은 갈대에 잘 싸 둬요. 하룻길이면 비린내가 조금 남을 거요. 그게 바다 냄새지."}, {"s": null, "t": "나는 짠물댁 지게의 항아리 하나를 들어 내 등짐에 옮겨 실었다. 아낙이 눈을 둥그렇게 떴다."}, {"s": "q:sx_ep_jjanmul", "t": "거 짐은 왜 덜어 가오. …고맙소. 품삯은 안 받겠다는 얼굴이네. 당신도 밑지는 장사를 하는구려."}, {"s": null, "t": "짠물댁이 지게를 다시 지려다 말고 부두 너머 땅굴 쪽을 흘끗 보았다. 지맥의 뿌리로 내려가는 굴 어귀였다. 아낙의 손이 지게 끈을 쥔 채 굳었다."}, {"s": "q:sx_ep_jjanmul", "t": "길은 굴로 내려가서 봉연을 지난다지. 봉연 물길에 박쥐 떼며 사슬 귀신들이 들끓는다오. 지난달에도 우리 부두 짐꾼 하나가 박쥐 떼에 짐을 다 쏟고 돌아왔어."}, {"s": "q:sx_ep_jjanmul", "t": "조사원 양반, 미안하지만 그것들부터 좀 쳐 주오. 내가 지나갈 만큼만. 그다음엔 따라가리다. 오늘 밤은 섬에서 묵고 가야겠소. 하룻길이라도 늙은 다리엔 길어."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_2', 3, '맞으러 나온 배', '구중 봉연의 요괴를 물리친다, 반요촌에서 쉰다', '{"at": ["banyo_village"], "tasks": [{"t": "win", "r": ["sealed_abyss"], "n": 6}, {"t": "rest", "r": ["banyo_village"], "n": 1}]}'::jsonb, '[{"s": null, "t": "봉연 물길을 지나는 동안 짠물댁은 내 등 뒤에 바싹 붙어 걸었다. 물에서 무언가 첨벙 튀어 오를 때마다 아낙이 「어이쿠」 하며 내 옷자락을 붙잡았다."}, {"s": null, "t": "물길 끝 어둠 속에서 등불 하나가 흔들렸다. 섬 끝 말뚝이었다. 말뚝 곁에 거룻배 한 척이 떠 있었고, 뱃머리에 여울이 등을 높이 들고 서 있었다."}, {"s": "q:g_yeoul", "t": "여기야. 이쪽으로."}, {"s": null, "t": "짠물댁이 걸음을 멈추었다. 등불 아래 여울의 왼 손목에 돋은 비늘이 푸르게 번뜩였다. 아낙이 숨을 들이켜며 한 걸음 물러섰다."}, {"s": null, "t": "여울은 소매를 내리지 않았다. 대신 배를 말뚝에 바싹 대고 손을 내밀었다."}, {"s": "q:g_yeoul", "t": "놀라지 마. 섬 사람은 다 이래. 나는 여울이야. 섬 길잡이. 짐부터 줘. 발은 거기, 판자 가운데 디뎌."}, {"s": null, "t": "짠물댁은 내민 손을 한참 보다가 지게를 먼저 넘겼다. 그러고는 여울의 손을 잡고 배에 올랐다. 배가 출렁하자 아낙이 그 손을 꽉 쥐었다."}, {"s": "q:sx_ep_jjanmul", "t": "…손이 차갑구려."}, {"s": null, "t": "여울은 노를 고쳐 쥐며 고개만 끄덕였다."}, {"s": "q:g_yeoul", "t": "응. 비늘이라서."}, {"s": null, "t": "여울이 노를 저었다. 배가 소리 없이 미끄러져 나아갔다. 여울은 한참 아무 말이 없다가, 앞만 보고 말했다."}, {"s": "q:g_yeoul", "t": "예전엔 섬으로 사람을 보내는 쪽이었어. 배에 태워서, 이름에 줄 그어서. …바깥 사람을 이렇게 배로 맞으러 나오는 날이 올 줄은 몰랐어."}, {"s": null, "t": "짠물댁은 그 말이 무슨 뜻인지 묻지 않았다. 아낙이 허리춤에서 소금 한 줌을 꺼내 여울의 배 바닥에 휙 뿌렸다."}, {"s": "q:sx_ep_jjanmul", "t": "부두에선 처음 타는 배에 소금을 뿌려 주오. 무사히 닿으라고. 섬 배라고 다를 거 있나."}, {"s": null, "t": "반요촌 선창에 닿자 마을 사람들이 등불을 들고 내려와 있었다. 그날 밤 짠물댁은 묵호의 집 화로 곁에서 묵었고, 나도 그 곁에서 쉬었다. 화로 너머에서 상쇠가 밤늦도록 무엇을 흥얼거렸다."}, {"s": null, "t": "이튿날 아침 단이가 선창으로 뛰어왔다. 나는 젖은 갈대에 싸 온 바다 물고기를 단이 앞에 펼쳤다. 단이가 무릎을 꿇고 얼굴을 바싹 갖다 댔다."}, {"s": "q:g_dani", "t": "…짜요. 냄새가 짜요. 비린데 짜요. 이게 바다예요?"}, {"s": null, "t": "짠물댁이 단이 곁에 쪼그려 앉으며 웃었다."}, {"s": "q:sx_ep_jjanmul", "t": "그게 바다 냄새요, 아가. 소금 냄새."}, {"s": null, "t": "짠물댁이 소금 한 알을 단이 손바닥에 올려 주었다. 단이가 혀끝으로 그 알을 톡 대 보고 얼굴을 잔뜩 찡그렸다가 활짝 웃었다."}, {"s": "q:g_dani", "t": "다음엔 진짜 바다를 볼래요. 말뚝 너머로요. 언젠가요."}, {"s": null, "t": "장터 쪽에서 상쇠의 노래가 들렸다. 둘째 소절이 붙어 있었다. 「검은 물길 건너온 손, 등불 들고 맞자꾸나.」 여울이 선창 말뚝에 기대어 그 노래를 들으며 손목의 비늘을 한 번 문질렀다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_gw_3', 'side', '뒷이야기·반요촌', '섬의 창고', '반요촌에 처음으로 창고가 서고 서신에 물건을 실어 보낼 수 있게 된다. 늘 어머니의 약 상자를 메고 다니던 단이가 그 상자를 맡길지 말지 망설인다.', 'banyo_village', 50, '{mdq_17,ep_gw_2}'::text[], null, 1507, '[]'::jsonb, true, null, null)
