update public.world_quests set open_req = '{"project": "c:gwiheo", "stage": 3}'::jsonb where quest_id = 'ep_gw_3';
delete from public.world_quest_steps where quest_id = 'ep_gw_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_3', 1, '맡길 데', '맡길 데', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "그사이 짠물댁은 장날마다 소금 항아리를 지고 섬 끝 말뚝까지 왔고, 여울은 그때마다 배로 맞으러 나갔다. 반요촌 부엌마다 소금 냄새가 돌기 시작했다."}, {"s": null, "t": "마을 끝 공터에 새 창고 하나가 서 있었다. 갈대 지붕 아래로 칸칸이 나뉜 선반이 늘어섰고, 사람들이 저마다 보따리를 안고 줄을 서 있었다. 갈대 영사로 꿰맨 이름표가 선반마다 달려 있었다."}, {"s": null, "t": "묵호가 창고 문간에 서서 사람들이 짐을 맡기는 것을 지켜보고 있었다. 노인이 나를 보고 손짓했다."}, {"s": "q:g_mukho", "t": "{이름}, 와서 보게. 섬 첫 창고일세. 바깥 조사원들이 넘겨준 낫이며 낚싯대며 관모 덕에 사업 셋째 단계가 찼다더군. 이제 맡겨 둘 데가 생겼고, 서신에 물건을 실어 보낼 수도 있다네."}, {"s": "q:g_mukho", "t": "섬에서는 물건을 오래 못 둬. 재가 앉고 물이 스미고, 저잣거리 것들이 기억째 물어 가. 그래서 다들 가진 걸 몸에 지니고 다녔지. 오늘 처음으로 내려놓는 걸세."}, {"s": null, "t": "줄 선 사람들 가운데 상쇠가 장날에 치는 북을 끌어안고 있었다. 상쇠가 북을 선반에 올려놓고 선반을 손바닥으로 탕탕 두드렸다."}, {"s": "q:sx_sangsoe", "t": "이 북 맡겨 두면 장날 아침마다 꺼내러 와야겠네! 그래도 좋아. 이제 내 북이 재 맞을 걱정은 없잖아!"}, {"s": null, "t": "창고 문간 옆 돌에 단이가 혼자 앉아 있었다. 아이는 등에 멘 약 상자를 무릎에 내려놓고 끈만 만지작거리고 있었다. 줄은 줄어드는데 단이는 일어서지 않았다."}, {"s": null, "t": "나는 단이 곁에 앉았다. 단이가 상자 뚜껑을 손바닥으로 쓸었다."}, {"s": "q:g_dani", "t": "{이름} 님. 여울 이모가 상자 맡기래요. 제가 이제 크니까 등이 굽는대요. 맞는 말이에요. 상자가 저보다 무거워요."}, {"s": "q:g_dani", "t": "근데 이거 내려놓으면, 엄마를 잊을 것 같아요. 엄마 얼굴은 원래 몰라요. 그래도 이 상자는 날마다 등에 있었어요. 무거운 게 엄마 같았어요."}, {"s": null, "t": "단이가 뚜껑을 살짝 열었다. 안에는 바싹 마른 고약 단지와 갈라진 환약 몇 알이 굴러다녔다. 뚜껑 안쪽에 낡은 종잇조각 하나가 아이 키 높이로 붙어 있었다."}, {"s": "q:g_dani", "t": "약도 다 말랐어요. 엄마가 그랬대요. 어느 쪽에서든 누군가를 고칠 수 있게 상자에 약을 채웠다고요. 그런데 지금 이걸로는 아무도 못 고쳐요."}, {"s": null, "t": "단이가 마른 고약 단지를 손가락으로 톡 두드렸다. 단지 속에서 굳은 고약이 돌멩이처럼 달그락거렸다."}, {"s": null, "t": "단이가 상자 뚜껑을 닫고 나를 올려다보았다. 눈이 동그랬다."}, {"s": "q:g_dani", "t": "{이름} 님, 바깥 약 지을 줄 알죠? 회춘단이요. 상처랑 독을 같이 고치는 거요. 세 알만 지어 주세요. 상자를 맡기든 안 맡기든, 엄마 상자는 고칠 수 있는 상자여야 해요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_3', 2, '상자 정리', '회춘단을(를) 만든다, 회춘단을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["rejuv_pill"], "n": 3}], "give": {"rejuv_pill": 3}}'::jsonb, '[{"s": null, "t": "회춘단 세 알을 지어 오자 단이가 두 손을 내밀었다가 도로 거두었다. 아이는 상자를 무릎에 올려놓고 고개를 저었다."}, {"s": "q:g_dani", "t": "아직 받으면 안 돼요. 빈자리부터 만들어야 해요. 마른 약이 자리를 다 차지하고 있거든요."}, {"s": null, "t": "단이가 상자를 열고 안에 든 것을 하나씩 꺼내 돌 위에 늘어놓았다. 마른 고약 단지 둘, 갈라진 환약 다섯 알, 돌돌 만 무명 붕대, 녹슨 자물쇠 하나였다. 단이는 자물쇠를 오래 들고 있었다."}, {"s": "q:g_dani", "t": "이건 거꾸로 선 사당 종 밑에서 나온 거예요. 상자랑 꼭 맞아요. 엄마도 거기 갔었대요."}, {"s": null, "t": "여울이 창고 쪽에서 장부를 들고 걸어왔다. 여울은 돌 위에 늘어놓은 것들을 보고 걸음을 멈추었다. 손목의 비늘을 문지르는 손이 빨라졌다."}, {"s": "q:g_yeoul", "t": "다 맡기라는 거 아니야. 무거운 것만. 등은 펴고 다녀야 해."}, {"s": null, "t": "단이가 자물쇠를 꼭 쥔 채 여울을 올려다보았다."}, {"s": "q:g_dani", "t": "알아요, 이모. 그래서 고르는 중이에요."}, {"s": null, "t": "단이가 마른 약과 자물쇠를 한쪽에 모았다. 그러고는 뚜껑 안쪽 종잇조각을 손끝으로 쓸었다. 종이 가장자리가 재에 그을려 거뭇거뭇했다."}, {"s": "q:g_dani", "t": "이 종이도 맡길래요. 재가 자꾸 앉아서 글씨가 흐려져요. 창고에 두면 안 흐려지죠? 대신 제가 외웠어요. 하나도 안 빼고요."}, {"s": null, "t": "바느질 아낙 솔래가 창고에서 나와 단이 곁에 쪼그려 앉았다. 솔래 손에는 빈 이름표 한 장과 바늘이 들려 있었다."}, {"s": "q:sx_sollae", "t": "단이야, 창고 칸에 이름표를 달아야 해. 먹으로 쓰면 또 지워질까 봐 다들 갈대 영사로 꿰매. 너는 누구 이름으로 달래?"}, {"s": null, "t": "단이가 이름표를 받아 들고 한참 생각했다. 그러고는 이름표를 반으로 접었다 폈다."}, {"s": "q:g_dani", "t": "둘이요. 제 이름이랑 엄마 이름이요. 문패처럼요. 저는 이름이 하나뿐이니까, 남은 칸에 엄마 이름을 넣으면 딱 맞아요."}, {"s": null, "t": "솔래가 이름표를 들여다보다가 실꾸리를 흔들어 보고 울상을 지었다."}, {"s": "q:sx_sollae", "t": "어쩌나, 이름 둘을 꿰매려면 실이 모자라. 창고 이름표 꿰매느라 갈대 영사를 다 썼어. 조사원, 갈대숲에서 세 타래만 더 걷어다 줄래? 그동안 단이는 상자를 다 비워 놓고."}, {"s": null, "t": "단이가 내 쪽으로 고개를 돌리고, 지어 온 회춘단을 손가락으로 가리켰다."}, {"s": "q:g_dani", "t": "그 회춘단은 실 갖다주실 때 같이 주세요. 상자 다 비우고 받을게요. 새 약은 빈 상자에 넣어야 하니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_3', 3, '두 이름 꿰맨 칸', '잿빛 갈대숲에서 갈대 영사을(를) 모은다, 회춘단을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 3}], "give": {"rejuv_pill": 3}}'::jsonb, '[{"s": null, "t": "갈대 영사를 건네자 솔래가 이름표에 한 땀씩 이름을 꿰맸다. 윗줄에 「단이」, 아랫줄에 「서연」이었다. 갈대 영사가 등불 아래 은빛으로 반짝였다."}, {"s": null, "t": "단이는 빈 상자를 무릎에 올려놓고 내가 건넨 회춘단 세 알을 하나씩 넣었다. 알약이 상자 바닥에 닿을 때마다 톡, 톡 작은 소리가 났다."}, {"s": "q:g_dani", "t": "됐다. 이제 진짜 의무관 상자 같아요."}, {"s": null, "t": "단이가 마른 약과 자물쇠와 종잇조각을 보자기에 싸서 창고로 들어갔다. 나는 그 뒤를 따라 들어갔다. 단이는 이름표가 달린 칸 앞에서 보자기를 내려놓고, 한참 손을 떼지 못했다."}, {"s": "q:g_dani", "t": "엄마, 여기 있어요. 저 밖에 있다 올게요."}, {"s": null, "t": "단이가 손을 떼고 돌아섰다. 아이는 마른 약을 덜어 낸 상자를 등에 메고 어깨를 으쓱 들썩여 보았다. 등이 조금 펴졌다."}, {"s": "q:g_dani", "t": "가벼워요. 근데 하나도 안 잊었어요. 다 외웠으니까요."}, {"s": null, "t": "창고 문간에서 묵호가 단이를 기다리고 있었다. 노인은 단이의 등을 손바닥으로 한 번 쓸어 보았다."}, {"s": "q:g_mukho", "t": "등이 펴졌구먼. 맡긴 건 맡긴 거고, 외운 건 외운 걸세. 둘 다 네 것이야."}, {"s": null, "t": "창고 문간에서 상쇠가 종이 한 장을 흔들며 소리쳤다. 서신이었다. 종이 사이에 작은 꾸러미 하나가 끼워져 있었다."}, {"s": "q:sx_sangsoe", "t": "단이야! 너한테 서신 왔어! 짠물댁이 보냈어! 이제 서신에 물건도 실어 온대!"}, {"s": null, "t": "단이가 꾸러미를 받아 끈을 풀었다. 안에서 말린 불가사리 하나가 나왔다. 손바닥만 한 다섯 갈래 별 모양이었다. 꾸러미 종이에 삐뚤삐뚤한 글씨가 적혀 있었다. 「바다에 사는 별이란다. 바다 냄새 맡고 싶다길래. 밑지는 장사다. 짠물댁.」"}, {"s": null, "t": "단이가 불가사리를 코에 대고 킁킁 냄새를 맡았다. 그러고는 상자를 열어 회춘단 곁에 불가사리를 넣었다."}, {"s": "q:g_dani", "t": "이건 맡기지 말아야지. 이건 들고 다닐 거예요."}, {"s": null, "t": "여울이 장부에 창고 칸 이름을 옮겨 적다가 「단이 · 서연」 줄에서 붓을 멈췄다. 여울은 그 줄을 다른 줄보다 천천히, 반듯하게 적었다."}, {"s": null, "t": "장터 쪽에서 상쇠의 노래가 셋째 소절로 넘어갔다. 「맡길 데가 생겼구나, 두고 가도 남는구나.」 묵호가 창고 문간에 기대어 그 노래에 맞춰 손가락으로 문설주를 톡톡 두드렸다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_gw_4', 'side', '뒷이야기·반요촌', '섬의 마구간', '반요촌에 거래소와 마구간과 조사원 의뢰 게시판이 선다. 처음 보는 말에 아이들이 기겁하고, 이름값으로만 사고팔던 반요들이 처음으로 제 물건에 전으로 값을 매긴다.', 'banyo_village', 50, '{mdq_17,ep_gw_3}'::text[], null, 1508, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:gwiheo", "stage": 4}'::jsonb where quest_id = 'ep_gw_4';
delete from public.world_quest_steps where quest_id = 'ep_gw_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_4', 1, '처음 보는 짐승', '처음 보는 짐승', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "그사이 반요촌 창고는 칸이 거의 다 찼다. 사람들은 이제 몸에 다 지니지 않고 다녔고, 등이 굽은 아이도 조금씩 줄었다."}, {"s": null, "t": "선창 위 공터에 새 마구간이 서 있었다. 그 앞에 아이들이 몰려 있었는데, 다들 마구간 문에서 열 걸음쯤 떨어져 서서 앞으로 나가지 못하고 있었다."}, {"s": null, "t": "마구간 안에서 말 한 마리가 푸르르 콧김을 뿜었다. 아이들이 꺄악 소리를 지르며 우르르 뒤로 물러났다. 마루만 맨 앞에 남아 손가락으로 무언가를 세고 있었다."}, {"s": "q:sx_maru", "t": "다리가 넷, 귀가 둘, 꼬리가 하나. 셈은 맞는데 너무 커요. 조사원님, 저게 정말 사람을 태워요?"}, {"s": null, "t": "나는 바깥에서는 말을 타고 먼 길을 간다고 했다. 마루가 입을 떡 벌렸다. 그 틈에 단이가 아이들 사이를 헤치고 나와 마구간 쪽으로 한 걸음 다가섰다. 마루가 단이의 약 상자 끈을 붙잡아 끌어당겼다."}, {"s": "q:sx_maru", "t": "가지 마! 저거한테 밟히면 셈이 하나 줄어!"}, {"s": null, "t": "단이가 마루의 손을 살짝 떼어 내며 말 쪽을 가리켰다."}, {"s": "q:g_dani", "t": "안 밟아요. 눈이 착해요. 저 눈 봐요."}, {"s": null, "t": "아이들이 옥신각신하는 사이 상쇠가 말 쪽을 흘끔거리며 다가왔다."}, {"s": "q:sx_sangsoe", "t": "사업 넷째 단계가 찼대. 바깥 조사원들이 투구며 곡괭이며 채집도를 넘겨줘서 마구간에 거래소에 의뢰 게시판까지 섰어. 저 짐승은 정청 마구간에서 배로 실어 왔고. 배에서 내릴 때 여울이 고삐를 잡았는데, 여울도 처음엔 다리가 후들거렸대."}, {"s": null, "t": "공터 한쪽 게시판 앞에서 붓을 들고 있던 여울이 그 말을 듣고 상쇠를 흘겨보았다."}, {"s": "q:g_yeoul", "t": "후들거린 거 아니야. 배가 흔들렸어."}, {"s": null, "t": "여울은 다시 게시판 쪽으로 돌아서서 첫 칸에 의뢰 글을 반듯하게 적었다."}, {"s": "q:g_yeoul", "t": "거래소가 섰으니 팔 물건이 있어야지. 섬에서 바깥 사람들이 탐낼 만한 건 거꾸로 향목이야. 거꾸로 선 사당에서만 나. 연기가 아래로 흐르는 향이라 바깥에선 귀해."}, {"s": "q:g_yeoul", "t": "그런데 사당 길목에 향로귀들이 눌러앉았어. 아래로 타는 연기를 두르고 길을 막아. 향목 캐러 간 사람들이 연기에 홀려 그 자리를 빙빙 돌다 왔대."}, {"s": null, "t": "여울이 게시판 첫 칸을 붓끝으로 짚었다. 「사당 길 터 주기. 향목 캐러 갈 길. 반요촌.」 글씨가 반듯했다."}, {"s": "q:g_yeoul", "t": "이게 섬 게시판 첫 의뢰야. 첫 의뢰는 아는 사람한테 맡기고 싶어. 사당 길목 향로귀를 좀 쳐 줘. 여섯이면 길이 트일 거야."}, {"s": null, "t": "마구간 안에서 말이 또 히이잉 울었다. 마루가 펄쩍 뛰며 내 등 뒤로 숨었다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_4', 2, '향목 한 짐', '뒤집힌 향로귀을(를) 물리친다', '{"at": ["banyo_village"], "tasks": [{"t": "win", "m": ["gw_shrine_2"], "n": 6}]}'::jsonb, '[{"s": null, "t": "사당 길목의 향로귀들을 흩어 놓고 돌아오니, 마구간 앞 풍경이 바뀌어 있었다. 단이가 말 코앞에 서서 손바닥을 펴 내밀고 있었다. 말이 단이의 손바닥에 코를 대고 킁킁거렸다."}, {"s": "q:g_dani", "t": "소금 냄새 맡나 봐요. 짠물댁이 준 소금을 쥐고 있었거든요. 하나도 안 무서워요. 코가 따뜻해요."}, {"s": null, "t": "아이들이 열 걸음에서 다섯 걸음까지 다가와 있었다. 마루는 여전히 내 등 뒤에 서서 고개만 빼꼼 내밀었다."}, {"s": "q:sx_maru", "t": "단이는 원래 겁이 없어요. 사당 천장에도 거꾸로 매달려 있었던 애예요."}, {"s": null, "t": "단이가 말 목을 쓰다듬다 말고 마루를 돌아보았다."}, {"s": "q:g_dani", "t": "매달린 거 아니에요. 거꾸로 선 사당이니까 천장이 바닥이었던 거예요."}, {"s": null, "t": "마루가 입을 삐죽이며 내 등 뒤로 도로 숨었다."}, {"s": null, "t": "거래소 앞에서는 상쇠가 빈 진열대 앞에서 팔짱을 끼고 있었다."}, {"s": "q:sx_sangsoe", "t": "길은 텄는데 향목이 한 바구니뿐이야. 거래소 첫 물건이 한 바구니면 체면이 안 서. 바깥 장터처럼 한 짐은 쌓아야지."}, {"s": null, "t": "게시판 앞에 있던 여울이 붓을 내려놓고 진열대 쪽으로 다가왔다."}, {"s": "q:g_yeoul", "t": "한 짐이면 사당 깊이 들어가서 며칠은 캐야 해. 바구니 들고 오가서는 안 돼."}, {"s": null, "t": "여울이 나를 보았다. 상쇠도 나를 보았다. 마루까지 내 등 뒤에서 나와 나를 올려다보았다."}, {"s": "q:sx_maru", "t": "원정이요. 조사원님은 원정 가면 짐을 한가득 들고 오시잖아요. 제가 셈해 봤는데요, 바구니로 열 번 오가는 것보다 원정 한 번이 빨라요."}, {"s": null, "t": "상쇠가 무릎을 탁 치며 맞장구를 쳤다."}, {"s": "q:sx_sangsoe", "t": "그래, 원정! 거꾸로 선 사당 원정 한 번만 다녀와 줘. 그동안 나는 값을 정해 놓을게."}, {"s": null, "t": "마루가 펄쩍 뛰며 두 손을 내저었다."}, {"s": "q:sx_maru", "t": "아저씨가 값을 정하시면 큰일 나요. 제가 정할게요."}, {"s": null, "t": "상쇠가 마루의 머리를 헝클며 껄껄 웃었다."}, {"s": "q:sx_sangsoe", "t": "둘이 같이 정하자!"}, {"s": null, "t": "단이가 말 목을 쓰다듬다가 내 쪽으로 고개를 돌렸다."}, {"s": "q:g_dani", "t": "{이름} 님 원정 다녀오시는 동안 저는 얘랑 친해져 있을게요. 돌아오시면 얘가 {이름} 님 냄새도 알 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_4', 3, '잔여 없음이 아니다', '거꾸로 선 사당에 원정을 다녀온다', '{"at": ["banyo_village"], "tasks": [{"t": "expedition", "r": ["inverted_shrine"], "n": 1}]}'::jsonb, '[{"s": null, "t": "원정에서 돌아오자 거래소 진열대 위에 거꾸로 향목이 한 짐 쌓였다. 향목 끝에 불을 붙여 보니 연기가 아래로 흘러 진열대 바닥에 뽀얗게 고였다. 구경하던 사람들이 「아」 하고 소리를 냈다."}, {"s": null, "t": "진열대 앞에서 상쇠와 마루가 머리를 맞대고 앉아 있었다. 상쇠가 손가락을 접었다 폈다 했고, 마루는 돌멩이로 땅바닥에 셈을 그렸다."}, {"s": "q:sx_sangsoe", "t": "한 묶음에 천 전!"}, {"s": null, "t": "마루가 돌멩이로 땅바닥을 톡톡 두드리며 고개를 저었다."}, {"s": "q:sx_maru", "t": "그럼 아무도 안 사요. 바깥 장터 값을 보니까 사백 전쯤이에요. 우리가 캐느라 수고했으니 조금 더 받아도 돼요. 사백오십 전이요."}, {"s": null, "t": "상쇠가 손가락을 접었다 폈다 하다가 물었다."}, {"s": "q:sx_sangsoe", "t": "사백오십. …이름값으로 치면 몇 번이야?"}, {"s": null, "t": "마루가 돌멩이를 내려놓고 단호하게 말했다."}, {"s": "q:sx_maru", "t": "이름값으로는 못 쳐요. 거래소는 전으로만 해요."}, {"s": null, "t": "상쇠가 머리를 긁적이며 붓을 들었다가 내려놓았다. 상쇠는 붓을 묵호에게 내밀었다."}, {"s": "q:sx_sangsoe", "t": "촌장님이 적어 주셔요. 섬 첫 거래소 값이잖아요."}, {"s": null, "t": "묵호가 붓을 받아 들고 진열대 앞 값표를 내려다보았다. 노인은 한동안 붓을 대지 않았다. 사람들이 숨을 죽이고 노인의 손을 보았다."}, {"s": "q:g_mukho", "t": "우리가 값을 매기는 게 처음은 아니지. 바깥이 우리 값을 먼저 매겼어. 「잔여 없음」. 남은 게 없다는 값일세. 이 섬 사람 다 그 값으로 실려 왔어."}, {"s": null, "t": "여울이 묵호 뒤에서 고개를 숙였다. 묵호는 돌아보지 않고 붓에 먹을 묻혔다."}, {"s": "q:g_mukho", "t": "오늘은 우리 손으로 우리 물건에 값을 매기는구먼. 남은 게 없다던 사람들이 바깥에 내다 팔 물건을 한 짐이나 쌓았어. …사백오십 전."}, {"s": null, "t": "묵호가 값표에 숫자를 적었다. 마루가 「셈 맞아요」 하고 작게 외쳤다. 상쇠는 코를 훌쩍이다가 크게 웃었다."}, {"s": null, "t": "해가 질 무렵 게시판 앞에서 거래소 장부를 들여다보던 여울이 장부를 번쩍 들어 올렸다. 짧게 끊던 목소리가 처음으로 높아졌다."}, {"s": "q:g_yeoul", "t": "팔렸어! 첫 묶음. 바깥에서 샀어. 누군지는 몰라. 섬 물건을 바깥에서 돈 주고 샀어."}, {"s": null, "t": "마구간에서 말이 히이잉 울었다. 이번에는 아이들이 도망가지 않았다. 단이가 말 목을 쓰다듬으며 나를 돌아보았다."}, {"s": "q:g_dani", "t": "{이름} 님, 얘 이름 지어 줘도 돼요? 바다 쪽에서 배 타고 왔으니까 「바닷말」이요. 이름을 불러 줘야 섬에 붙어 있대요."}, {"s": null, "t": "나는 좋은 이름이라고 했다. 단이가 말 귀에 대고 「바닷말」 하고 불렀다. 말이 귀를 쫑긋 세웠다."}, {"s": null, "t": "그날 밤 장터에서 상쇠의 노래가 넷째 소절로 넘어갔다. 「값을 매긴 첫 장날에, 잔여 없음 아니로다.」 마루가 곁에서 박자를 손가락으로 세다가, 이번에는 고치지 않고 따라 불렀다."}]'::jsonb, '{"gil": 400}'::jsonb)
