insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_gw_5', 'side', '뒷이야기·반요촌', '문패 없는 대장간', '반요촌 대장간이 바깥 대장간만큼 쇠를 다루게 된다. 묵호가 오늘 아직 기억하는 바깥 이름 한 글자를 쇠 문패에 새기고, 갈대 지붕마다 푸른 반요 등이 걸리는 낙성 밤에 맞이하는 노래가 다섯 소절까지 이어진다.', 'banyo_village', 50, '{mdq_17,ep_gw_4}'::text[], null, 1509, '[]'::jsonb, true, null, null)
