update public.world_quests set open_req = '{"project": "c:gwiheo", "stage": 5}'::jsonb where quest_id = 'ep_gw_5';
delete from public.world_quest_steps where quest_id = 'ep_gw_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_5', 1, '흑철을 다루는 손', '흑철을 다루는 손', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "그사이 바닷말은 아이들을 태우고 선창 공터를 한 바퀴씩 돌게 되었다. 거꾸로 향목은 장날마다 거래소에서 팔려 나갔다."}, {"s": null, "t": "반요촌 끝자락 대장간에서 땅, 땅, 망치 소리가 울렸다. 화덕 불이 활활 타올랐고, 모루 위에는 검게 번들거리는 쇳덩이가 올려져 있었다. 귀허 흑철이었다."}, {"s": null, "t": "대장장이 풀무가 비늘 덮인 맨손으로 흑철을 뒤집었다. 손등의 검은 비늘이 불빛에 번쩍였다."}, {"s": "q:sx_pulmu", "t": "조사원이구먼. 보게, 흑철이야. 예전엔 너무 세서 내 손으로는 못 다뤘지. 바깥 조사원들이 노리개며 탈이며 호패를 넘겨줘서 사업 다섯째 단계가 찼다더군. 그 몫으로 바깥 대장간 연장이 들어왔네. 이제 고치는 값도 바깥만큼이고, 되팔기도 바깥만큼일세."}, {"s": null, "t": "풀무가 망치를 내려놓고 대장간 기둥을 턱으로 가리켰다. 기둥에는 문패 대신 작은 나무패 하나가 걸려 있었다. 「풀무네」 세 글자였다."}, {"s": "q:sx_pulmu", "t": "이 대장간엔 문패가 없어. 마을 아낙들이 걸어 준 저 나무패뿐이지. 내 바깥 이름은 요기 따라 다 흐려졌거든. 위 칸에 쓸 게 없으니 문패를 못 달았네."}, {"s": null, "t": "대장간 문간에 묵호가 서 있었다. 노인은 손에 제 집 문패를 들고 있었다. 먹 글씨가 번진 나무 문패였다."}, {"s": "q:g_mukho", "t": "풀무, 부탁이 있어 왔네. 쇠 문패 하나 쳐 주게. 먹은 번지고 나무는 썩어. 쇠에 새기면 안 지워지겠지."}, {"s": null, "t": "묵호가 문패 위 칸을 손가락으로 짚었다. 번진 먹 사이로 글자 하나만 겨우 알아볼 만했다."}, {"s": "q:g_mukho", "t": "오늘 아침 짚어 보니 또렷한 건 한 글자뿐이더군. 나머지는 번졌다 돌아왔다 하네. 내일은 모르겠어. 그러니 오늘 새겨 두고 싶네. 한 글자라도."}, {"s": null, "t": "풀무가 망치 자루를 쥔 채 묵호를 오래 보았다. 자루 끝에 닳은 글자 두 개가 새겨져 있었다. 풀무의 스승 이름이었다."}, {"s": "q:sx_pulmu", "t": "…알겠네. 쇠에 새긴 이름은 안 흐려지지. 이 망치가 그래. 다만 흑철이 모자라. 문패 하나에 등 고리도 쳐야 하거든. 낙성 날 갈대 지붕마다 반요 등을 건다고 상쇠가 난리야."}, {"s": null, "t": "대장간 밖에서 상쇠의 목소리가 쩌렁쩌렁 울렸다."}, {"s": "q:sx_sangsoe", "t": "풀무! 등 고리 몇 개 됐어? 마루가 지붕이 서른둘이래!"}, {"s": null, "t": "풀무가 망치를 다시 쥐며 대장간 밖 쪽으로 턱짓을 했다."}, {"s": "q:sx_pulmu", "t": "들었지? 조사원, 귀허에 가서 흑철을 네 덩이만 캐다 주게. 섬 끝 바다 쪽에 흑철이 박힌 바위가 있어. 나는 이 불을 못 비우네."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_5', 2, '한 글자', '귀허에서 귀허 흑철을(를) 모은다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["gwiheo_iron"], "r": ["gwiheo_core"], "n": 4}]}'::jsonb, '[{"s": null, "t": "흑철 네 덩이를 모루 곁에 내려놓자 풀무가 그중 하나를 화덕에 넣었다. 쇳덩이가 시뻘겋게 달아오르자 풀무가 집게로 꺼내 모루 위에 올렸다. 망치가 땅, 땅, 땅 내리칠 때마다 쇠가 넓게 펴지며 손바닥만 한 판이 되었다."}, {"s": null, "t": "풀무가 판 가운데에 금을 그어 위 칸과 아래 칸을 나누었다. 그러고는 각인 끌을 묵호에게 내밀었다."}, {"s": "q:sx_pulmu", "t": "글자는 촌장이 새기게. 이름은 제 손으로 새기는 게 낫지. 망치는 내가 들어 주겠네."}, {"s": null, "t": "묵호가 끌을 받아 쥐고 위 칸에 끌 끝을 댔다. 노인의 손이 조금 떨렸다. 풀무가 망치로 끌 머리를 톡톡 두드렸다. 끌이 쇠를 파고들 때마다 쨍쨍 맑은 소리가 났다."}, {"s": null, "t": "한 글자가 다 새겨졌다. 묵호는 그 글자를 나에게도 보여 주지 않고 손바닥으로 덮었다. 노인은 입속으로 그 글자를 한 번 읽었다."}, {"s": "q:g_mukho", "t": "됐네. 이 글자는 내일도 여기 있겠지. 내가 잊어도."}, {"s": null, "t": "묵호가 끌을 아래 칸으로 옮겨 「묵호」 두 글자를 새겼다. 아래 칸 글자는 망설임 없이 쑥쑥 새겨졌다. 노인은 쇠 문패를 들어 화덕 불에 비춰 보았다."}, {"s": null, "t": "대장간 문간에 단이가 서 있었다. 단이는 문패를 보더니 대장간 기둥의 「풀무네」 나무패를 올려다보았다."}, {"s": "q:g_dani", "t": "풀무 아저씨는 문패 안 만들어요? 아저씨도 아래 칸 이름 있잖아요. 「풀무」요."}, {"s": null, "t": "풀무가 화덕에 숯을 밀어 넣다가 손을 멈추었다. 굵은 목소리가 조금 느려졌다."}, {"s": "q:sx_pulmu", "t": "위 칸이 비잖아. 빈 문패는 보기 싫어."}, {"s": null, "t": "단이가 고개를 갸웃하며 풀무를 올려다보았다."}, {"s": "q:g_dani", "t": "빈 칸도 괜찮대요. 갈대숲에 떠밀려 와서 제 이름을 못 떠올린 아저씨도 문패 아래 칸을 비워 뒀대요. 누가 와서 적어 줄지도 모른다고요. 위 칸 비워 두면, 아저씨 스승님이 와서 적어 주실지도 몰라요."}, {"s": null, "t": "풀무가 대답하지 않았다. 대장장이는 남은 흑철 한 덩이를 집어 화덕에 넣었다. 땅, 땅 망치 소리가 다시 울렸다. 이번에는 문패 하나만큼 쇠를 폈다."}, {"s": null, "t": "밖에서 상쇠가 대장간 문간으로 고개를 들이밀었다."}, {"s": "q:sx_sangsoe", "t": "문패는 문패고, 등은? 고리는 다 됐는데 등이 없어! 반요 등은 푸른 불이 나야 하는데, 섬 등잔은 노란 불만 나잖아."}, {"s": null, "t": "여울이 상쇠 뒤에서 다가와 대장간 처마를 올려다보았다."}, {"s": "q:g_yeoul", "t": "바깥 혼등이면 돼. 넋을 비추는 등이라 불이 푸르게 타. 장터 천막 둘에 하나씩 걸고, 나머지 지붕 등은 그 불을 옮겨 붙이면 돼. 혼등 두 개만 지어 줘."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_gw_5', 3, '맞이하는 노래', '혼등을(를) 만든다, 혼등을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["lt_lantern_6"], "n": 2}], "give": {"lt_lantern_6": 2}}'::jsonb, '[{"s": null, "t": "내가 건넨 혼등 두 개를 상쇠가 장터 천막 두 채 처마에 하나씩 걸었다. 혼등에서 푸른 불이 일렁였다. 마을 사람들이 등심을 대어 그 불을 옮겨 갔다. 갈대 지붕마다 풀무가 친 쇠고리에 반요 등이 하나씩 걸렸다."}, {"s": null, "t": "해가 지자 반요촌 갈대 지붕 서른둘 위로 푸른 불이 줄줄이 켜졌다. 검은 물길 위로 그 불빛이 길게 비쳤다. 섬 끝 말뚝 쪽에서 짠물댁이 탄 배가 그 불빛을 따라 들어오고 있었다."}, {"s": "q:sx_maru", "t": "서른둘이요. 하나도 안 빠졌어요. 아저씨, 이번엔 세지 마세요. 제가 다 셌어요."}, {"s": null, "t": "장터 한가운데 낙성 떡 시루가 열렸다. 김이 푸른 불빛에 물들어 하늘로 올라갔다. 단이가 떡을 접시에 담아 사람들에게 돌리다가 내 앞에 한 접시를 내밀었다."}, {"s": "q:g_dani", "t": "{이름} 님 몫이에요. 바깥 몫은 크게 썰었어요. 바깥에서 넘겨준 게 많으니까요."}, {"s": null, "t": "묵호가 제 집 문간에 쇠 문패를 걸었다. 쾅쾅 못 박는 소리가 장터까지 들렸다. 노인은 문패를 다 건 뒤 위 칸을 손가락으로 짚어 보지 않았다. 대신 아래 칸 「묵호」를 한 번 쓸고 장터로 돌아왔다."}, {"s": "q:g_mukho", "t": "오늘은 안 짚었네. 쇠에 새겼으니 내일 짚어도 되겠지."}, {"s": null, "t": "대장간 기둥에도 쇠 문패 하나가 새로 걸려 있었다. 위 칸은 비어 있었고, 아래 칸에 「풀무」 두 글자가 새겨져 있었다. 「풀무네」 나무패는 그 문패 아래 그대로 매달려 있었다. 풀무는 화덕 앞에 앉아 그 문패를 한 번도 올려다보지 않았지만, 망치를 드는 손이 평소보다 느긋했다."}, {"s": null, "t": "여울이 장부를 펴고 「반요촌 주민 명부」 맨 끝에 새 줄을 적었다. 「대장간. 풀무.」 붓을 내려놓은 여울이 그 줄을 오래 보았다."}, {"s": "q:g_yeoul", "t": "이 명부, 처음엔 「잔여 없음」을 지우려고 쓰기 시작했어. 오늘은 그냥 적고 싶어서 적었어. 대장간이 생겼으니까. 마을에 생긴 걸 적는 거, 원래 서리 일이 이거였어."}, {"s": null, "t": "장터 한가운데에서 상쇠가 목청을 가다듬었다. 사람들이 하나둘 노래를 따라 부르기 시작했다. 지금까지 지은 다섯 소절이 처음으로 한 번에 이어졌다."}, {"s": "q:sx_sangsoe", "t": "바깥 물건 왔구나, 좌판 둘이 더 섰구나. 검은 물길 건너온 손, 등불 들고 맞자꾸나. 맡길 데가 생겼구나, 두고 가도 남는구나. 값을 매긴 첫 장날에, 잔여 없음 아니로다. 쇠에 새긴 이름 한 자, 불러 주면 남는구나."}, {"s": null, "t": "마지막 소절이 끝나자 아무도 말하지 않았다. 상쇠가 두 손을 허리에 짚고 마루를 내려다보았다."}, {"s": "q:sx_sangsoe", "t": "마루야, 몇 소절이야?"}, {"s": null, "t": "마루가 손가락 다섯을 다 펴 들고 폴짝 뛰었다."}, {"s": "q:sx_maru", "t": "다섯이요. 처음으로 맞았어요, 아저씨."}, {"s": null, "t": "상쇠가 코끝을 손등으로 쓱 문지르고 씩 웃었다."}, {"s": "q:sx_sangsoe", "t": "다섯이라. …끝은 아직이야. 맞을 사람이 또 오면 또 붙일 거거든."}, {"s": null, "t": "짠물댁이 선창에서 올라오며 「밑지는 장사 아니네」 하고 중얼거렸다. 배웅 노래밖에 없던 섬에서, 그날 밤 맞이하는 노래가 처음으로 다섯 소절까지 불렸다."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_lotus_1', 'side', '뒷이야기·십삼문 암시장', '비어 버린 서가', '맡아 둔 이름을 모두 돌려준 뒤 열세 번째 문 안쪽 장부방의 회원 장부 서가가 텅 비었다. 장부지기 구슬이 그 자리에 무엇을 꽂을지 셈을 못 하는 사이, 이름을 돌려받은 늙은 회원 끝순이 「이름은 돌아왔는데 골무가 어디로 갔나」 하며 장부방을 찾아온다.', 'hidden_bazaar', 50, '{mdq_17}'::text[], null, 1510, '[]'::jsonb, true, null, null)
