update public.world_quests set open_req = '{"project": "f:black_lotus", "stage": 1}'::jsonb where quest_id = 'ep_lotus_1';
delete from public.world_quest_steps where quest_id = 'ep_lotus_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_1', 1, '셈이 안 서는 서가', '셈이 안 서는 서가', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "십삼문 암시장은 낮에도 등을 켜 두었다. 열두 개의 문을 지나 골목 끝 열세 번째 문 앞에 이르자, 좌판 장수들이 외치는 소리가 등 뒤에서 웅웅 멀어졌다."}, {"s": null, "t": "문 앞 좌판에 못 보던 단지 둘이 새로 올라와 있었다. 한 단지에는 「어둠 눈 약」, 다른 단지에는 「무광 가오리찜」이라고 쓴 종이가 붙어 있었다. 가오리찜 단지 뚜껑 틈으로 매큼한 냄새가 솔솔 새어 나왔다."}, {"s": null, "t": "열세 번째 문 안쪽은 구슬의 장부방이었다. 방 한쪽 벽을 차지한 서가는 천장에 닿을 만큼 높았는데, 칸마다 먼지 자국만 네모나게 남아 있었다."}, {"s": null, "t": "구슬은 그 서가 앞에 주판을 안고 서 있었다. 손가락이 주판알 위에서 몇 번 들썩였지만, 알은 하나도 움직이지 않았다."}, {"s": "black_lotus:guseul", "t": "어머, 조사원님. 손님한테 이런 꼴을 보여 드리면 안 되는데요. 장부지기가 서가 앞에서 주판도 못 튕기고 서 있는 꼴이요.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:guseul", "t": "우리 회원님 오셨네요. 장부지기가 서가 앞에서 주판도 못 튕기고 서 있는 꼴은 식구한테만 보여 드리는 거예요.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": null, "t": "나는 서가가 왜 비었냐고 물었다. 구슬이 맨 위 칸부터 맨 아래 칸까지 천천히 눈으로 훑었다."}, {"s": "black_lotus:guseul", "t": "여기가 회원 장부 자리였어요. 식구들이 들어올 때 맡긴 이름을 적어 두던 장부요. 회주님이 금고를 열고 이름을 다 돌려주신 날, 저도 여기 사본을 한 장씩 지웠거든요. 다 지우고 나니 장부가 장부가 아니라서 내렸어요."}, {"s": "black_lotus:guseul", "t": "빚 장부는 아래 칸에 그대로 있어요. 빚은 돌려주는 게 아니라 받는 거니까요. 그런데 빚 장부만 꽂으면 이 서가의 사 할도 안 차요."}, {"s": null, "t": "구슬이 주판을 옆구리에 끼고 빈 칸 하나에 손바닥을 넣어 보았다. 손을 빼자 손바닥에 먼지가 하얗게 묻어났다."}, {"s": "black_lotus:guseul", "t": "우리 장부고 넓히기가 첫 단계를 넘긴 건 아세요? 여러 조사원님들이 봉인 먹이며 황지며 원령재를 실어다 주셔서 첫 칸이 찼어요. 문 앞 좌판에 단지 둘이 새로 선 것도 그 덕이에요."}, {"s": "black_lotus:guseul", "t": "어둠 눈 약은 장부지기들 눈 버리지 말라고 들였어요. 가오리찜은… 회주님이 드시고 싶다 하셔서요."}, {"s": null, "t": "구슬이 그 말을 하다가 저도 모르게 쿡 웃었다. 웃음은 금방 걷히고, 구슬의 눈이 다시 빈 서가로 돌아갔다."}, {"s": "black_lotus:guseul", "t": "그런데 넓히기만 하면 뭐해요. 넓힌 데 뭘 꽂을지를 모르는데. 소문 장부를 꽂을까, 물건 장부를 꽂을까, 셈을 해 봐도 답이 안 나와요."}, {"s": null, "t": "나는 무엇을 꽂든 새 장부를 맬 종이와 먹부터 있어야 하지 않느냐고 했다. 구슬이 눈을 깜빡이더니 주판알 하나를 탁 올렸다."}, {"s": "black_lotus:guseul", "t": "맞아요. 적을 게 정해지기 전에 종이부터 마련해 두는 게 장부지기 일이죠. 제가 그걸 잊고 있었네요."}, {"s": "black_lotus:guseul", "t": "등잔골 뒷골목 담 밑에 먹정이 굴러다니고, 버려진 기름집 다락에 묵은 황지가 쌓여 있어요. 등잔 그을음이 앉은 황지라 먹이 잘 먹어요. 셋씩만 주워다 주세요. 그동안 저는 이 빈 칸이나 세고 있을게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_1', 2, '골무', '등잔골 뒷골목에서 먹정을(를) 모은다, 등잔골 뒷골목에서 황지을(를) 모은다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "gather", "items": ["inkstone"], "r": ["lamp_alley"], "n": 3}, {"t": "gather", "items": ["seal_paper"], "r": ["lamp_alley"], "n": 3}]}'::jsonb, '[{"s": null, "t": "먹정과 황지를 꾸려 장부방에 돌아오니, 빈 서가 앞에 낯선 할멈 하나가 서 있었다. 허리가 반쯤 굽은 할멈은 손가락마다 놋골무를 끼고 있었다."}, {"s": null, "t": "할멈은 서가의 빈 칸을 하나하나 골무 낀 손끝으로 톡톡 두드려 보았다. 구슬은 책상 앞에서 그 모습을 지켜보다가 내가 들어오자 손짓했다."}, {"s": "black_lotus:guseul", "t": "조사원님, 이분이 골무 할머니세요. 암시장 버선 가게를 마흔 해 하셨어요. 손님 발 치수를 한 번 보면 안 잊으세요."}, {"s": null, "t": "할멈이 골무 낀 손을 내저으며 나를 돌아보았다. 웃는 입에 이가 듬성듬성했다."}, {"s": "q:sx_ep_kkeutsun", "t": "골무는 무슨. 이제 끝순이유, 끝순. 회주님이 이름을 돌려주셨으니 끝순이라고 불러 줘요."}, {"s": null, "t": "끝순은 그렇게 말해 놓고 서가 쪽으로 다시 몸을 돌렸다. 빈 칸에 넣은 손이 한참 나오지 않았다."}, {"s": "q:sx_ep_kkeutsun", "t": "그런데 장부지기, 내 이름 적혔던 장부가 정말 없어진 거유? 돌려받은 날은 좋아서 버선을 밤새 기웠는데, 며칠 지나니까 속이 허해. 마흔 해를 여기 어디 적혀 있다가 갑자기 아무 데도 안 적힌 것 같아서."}, {"s": null, "t": "구슬의 주판을 쥔 손이 멈췄다. 구슬은 대답을 고르듯 입술을 몇 번 달싹였다."}, {"s": "black_lotus:guseul", "t": "할머니 이름은 명등청 명부에 다 올라 있어요. 정청 서리님들이 한 줄도 안 빼고 칸까지 그었대요."}, {"s": "q:sx_ep_kkeutsun", "t": "그건 아는데. 거기엔 끝순, 나이, 십삼문 그렇게만 적혔다며. 여기선 내가 버선 기우는 골무였는데. 이름은 돌아왔는데 골무가 어디로 갔나 싶어서 그래요."}, {"s": null, "t": "구슬이 끝순을 오래 보았다. 그러다 내가 책상 위에 내려놓은 황지 꾸러미로 눈길을 옮겼다."}, {"s": null, "t": "나는 끝순에게, 이름 곁에 골무였다는 것까지 함께 적어 두면 어떻겠냐고 물었다. 끝순이 눈을 둥그렇게 떴다."}, {"s": "q:sx_ep_kkeutsun", "t": "이름 곁에? 그런 장부도 있수?"}, {"s": "black_lotus:guseul", "t": "…없어요. 없으니까 만들면 되죠."}, {"s": null, "t": "구슬이 주판을 책상에 탁 내려놓았다. 장부방에 들어선 뒤로 처음 듣는 단단한 목소리였다."}, {"s": "black_lotus:guseul", "t": "맡아 두는 장부 말고 곁에 적어 두는 장부요. 이름은 주인이 갖고, 우리는 그 곁에 그 사람이 누구였는지를 적어 두는 거예요. 값은 안 받고요."}, {"s": "black_lotus:guseul", "t": "예전에 지맥의 뿌리 갱에서 채굴 감독님한테 그런 말을 한 적이 있어요. 먹으로 적은 글자만으로는 이름이 오래 못 버틴다고요. 그 사람이 누구였는지 곁에 얹어 둬야 글자가 사람으로 남는다고요. 그래 놓고 정작 제 장부에는 그걸 한 번도 안 적었네요."}, {"s": "black_lotus:guseul", "t": "조사원님, 주워 오신 먹정이랑 황지로 봉인 먹을 좀 지어 주세요. 요기 결정은 한 알씩만 섞으시면 돼요. 흑련 장부 먹은 봉인 먹이어야 백 년을 가요. 정식 장부는 장부고가 다 넓혀진 뒤에 매고, 오늘은 낱장 한 장에 먼저 할머니 줄을 적어 볼게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_1', 3, '낱장 한 장', '봉인 먹을(를) 만든다, 봉인 먹을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "craft", "items": ["sealing_ink"], "n": 3}], "give": {"sealing_ink": 3}}'::jsonb, '[{"s": null, "t": "지은 봉인 먹을 건네자 구슬이 벼루에 먹을 갈았다. 먹이 사르르 풀리며 장부방에 쌉쌀한 냄새가 번졌다."}, {"s": null, "t": "끝순은 책상 맞은편에 앉아 골무 낀 손을 무릎에 모으고 있었다. 구슬이 황지 한 장을 펴고 붓을 들자, 끝순이 저도 모르게 허리를 폈다."}, {"s": "black_lotus:guseul", "t": "불러 주세요, 할머니. 적을게요."}, {"s": "q:sx_ep_kkeutsun", "t": "뭘 불러. 나 같은 거 뭐 적을 게 있다고."}, {"s": null, "t": "끝순은 손사래를 치다가, 구슬이 붓을 든 채 기다리자 헛기침을 했다."}, {"s": "q:sx_ep_kkeutsun", "t": "끝순. 일흔둘. 버선 가게. …마흔 해 동안 암시장 사람 발 치수는 다 외웠수. 막쇠 발은 열한 치 반, 장부지기 발은 일곱 치. 회주님 발은 끝내 못 재 봤고."}, {"s": null, "t": "구슬이 웃음을 참으며 그대로 받아 적었다. 붓끝이 황지 위를 또박또박 눌러 갔다."}, {"s": null, "t": "황지 위에 「끝순 · 십삼문 · 골무 · 마흔 해 버선을 기움 · 암시장 사람 발 치수를 다 외움」이 적혔다. 구슬이 마지막 획을 긋고 붓을 내려놓았다."}, {"s": null, "t": "구슬이 마른 낱장을 들어 빈 서가 맨 가운데 칸에 세웠다. 텅 빈 서가에 종이 한 장이 기대 서자, 서가가 오히려 더 넓어 보였다."}, {"s": "q:sx_ep_kkeutsun", "t": "에구, 저 큰 데 나 혼자 꽂혀 있으니 쑥스럽네."}, {"s": "black_lotus:guseul", "t": "혼자 오래 두진 않을게요. 장부고가 넓혀지는 대로 식구들 줄을 다 받을 거예요. 할머니가 첫 손님이니까 이자는 없어요."}, {"s": null, "t": "끝순이 그 말에 깔깔 웃었다. 웃다가 골무 낀 손등으로 눈가를 꾹 눌렀다."}, {"s": null, "t": "구슬이 서랍에서 작은 약병 하나를 꺼내 끝순의 손에 쥐여 주었다. 문 앞 좌판에서 본 「어둠 눈 약」이었다."}, {"s": "black_lotus:guseul", "t": "이건 장부지기 몫인데 할머니 드릴게요. 밤마다 버선 기우시느라 눈이 짓무르셨잖아요."}, {"s": "q:sx_ep_kkeutsun", "t": "장부지기 몫을 왜 날 줘."}, {"s": "black_lotus:guseul", "t": "할머니 줄 적는 것도 이제 장부지기 일이니까요."}, {"s": null, "t": "끝순이 약병을 품에 넣고 돌아간 뒤, 구슬이 빈 서가 앞에 다시 섰다. 주판을 쥔 손가락이 이번에는 알을 하나 올렸다."}, {"s": "black_lotus:guseul", "t": "한 장. …셈이 이제 시작됐네요. 조사원님, 장부고가 다 넓혀지면 이 서가가 다 찰 거예요. 그때 또 와 주세요. 저 혼자 세기엔 칸이 너무 많아요."}, {"s": null, "t": "그때 장부방 바닥의 계단 아래에서 낮은 목소리가 울려 올라왔다. 땅 밑 장부고 금고 쪽이었다."}, {"s": "black_lotus:mumyeong", "t": "장부지기. 그 낱장, 나중에 올라가서 나도 읽어 보겠소."}, {"s": null, "t": "구슬이 계단 쪽으로 고개를 숙였다. 서가 한가운데의 낱장은 등불 아래에서 조금 기운 채 그대로 서 있었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_lotus_2', 'side', '뒷이야기·십삼문 암시장', '숫자로 부르던 사람', '채무 추적자 여섯째가 열 해 묵은 빚을 받으러 등잔골 뒷골목에 간다. 빚 장부에는 「서른하나」라는 숫자만 있고, 회주는 이번부터 빚도 이름으로 받아 오라 했다. 숫자로 부르면 문이 열리지 않는다.', 'hidden_bazaar', 50, '{mdq_17,ep_lotus_1}'::text[], null, 1511, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:black_lotus", "stage": 2}'::jsonb where quest_id = 'ep_lotus_2';
delete from public.world_quest_steps where quest_id = 'ep_lotus_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_2', 1, '서른하나', '서른하나', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "그사이 장부방 서가 가운데 칸에는 낱장이 열댓 장으로 늘어 있었다. 낱장마다 다른 손으로 누른 엄지 도장이 찍혀 있었다."}, {"s": null, "t": "책상 옆 벽에는 여섯째가 등을 대고 서 있었다. 검은 옷을 입은 말 없는 사내였다. 왼손 손등에 점 여섯이 새겨져 있었는데, 그 가운데 하나는 지워져 있었다."}, {"s": null, "t": "여섯째는 빚 장부 한 권을 펴 든 채 한 줄을 손가락으로 짚고 움직이지 않았다. 구슬이 나를 보고 한숨 섞인 웃음을 지었다."}, {"s": "black_lotus:guseul", "t": "조사원님, 오셨어요? 여섯째 씨가 아침부터 저 줄 하나를 안 넘기고 있어요."}, {"s": "black_lotus:six", "t": "…손님. 마침.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:six", "t": "…식구. 마침.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": null, "t": "여섯째가 장부를 내 쪽으로 돌렸다. 짚고 있던 줄에는 「서른하나 · 등잔골 · 심지 값 · 열 해」라고만 적혀 있었다."}, {"s": "black_lotus:six", "t": "서른하나. 열 해. 이자는 첫 해에 끊었다. 남은 건 원금."}, {"s": "black_lotus:guseul", "t": "흑련 빚 장부는 이름을 안 적어요. 빚쟁이도 숫자로 적고, 받으러 가는 사람도 숫자로 불렀거든요. 식구들 이름은 회원 장부가 지키고, 빚 장부는 숫자만 세면 됐으니까요."}, {"s": "black_lotus:guseul", "t": "그런데 이제 회원 장부가 없잖아요. 회주님이 이번 빚부터는 이름으로 받아 오라 하셨어요. 숫자로 남의 문을 두드리는 건 정리소가 하던 짓이라고요."}, {"s": null, "t": "여섯째의 손가락이 줄 위에서 조금 굽었다. 나는 여섯째에게 서른하나의 이름을 아느냐고 물었다."}, {"s": "black_lotus:six", "t": "모른다. 열 해 동안 서른하나였다. …나도 열 해 동안 여섯째였고."}, {"s": null, "t": "구슬이 주판알을 한 줄 내렸다가 다시 올렸다. 여섯째가 장부를 탁 덮었다."}, {"s": "black_lotus:six", "t": "간다. 그 집 골목은 등잔 그늘이 깊다. 소매치기귀가 끓는다. 문 앞까지 가는 길부터 쓸어야 한다."}, {"s": "black_lotus:guseul", "t": "등잔골은 요새 좀 나아졌어요. 사업이 둘째 단계를 넘기고 나서 우리가 골목 어귀에 탕약 솥을 걸고, 소식꾼들 좌판도 다시 세웠거든요. 여러 조사원님들이 넘겨준 영사랑 수귀 비늘 몫이에요. 다친 사람은 솥 앞에서 약 한 사발 얻어 마시면 되고, 사람을 찾을 땐 좌판에 물으면 돼요."}, {"s": "black_lotus:guseul", "t": "그래도 그늘은 그늘이에요. 조사원님, 여섯째 씨랑 같이 가 주세요. 여섯째 씨는 빚은 잘 받는데 길은 못 쓸어요. 사람을 숫자로만 세서 그런지, 귀신은 셀 줄을 모르더라고요."}, {"s": null, "t": "여섯째가 구슬을 흘끗 보았다. 대꾸는 하지 않았지만, 문간에서 나를 기다리는 걸음이 여느 때보다 느렸다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_2', 2, '닫힌 문', '등잔 그늘 소매치기귀을(를) 물리친다', '{"at": ["lamp_alley"], "tasks": [{"t": "win", "m": ["r71_lamp_2"], "n": 6}]}'::jsonb, '[{"s": null, "t": "등잔골 뒷골목은 이름대로 처마마다 등잔이 걸린 골목이었다. 소매치기귀들이 그늘에서 사라지자, 기름 냄새 밴 골목에 등잔불이 고르게 흔들렸다."}, {"s": null, "t": "골목 어귀에는 구슬의 말대로 커다란 탕약 솥이 걸려 있었다. 다리를 저는 짐꾼 하나가 솥 앞에서 약 사발을 후후 불어 마셨다. 맞은편 좌판에서는 젊은 소식꾼이 쪽지 다발을 늘어놓고 손님을 불렀다."}, {"s": null, "t": "여섯째가 골목 맨 끝 낮은 문 앞에 섰다. 문틈으로 삼 실 꼬는 냄새가 새어 나왔고, 안쪽에서 누가 콜록콜록 기침을 했다."}, {"s": null, "t": "여섯째가 주먹으로 문을 쿵, 쿵 두 번 두드렸다."}, {"s": "black_lotus:six", "t": "서른하나."}, {"s": null, "t": "안쪽의 기침이 뚝 멎었다. 누군가 문짝에 몸을 기대는 소리가 쿵 났다."}, {"s": "q:sx_ep_gaprye", "t": "없어! 서른하나 같은 거 여기 없어! 흑련 사람이면 돌아가. 열 해 전 그 숫자는 죽었어!"}, {"s": null, "t": "여섯째가 주먹을 든 채 그대로 굳었다. 나는 여섯째에게 이름으로 불러 보라고 했다. 여섯째가 나를 돌아보았다."}, {"s": "black_lotus:six", "t": "…모른다니까."}, {"s": null, "t": "여섯째가 다시 문을 보았다. 손등의 지워진 점 자리를 엄지로 문지르는 손이 조금 빨라졌다."}, {"s": "black_lotus:six", "t": "서른하나라고 부르면 저 사람은 빚쟁이가 된다. 빚쟁이는 문을 안 연다. 그건 열 해 동안 셌다. 이름으로 부르면… 모르겠다. 그건 세어 본 적이 없다."}, {"s": null, "t": "문 안쪽에서 노파가 다시 소리쳤다. 목소리는 사나웠지만 끝이 갈라져 있었다."}, {"s": "q:sx_ep_gaprye", "t": "심지 값은 갚을 거야. 갚을 거라고! 그러니 그 숫자로 내 문 두드리지 마!"}, {"s": null, "t": "소리친 끝에 노파가 콜록콜록 기침을 터뜨렸다. 기침은 한참 그치지 않았다."}, {"s": null, "t": "여섯째가 문에서 한 걸음 물러섰다. 여섯째는 아무 말 없이 골목 어귀의 좌판 쪽을 보았다."}, {"s": "black_lotus:six", "t": "좌판. 사람 찾을 땐 좌판에 물으라 했다."}, {"s": null, "t": "좌판 앞에 서자 소식꾼이 쪽지 다발을 부채처럼 펼쳐 들고 우리를 보았다. 손목에 흑련 검은 끈을 맨 젊은이였다."}, {"s": "q:sx_ep_sosik", "t": "추적자님이 소식을 사러 오셨네요. 골목 끝 할머니요? 저도 이름은 몰라요. 그 할머니는 이 골목에서 「심지 할멈」으로만 불렸거든요."}, {"s": "q:sx_ep_sosik", "t": "이름을 아는 사람은 오래 산 사람들뿐일 거예요. 골목 안쪽 집들을 돌며 물어보세요. 문 닫힌 집도, 버려진 집도요. 옛날 사람들은 문설주에 식구 이름을 새기기도 했으니까요."}, {"s": null, "t": "여섯째가 고개를 끄덕이고 나를 보았다. 무엇을 부탁하는 사람의 얼굴은 처음 보는 것 같았다."}, {"s": "black_lotus:six", "t": "…찾아 줘라. 나는 셀 줄만 안다. 찾는 건 못 한다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_2', 3, '처음 부른 이름', '등잔골 뒷골목에서 실마리를 찾는다', '{"at": ["lamp_alley"], "tasks": [{"t": "clue", "r": ["lamp_alley"], "n": 1}]}'::jsonb, '[{"s": null, "t": "실마리는 골목 안쪽 버려진 기름집 문설주에 있었다. 칼끝으로 긁은 글자 둘이 그을음에 덮여 있었는데, 소매로 문지르자 「갑례」가 드러났다. 그 아래에 작은 글씨로 「심지 꼬는 집 막내딸」이 새겨져 있었다."}, {"s": null, "t": "해가 지고 골목에 밤이 내려앉았다. 여섯째는 낮은 문 앞에 서서 한참 숨을 골랐다. 문을 두드리려던 주먹을 펴서, 손바닥을 문짝에 가만히 댔다."}, {"s": "black_lotus:six", "t": "…갑례."}, {"s": null, "t": "여섯째의 입김이 흩어지지 않았다. 하얀 입김이 가느다란 금빛 실로 엉기더니, 처마 등잔불보다 환하게 반짝이며 문틈으로 스르르 스며들었다."}, {"s": null, "t": "실이 지나간 문짝 나뭇결에 온기가 남았다. 여섯째는 문에 댄 손을 떼지 못한 채 제 입가를 내려다보았다. 금빛이 제 입에서 나갔다는 것을 믿지 못하는 얼굴이었다."}, {"s": null, "t": "문 안쪽에서 무언가 툭 떨어지는 소리가 났다. 빗장이 끼익 풀리고 문이 반 뼘 열렸다."}, {"s": null, "t": "하얗게 센 머리의 노파가 문틈으로 얼굴을 내밀었다. 노파는 한 손으로 제 가슴께를 꼭 누르고 있었다."}, {"s": "q:sx_ep_gaprye", "t": "…방금 누가 날 불렀어? 그 이름, 누가 불렀어?"}, {"s": "black_lotus:six", "t": "내가."}, {"s": "q:sx_ep_gaprye", "t": "흑련 추적자가? 그 이름 부르던 사람은 다 갔는데. 서방도, 어머니도, 기름집 식구들도. 열 해 동안 다들 심지 할멈이라고만 했어."}, {"s": null, "t": "갑례의 손이 가슴께에서 떨렸다. 금빛 실이 닿은 자리였다. 여섯째는 대답 대신 빚 장부를 꺼내 펼쳤다."}, {"s": "black_lotus:six", "t": "갑례. 심지 값. 열 해. 원금만."}, {"s": "q:sx_ep_gaprye", "t": "…못 갚아. 돈이 없어. 기침 때문에 심지도 하루에 열 가닥밖에 못 꼬아."}, {"s": null, "t": "여섯째가 장부를 든 채 나를 보았다. 나는 장부고가 넓혀지면 등잔이 많이 걸릴 거라고 했다. 등잔마다 심지가 들 거라고 했다. 여섯째가 장부로 눈을 내렸다."}, {"s": "black_lotus:six", "t": "…심지 삼백 가닥. 장부고 등잔 몫. 그걸로 원금."}, {"s": "q:sx_ep_gaprye", "t": "삼백? 그게 다야? 열 해 묵은 빚인데?"}, {"s": "black_lotus:six", "t": "이자는 첫 해에 끊었다. 구슬이 그랬다."}, {"s": null, "t": "여섯째가 품에서 붓을 꺼내 그 줄에 먹을 쭉 그었다. 줄 끝에 「심지로 갚음」을 덧붙이고, 「서른하나」 옆에 「갑례」 두 글자를 서툴게 적었다."}, {"s": null, "t": "갑례가 장부의 서툰 글씨를 오래 내려다보다가 여섯째를 올려다보았다."}, {"s": "q:sx_ep_gaprye", "t": "당신은 이름이 뭐야. 내 이름을 불렀으니 나도 당신 이름 하나 불러야 셈이 맞지."}, {"s": null, "t": "여섯째의 입이 열렸다가 닫혔다. 손등의 지워진 점 자리를 엄지로 한 번 쓸었다."}, {"s": "black_lotus:six", "t": "…장부에서 돌아왔다. 아직 입에 안 붙었다. 붙으면 그때 오겠다. 심지 받으러."}, {"s": null, "t": "갑례가 피식 웃으며 문을 활짝 열었다. 방 안 가득 걸린 심지 다발이 처마 등잔불에 누렇게 빛났다."}, {"s": "q:sx_ep_gaprye", "t": "그럼 그때까진 여섯째 양반이라고 부르지 뭐. 들어와. 심지는 오늘부터 꼴 테니까 차라도 한잔하고 가. 둘 다."}, {"s": null, "t": "여섯째가 문턱을 넘으며 빚 장부를 품에 넣었다. 뒤에서 보니 장부를 넣는 손이 조금 느렸다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_lotus_3', 'side', '뒷이야기·십삼문 암시장', '하수도 옛 물길', '장부고 넓히기 셋째 단계로 장부고 아래에서 연등 하수도·만인장으로 가는 옛 짐꾼 물길이 다시 트인다. 흑련 문지기 막쇠·두례·막동이와 함께 깜깜한 물길 둑에 검은 연꽃 등을 걸러 내려간다.', 'hidden_bazaar', 50, '{mdq_17,ep_lotus_2}'::text[], null, 1512, '[]'::jsonb, true, null, null)
