update public.world_quests set open_req = '{"project": "f:black_lotus", "stage": 3}'::jsonb where quest_id = 'ep_lotus_3';
delete from public.world_quest_steps where quest_id = 'ep_lotus_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_3', 1, '셋째 둑', '셋째 둑', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "그사이 장부방 처마 밑에는 갑례가 꼰 심지 다발이 수북이 쌓였다. 구슬은 심지 다발을 세다 말고 나를 장부방 바닥 계단 쪽으로 이끌었다."}, {"s": null, "t": "계단을 반 층 내려가자 땅 밑 장부고로 가는 길목 옆에 낮은 돌문 하나가 열려 있었다. 문 너머에서 찬 물 냄새가 훅 끼쳐 올라왔고, 졸졸 물 흐르는 소리가 멀리까지 이어졌다."}, {"s": null, "t": "돌문 앞에는 흑련 문지기 셋이 등짐을 지고 서 있었다. 막쇠는 칼집째 쥔 칼을 지팡이처럼 짚고 있었고, 두례는 등짐 끈을 쥔 손을 꼼지락거렸다."}, {"s": null, "t": "막동이는 돌문 위 이끼 낀 글씨를 손가락으로 짚으며 소리 내어 읽고 있었다."}, {"s": "q:sx_md_makdong", "t": "「셋째 둑 · 연등 · 만인」. 조사원님, 여기 이렇게 써 있어요! 셋째 둑으로 가면 연등 하수도고, 더 가면 만인장이래요!"}, {"s": "black_lotus:guseul", "t": "옛날 흑련 짐꾼들이 다니던 물길이에요. 장부랑 물건을 정청 눈 피해 나르던 길이요. 둑이 무너지고 물이 막혀서 마흔 해 넘게 아무도 안 다녔어요."}, {"s": "black_lotus:guseul", "t": "사업이 셋째 단계를 넘기고 나서 막힌 데를 다 텄어요. 여러 조사원님들이 넘겨준 회생 부적이랑 결계 파편으로 무너진 둑을 받쳤고요. 이제 십삼문에서 연등 하수도까지 땅 위로 돌아가지 않아도 되고, 노정패도 안 들어요."}, {"s": "black_lotus:guseul", "t": "다만 물길이 깜깜해요. 짐꾼들이 다니려면 둑마다 등을 걸어야 해요."}, {"s": null, "t": "두례가 돌문 안쪽 어둠을 들여다보다가 어깨를 움찔했다."}, {"s": "q:sx_md_durye", "t": "깜깜한 정도가 아니에요. 아까 막쇠 씨랑 셋째 둑까지 가 봤는데, 물 위에 뭐가 둥둥 떠다녀요. 등잔 그림자 같은 거요. 그림자가 혼자 떠다니면 안 되잖아요. 그건 안 되는 거잖아요, 조사원님."}, {"s": "q:sx_md_maksoe", "t": "말 많다."}, {"s": "q:sx_md_durye", "t": "무서우니까 많은 거예요!"}, {"s": null, "t": "막쇠가 짧게 혀를 차고 등짐을 추슬렀다. 등짐 안에서 검은 종이로 접은 연꽃 등들이 바스락거렸다."}, {"s": "q:sx_md_maksoe", "t": "연꽃 등이 스물. 둑이 스물. 기름은 없다."}, {"s": "black_lotus:guseul", "t": "그게 문제예요. 등은 접었는데 기름을 못 구했어요. 연등 하수도 물길 벽 틈에 등롱 어유가 고여 있다니까, 내려가는 길에 좀 모아 주세요. 등 하나에 어유 반 종지면 사흘은 가요."}, {"s": "q:sx_md_makdong", "t": "그럼 저희가 앞장설게요! 글씨는 제가 읽을게요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_3', 2, '장부는 머리에', '연등 하수도에 간다, 연등 하수도에서 등롱 어유을(를) 모은다', '{"at": ["lotus_sewer"], "tasks": [{"t": "travel", "r": ["lotus_sewer"], "n": 1}, {"t": "gather", "items": ["lantern_oil"], "r": ["lotus_sewer"], "n": 4}]}'::jsonb, '[{"s": null, "t": "연등 하수도 물길은 생각보다 넓었다. 돌로 쌓은 둑 위로 둘이 나란히 걸을 수 있었고, 둑 아래로는 거무스름한 물이 쿨렁쿨렁 흘렀다."}, {"s": null, "t": "벽 틈에서 등롱 어유를 긁어 모으는 동안, 막동이는 둑마다 새겨진 옛 짐꾼 글씨를 읽었다. 두례는 내 등 뒤에 바짝 붙어 다녔다."}, {"s": "q:sx_md_makdong", "t": "「여기서 쉬어 감」. 「물 불면 위로」. 「장부는 젖지 않게 머리에」. …머리에요? 장부를 머리에 이고 다녔나 봐요!"}, {"s": "q:sx_md_durye", "t": "그러니까 옛날 사람들도 무서웠던 거예요. 장부를 머리에 이고 깜깜한 데를 걸었으니까요. 저도 지금 머리에 뭐라도 이고 싶어요."}, {"s": null, "t": "셋째 둑에 이르자 둑 아래 물에서 등잔 그림자 몇이 어유 냄새를 맡고 기어올랐다. 막쇠가 칼집째 휘두르자 그림자들이 첨벙첨벙 물로 떨어졌다."}, {"s": "q:sx_md_maksoe", "t": "기름. 다 모았나."}, {"s": null, "t": "내가 어유 단지를 내보이자 막쇠가 고개를 끄덕이고 등짐을 풀었다. 검은 종이 연꽃 등 스무 개가 둑 위에 줄지어 놓였다."}, {"s": null, "t": "연꽃 등은 겉은 검고 안쪽은 흰 종이로 덧대어 있었다. 불을 넣으면 검은 꽃잎 사이로 흰빛이 샐 것 같았다."}, {"s": "q:sx_md_makdong", "t": "근데 등에 넣을 등잔이 없어요. 기름만 있고 그릇이 없어요."}, {"s": null, "t": "두례가 막동이를 보고, 막쇠가 두례를 보았다. 셋이 한꺼번에 나를 보았다."}, {"s": "q:sx_md_durye", "t": "…조사원님. 등잔 지을 줄 아시죠? 황지에 어유 먹여서 만드는 거요. 저희는 칼만 들 줄 알아서요. 막쇠 씨는 칼도 칼집째 들고요."}, {"s": "q:sx_md_maksoe", "t": "시끄럽다."}, {"s": null, "t": "막쇠가 제 등짐에서 황지 한 묶음을 꺼내 내게 내밀었다. 구슬이 미리 챙겨 넣은 모양이었다."}, {"s": "q:sx_md_maksoe", "t": "셋. 우선 셋. 첫째 둑, 셋째 둑, 끝 둑."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_3', 3, '끄지 않는 등', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["lotus_sewer"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 3}], "give": {"fish_oil_lamp": 3}}'::jsonb, '[{"s": null, "t": "지은 어유 등잔을 연꽃 등에 하나씩 넣자, 검은 꽃잎 사이로 흰빛이 새어 나왔다. 막쇠가 그 등을 첫째 둑 쇠고리에 걸었다."}, {"s": null, "t": "등 하나가 켜지자 물길 벽이 처음으로 제 모양을 드러냈다. 둑을 따라 벽돌마다 짐꾼들의 손자국이 거뭇하게 남아 있었고, 물 위에는 흰 꽃잎 같은 빛이 흔들렸다."}, {"s": "q:sx_md_makdong", "t": "우와… 연꽃이 물에 떠 있는 것 같아요. 흑련이라서 검은 연꽃인 줄 알았는데, 불을 넣으니까 흰 연꽃이네요."}, {"s": "q:sx_md_durye", "t": "그러게. 이제 하나도 안 무서워요. …아니, 조금 덜 무서워요."}, {"s": null, "t": "셋째 둑에도 등을 걸고 끝 둑에 이르자, 물길 저 끝에 만인장 쪽으로 오르는 돌계단이 희미하게 보였다. 두례가 계단을 보다가 막쇠의 소매를 잡아당겼다."}, {"s": "q:sx_md_durye", "t": "막쇠 씨, 저 계단으로 짐꾼들이 올라간 거예요? 그런 걸 어떻게 알아요?"}, {"s": "q:sx_md_maksoe", "t": "장부고 어른들이 그랬다. 짐꾼은 머리에 장부, 손에 등."}, {"s": null, "t": "막쇠가 마지막 등을 끝 둑 쇠고리에 걸려다 말고, 한 뼘 낮은 고리로 옮겨 걸었다. 두례의 눈높이였다."}, {"s": "q:sx_md_durye", "t": "…막쇠 씨, 일부러 낮게 건 거죠?"}, {"s": "q:sx_md_maksoe", "t": "키 작은 게 자꾸 넘어지니까."}, {"s": null, "t": "두례가 입을 삐죽 내밀었다. 그래도 낮게 걸린 등 아래를 지날 때는 한 번도 넘어지지 않았다."}, {"s": null, "t": "셋째 둑으로 돌아와 짐을 내리고 둑에 걸터앉았다. 두례가 품에서 마른 떡을 꺼내 넷으로 갈라 나눠 주었다. 막동이는 떡을 오물거리면서도 벽 글씨를 계속 읽었다."}, {"s": "q:sx_md_makdong", "t": "「돌아갈 땐 등을 끄지 말 것. 뒤에 오는 사람 몫」. …조사원님, 저희 등 안 끄고 가도 되는 거죠?"}, {"s": null, "t": "나는 막동이에게 등을 끄지 말고 가자고 했다. 그 대신 구슬에게 등잔이 열일곱 개 더 필요하다고 전하자고 했다. 막동이가 손가락을 꼽다가 고개를 끄덕였다."}, {"s": "q:sx_md_makdong", "t": "열일곱 개. 제가 외울게요. 소리 내서 외우면 안 까먹어요. 열일곱, 열일곱, 열일곱."}, {"s": "q:sx_md_maksoe", "t": "그만 외워라. 귀에 박혔다."}, {"s": null, "t": "돌아오는 길, 등 셋이 켜진 물길은 오던 길보다 짧게 느껴졌다. 뒤를 돌아보니 흰 연꽃 같은 불빛 셋이 검은 물 위에 나란히 떠 있었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_lotus_4', 'side', '뒷이야기·십삼문 암시장', '검은 서가', '장부방 위로 볕 드는 다락이 새로 올라가고, 그 방에 들일 검은 서가를 짠다. 목수 대패는 새 나무 대신 땅 밑 장부고의 빈 맡김 서가를 뜯어 쓰자 하고, 회주 무명이 그 판자를 제 손으로 떼어 놓아준 뒤 처음으로 볕 아래에 앉는다.', 'hidden_bazaar', 50, '{mdq_17,ep_lotus_3}'::text[], null, 1513, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:black_lotus", "stage": 4}'::jsonb where quest_id = 'ep_lotus_4';
delete from public.world_quest_steps where quest_id = 'ep_lotus_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_4', 1, '볕 드는 다락', '볕 드는 다락', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "그사이 장부방 위로 다락 한 층이 새로 올라갔다. 암시장 지붕 밑을 터서 낸 방이었다. 동쪽 벽에 낸 들창으로 볕이 비스듬히 들어와 마룻바닥에 네모를 그렸다."}, {"s": null, "t": "새 방 한가운데에서 흑련 목수 대패가 대팻날을 갈고 있었다. 머리에 대팻밥을 뒤집어쓴 사내는 나무 토막을 집을 때마다 코부터 갖다 대 킁킁 냄새를 맡았다."}, {"s": null, "t": "들창 아래에서는 구슬과 끝순이 검은 비단을 재고 있었다. 끝순이 골무 낀 손으로 천을 접으면, 구슬이 그 길이를 장부에 적었다."}, {"s": "black_lotus:guseul", "t": "조사원님, 올라와 보세요. 장부고가 이만큼 넓어졌어요. 볕 드는 장부방은 흑련 생기고 처음일걸요.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:guseul", "t": "회원님, 올라와 보세요. 우리 장부고가 이만큼 넓어졌어요. 흑련 식구가 볕 드는 데서 장부를 펴는 건 처음일걸요.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": "black_lotus:guseul", "t": "사업이 넷째 단계를 넘겼어요. 여러 조사원님들이 넘겨준 비단 부적낭이며 응축 영핵 몫으로 비고에 새 물건 둘을 들이게 됐고요. 하나는 이 방에 짜 넣을 검은 서가를 줄여 짠 장부지기 서가, 하나는 할머니가 짓고 계신 장부지기 토시예요."}, {"s": "q:sx_ep_kkeutsun", "t": "장부 넘기다가 소매 닳지 말라고 끼는 거유. 장부지기 소매가 맨날 반질반질해서, 내가 보다 못해 짓는 거지."}, {"s": null, "t": "대패가 대팻날을 내려놓고 나를 보았다. 입에 물고 있던 나무 부스러기를 퉤 뱉었다."}, {"s": "q:sx_ep_daepae", "t": "서가는 내가 짜는데 나무가 없소. 새 나무는 냄새가 너무 생생하오. 장부는 오래 묵은 나무 냄새 속에 있어야 안 뒤틀리오."}, {"s": "black_lotus:guseul", "t": "그래서 생각했어요. 땅 밑 장부고 금고 앞에 맡김 장부를 꽂던 서가가 있잖아요. 이름을 다 돌려주고 나서 텅 빈 채로 서 있는 서가요. 그걸 뜯어 올려서 새로 짜면 어떨까 해서요."}, {"s": null, "t": "구슬이 그 말을 하며 방바닥의 계단 쪽을 보았다. 금고로 내려가는 계단이었다."}, {"s": "q:sx_ep_kkeutsun", "t": "그 서가 판자면 내 이름도 거기 꽂혀 있었겠네. 마흔 해를 같이 산 나무유."}, {"s": null, "t": "끝순이 골무 낀 손으로 천을 쓰다듬다 말고 계단 쪽을 오래 보았다."}, {"s": "black_lotus:guseul", "t": "회주님께 여쭸더니 그러라고 하셨어요. 대신 판자를 뜯을 때 회주님도 보시겠대요. 그 서가는 회주님이 회주가 되신 날부터 지키신 거라서요."}, {"s": "q:sx_ep_daepae", "t": "판자는 무겁고, 아래 장부고엔 요즘 또 먹 낀 것들이 기어 다니오. 장부 찢는 손이니 먹 거인이니. 판자를 뜯어 올리는 동안 그것들을 좀 막아 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_4', 2, '날짜만 새긴 판자', '흑련 장부고에 원정을 다녀온다', '{"at": ["ledger_cellar"], "tasks": [{"t": "expedition", "r": ["ledger_cellar"], "n": 1}]}'::jsonb, '[{"s": null, "t": "원정을 다녀오는 동안 대패와 짐꾼들이 맡김 서가의 판자를 한 장씩 뜯어 계단 위로 올려 보냈다. 금고 앞 서가 틀에는 맨 아래 칸 판자 한 장만 붙어 남았다."}, {"s": null, "t": "금고 문 앞에는 무명이 앉아 있었다. 키가 작고 허리가 굽은 노인이 검은 천을 머리까지 덮어쓰고, 먹 줄이 수없이 그어진 두 손을 무릎에 얹고 있었다."}, {"s": "black_lotus:mumyeong", "t": "조사원. 판자 지는 일까지 시켜서 미안하구려.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:mumyeong", "t": "식구가 왔구려. 판자 지는 일은 식구끼리 하는 일이니, 미안하다는 말은 안 하겠소.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": null, "t": "대패가 마지막 판자에 쇠지레를 대자 무명이 손을 들었다. 대패가 지레를 멈췄다."}, {"s": "black_lotus:mumyeong", "t": "그 판자는 내가 떼겠소."}, {"s": null, "t": "무명이 지팡이를 짚고 일어섰다. 무명이 판자 뒷면을 손으로 더듬자, 칼로 긁은 작은 글씨들이 드러났다. 날짜 몇 개가 위아래로 새겨져 있었다."}, {"s": null, "t": "나는 무명에게 그 날짜들이 무엇이냐고 물었다. 무명이 손끝으로 날짜 하나를 쓸었다."}, {"s": "black_lotus:mumyeong", "t": "회주가 바뀐 날들이오. 회주가 되는 사람은 그날 제 이름을 금고에 맡기고, 이 서가 맨 아래 칸 판자 뒤에 날짜만 새기오. 이름은 안 새기고."}, {"s": "black_lotus:mumyeong", "t": "맨 위 날짜는 칠십 년 전이오. 그날 맡긴 이름은 없소. 첫 회주는 맡길 이름도 없이 물길로 나왔으니까."}, {"s": null, "t": "무명이 맨 위 날짜 곁의 빈자리를 오래 쓸었다. 나는 그 자리의 주인이 누구인지 알았다. 맹약 마당으로 가기 전, 무명이 여운비에게 들려준 이름이었다."}, {"s": "black_lotus:mumyeong", "t": "내 이름 장은 이 판자에 있지 않소. 금고 맨 안쪽, 내가 펴지 않는 장에 있소. 이 판자는 날짜만 지켰지. …그러니 이제 놓아주어도 되오."}, {"s": null, "t": "무명이 손바닥으로 판자를 한 번 밀었다. 오래 박혀 있던 못이 끼기긱 빠지며 판자가 그의 손 안으로 내려왔다."}, {"s": "q:sx_ep_daepae", "t": "회주님, 날짜는 대패로 밀어 버릴까요? 새로 짜면 뒷면은 아무도 안 볼 텐데요."}, {"s": "black_lotus:mumyeong", "t": "밀지 마시오. 새 서가 뒤판으로 쓰시오. 안 보이는 데 있어야 하는 것도 있소."}, {"s": null, "t": "대패가 판자를 받아 들고 코를 갖다 댔다. 칠십 년 묵은 나무 냄새에 대패가 눈을 지그시 감았다."}, {"s": "q:sx_ep_daepae", "t": "좋은 냄새요. 이걸로 짜면 장부가 백 년은 편하겠소. 다만 검게 칠을 올려야 하는데 칠액이 모자라오. 흑련 서가는 칠액에 봉인 먹을 풀어 검게 올리는 법이오. 칠액 세 단지만 지어 주시겠소?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_4', 3, '볕 아래의 손', '칠액을(를) 만든다, 칠액을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "craft", "items": ["lacquer"], "n": 3}], "give": {"lacquer": 3}}'::jsonb, '[{"s": null, "t": "대패가 칠액에 봉인 먹을 풀어 바르자, 묵은 판자 위로 검은 칠이 번들번들 올라앉았다. 칠이 마르는 사흘 동안 새 방에는 송진과 먹 냄새가 가득 찼다."}, {"s": null, "t": "나흘째 아침, 들창 아래 벽에 검은 서가 하나가 섰다. 칸마다 칠이 거울처럼 매끄러웠다. 맨 가운데 칸에는 끝순의 낱장을 비롯해 그사이 모인 낱장들이 가지런히 꽂혔다."}, {"s": null, "t": "구슬이 서가 앞에 등받이가 낮은 나무 의자 하나를 내다 놓았다. 계단 쪽에서 지팡이 짚는 소리가 탁, 탁 올라왔다."}, {"s": null, "t": "무명이 계단을 다 올라와 새 방 문턱에서 멈춰 섰다. 들창으로 든 볕이 의자 위에 네모나게 내려앉아 있었다."}, {"s": "black_lotus:guseul", "t": "회주님, 여기 앉으세요. 회주님 자리예요. 금고 앞 말고요."}, {"s": "black_lotus:mumyeong", "t": "…내 자리는 문 앞이오. 문 안쪽이든 바깥쪽이든."}, {"s": "black_lotus:guseul", "t": "그러니까 이 방 문 앞이에요. 이 방도 이제 장부고잖아요."}, {"s": null, "t": "무명이 한참 서 있다가 의자에 앉았다. 볕이 검은 천 위로 쏟아졌다. 무명이 천 밖으로 내민 두 손이 볕 한가운데 놓였다."}, {"s": null, "t": "먹 줄이 그어진 손등 위로 볕이 고였다. 무명은 손을 뒤집었다가 다시 뒤집으며 손바닥과 손등에 번갈아 볕을 받았다."}, {"s": "black_lotus:mumyeong", "t": "따뜻하구려. 회주가 된 뒤로 볕에 손을 대 본 적이 없소. 장부는 볕을 보면 바래니까, 장부를 지키는 손도 볕을 안 봐야 한다고 배웠지."}, {"s": null, "t": "나는 무명에게 이제 장부는 칠을 올린 서가에 있다고 했다. 서가가 볕을 막아 주니 손은 볕을 봐도 된다고 했다. 무명이 검은 천 아래에서 낮게 웃었다."}, {"s": "black_lotus:mumyeong", "t": "그대는 셈이 빠르구려. 구슬보다 빠르오."}, {"s": "black_lotus:guseul", "t": "회주님, 그건 셈이 아니라 핑계예요. 그 핑계를 만든 건 의자를 갖다 놓은 저고요."}, {"s": null, "t": "끝순이 다 지은 토시 한 켤레를 들고 무명 앞으로 갔다. 검은 비단에 연잎 무늬를 박은 토시였다."}, {"s": "q:sx_ep_kkeutsun", "t": "회주님, 이건 비고에 들일 거 말고 하나 더 지은 거유. 회주님 발 치수는 끝내 못 쟀는데, 손목은 오늘 쟀어요. 볕 쬐시느라 손을 내놓고 계시니까."}, {"s": null, "t": "무명이 토시를 받아 손목에 꼈다. 볕 아래에서 검은 토시가 반들반들 빛났다."}, {"s": "black_lotus:mumyeong", "t": "잘 맞는구려. 손목 치수를 잰 사람은 그대가 처음이오, 끝순."}, {"s": null, "t": "끝순이 「끝순」이라는 말에 골무 낀 손으로 입을 가렸다. 웃음인지 울음인지 모를 소리가 손 틈으로 새어 나왔다."}, {"s": null, "t": "대패가 서가 앞에 서서 칸을 하나하나 두드려 보았다. 통, 통, 맑은 소리가 났다."}, {"s": "q:sx_ep_daepae", "t": "비고에 들일 작은 서가는 남은 판자로 짜겠소. 뒤판에 날짜는 안 넣소. 날짜 든 판자는 이 서가 하나뿐이어야 하오."}, {"s": null, "t": "무명은 대답하지 않았다. 의자에 앉은 채 고개를 조금 들어 들창 밖 하늘을 보았다. 볕이 검은 천 가장자리를 하얗게 비추었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_lotus_5', 'side', '뒷이야기·십삼문 암시장', '연잎 장부 무늬', '넓힌 장부고가 다 지어진 날, 암시장 골목 처마마다 검은 연꽃 등이 걸리고 새 장부의 낱장들이 줄에 널린다. 낙성 밤을 새우며 장부지기 구슬이 새 장부 첫 장에 무엇을 적을지 정한다.', 'hidden_bazaar', 50, '{mdq_17,ep_lotus_4}'::text[], null, 1514, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:black_lotus", "stage": 5}'::jsonb where quest_id = 'ep_lotus_5';
delete from public.world_quest_steps where quest_id = 'ep_lotus_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_5', 1, '줄에 널린 장부', '줄에 널린 장부', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "장부고가 다 지어지는 날, 십삼문 암시장 골목 처마마다 검은 연꽃 등이 걸렸다. 막쇠와 두례가 사다리를 붙잡고, 막동이가 사다리 위에서 등을 하나씩 올려 걸었다."}, {"s": null, "t": "흰빛이 새는 검은 꽃잎이 골목 끝 열세 번째 문까지 줄지어 이어졌다. 처마와 처마 사이에는 새끼줄이 가로질러 걸렸고, 줄마다 새 장부의 낱장들이 집게에 물려 팔랑거렸다."}, {"s": null, "t": "구슬은 열세 번째 문 앞에서 그 줄들을 올려다보며 주판을 안고 있었다. 빈 서가 앞에서 셈이 안 선다던 날과 달리, 구슬의 얼굴은 들떠 있었다."}, {"s": "black_lotus:guseul", "t": "조사원님! 오늘 낙성이에요. 오늘은 손님도 식구 자리에 앉으셔야 해요. 흑련 낙성 떡은 손님이라고 덜 주는 법이 없어요.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:guseul", "t": "회원님! 오늘 낙성이에요. 식구 자리는 맨 앞이에요. 떡은 제가 셀게요.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": "black_lotus:guseul", "t": "사업이 다섯째 단계까지 다 찼어요. 여러 조사원님들이 넘겨준 처용탈이며 월광 정수며, 다 셈하면 장부 한 권이 넘어요. 그 몫으로 처마 등을 다 달았고, 골목 깃발에 연잎 장부 무늬를 놓았어요."}, {"s": null, "t": "구슬이 골목 어귀 깃대를 가리켰다. 검은 깃발 한가운데, 펼친 장부 위로 연잎 한 장이 덮인 무늬가 수놓여 있었다."}, {"s": null, "t": "나는 줄에 널린 낱장들이 무엇이냐고 물었다. 구슬이 줄 하나를 손끝으로 톡 건드렸다."}, {"s": "black_lotus:guseul", "t": "식구들이 불러 주고 간 줄이에요. 먹이 마르면 묶을 거예요. 그런데 묶기 전에 하나가 남았어요. 새 장부 첫 장이요. 장부는 첫 장이 그 장부가 뭔지 말해 주거든요."}, {"s": "black_lotus:guseul", "t": "빚 장부 첫 장엔 「첫 손님 이자 없음」이 적혀 있어요. 회원 장부 첫 장엔 회주님들 날짜가 있었고요. 새 장부 첫 장엔… 아직 모르겠어요. 오늘 밤 안에 정하려고요."}, {"s": null, "t": "나는 첫 장만은 정제 황지로 하자고 했다. 낱장들보다 오래가야 하니까 좋은 종이를 쓰자고 했다. 구슬이 고개를 끄덕였다."}, {"s": "black_lotus:guseul", "t": "좋아요. 정제 황지 세 장만 구해다 주세요. 첫 장이랑 겉장 둘이요."}, {"s": "black_lotus:guseul", "t": "첫 장 먹은 흑련 먹으로 쓰고 싶어요. 밀수 부두 물에 먹빛 노래미가 올라오는데, 그놈 먹물로 지은 먹이 옛날 흑련 장부 먹이었대요. 부두에서 줄을 몇 번만 드리워 주세요. 먹은 제가 지을게요."}, {"s": "q:sx_md_maksoe", "t": "떡 상 차릴 기름은 내가."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_5', 2, '낙성 상', '십삼문 암시장에서 낚시를 한다, 정제 황지을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "fish", "r": ["hidden_bazaar"], "n": 3}], "give": {"fine_paper": 3}}'::jsonb, '[{"s": null, "t": "정제 황지와 먹빛 노래미를 건네자, 구슬이 황지를 장부방 책상 위에 반듯하게 펴 두고 노래미를 들고 부엌으로 갔다. 아무것도 적지 않은 황지 위로 처마 등 불빛이 어른거렸다."}, {"s": null, "t": "해가 지자 열세 번째 문 앞 골목에 상이 길게 차려졌다. 상 위에는 낙성 떡과 무광 가오리찜이 놓였고, 갑례가 꼰 심지로 켠 등잔이 군데군데 불을 밝혔다."}, {"s": null, "t": "갑례는 여섯째 맞은편에 앉아 기침 사이사이 떡을 뜯었다. 끝순은 떡 접시를 돌리면서 사람들 발치를 흘끔거렸다."}, {"s": "q:sx_ep_kkeutsun", "t": "저 젊은 소식꾼 발이 여덟 치 반이네. 버선 하나 지어 줘야겠어."}, {"s": "q:sx_ep_gaprye", "t": "할멈은 낙성 날에도 남의 발만 보우?"}, {"s": "q:sx_ep_kkeutsun", "t": "당신은 낙성 날에도 심지만 꼬잖아."}, {"s": null, "t": "두 노파가 서로 흘겨보다가 동시에 웃음을 터뜨렸다. 막동이가 떡을 입에 문 채 그 소리에 따라 웃었다."}, {"s": null, "t": "여섯째는 떡 하나를 손에 쥔 채 먹지 않고 있었다. 갑례가 여섯째의 손등을 톡 쳤다."}, {"s": "q:sx_ep_gaprye", "t": "여섯째 양반. 이름 아직 입에 안 붙었수?"}, {"s": "black_lotus:six", "t": "…아직."}, {"s": "q:sx_ep_gaprye", "t": "그럼 내가 기다리지 뭐. 심지 값 다 갚을 때까지는 기다려 줄게."}, {"s": null, "t": "여섯째가 떡을 한 입 베어 물었다. 무엇을 셀 때처럼 천천히 씹었다."}, {"s": null, "t": "상 맨 끝, 열세 번째 문 문턱에는 무명이 앉아 있었다. 손목에 끝순이 지은 검은 토시를 끼고 있었다. 무명은 떡을 무릎에 올려 둔 채 골목의 등과 줄에 널린 낱장들을 오래 보았다."}, {"s": "black_lotus:mumyeong", "t": "장부를 바람에 널어 말리는 날이 오는구려. 흑련 장부는 늘 금고 안에서 말렸소. 남의 눈에 띄면 안 되니까."}, {"s": "black_lotus:guseul", "t": "이건 눈에 띄라고 너는 거예요, 회주님. 식구들이 지나가다 제 줄을 보라고요."}, {"s": null, "t": "두례가 떡을 들고 줄 아래를 지나다가 발돋움을 했다. 낱장 하나를 올려다보더니 막쇠를 돌아보았다."}, {"s": "q:sx_md_durye", "t": "막쇠 씨! 막쇠 씨 줄이에요. 「막쇠 · 문지기 · 칼을 칼집째 쥠 · 말이 없음」. …이거 누가 불러 줬어요? 막쇠 씨가 직접 불렀어요?"}, {"s": "q:sx_md_maksoe", "t": "…네가 불렀잖아."}, {"s": "q:sx_md_durye", "t": "아, 맞다."}, {"s": null, "t": "밤이 깊어 상을 치운 뒤에도 구슬은 장부방 책상 앞에 앉아 있었다. 노래미 먹물로 지은 먹이 벼루에 까맣게 고여 있었지만, 정제 황지는 여전히 비어 있었다. 구슬이 나를 돌아보았다."}, {"s": "black_lotus:guseul", "t": "조사원님, 오늘 밤 장부고에 있어 주세요. 첫 장 정하는 거, 혼자 하면 또 셈만 하다 날이 샐 것 같아요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_lotus_5', 3, '첫 장', '십삼문 암시장에서 쉰다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "rest", "r": ["hidden_bazaar"], "n": 1}]}'::jsonb, '[{"s": null, "t": "밤이 깊도록 구슬은 붓을 들었다 놓았다 했다. 나는 장부방 문간에 앉아 그것을 지켜보았다. 바깥 골목에서는 처마 등이 하나둘 기름을 다해 가며 깜빡였다."}, {"s": "black_lotus:guseul", "t": "조사원님. 흑련은 이제 뭐 하는 데예요? 이름을 맡아 주는 데였는데, 이름을 다 돌려줬어요. 빚 받는 데라고 하기엔… 여섯째 씨가 요새 빚을 심지로 받아 와요."}, {"s": null, "t": "나는 구슬에게 오늘 줄에 널린 낱장들이 무엇이었냐고 되물었다. 구슬이 들창 밖의 줄을 보았다."}, {"s": "black_lotus:guseul", "t": "식구들 줄이요. 이름이랑, 그 곁에 그 사람이 누구였는지요. 골무, 심지, 문지기, 짐꾼…"}, {"s": null, "t": "구슬의 목소리가 거기서 멎었다. 구슬이 바닥의 계단 쪽, 땅 밑 금고가 있는 쪽을 한참 내려다보았다."}, {"s": "black_lotus:guseul", "t": "흑련은 처음부터 그런 데였네요. 첫 회주님이 이름 잃은 사람들을 모아서, 이름 대신 지켜 준 데. 이름을 맡아 준 건, 그 사람이 누구였는지를 지켜 주려던 거였어요. 글자만 지키려던 게 아니라요."}, {"s": null, "t": "구슬이 붓에 먹을 듬뿍 묻혔다. 이번에는 손이 멈추지 않았다."}, {"s": null, "t": "정제 황지 첫 장 맨 위에 「여사온」 세 글자가 적혔다. 그 곁으로 「북령 종지기 · 종을 울려 이름을 잃음 · 이름 잃은 이들을 모아 흑련을 세움 · 흑련 첫 회주」가 이어졌다."}, {"s": null, "t": "그 아래 줄들은 비어 있었다. 구슬이 붓끝으로 둘째 줄을 가리켰다."}, {"s": "black_lotus:guseul", "t": "둘째 줄부터는 식구들이에요. 셋째 줄도, 넷째 줄도요. 맨 끝 줄은 비워 둘 거예요. 맨 끝은 늘 다음 사람 자리니까요."}, {"s": null, "t": "계단 아래에서 지팡이 소리가 올라왔다. 무명이 문간에 서서 첫 장을 내려다보았다. 무명은 오래 말이 없다가 검은 천 아래에서 숨을 길게 내쉬었다."}, {"s": "black_lotus:mumyeong", "t": "…첫 회주 이름을 흑련 장부 맨 앞에 적었구려. 금고 맨 안쪽이 아니라."}, {"s": "black_lotus:guseul", "t": "회주님 줄도 적어 드릴까요? 이름은 안 적고, 곁에만요."}, {"s": null, "t": "무명이 고개를 저으며 손을 들었다. 토시 낀 손목이 등불에 반들거렸다."}, {"s": "black_lotus:mumyeong", "t": "내 곁에 적을 말은 아직 모르겠구려. 정해지면 내가 직접 말하리다. 그때까진 「문 앞에 앉던 사람」이면 되오."}, {"s": null, "t": "구슬이 웃으며 맨 끝 줄 바로 위에 작은 글씨로 「문 앞에 앉던 사람」이라고 적었다. 이름 칸은 비워 두었다."}, {"s": null, "t": "새벽빛이 들창으로 들어올 무렵, 구슬이 첫 장을 들고 골목으로 나가 처마 줄 맨 앞 집게에 물렸다. 검은 연꽃 등 아래에서 첫 장이 바람에 팔랑였다."}, {"s": "black_lotus:guseul", "t": "조사원님 줄은 다음에 받을게요. 그 줄은 조사원님이 직접 불러 주셔야 하니까요. 제가 대신 셈하면 반은 틀릴 거예요."}, {"s": null, "t": "구슬이 주판을 두 손으로 들어 알을 한 번에 쭉 내렸다. 다 내린 주판은 처음부터 다시 셀 수 있었다."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mandate_1', 'side', '뒷이야기·무극 관성대', '이어 붙일 별 기록', '열 해 동안 말을 하지 않던 태사령 하후정이 비어 버린 천명원 별 기록을 잇자고 한다. 수석 관측관 서이연이 열 해 동안 밤마다 몰래 적어 둔 쪽지 상자를 내놓는다.', 'star_observatory', 50, '{mdq_17}'::text[], null, 1515, '[]'::jsonb, true, null, null)
