update public.world_quests set open_req = '{"project": "f:mandate_court", "stage": 1}'::jsonb where quest_id = 'ep_mandate_1';
delete from public.world_quest_steps where quest_id = 'ep_mandate_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_1', 1, '날짜만 있는 장', '날짜만 있는 장', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "무극 관성대 아래 돌계단 어귀에 별 깃발 하나가 새로 꽂혀 있었다. 남색 천에 은실로 수놓은 국자별 일곱이 밤바람에 펄럭펄럭 나부꼈다."}, {"s": null, "t": "계단 아래 상점 앞에는 관측생들이 몰려 있었다. 상점 주인이 화로에 청새치를 올리고 영초 차를 끼얹을 때마다 치이익 소리와 함께 달큰한 냄새가 퍼졌다. 시렁 맨 앞에는 처음 보는 맑은 비약 병이 줄지어 있었다."}, {"s": null, "t": "문을 지키던 관상감 수직 운해가 나를 알아보고 창을 벽에 기대 세웠다."}, {"s": "q:bl_unhae", "t": "{등급}님, 오셨습니까. 깃발 보셨지요? 우리 사업 첫 단계가 찼습니다.", "fac": "mandate_court", "spec": 1, "grp": 1}, {"s": "q:bl_unhae", "t": "조사원님, 오셨습니까. 깃발 보셨지요? 천명원 사업 첫 단계가 찼습니다.", "fac_not": "mandate_court", "spec": 2, "grp": 1}, {"s": "q:bl_unhae", "t": "여러 조사원님이 정제 황지며 부적실이며 운면을 넘겨주신 덕에 상점에 청명 비약하고 청새치 별빛구이가 들어왔습니다. 관측생들은 벌써 저 냄새에 넋이 나갔고요."}, {"s": null, "t": "나는 그래서 다들 상점 앞에 모여 있느냐고 물었다. 운해가 고개를 젓고 관성대 꼭대기를 올려다보았다."}, {"s": "q:bl_unhae", "t": "그것도 그렇지만, 오늘은 다른 일입니다. 태사령께서 조사원님을 찾으셨습니다. …석판이 아니라 말씀으로요."}, {"s": null, "t": "운해는 「말씀으로요」에 힘을 주고는 앞장서 계단을 올랐다. 서고 안쪽 탁자에 천명원 별 기록 책이 펼쳐져 있었다. 태사령 하후정이 그 앞에 지팡이를 세워 두고 앉아 있었고, 기밀 사관 문서진이 곁에 꼿꼿이 서 있었다."}, {"s": null, "t": "펼쳐진 장에는 날짜만 줄줄이 적혀 있었다. 날짜 아래 칸은 모두 비어 있었다. 문서진이 장을 넘기자 다음 장도, 그다음 장도 그랬다."}, {"s": "mandate_court:mun", "t": "열 해 전 동지 무렵부터 이렇습니다. 천명원 별 기록은 태사령께서 하늘을 읽어 부르시면 사관이 받아 적는 법입니다. 부르지 않으신 밤은 적을 수가 없었습니다."}, {"s": null, "t": "하후정이 빈 장 위에 마른 손을 펴 얹었다. 노인의 목에서 쉰 소리가 몇 번 긁히듯 새어 나온 뒤에야 말이 되었다."}, {"s": "mandate_court:hahu", "t": "…열 해가 비었다. 잇자."}, {"s": null, "t": "문서진의 눈썹이 아주 조금 움직였다. 문서진은 탁자 끝을 손가락으로 짚었다."}, {"s": "mandate_court:mun", "t": "무엇으로 잇습니까. 기록은 정확해야 합니다. 열 해 전 하늘을 지금의 기억으로 부르실 수는 없습니다."}, {"s": null, "t": "그때 서고 문이 삐걱 열렸다. 수석 관측관 서이연이 낡은 찻상자 하나를 두 팔로 안고 들어왔다. 뚜껑 틈으로 누렇게 바랜 종이 귀퉁이가 비죽비죽 삐져나와 있었다."}, {"s": "mandate_court:seo", "t": "이걸로 이으시면 돼요."}, {"s": null, "t": "서이연이 상자를 탁자에 내려놓고 뚜껑을 열었다. 손바닥만 한 황지 쪽지가 상자 가득 차곡차곡 쌓여 있었다. 쪽지마다 날짜와 별자리가 깨알 같은 글씨로 적혀 있었다."}, {"s": "mandate_court:seo", "t": "열 해 동안 밤마다 적어 뒀어요. 부적 쓰고 남은 황지 귀퉁이예요. 언젠가 태사령께서 다시 부르실 날이 오면 그날 읽으시라고요."}, {"s": null, "t": "하후정이 쪽지 한 장을 집어 들었다. 노인의 손가락이 바들바들 떨렸다. 하후정은 쪽지를 오래 내려다보다가 서이연을 올려다보았다."}, {"s": "mandate_court:hahu", "t": "…열 해를. 밤마다."}, {"s": null, "t": "서이연이 쑥스러운 듯 손사래를 쳤다."}, {"s": "mandate_court:seo", "t": "어차피 밤에 못 자는 사람이에요, 저는. 관측관이 밤에 할 일이 그것밖에 더 있나요."}, {"s": null, "t": "서이연은 웃으며 말했지만, 쪽지를 집어 든 손이 쪽지 위를 한참 헤맸다. 서이연은 글씨에 눈을 바싹 갖다 대고서야 날짜를 읽었다."}, {"s": "mandate_court:seo", "t": "조사원님, 실은 제 글씨를 이제 제가 못 읽어요. 요즘은 큰 별도 번져 보여서요. 그래서 오시라고 했어요. 태사령께서 부르실 때 곁에서 쪽지를 읽어 주세요."}, {"s": null, "t": "하후정이 쪽지를 탁자에 내려놓고 창밖을 보았다."}, {"s": "mandate_court:hahu", "t": "오늘 밤 하늘에 대 보고 부르마. 별은 해마다 같은 날 같은 자리로 돌아온다."}, {"s": null, "t": "운해가 천리경 쪽을 돌아보다가 얼굴을 찡그렸다. 천리경 알에 뿌연 먼지가 두껍게 앉아 있었다."}, {"s": "q:bl_unhae", "t": "그러려면 천리경부터 닦아야 합니다. 열 해 치 먼지가 앉았습니다. 닦개 없이 손으로 문질렀다가는 목담성 일이 또 납니다. 알에 붙은 성진사 한 알을 세 해 동안 별로 적었던 일 말입니다."}, {"s": null, "t": "문서진이 운해를 돌아보았다. 웃지 않는 얼굴이었다. 운해가 움찔하며 입을 다물었다."}, {"s": "mandate_court:mun", "t": "그 일은 기록에 있다. 지우지 않았다."}, {"s": null, "t": "운해가 목을 움츠리고 헛기침을 한 번 하더니 내 쪽으로 돌아섰다."}, {"s": "q:bl_unhae", "t": "…예. 아무튼 닦개는 운면이 제일입니다. 별바라기 언덕 풀숲에 바람에 날려 온 운면이 걸려 있습니다. 네 줌만 걷어다 주십시오. 저는 문을 비울 수가 없어서요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_1', 2, '천리경 닦기', '별바라기 언덕에서 운면을(를) 모은다', '{"at": ["star_observatory"], "tasks": [{"t": "gather", "items": ["cloud_cotton"], "r": ["star_hill"], "n": 4}]}'::jsonb, '[{"s": null, "t": "운면을 들고 돌아오니 운해가 관성대 지붕 위 천리경 곁에서 기다리고 있었다. 나는 운면 한 줌을 받아 천리경 알을 둥글게 문질렀다. 운해는 사다리를 붙잡고 서서 내 손을 지켜보았다."}, {"s": "q:bl_unhae", "t": "천천히, 원을 그리면서요. 거기, 그 가장자리에 반짝이는 거 보이십니까? 그게 성진사입니다. 그걸 털어 내셔야 합니다."}, {"s": null, "t": "내가 성진사 알갱이를 손톱으로 톡 털어 내자, 운해가 숨을 후 내쉬었다."}, {"s": "q:bl_unhae", "t": "이제 목담성은 안 뜹니다. 다행입니다."}, {"s": null, "t": "어둠이 내리자 하후정이 지팡이를 짚고 지붕으로 올라왔다. 서이연이 쪽지 상자를 안고 뒤따랐다. 노인은 천리경에 눈을 대고 한참 움직이지 않았다."}, {"s": null, "t": "서이연이 상자에서 맨 위의 쪽지를 꺼내 내 손에 쥐여 주었다. 나는 쪽지를 등잔 가까이 들고 소리 내어 읽었다. 「열 해 전 동지 다음 날, 삼경. 국자 손잡이 끝 맑음. 서쪽에 구름 한 덩이.」"}, {"s": null, "t": "하후정이 천리경에서 눈을 떼고 북쪽 하늘을 보았다. 노인이 고개를 아주 천천히 끄덕였다."}, {"s": "mandate_court:hahu", "t": "같다. 구름만 다르다."}, {"s": null, "t": "서이연이 두 손을 가슴께에 모았다. 손가락 마디가 하얗게 될 만큼 꽉 쥐고 있었다."}, {"s": "mandate_court:seo", "t": "…다행이에요. 제 눈이 그때는 아직 괜찮았나 봐요."}, {"s": null, "t": "나는 상자 안을 들여다보다가 맨 위 쪽지의 날짜가 이상하다는 것을 알았다. 열 해 전 동지 다음 날부터였다. 나는 동짓날 밤 쪽지는 어디 있느냐고 물었다."}, {"s": null, "t": "서이연이 대답하려다 하후정 쪽을 보았다. 하후정은 하늘만 보고 있었다."}, {"s": "mandate_court:seo", "t": "그날 밤 건 없어요. 그 밤엔 제가 별을 못 봤거든요. …그 이야기는 나중에 해요. 오늘은 이어지는 밤부터요."}, {"s": null, "t": "지붕 아래에서 문서진이 별 기록 책을 안고 올라왔다. 문서진은 비어 있던 첫 장을 펴고 붓에 먹을 묻혀 한 획을 그어 보았다. 획이 곰팡이 피듯 사방으로 번져 나갔다."}, {"s": "mandate_court:mun", "t": "안 됩니다. 열 해 동안 펴 보지 않은 장들이라 습을 먹었습니다. 이 종이에는 먹이 앉지 않습니다."}, {"s": null, "t": "서이연이 번진 자국을 들여다보려고 등잔을 끌어당겼다. 등잔 기름이 출렁이며 쪽지 상자 쪽으로 기울었고, 나는 급히 상자를 내 쪽으로 끌어안았다."}, {"s": "mandate_court:seo", "t": "어머, 어머. 큰일 날 뻔했네요. 고마워요, 조사원님. 이 쪽지들도 다 귀퉁이 황지라 기름 한 방울이면 끝이에요."}, {"s": null, "t": "문서진이 상자 쪽으로 기운 등잔을 바로 세워 놓고 입을 열었다."}, {"s": "mandate_court:mun", "t": "그러니 새 장을 덧대야 합니다. 빈 장마다 정제 황지를 덧대고, 그 위에 적겠습니다. 쪽지는 옮겨 적은 뒤 상자째 서고에 둡니다. 서고 문서는 밖으로 나가지 않습니다."}, {"s": null, "t": "문서진이 나를 돌아보았다. 사관은 부탁할 때도 얼굴이 조금도 풀리지 않았다."}, {"s": "mandate_court:mun", "t": "조사원님, 정제 황지 세 장을 지어 주십시오. 오늘 밤 부르실 만큼이면 됩니다. 나머지는 관측생들에게 짓게 하겠습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_1', 3, '처음 부르는 밤', '정제 황지을(를) 만든다, 정제 황지을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["fine_paper"], "n": 3}], "give": {"fine_paper": 3}}'::jsonb, '[{"s": null, "t": "문서진은 내가 건넨 정제 황지를 빈 장 위에 한 장씩 대고 풀을 먹였다. 사관의 손이 종이 귀를 맞출 때마다 사각사각 소리가 났다. 덧댄 장 위로 날짜 글씨가 희미하게 비쳐 올라왔다."}, {"s": null, "t": "지붕 계단 쪽에서 더듬더듬 발소리가 났다. 서하람이 한 손으로 벽을 짚고 다른 손으로 계단 수를 세며 올라오고 있었다. 하얗게 바랜 눈이 사람들 목소리 쪽으로 향했다."}, {"s": "q:r71_seoharam", "t": "스물하나, 스물둘… 다 왔다. 할머니, 계세요? 갈매 씨가 잔불촌에 가서 오늘은 혼자 세면서 왔어요."}, {"s": null, "t": "서이연이 벌떡 일어나 서하람의 팔을 붙잡았다."}, {"s": "mandate_court:seo", "t": "람아, 혼자 오면 어떡하니. 넘어지면 어쩌려고."}, {"s": null, "t": "서하람이 할머니 손을 더듬어 잡으며 빙긋 웃었다."}, {"s": "q:r71_seoharam", "t": "안 넘어졌어요. 태사령님이 별을 부르신다길래요. 그건 못 보지만 듣는 건 할 수 있잖아요."}, {"s": null, "t": "서하람은 천리경 곁에 무릎을 끌어안고 앉았다. 하후정이 천리경 앞에 서서 지팡이를 고쳐 짚었다. 나는 쪽지 상자에서 다음 쪽지를 꺼내 읽었다. 하후정이 하늘에 대 보고 같은 말을 소리 내어 불렀다."}, {"s": "mandate_court:hahu", "t": "열 해 전 동지 다음 날. 삼경. 국자 손잡이 끝 맑음. 서쪽 구름 한 덩이."}, {"s": null, "t": "문서진이 붓을 들어 덧댄 장에 그 말을 받아 적었다. 먹이 번지지 않고 반듯하게 앉았다. 문서진은 줄 끝에 「태사령 하후정 부름」을 적으려다 붓을 멈추었다. 하후정의 지팡이가 장 끝을 톡 짚고 있었다."}, {"s": "mandate_court:hahu", "t": "관측도 적어라. 서이연."}, {"s": null, "t": "문서진이 고개를 들었다. 사관의 목소리는 여전히 낮고 고르게 나왔다."}, {"s": "mandate_court:mun", "t": "천명원 별 기록에 관측관 이름을 적은 일은 없습니다. 태사령께서 읽으신 하늘만 적습니다."}, {"s": null, "t": "하후정이 지팡이를 장 끝에서 떼지 않은 채 사관을 올려다보았다."}, {"s": "mandate_court:hahu", "t": "그 밤 하늘을 읽은 것은 내가 아니다. 이연이다. 기록은 정확해야 한다고 했지."}, {"s": null, "t": "문서진은 잠깐 말이 없었다. 문서진이 줄 끝에 「관측 서이연」 네 글자를 작게 적었다. 서이연이 그 글자를 보려고 등잔을 끌어당겼다가, 끝내 읽지 못하고 고개를 돌렸다. 어깨가 조금씩 들썩였다."}, {"s": "q:r71_seoharam", "t": "할머니, 우세요?"}, {"s": null, "t": "서이연이 등잔 쪽으로 고개를 돌린 채 코를 훌쩍였다."}, {"s": "mandate_court:seo", "t": "아니다. 등잔 연기가 매워서 그래. 람아, 너는 거기 가만히 있어."}, {"s": null, "t": "서하람이 웃음을 참으며 고개를 끄덕였다. 나는 다음 쪽지를 꺼냈다. 그 밤 우리는 열 해 전 겨울의 한 달 치를 불렀다. 쪽지를 읽는 내 목소리가 쉬어 갈 즈음 운해가 지붕으로 꿀물을 들고 올라왔다."}, {"s": "q:bl_unhae", "t": "하룻밤에 한 달 치씩이면 열 해는… 백스무 밤입니다. 관측생들이 벌써 내기를 걸었습니다. 태사령께서 백스무 밤을 다 말씀으로 채우시는지, 중간에 석판을 다시 꺼내시는지요."}, {"s": null, "t": "하후정이 꿀물 잔을 받아 들고 운해를 내려다보았다."}, {"s": "mandate_court:hahu", "t": "너는 어느 쪽에 걸었느냐."}, {"s": null, "t": "운해가 꿀물 쟁반을 든 채 잠깐 머뭇거렸다."}, {"s": "q:bl_unhae", "t": "…말씀 쪽입니다. 저는 늘 말씀 쪽이었습니다, 열 해 내내요."}, {"s": null, "t": "하후정은 대답하지 않고 꿀물을 마셨다. 잔을 내려놓은 노인이 상자 맨 아래 빈자리를 지팡이로 가리켰다. 동짓날 밤 쪽지가 있어야 할 자리였다."}, {"s": "mandate_court:hahu", "t": "그 밤은 빈칸으로 두어라. 그 밤은 별이 아니라 내 일이다. 다음에 채우마."}, {"s": null, "t": "문서진이 덧댄 장 맨 앞 줄을 비워 둔 채 붓을 씻었다. 서하람은 천리경 곁에서 무릎에 턱을 괴고 눈을 감았다. 졸린 얼굴이 아니라 하늘 소리를 듣는 얼굴이었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mandate_2', 'side', '뒷이야기·무극 관성대', '웃지 않는 사관', '비워 둔 열 해 전 동짓날 밤을 채울 때가 온다. 그 밤 하후정이 백옥 천문탑 지하에 두고 온 석판 조각이 나오고, 「결론은 쓰지 마라」를 지켜 온 기밀 사관 문서진이 처음으로 결론 한 줄을 적는다.', 'star_observatory', 50, '{mdq_17,ep_mandate_1}'::text[], null, 1516, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:mandate_court", "stage": 2}'::jsonb where quest_id = 'ep_mandate_2';
delete from public.world_quest_steps where quest_id = 'ep_mandate_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_2', 1, '비워 둔 첫 줄', '비워 둔 첫 줄', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "그사이 관성대 사람들은 밤마다 한 달 치씩 열 해 전 하늘을 불러 왔다. 서고 탁자 위 별 기록 책은 덧댄 장으로 두툼해졌고, 쪽지 상자는 반쯤 비어 있었다."}, {"s": null, "t": "관성대 마당에는 관측생 여럿이 나무판을 등에 지고 길을 떠날 채비를 하고 있었다. 판마다 「내일 새벽 안개」「사흘 뒤 삭풍」 같은 글씨가 적혀 있었다. 운해가 판 하나를 붙들고 끈을 조여 주었다."}, {"s": "q:bl_unhae", "t": "{등급}님, 마침 오셨습니다. 사업 둘째 단계가 차서 이제 이웃 고을 길목마다 하늘 예보 판을 세웁니다.", "fac": "mandate_court", "spec": 1, "grp": 1}, {"s": "q:bl_unhae", "t": "조사원님, 마침 오셨습니다. 천명원 사업 둘째 단계가 차서 이제 이웃 고을 길목마다 하늘 예보 판을 세웁니다.", "fac_not": "mandate_court", "spec": 2, "grp": 1}, {"s": "q:bl_unhae", "t": "여러 조사원님이 봉인 먹이며 결계 파편을 넘겨주셔서 판을 칠하고 길목 결계를 새로 그었습니다. 구름 위 회랑, 수경루, 백옥 천문탑, 뇌명봉까지요. 언제 안개가 끼는지 알고 다니면 다치는 사람도 줄고, 잃은 물건 찾기도 쉽다고들 합니다."}, {"s": null, "t": "운해가 판 끈을 다 조이고 나를 서고로 이끌었다. 서고 안에서는 문서진이 별 기록 책 맨 앞 장을 펴 놓고 서 있었다. 덧댄 장 맨 앞 줄 하나만 여전히 비어 있었다. 열 해 전 동짓날 밤이었다."}, {"s": "mandate_court:mun", "t": "태사령께서 오늘 그 밤을 채우겠다고 하셨습니다. 그런데 그 밤에는 별 쪽지가 없습니다. 쪽지 없이 무엇을 적을지 저는 모르겠습니다."}, {"s": null, "t": "나는 그 밤에 무슨 일이 있었는지 아는 사람이 없느냐고 물었다. 문서진이 대답하기 전에 문간의 운해가 헛기침을 했다."}, {"s": "q:bl_unhae", "t": "제가… 조금 압니다. 그때 저는 막 수직 일을 배우던 때였습니다. 그 밤 태사령께서 어유 등잔을 들라 하셔서 백옥 천문탑까지 따라갔습니다. 탑 지하 옛 성도 앞까지요."}, {"s": "q:bl_unhae", "t": "태사령께서는 성도 귀퉁이를 오래 읽으시고, 들고 가신 석판에 무언가를 쓰셨습니다. 그러고는 석판을 바닥에 내려치셨습니다. 돌 깨지는 소리가 지하 가득 울렸습니다. 그 소리가 아직도 귀에 남아 있습니다."}, {"s": "q:bl_unhae", "t": "돌아오시는 길에는 한 말씀도 안 하셨습니다. 그 뒤로 열 해였습니다. 저는 무서워서 석판 조각을 줍지도 못했습니다."}, {"s": null, "t": "서이연이 서고 안쪽 의자에서 천천히 일어섰다. 서이연은 운해를 보다가 나를 보았다."}, {"s": "mandate_court:seo", "t": "그 밤 저는 관성대에 없었어요. 태사령이 안 돌아오셔서 백옥 천문탑 아래까지 찾으러 내려갔거든요. 그래서 그 밤 쪽지가 없는 거예요."}, {"s": null, "t": "문서진이 탁자 끝을 손가락으로 톡 두드렸다."}, {"s": "mandate_court:mun", "t": "그 석판이 아직 탑 지하에 있다면, 그 밤을 적을 수 있습니다. 태사령께서 그 밤 쓰신 글이니까요."}, {"s": null, "t": "문서진이 나를 똑바로 보았다. 사관의 눈에는 부탁보다 셈이 먼저 서 있었다."}, {"s": "mandate_court:mun", "t": "조사원님, 백옥 천문탑 지하를 살펴 석판 조각을 찾아 주십시오. 두 조각은 되어야 글이 이어질 겁니다. 길목 판에 오늘 안개 시각이 적혀 있으니, 안개 끼기 전에 다녀오시면 찾기 쉬울 겁니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_2', 2, '석판 조각', '백옥 천문탑에서 실마리를 찾는다', '{"at": ["star_observatory"], "tasks": [{"t": "clue", "r": ["white_tower"], "n": 2}]}'::jsonb, '[{"s": null, "t": "백옥 천문탑 지하 옛 성도 앞 돌바닥 틈에서 나는 석판 조각 둘을 찾았다. 먼지를 털자 분필 글씨가 희미하게 살아났다. 깨진 두 조각을 맞대니 금 하나를 사이에 두고 글이 이어졌다."}, {"s": null, "t": "내가 조각을 탁자에 내려놓자 서고 안이 조용해졌다. 문서진이 조각 위로 몸을 숙였고, 서이연은 등잔을 끌어당겼다. 운해는 문간에서 창을 쥔 채 들어오지 못했다."}, {"s": null, "t": "하후정이 지팡이를 짚고 탁자로 왔다. 노인은 조각을 내려다보았지만 손을 대지 않았다. 나는 서이연을 위해 그 글을 소리 내어 읽었다. 「백 년 전, 우리가 별을 잘못 읽었다. 그 말이 칸을 긁었다. 남명이 그 칸으로 망했다. 나는 오늘부터 말하지 않는다.」"}, {"s": null, "t": "아무도 움직이지 않았다. 서이연이 입을 막았다. 문서진의 손가락이 탁자 모서리를 꽉 쥐었다."}, {"s": null, "t": "문간의 운해가 창 자루를 쥔 손에 힘을 주었다. 운해의 목소리가 떨렸다."}, {"s": "q:bl_unhae", "t": "그 밤 그 소리가… 이 글을 깨뜨리는 소리였군요. 저는 열 해 동안 석판이 손에서 미끄러진 줄로만 알았습니다."}, {"s": null, "t": "하후정이 운해 쪽으로 고개를 돌렸다. 노인의 눈가가 붉었다."}, {"s": "mandate_court:hahu", "t": "미끄러진 게 아니다. 내가 깼다. 그 밤 말도 같이 깼다."}, {"s": "mandate_court:hahu", "t": "적어라. 그 밤을 그대로."}, {"s": null, "t": "문서진이 고개를 들었다. 처음으로 사관의 목소리가 조금 흔들렸다."}, {"s": "mandate_court:mun", "t": "태사령. 천명원 기록은 결론을 적지 않습니다. 「우리가 잘못 읽었다」는 하늘이 아니라 결론입니다. 이 줄을 적으면 천명원 기록은 처음으로 스스로를 판가름하게 됩니다."}, {"s": null, "t": "하후정이 석판 조각 위로 마른 손을 펴 얹었다."}, {"s": "mandate_court:hahu", "t": "그래서 적으라는 것이다. 열 해 동안 아무것도 적지 않은 것이 가장 큰 결론이었다."}, {"s": null, "t": "문서진은 오래 대답하지 않았다. 사관이 품에서 쇠못 하나를 꺼내 손바닥 위에 굴렸다. 목판에 기록을 새길 때 쓰는 못이었다."}, {"s": "mandate_court:seo", "t": "문 사관. 남명 사람들은 그 칸 때문에 나라를 잃었어요. 우리는 열 해 동안 입만 다물고 있었고요. …그 사람들한테 우리가 할 수 있는 건 이 한 줄밖에 없어요."}, {"s": null, "t": "문서진이 쇠못을 탁자에 내려놓았다. 딸깍, 작은 소리가 났다."}, {"s": "mandate_court:mun", "t": "…적겠습니다. 다만 이 줄은 아무도 지우지 못할 먹으로 적겠습니다. 다음 태사령이, 그다음 태사령이 지우고 싶어져도 못 지우게요."}, {"s": "mandate_court:mun", "t": "조사원님, 봉인 먹 두 개를 지어 주십시오. 한 개는 책에, 한 개는 제 목판에 쓰겠습니다. 결론을 적는 김에, 제 손으로도 새겨 두겠습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_2', 3, '결론 한 줄', '봉인 먹을(를) 만든다, 봉인 먹을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["sealing_ink"], "n": 2}], "give": {"sealing_ink": 2}}'::jsonb, '[{"s": null, "t": "문서진이 내가 건넨 봉인 먹을 벼루에 갈았다. 먹 냄새가 서고 가득 퍼졌다. 사관은 비워 두었던 맨 앞 줄에 붓을 대고, 석판의 글을 한 자씩 옮겨 적었다."}, {"s": null, "t": "마지막 글자를 적은 붓이 장에서 떨어졌다. 봉인 먹은 번지지 않고 종이 깊이 배어들었다. 문서진이 줄 끝에 「사관 문서진 적음. 결론을 적음.」이라고 덧붙였다."}, {"s": null, "t": "서이연이 등잔을 그 줄 가까이 들고 한 글자씩 손가락으로 짚어 보았다. 끝내 다 읽지는 못했지만 서이연은 고개를 끄덕였다."}, {"s": "mandate_court:seo", "t": "남명 갈매 씨한테도 이 줄은 보여 주고 싶네요. …아니다, 갈매 씨는 이런 거 보면 또 화낼 거야."}, {"s": null, "t": "하후정이 그 말에 입가를 아주 조금 늘였다. 노인은 문서진에게 고개를 한 번 숙였다. 태사령이 사관에게 고개를 숙이는 것을 나는 처음 보았다."}, {"s": "mandate_court:hahu", "t": "고맙다, 서진아."}, {"s": null, "t": "문서진은 대답 대신 쇠못을 쥐고 목판 앞에 앉았다. 끽끽 소리를 내며 같은 글을 나무에 새기기 시작했다. 한 줄을 다 새긴 사관이 못을 내려놓고 손가락으로 홈을 쓸었다. 그 순간, 사관의 입꼬리가 아주 조금 올라갔다."}, {"s": null, "t": "문간에서 그것을 본 운해가 창을 떨어뜨렸다. 창 자루가 돌바닥에 탕 부딪혔다."}, {"s": "q:bl_unhae", "t": "웃으셨습니다! 방금 웃으셨지요, 사관님? 조사원님도 보셨지요?"}, {"s": null, "t": "문서진이 못을 쥔 채 고개도 들지 않고 대답했다."}, {"s": "mandate_court:mun", "t": "웃지 않았다."}, {"s": null, "t": "운해가 창을 주워 들다 말고 다시 외쳤다."}, {"s": "q:bl_unhae", "t": "웃으셨습니다! 관측생들이 그러는데, 사관님 웃는 걸 보면 좋은 일이 생긴답니다. 저 열 해 만에 처음 봤습니다!"}, {"s": null, "t": "문서진이 운해를 돌아보았다. 웃지 않는 얼굴이었지만 귀 끝이 조금 붉었다. 나는 운해 편을 들어, 나도 보았다고 했다."}, {"s": "mandate_court:mun", "t": "조사원님까지. …기록은 정확해야 합니다."}, {"s": null, "t": "하후정이 지팡이로 목판 귀퉁이를 톡 짚었다."}, {"s": "mandate_court:hahu", "t": "웃었다. 적어 두어라."}, {"s": null, "t": "문서진이 한참 하후정을 보다가 쇠못을 다시 쥐었다. 사관은 목판 맨 아래 귀퉁이에 아주 작게 새겼다. 「이날 사관이 웃었다고 수직이 우김. 태사령도 우김.」"}, {"s": null, "t": "서이연이 그 글을 내게서 전해 듣고 소리 내어 웃었다. 웃음 끝에 눈가를 훔쳤다. 운해는 떨어뜨린 창을 주우며 「좋은 일이 생깁니다」를 두 번이나 되뇌었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mandate_3', 'side', '뒷이야기·무극 관성대', '물시계 터 길', '관성대에서 이웃 땅으로 가는 지름길이 열린다. 열 해 동안 문을 비운 적 없던 수직 운해가 처음 문을 나서 새 길을 걷고, 아무도 시각을 묻지 않아 멈춰 버린 물시계 터의 물시계를 다시 돌린다.', 'star_observatory', 50, '{mdq_17,ep_mandate_2}'::text[], null, 1517, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:mandate_court", "stage": 3}'::jsonb where quest_id = 'ep_mandate_3';
delete from public.world_quest_steps where quest_id = 'ep_mandate_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_3', 1, '문을 나서는 수직', '문을 나서는 수직', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "그사이 관성대 별 기록 책은 열 해 전 하늘을 거의 다 따라잡았다. 이제 남은 일은 앞으로의 밤을 적는 일이었다."}, {"s": null, "t": "관성대 문 앞에 새 돌기둥이 줄지어 서 있었다. 기둥마다 작은 별 깃발이 꽂혀, 물시계 터와 별바라기 언덕과 혜성 낙하지 쪽으로 길을 그리며 이어졌다. 운해가 창 대신 등짐을 지고 문 앞에 서 있었다."}, {"s": "q:bl_unhae", "t": "{등급}님! 사업 셋째 단계가 찼습니다. 이제 {등급}님 같은 천명원 분들은 이 길로 물시계 터며 혜성 낙하지며 다니시면 훨씬 빠르고 운임도 안 드십니다.", "fac": "mandate_court", "spec": 1, "grp": 1}, {"s": "q:bl_unhae", "t": "조사원님! 천명원 사업 셋째 단계가 찼습니다. 이 지름길은 천명원 사람들한테만 빠르다지만, 오늘은 함께 걸어 주시지요.", "fac_not": "mandate_court", "spec": 2, "grp": 1}, {"s": "q:bl_unhae", "t": "여러 조사원님이 영유리며 강화 부적목을 넘겨주셔서 길목마다 기둥을 박을 수 있었습니다. 저 깃발 하나하나가 다 그 덕입니다."}, {"s": null, "t": "나는 운해가 등짐을 진 까닭을 물었다. 운해 뒤에서 문서진이 별 기록 책을 품에 안고 나왔다."}, {"s": "mandate_court:mun", "t": "제가 보냅니다. 이제부터는 열 해 전 쪽지가 아니라 오늘 밤 하늘을 적습니다. 오늘 밤 기록에는 시각이 정확해야 합니다. 몇 경 몇 점인지를요."}, {"s": "mandate_court:mun", "t": "천명원의 시각은 물시계 터의 물시계가 정합니다. 그런데 그 물시계를 열 해 동안 아무도 보러 가지 않았습니다. 태사령께서 하늘을 부르지 않으시니, 아무도 시각을 묻지 않았던 겁니다."}, {"s": null, "t": "운해가 등짐 끈을 고쳐 매며 길 쪽을 바라보았다. 들뜬 얼굴이었지만 손가락이 끈을 자꾸 만지작거렸다."}, {"s": "q:bl_unhae", "t": "저는 열 해 동안 이 문 밖으로 나가 본 적이 없습니다. 태사령께서 말씀을 안 하시니, 문이라도 지키는 사람이 있어야 할 것 같아서요."}, {"s": "q:bl_unhae", "t": "오늘은 태사령께서 직접 말씀하셨습니다. 「문은 하루 비워도 된다. 시각을 받아 오너라.」 …그 말씀 한마디에 어젯밤 잠을 못 잤습니다."}, {"s": null, "t": "문서진이 운해의 등짐을 손바닥으로 한 번 두드렸다. 사관치고는 꽤 다정한 손길이었다."}, {"s": "mandate_court:mun", "t": "물시계 터에서 녹슨 구슬 떼가 굴러다닌다는 보고가 있다. 조사원님 곁에서 떨어지지 마라."}, {"s": null, "t": "운해가 나를 돌아보며 고개를 꾸벅 숙였다."}, {"s": "q:bl_unhae", "t": "조사원님, 길동무를 부탁드립니다. 물시계 터에 닿거든 구슬 떼부터 좀 치워 주십시오. 저는 창보다 옛이야기를 더 잘 다루는 사람이라서요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_3', 2, '구슬이 넘친 그릇', '물시계 터에 간다, 녹슨 구슬 떼을(를) 물리친다', '{"at": ["water_clock"], "tasks": [{"t": "travel", "r": ["water_clock"], "n": 1}, {"t": "win", "m": ["r71_clock_2"], "n": 6}]}'::jsonb, '[{"s": null, "t": "새 길은 빨랐다. 돌기둥과 별 깃발을 따라 걸으니 고개 하나를 돌아가던 길이 곧장 이어졌다. 운해는 기둥을 지날 때마다 손바닥으로 기둥을 한 번씩 짚었다."}, {"s": null, "t": "걸으며 운해는 쉬지 않고 이야기를 했다. 기둥을 짚던 손이 저 앞 물시계 터 쪽을 가리켰다."}, {"s": "q:bl_unhae", "t": "옛 태사령께서는 밤마다 이 길을 걸어 물시계 터에 가셨답니다. 물방울 소리를 귀로 세시려고요. 그분 말씀이 「하늘은 눈으로 보고, 시각은 귀로 듣는다. 둘 중 하나라도 놓치면 기록은 반쪽이다」였답니다. 그래서 천명원 관측관은 별을 볼 때 귀를 막지 않는답니다."}, {"s": null, "t": "고갯마루 기둥 곁에서 운해가 등짐을 내렸다. 운해는 주먹밥 두 덩이를 꺼내 하나를 내 손에 쥐여 주었다. 소금을 넉넉히 친 주먹밥이었다."}, {"s": "q:bl_unhae", "t": "관측생들이 싸 줬습니다. 수직이 처음 문을 나서는 날이라고요. 하나는 조사원님 몫입니다. 저 혼자 먹으면 체할 것 같아서요."}, {"s": null, "t": "나는 주먹밥을 받아 들고 운해와 나란히 기둥 곁에 앉아 먹었다. 운해는 한 입 먹을 때마다 뒤를 돌아 관성대 지붕을 확인했다."}, {"s": "q:bl_unhae", "t": "문이 아직 거기 있나 보고 있습니다. 버릇이라서요. …있네요. 안 도망갔습니다."}, {"s": null, "t": "물시계 터에 닿자 구슬 떼가 덜그럭덜그럭 돌바닥을 굴러다니고 있었다. 내가 구슬 떼를 다 흩어 놓자 녹슨 구리 구슬이 바닥 가득 흩어졌다. 운해가 구슬 하나를 주워 들고 물시계 받침의 커다란 놋그릇을 들여다보았다."}, {"s": "q:bl_unhae", "t": "아… 이거였군요. 물시계는 한 경마다 구슬을 하나씩 이 그릇에 떨어뜨립니다. 관성대 사람이 날마다 와서 그릇을 비우고 구슬 수로 시각을 적어 갔고요."}, {"s": "q:bl_unhae", "t": "열 해 동안 아무도 비우지 않았으니, 그릇이 넘쳐서 구슬이 굴러떨어진 겁니다. 굴러떨어진 구슬들이 녹이 슬어 저렇게 돌아다니게 된 거고요. 아무도 시각을 묻지 않으니까 시각이 저 혼자 굴러다녔던 겁니다."}, {"s": null, "t": "운해는 놋그릇의 녹을 소매로 문지르다가 손을 멈추었다. 물시계 꼭대기 물동이에서 내려오는 대롱이 말라 있었다. 물을 받아 시각을 재는 유리 뜨개가 쩍 갈라져 있었다."}, {"s": "q:bl_unhae", "t": "뜨개가 깨졌습니다. 이게 있어야 물 높이를 재는데요. 이대로는 물을 부어도 시각이 안 나옵니다."}, {"s": null, "t": "운해가 갈라진 뜨개를 두 손으로 들어 올렸다. 손바닥만 한 영유리였다. 운해의 얼굴이 금방이라도 울 것처럼 일그러졌다."}, {"s": "q:bl_unhae", "t": "제가 그때 문만 지키지 말고 한 번이라도 와 봤더라면… 열 해 동안 아무도 안 왔으니, 이건 제 잘못이기도 합니다."}, {"s": null, "t": "나는 운해에게 문을 지킨 것도 일이었다고 했다. 운해가 코를 훌쩍이며 고개를 끄덕였다."}, {"s": "q:bl_unhae", "t": "…예. 그 말씀은 받아 두겠습니다. 조사원님, 이 터 바위틈에 영유리가 맺힌다고 들었습니다. 세 조각만 모아 주십시오. 겹쳐 붙이면 뜨개 하나는 됩니다. 붙이는 건 제가 하겠습니다. 수직이라도 이건 배웠습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_3', 3, '첫 물방울', '물시계 터에서 영유리을(를) 모은다', '{"at": ["water_clock"], "tasks": [{"t": "gather", "items": ["spirit_glass"], "r": ["water_clock"], "n": 3}]}'::jsonb, '[{"s": null, "t": "운해는 내가 모아 온 영유리 세 조각을 송진으로 겹쳐 붙였다. 운해의 손이 서툴렀지만 끝까지 떨리지 않았다. 새 뜨개를 물받이에 띄우고, 둘이서 물동이에 물을 길어 부었다."}, {"s": null, "t": "마른 대롱 안에서 물이 꿀렁꿀렁 내려가는 소리가 났다. 한참 뒤 대롱 끝에 물방울 하나가 맺혔다. 물방울이 똑 떨어지자 물받이의 뜨개가 아주 조금 떠올랐다."}, {"s": null, "t": "운해가 숨을 멈추고 그 소리를 들었다. 물방울이 똑, 똑 이어 떨어졌다. 운해의 입술이 소리 없이 수를 세었다."}, {"s": "q:bl_unhae", "t": "…돌아갑니다. 조사원님, 돌아갑니다!"}, {"s": null, "t": "운해가 내 팔을 붙잡고 흔들었다. 물시계 터의 바람 소리 사이로 물방울 소리가 일정하게 이어졌다."}, {"s": null, "t": "바닥 구석에 흩어져 있던 녹슨 구슬 몇 알이 또르르 굴러와 놋그릇 곁에 멈췄다. 운해가 웃으며 그 구슬을 주워 그릇에 담았다."}, {"s": "q:bl_unhae", "t": "너희도 돌아왔구나. 이제 굴러다니지 마라. 날마다 비워 주러 올게."}, {"s": null, "t": "운해가 그릇 곁에 쪼그려 앉은 채 나를 올려다보았다."}, {"s": "q:bl_unhae", "t": "옛 태사령께서도 이 소리를 들으셨겠지요. 저는 그분 이야기를 다 외웁니다. 열 해 동안 문 앞에서 할 일이 없어서, 서고에서 빌린 옛이야기만 외웠거든요. 언젠가 누가 물어 주면 대답하려고요."}, {"s": "q:bl_unhae", "t": "그런데 아무도 안 물었습니다. 태사령께서는 말씀을 안 하셨고, 관측생들은 저를 지나쳐 갔고요. 그래서 오늘 조사원님한테 오는 길 내내 떠들었습니다. 시끄러우셨지요?"}, {"s": null, "t": "나는 옛 태사령이 물방울을 몇 번까지 세었는지 물었다. 운해의 얼굴이 환해졌다."}, {"s": "q:bl_unhae", "t": "밤새요! 한 경에 구슬 하나, 구슬 하나에 물방울 천이백. 그분은 그걸 다 세셨답니다. 세다가 졸면 처음부터 다시 세셨대요. 그래서 천명원에 「물방울을 세는 사람은 잠들지 않는다」는 말이 생겼답니다."}, {"s": null, "t": "운해는 놋그릇에 첫 구슬이 떨어질 때까지 기다렸다. 땡그랑, 구슬이 그릇 바닥을 굴렀다. 운해가 품에서 장부를 꺼내 「오늘 밤 일경」이라고 또박또박 적었다."}, {"s": "q:bl_unhae", "t": "이걸 사관님께 가져가겠습니다. 이 길이면 관성대까지 한 시진도 안 걸립니다. 앞으로는 관측생들이 밤마다 돌아가며 이 그릇을 비우러 오기로 했습니다."}, {"s": null, "t": "운해가 장부를 품에 넣고 물시계를 한 번 더 돌아보았다. 그러고는 기둥에 꽂힌 별 깃발 하나를 바로 세워 놓고 길에 올랐다."}, {"s": "q:bl_unhae", "t": "다음에 관성대에 오시면 물어봐 주십시오. 옛 태사령 이야기든 뭐든요. 이제는 대답할 사람이 문 앞에 있습니다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mandate_4', 'side', '뒷이야기·무극 관성대', '탁상 혼천의', '천명원 비고에 들일 작은 혼천의와 별 수놓은 도포를 만든다. 두 눈을 잃은 서하람이 손끝과 귀로 혼천의 고리를 맞추고, 눈이 침침해진 서이연이 손자의 말을 따라 도포에 별을 수놓는다.', 'star_observatory', 50, '{mdq_17,ep_mandate_3}'::text[], null, 1518, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:mandate_court", "stage": 4}'::jsonb where quest_id = 'ep_mandate_4';
delete from public.world_quest_steps where quest_id = 'ep_mandate_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_4', 1, '고리 셋', '고리 셋', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "그사이 관성대에는 물시계 터에서 시각을 받아 오는 관측생들의 발소리가 밤마다 이어졌다. 별 기록 책은 이제 오늘 밤 하늘을 적고 있었다."}, {"s": null, "t": "서고 옆 작은 방에 문서진이 비고 장부를 펴 놓고 앉아 있었다. 그 앞 탁자 위에 손바닥 두 개만 한 혼천의 뼈대가 놓여 있었다. 받침도 고리도 없이 가운데 축 하나만 서 있었다."}, {"s": "mandate_court:mun", "t": "조사원님. 사업 넷째 단계가 차서 비고에 새 물건을 들입니다. 천명원 조사원은 공훈으로 받아 갈 수 있게 될 겁니다.", "fac": "mandate_court", "spec": 1, "grp": 1}, {"s": "mandate_court:mun", "t": "조사원님. 천명원 사업 넷째 단계가 차서 비고에 새 물건을 들입니다. 비고 물건은 천명원 조사원에게만 내줍니다만, 만드는 일은 누구 손이든 상관없습니다.", "fac_not": "mandate_court", "spec": 2, "grp": 1}, {"s": "mandate_court:mun", "t": "별 기록관이 쓰던 작은 혼천의, 그리고 기록관들이 입던 별 수놓은 도포입니다. 여러 조사원님이 넘겨주신 월광 정수와 어유 등 덕에 들일 값은 마련했습니다. 남은 것은 만드는 손입니다."}, {"s": null, "t": "방 한쪽 창가에서 서하람이 혼천의 축을 손끝으로 더듬고 있었다. 갈매가 그 곁 의자에 다리를 꼬고 앉아 구운 밤을 까먹고 있었다."}, {"s": "q:r71_seoharam", "t": "{이름} 님 오셨어요? 발소리로 알았어요. 이거 제가 맞추기로 했어요. 고리는 손으로 맞추는 거라서요."}, {"s": null, "t": "갈매가 밤 껍질을 손바닥에 털며 피식 웃었다."}, {"s": "southern_remnant:galmae", "t": "손으로 맞추겠다는데 고리가 없어. 잠꾸러기가 허공을 맞추고 있는 거야, 지금."}, {"s": null, "t": "서하람이 갈매 쪽으로 얼굴을 돌리고 입을 비죽였다."}, {"s": "q:r71_seoharam", "t": "허공 아니에요. 축이에요. 고리 셋이 들어갈 자리를 재는 중이에요."}, {"s": null, "t": "문서진이 비고 장부에 무언가를 적으며 고개를 들었다."}, {"s": "mandate_court:mun", "t": "관성대 혼천의 고리는 예부터 혜성 낙하지 쇠로 부었습니다. 하늘에서 떨어진 자리의 쇠라 별을 가리키는 고리에 맞는다는 옛 법입니다. 대장간에 쇠가 다 떨어졌습니다."}, {"s": null, "t": "갈매가 밤 껍질을 손바닥에 모아 쥐고 벌떡 일어났다."}, {"s": "southern_remnant:galmae", "t": "그럼 내가 가지. 혜성 낙하지면 지름길로 금방이잖아."}, {"s": null, "t": "서하람이 갈매의 소매를 붙잡았다. 붙잡는 손끝이 정확하게 소매 끝을 찾았다."}, {"s": "q:r71_seoharam", "t": "갈매 씨는 여기 있어야 해요. 고리를 끼울 때 하늘을 읽어 줘야 하잖아요. 북극성이 창 어디쯤인지요. 쇠는 {이름} 님이 캐 오면 돼요. {이름} 님은 지름길로 금방 다녀오시니까요."}, {"s": null, "t": "갈매가 나를 흘끗 보고 다시 의자에 털썩 앉았다."}, {"s": "southern_remnant:galmae", "t": "…알았어. 대신 빨리 와. 나 여기 가만히 있는 거 못 해. 람이 할머니가 바늘에 실 꿰라고 자꾸 부른다고."}, {"s": null, "t": "방 반대편에서 서이연이 수틀을 무릎에 올려놓고 손을 흔들었다. 남색 비단에 은실 별 몇 개가 이미 박혀 있었다."}, {"s": "mandate_court:seo", "t": "들었어요, 남명 갈매 씨. 실은 한 번만 더 꿰어 주면 돼요. 오늘만 스무 번째지만요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_4', 2, '받침 나무', '혜성 낙하지에서 생 월철을(를) 모은다', '{"at": ["star_observatory"], "tasks": [{"t": "gather", "items": ["raw_iron"], "r": ["comet_crater"], "n": 4}]}'::jsonb, '[{"s": null, "t": "혜성 낙하지에서 캔 생 월철은 쪼갠 단면에 반짝이는 알갱이가 박혀 있었다. 내가 그 쇠를 관성대 대장간에 맡겨 고리 셋을 부어 오자, 서하람이 고리를 하나씩 받아 손바닥 위에서 굴려 보았다."}, {"s": "q:r71_seoharam", "t": "따뜻해요. 혜성 쇠는 식어도 오래 따뜻하대요. 할머니가 그랬어요."}, {"s": null, "t": "서하람이 바깥 고리를 축에 끼웠다. 찰칵, 고리가 맞물리는 소리가 났다. 서하람이 고개를 갸웃하고 고리를 살짝 돌려 보았다. 고리가 축 위에서 덜컥덜컥 흔들렸다."}, {"s": "q:r71_seoharam", "t": "소리가 틀려요. 맞는 고리는 「찰칵」 하고 끝나야 하는데, 이건 「찰칵, 덜컥」이에요. 받침이 기울었나 봐요."}, {"s": null, "t": "갈매가 혼천의를 들어 올려 아래를 들여다보았다. 받침이라고 놓인 나무토막이 한쪽으로 쩍 갈라져 있었다."}, {"s": "southern_remnant:galmae", "t": "받침이 쪼개졌어. 이걸로 하늘을 받치겠다고? 내가 앉아도 무너지겠다."}, {"s": null, "t": "서이연이 수틀에서 눈을 들었다. 바늘을 쥔 손이 허공에서 멈췄다."}, {"s": "mandate_court:seo", "t": "그 나무는 열 해 전에 혼천의를 고치려고 잘라 둔 거예요. 아무도 손을 안 대서 그대로 말라 터졌네요."}, {"s": null, "t": "나는 서이연 곁으로 가서 수틀을 들여다보았다. 은실 별 하나가 자리를 조금 벗어나 있었다. 서이연이 내 눈길을 느끼고 웃었다."}, {"s": "mandate_court:seo", "t": "알아요, 삐뚤었죠. 요즘은 바늘구멍도 번져 보여서요. 람아, 할머니 지금 어디 놨니?"}, {"s": null, "t": "서하람이 수틀 쪽으로 손을 뻗었다. 서하람의 손끝이 비단 위의 은실 별을 하나씩 짚어 나갔다."}, {"s": "q:r71_seoharam", "t": "국자 셋째 별이요. 그다음은 위로 두 땀, 오른쪽으로 한 땀이에요. 그날 밤 태사령님이 처음 부르신 하늘 그대로죠? 그 밤 하늘은 제가 다 외웠어요."}, {"s": null, "t": "서이연이 바늘을 든 채 눈을 가늘게 뜨고 웃었다."}, {"s": "mandate_court:seo", "t": "그래, 그 밤 하늘이다. 이 도포를 입는 기록관은 그 밤을 입는 거란다."}, {"s": null, "t": "서이연이 서하람이 짚어 준 자리에 바늘을 찔렀다. 이번에는 별이 제자리에 박혔다. 갈매가 그 모습을 보다가 혀를 끌끌 찼다."}, {"s": "southern_remnant:galmae", "t": "눈 안 보이는 애가 눈 침침한 할머니 바느질을 가르치고 있네. 천명원은 별나."}, {"s": null, "t": "문서진이 비고 장부를 덮고 일어섰다."}, {"s": "mandate_court:mun", "t": "받침은 강화 부적목 두 대를 엇갈려 짜면 됩니다. 비고 물건은 오래 가야 합니다. 조사원님, 강화 부적목 두 대를 지어 주십시오. 짜는 일은 갈매 씨가 하겠다고 했습니다."}, {"s": null, "t": "갈매가 쪼개진 받침을 내려놓다 말고 눈을 치켜떴다."}, {"s": "southern_remnant:galmae", "t": "내가 언제. …알았어. 앉아만 있는 것보다 낫지."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_4', 3, '찰칵', '강화 부적목을(를) 만든다, 강화 부적목을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["reinforced_lumber"], "n": 2}], "give": {"reinforced_lumber": 2}}'::jsonb, '[{"s": null, "t": "갈매는 내가 건넨 강화 부적목을 칼로 홈을 파 엇갈려 끼웠다. 나무가 탁탁 맞물리자 갈매가 받침을 두 손으로 눌러 보았다. 흔들리지 않았다."}, {"s": "southern_remnant:galmae", "t": "됐어. 이건 내가 앉아도 안 무너져."}, {"s": null, "t": "서하람이 받침을 손바닥으로 감싸며 얼른 말했다."}, {"s": "q:r71_seoharam", "t": "앉지 마요."}, {"s": null, "t": "서하람이 받침 위에 축을 세우고 바깥 고리를 다시 끼웠다. 고리가 찰칵 맞물리고, 소리가 한 번에 끝났다. 서하람의 입가가 올라갔다. 둘째 고리, 셋째 고리도 찰칵 소리를 내며 맞물렸다."}, {"s": "q:r71_seoharam", "t": "갈매 씨, 창밖이요. 북극성이 창틀 어디쯤이에요?"}, {"s": null, "t": "갈매가 창가로 가서 하늘을 올려다보았다. 이번에는 몸을 하늘 쪽으로 돌린 채였다."}, {"s": "southern_remnant:galmae", "t": "창틀 위에서 손가락 셋 아래. 왼쪽 기둥에서 손바닥 하나. 하늘 쪽에서 본 왼쪽이야. 너 또 따지지 마."}, {"s": null, "t": "서하람이 웃음을 터뜨리며 축 끝을 그 방향으로 기울였다. 손끝으로 고리 눈금을 세다가 한 칸에서 멈추고 나사를 조였다. 서하람이 두 손을 떼고 귀를 혼천의에 가까이 댔다. 고리를 톡 건드리자 세 고리가 함께 사르르 돌다가 한자리에 섰다."}, {"s": null, "t": "하후정이 지팡이를 짚고 방으로 들어왔다. 노인은 혼천의를 내려다보고 고리 하나를 손가락으로 돌려 보았다. 고리가 찰칵 제자리로 돌아왔다."}, {"s": "mandate_court:hahu", "t": "…되었다."}, {"s": null, "t": "서하람이 숨을 내쉬며 의자 등받이에 기댔다. 서이연이 마지막 별 한 땀을 꿰고 실을 이로 끊었다. 남색 도포 등판에 은실 별 서른여섯이 박혀 있었다."}, {"s": "mandate_court:seo", "t": "나도 다 됐어요. 람이가 짚어 준 자리 그대로예요. …조사원님, 한번 대 봐 주세요. 별이 어디 하나 삐뚤지 않았는지."}, {"s": null, "t": "나는 도포를 받아 등판을 펼쳐 보았다. 처음에 삐뚤던 별 하나만 조금 비껴 있었고 나머지는 반듯했다. 나는 서이연에게 하나만 빼고 다 반듯하다고 했다."}, {"s": "mandate_court:seo", "t": "그 하나는 그냥 둬요. 첫 땀이니까요. 누가 처음에 헤맸는지도 별 기록이에요."}, {"s": null, "t": "문서진이 혼천의와 도포를 받아 비고 장부에 올렸다. 사관은 이번에도 웃지 않았다."}, {"s": "mandate_court:mun", "t": "비고에 들였습니다. 조사원님도 공훈이 모이면 이 혼천의나 도포를 받아 가실 수 있습니다. 받아 가시거든 처음 헤맨 별 하나도 함께 받아 가시는 겁니다.", "fac": "mandate_court", "spec": 1, "grp": 1}, {"s": "mandate_court:mun", "t": "비고에 들였습니다. 천명원 조사원이 아니시니 받아 가실 수는 없지만, 조사원님 손이 들어간 것은 비고 장부에 적어 두겠습니다. 받침 짠 손, 쇠 캐 온 손까지요.", "fac_not": "mandate_court", "spec": 2, "grp": 1}, {"s": null, "t": "갈매가 받침을 짠 칼을 칼집에 넣으며 서하람의 머리를 헝클었다. 서하람은 혼천의 고리를 손끝으로 한 번 더 톡 건드리고, 찰칵 소리가 끝날 때까지 귀를 기울였다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mandate_5', 'side', '뒷이야기·무극 관성대', '성도 무늬', '이어 붙인 별 기록의 낙성 날. 관성대 위에 별자리 등을 달고 성도 무늬 깃발을 올린다. 열 해 동안 밤마다 쪽지를 적느라 깨어 있던 서이연이 처음으로 밤을 새우지 않고 잔다.', 'star_observatory', 50, '{mdq_17,ep_mandate_4}'::text[], null, 1519, '[]'::jsonb, true, null, null)
