update public.world_quests set open_req = '{"project": "f:mandate_court", "stage": 5}'::jsonb where quest_id = 'ep_mandate_5';
delete from public.world_quest_steps where quest_id = 'ep_mandate_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_5', 1, '마지막 쪽지', '마지막 쪽지', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "그사이 관성대 지붕에는 별 깃발이 하나둘 늘어 처마 끝까지 이어졌다. 혼천의 고리를 본뜬 쇠고리 장식이 깃대마다 달려 바람이 불 때마다 쟁그랑쟁그랑 울렸다."}, {"s": null, "t": "서고 탁자 위 쪽지 상자는 비어 있었다. 서이연이 빈 상자 바닥을 손바닥으로 쓸고 있었다. 마지막 쪽지 한 장이 그 손 옆에 놓여 있었다."}, {"s": "mandate_court:seo", "t": "조사원님, 이게 마지막이에요. 어젯밤 거예요. 이제 쪽지는 더 없어요. 오늘 밤부터는 태사령께서 부르시고, 사관이 바로 적으시니까요."}, {"s": null, "t": "서이연은 빈 상자를 한참 들여다보았다. 무엇을 잃은 사람 같기도 하고 무엇을 내려놓은 사람 같기도 했다."}, {"s": "mandate_court:seo", "t": "조사원님, 사업이 다섯째 단계까지 찼어요. 오늘 낙성이에요. 천명원 조사원들한테는 성도 무늬가 내려온대요. 별자리를 그린 바탕 무늬요.", "fac": "mandate_court", "spec": 1, "grp": 1}, {"s": "mandate_court:seo", "t": "조사원님, 천명원 사업이 다섯째 단계까지 찼어요. 오늘 낙성이에요. 바깥 분들 손도 많이 빌렸어요.", "fac_not": "mandate_court", "spec": 2, "grp": 1}, {"s": "mandate_court:seo", "t": "여러 조사원님이 청새치며 대환단이며 청등을 넘겨주셨어요. 그 덕에 오늘 밤 지붕에 별자리 등을 달아요. 별 하나에 등 하나씩요."}, {"s": null, "t": "서이연이 마지막 쪽지를 상자에 넣고 뚜껑을 덮었다. 그러고는 소매를 걷어붙였다."}, {"s": "mandate_court:seo", "t": "오늘 밤은 저도 지붕에 올라가 등을 달 거예요. 낙성 밤인데 밤새 지켜봐야죠."}, {"s": null, "t": "하후정이 지팡이로 바닥을 톡 짚었다. 서고 안 사람들이 모두 그쪽을 보았다."}, {"s": "mandate_court:hahu", "t": "이연아. 오늘부터는 자거라."}, {"s": null, "t": "서이연이 웃으며 하후정 쪽으로 고개를 저었다."}, {"s": "mandate_court:seo", "t": "태사령도 참. 열 해를 밤에 깨어 있던 사람이 어떻게 하루아침에 자요. 눈 감아도 별이 보여요."}, {"s": null, "t": "하후정은 대답하지 않고 나를 보았다. 노인이 무엇을 바라는지 나는 알 것 같았다."}, {"s": null, "t": "그때 문서진이 서고 안쪽에서 등롱 뼈대 한 묶음을 들고 나왔다. 대오리로 엮은 둥근 뼈대 서른여섯 개였다."}, {"s": "mandate_court:mun", "t": "등보다 먼저 할 일이 있습니다. 등 속에 성진사를 넣어야 별빛이 나는데, 관성대 성진사로는 모자랍니다. 백옥 천문탑 위층에 별빛 머금은 성진사가 많이 맺혀 있습니다. 한두 줌이 아니라 짐으로 날라 와야 합니다."}, {"s": null, "t": "운해가 문간에서 창을 기대 세우며 고개를 내밀었다."}, {"s": "q:bl_unhae", "t": "천문탑이면 길목 판이 서 있으니 길은 수월하실 겁니다. 짐이 많으니 원정으로 다녀오시지요. 조사원님이 해 지기 전에 돌아오셔야 등을 달 수 있습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_5', 2, '별자리 등', '백옥 천문탑에 원정을 다녀온다', '{"at": ["star_observatory"], "tasks": [{"t": "expedition", "r": ["white_tower"], "n": 1}]}'::jsonb, '[{"s": null, "t": "백옥 천문탑에서 날라 온 성진사 짐을 풀자 서고 바닥이 반짝반짝 빛났다. 관측생들이 등롱 뼈대마다 성진사를 한 줌씩 넣고 한지를 발랐다."}, {"s": null, "t": "해가 질 무렵 관성대 지붕에 별자리 등 서른여섯이 걸렸다. 등을 하나 걸 때마다 서하람이 지붕 끝에 앉아 별 이름을 불렀고, 갈매가 등 거는 관측생에게 「거기 말고 손가락 하나 왼쪽, 하늘 쪽 왼쪽」 하고 소리쳤다."}, {"s": "southern_remnant:galmae", "t": "셋째 등 삐뚤었어. 아니, 너 말고 네 옆. 아, 그것도 아니고!"}, {"s": null, "t": "서하람이 지붕 끝에서 무릎을 끌어안은 채 키득거렸다."}, {"s": "q:r71_seoharam", "t": "갈매 씨, 별이 아니라 등이니까 조금 삐뚤어도 돼요."}, {"s": null, "t": "마지막 등이 걸리자 운해가 깃대에 남색 깃발을 올렸다. 별자리 무늬가 은실로 수놓인 성도 무늬 깃발이었다. 깃발이 바람을 받아 활짝 펴지자 관측생들이 와아 소리를 질렀다."}, {"s": null, "t": "아래 마당에서 낙성 떡 시루가 열렸다. 김이 모락모락 올라 별자리 등 불빛에 하얗게 비쳤다. 운해가 떡을 한 접시씩 나르며 「좋은 일이 생깁니다」를 연신 중얼거렸다."}, {"s": null, "t": "밤이 깊자 하후정이 천리경 앞에 섰다. 문서진이 별 기록 책을 펴고 붓을 들었다. 쪽지 없이 부르는 첫 밤이었다."}, {"s": "mandate_court:hahu", "t": "오늘 밤. 일경. 국자 손잡이 끝 맑음. 지붕에 등 서른여섯."}, {"s": null, "t": "문서진이 붓을 멈추고 고개를 들었다."}, {"s": "mandate_court:mun", "t": "등은 하늘이 아닙니다, 태사령."}, {"s": null, "t": "하후정은 천리경에서 눈을 떼지 않고 대답했다."}, {"s": "mandate_court:hahu", "t": "오늘 하늘에는 있다."}, {"s": null, "t": "문서진이 잠깐 붓을 멈췄다가 그대로 적었다. 서이연은 지붕 한쪽에 담요를 덮고 앉아 있었다. 눈꺼풀이 자꾸 내려왔지만 서이연은 그때마다 고개를 흔들고 눈을 비볐다."}, {"s": "mandate_court:seo", "t": "안 자요. 안 자. 람아, 할머니 깨어 있지?"}, {"s": null, "t": "서하람이 지붕 끝에서 고개만 돌려 대답했다."}, {"s": "q:r71_seoharam", "t": "아까부터 세 번째 물으셨어요, 할머니."}, {"s": null, "t": "하후정이 천리경에서 눈을 떼고 나를 손짓해 불렀다. 노인이 낮은 목소리로 말했다."}, {"s": "mandate_court:hahu", "t": "조사원. 저 아이 곁에 앉아 있거라. 곁에 누가 깨어 있으면 이연이 눕겠지. 열 해 동안 저 아이 곁에는 아무도 깨어 있지 않았다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mandate_5', 3, '잔 사람', '무극 관성대에서 쉰다', '{"at": ["star_observatory"], "tasks": [{"t": "rest", "r": ["star_observatory"], "n": 1}]}'::jsonb, '[{"s": null, "t": "나는 서이연 곁에 앉아 담요 끝을 여며 주었다. 서이연이 쪽지는 이제 안 적어도 되느냐고 몇 번 물었고, 나는 그때마다 사관이 적고 있다고 대답했다. 서이연이 언제 잠들었는지는 나도 몰랐다. 한참 뒤에 보니 서이연의 고개가 내 어깨에 기울어 있었다."}, {"s": null, "t": "아침 햇살이 관성대 지붕의 별자리 등 위로 내려앉았다. 서이연이 화들짝 놀라 눈을 떴다. 담요가 어깨에서 흘러내렸다."}, {"s": "mandate_court:seo", "t": "어머, 어머나. 해가 떴네요. 제가… 잤어요?"}, {"s": null, "t": "서하람이 지붕 끝에서 고개를 돌렸다. 서하람은 밤새 별 소리를 듣는다며 그 자리에 앉아 있었다."}, {"s": "q:r71_seoharam", "t": "코 고셨어요, 할머니. 세 번이요. 갈매 씨가 세었어요."}, {"s": null, "t": "갈매가 지붕 처마 쪽에서 팔짱을 낀 채 끼어들었다."}, {"s": "southern_remnant:galmae", "t": "네 번이야. 마지막 건 작아서 너 못 들었어."}, {"s": null, "t": "서이연이 두 손으로 얼굴을 감싸고 웃음을 터뜨렸다. 웃음 끝이 젖어 있었다. 서이연은 손을 내리고 하늘을 올려다보았다. 별은 이미 다 들어가 있었다."}, {"s": "mandate_court:seo", "t": "열 해 만에 처음이에요. 밤새 안 깨고 잔 거요. …그런데 이상하네요. 하나도 안 무서웠어요. 누가 대신 깨어 있었으니까요."}, {"s": null, "t": "문서진이 별 기록 책을 안고 지붕으로 올라왔다. 사관은 책을 펴 지난밤 장을 서이연 앞에 내밀었다. 나는 서이연 대신 마지막 줄을 소리 내어 읽었다. 「삼경. 국자 손잡이 끝 맑음. 이 밤 수석 관측관 서이연, 잠. 곁에 조사원 {이름} 깨어 있음. 관측 운해·관측생 넷.」"}, {"s": "mandate_court:seo", "t": "문 사관! 그런 걸 왜 적어요!"}, {"s": null, "t": "문서진이 책을 덮지도 않고 태연하게 대답했다."}, {"s": "mandate_court:mun", "t": "기록은 정확해야 합니다. 수석 관측관이 처음으로 잔 밤입니다. 천명원에 그런 밤은 없었습니다."}, {"s": null, "t": "운해가 마당에서 낙성 떡 접시를 들고 계단을 뛰어 올라왔다. 운해는 떡 접시를 서이연 손에 쥐여 주고 숨을 헐떡였다."}, {"s": "q:bl_unhae", "t": "수석 관측관님 몫입니다. 밤새 깨어 있던 사람 몫은 따로 챙겨 두는 거라고 태사령께서 그러셨습니다. 오늘은 수석 관측관님이 아니라 조사원님이 깨어 있었으니까… 조사원님 몫도요."}, {"s": null, "t": "문서진이 운해 뒤에서 책을 덮으며 나를 보았다."}, {"s": "mandate_court:mun", "t": "조사원님 몫의 성도 무늬도 내려왔습니다. 바탕에 별자리를 까시면, 오늘 밤 지붕에 단 등 서른여섯이 그대로 들어 있습니다.", "fac": "mandate_court", "spec": 1, "grp": 1}, {"s": "mandate_court:mun", "t": "성도 무늬는 천명원 조사원에게만 내려갑니다. 다만 오늘 밤 기록에는 조사원님이 깨어 있었다고 적어 두었습니다.", "fac_not": "mandate_court", "spec": 2, "grp": 1}, {"s": null, "t": "하후정이 지팡이를 짚고 지붕으로 올라와 서이연 곁에 섰다. 노인은 별이 다 들어간 아침 하늘을 오래 올려다보았다."}, {"s": "mandate_court:hahu", "t": "오늘 밤에도 자거라."}, {"s": null, "t": "서이연이 떡 접시를 두 손으로 받쳐 든 채 고개를 끄덕였다."}, {"s": "mandate_court:seo", "t": "…네. 오늘 밤에도 잘게요."}, {"s": null, "t": "서이연이 떡을 한 입 베어 물었다. 관성대 지붕 위에서 성도 무늬 깃발이 아침 바람을 받아 크게 펄럭였다."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mk_1', 'side', '뒷이야기·묵창 나루', '주막 외상 장부', '묵창 주막 선반에 바깥 물건이 늘었다. 주모 홍매댁이 외상 장부를 이름으로 고쳐 적으려다, 스무 해를 함께 산 나루 사람들의 이름을 거의 모른다는 것을 알게 된다.', 'mukchang_ferry', 50, '{mdq_17}'::text[], null, 1520, '[]'::jsonb, true, null, null)
