update public.world_quests set open_req = '{"project": "c:mukjeok", "stage": 1}'::jsonb where quest_id = 'ep_mk_1';
delete from public.world_quest_steps where quest_id = 'ep_mk_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_1', 1, '여섯 가지 선반', '여섯 가지 선반', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "묵창 주막 술청 한쪽 벽에 새 선반이 붙어 있었다. 짐꾼이 빙혼곡을 넘어 지고 온 상자들이 그 앞에 쌓여 있었다."}, {"s": null, "t": "주모 홍매댁이 상자를 하나씩 뜯어 물건을 선반에 올렸다. 먹물 묻은 앞치마로 병마다 먼지를 훔치는 손이 신이 나 있었다."}, {"s": "q:ug_hongmae", "t": "어머, 조사원님! 마침 잘 오셨어요. 이것 좀 보세요. 선반 물건이 네 가지에서 여섯 가지가 됐어요."}, {"s": null, "t": "홍매댁이 맨 윗칸의 작은 병 둘을 손끝으로 톡톡 짚었다. 병마다 붉은 끈으로 값표가 매여 있었다."}, {"s": "q:ug_hongmae", "t": "대환단이랑 천령 감로예요. 이런 귀한 약이 이 먹비 나루까지 들어올 줄 누가 알았겠어요. 나루 넓히는 일에 조사원님들이 물건을 보태 주셔서 이런 것도 짐에 실려 온대요."}, {"s": null, "t": "부뚜막 쪽에서 국자로 솥전을 두드리는 소리가 땅땅 울렸다. 주막 아낙 묵창댁이 국자를 쥔 채 술청을 넘겨다보고 있었다."}, {"s": "q:sx_mk_jumak", "t": "선반 늘렸다고 내 부뚜막 쪽으로 한 뼘 넘어왔잖아! 부엌은 내 거고 술청이랑 선반은 네 거라고 했지!"}, {"s": null, "t": "홍매댁은 돌아보지도 않고 손을 휘휘 저었다."}, {"s": "q:ug_hongmae", "t": "한 뼘 가지고 또 그러신다. 조사원님, 저 언니는 이 주막 솥을 스무 해째 지키고, 저는 술상을 스무 해째 닦았어요. 그러니까 말다툼도 스무 해째예요."}, {"s": null, "t": "홍매댁이 선반 맨 아래 칸에서 손때 묻은 장부 한 권을 꺼냈다. 표지에 「선반 외상」이라고 적혀 있었다."}, {"s": "q:ug_hongmae", "t": "그런데 걱정이 하나 생겼어요. 물건이 비싸지면 외상도 늘 거잖아요. 그래서 이참에 외상 장부를 제대로 쓰려고요. 희수 서리님이 명등청 명부처럼 이름으로 적으래요."}, {"s": null, "t": "홍매댁이 장부를 펼쳐 보였다. 줄마다 이름 대신 「우물가 · 청심환 둘」, 「감나무 집 · 등잔 기름」, 「선창 끝 · 먹 한 덩이」 같은 글씨가 적혀 있었다."}, {"s": null, "t": "구석 서안에서 명부를 대조하던 서리 희수가 붓을 내려놓고 고개를 들었다."}, {"s": "q:mk_hisu", "t": "나루 주민 명부와 맞춰 보려 했는데, 장부에 사는 자리만 있어요. 사는 자리는 바뀌어도 이름은 안 바뀌니까요."}, {"s": null, "t": "홍매댁이 장부를 덮고 앞치마 자락을 손가락에 감았다. 처음으로 말끝이 작아졌다."}, {"s": "q:ug_hongmae", "t": "저는 손님 말은 한 마디도 안 잊어요. 누가 무슨 술을 시키고 누구 흉을 봤는지 다 외워요. 그런데 이름은…… 들은 적이 없어요. 다들 우물가, 감나무 집, 국밥집 영감 하고만 불렀으니까요."}, {"s": null, "t": "마침 국밥집 노인 덕배가 문간에 들어서다가 그 말을 듣고 걸음을 멈췄다."}, {"s": "q:sx_mk_gukbap", "t": "나 덕배야. 덕배. 그건 알지?"}, {"s": null, "t": "홍매댁이 덕배를 보고 손뼉을 짝 쳤다."}, {"s": "q:ug_hongmae", "t": "영감님 이름은 알죠. 하도 두 번씩 말씀하시니까요. 그러니까 이렇게 하려고요. 외상 갚으러 오시는 분이 이름을 대고 가시면 나물밥 한 그릇을 덤으로 드리는 거예요."}, {"s": null, "t": "부뚜막 쪽에서 묵창댁이 국자를 솥에 푹 꽂으며 코웃음을 쳤다."}, {"s": "q:sx_mk_jumak", "t": "내 솥에 손댈 생각은 마라. 내 쌀은 내 국밥 손님 거야."}, {"s": null, "t": "홍매댁이 묵창댁 쪽을 향해 혀를 쏙 내밀었다. 그러고는 나를 돌아보며 두 손을 모았다."}, {"s": "q:ug_hongmae", "t": "들으셨죠? 솥도 쌀도 못 빌려요. 쌀은 제 노정 건량을 풀면 돼요. 빈칸 벌판에 야령초가 지천이래요. 여섯 줌만 뜯어다 주세요. 나물밥은 제 술청 화로에서 어떻게든 해 볼게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_1', 2, '탄 냄비', '빈칸 벌판에서 야령초을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["herb"], "r": ["blank_field"], "n": 6}]}'::jsonb, '[{"s": null, "t": "야령초를 한 아름 뜯어 오니 술청에 탄내가 자욱했다. 홍매댁이 화로 앞에 쭈그려 앉아 시커먼 냄비를 들여다보고 있었다."}, {"s": "q:ug_hongmae", "t": "조사원님, 보지 마세요. 아니, 벌써 보셨네요."}, {"s": null, "t": "냄비 바닥에는 밥알이 새카맣게 눌어붙어 있었다. 홍매댁이 숟가락으로 박박 긁다가 숟가락까지 들러붙자 냄비째 내려놓았다."}, {"s": null, "t": "부뚜막 너머에서 묵창댁이 국자를 든 채 어깨를 들썩였다. 웃음을 참느라 얼굴이 벌게져 있었다."}, {"s": "q:sx_mk_jumak", "t": "스무 해 술상만 닦은 손이 밥을 하면 그렇게 돼. 내가 진작 말했잖아."}, {"s": null, "t": "홍매댁이 앞치마로 냄비 손잡이를 감싸 쥐고 묵창댁을 흘겨보았다."}, {"s": "q:ug_hongmae", "t": "언니가 솥을 안 빌려줘서 그렇잖아요!"}, {"s": null, "t": "그사이 문간에 사람들이 기웃거리기 시작했다. 홍매댁이 문밖 기둥에 붙여 둔 종이 때문이었다. 종이에는 「외상 갚으실 분, 이름을 대고 가시면 나물밥 한 그릇」이라고 적혀 있었다."}, {"s": null, "t": "맨 앞에는 우물가 아낙이 물동이를 내려놓고 서 있었다. 그 뒤로 감나무 집 노인과 선창 끝 뱃사람들이 줄을 섰다. 다들 탄내를 맡고 코를 찡그렸다."}, {"s": null, "t": "홍매댁이 냄비를 등 뒤로 감추며 줄을 내다보았다. 목소리가 울상이었다."}, {"s": "q:ug_hongmae", "t": "저 줄 좀 보세요. 밥이 없다고 하면 이름도 안 대고 돌아가실 거예요. 이름 한 자 듣는 게 이렇게 어려울 줄이야."}, {"s": null, "t": "희수가 서안에서 일어나 줄 선 사람을 세어 보았다. 손가락이 여섯에서 멈췄다가 일곱으로 넘어갔다."}, {"s": "q:mk_hisu", "t": "일곱 분입니다. 나물밥이 일곱 그릇은 있어야 해요."}, {"s": null, "t": "홍매댁이 희수를 한 번, 나를 한 번 보았다. 그러고는 아주 공손하게 냄비를 내 쪽으로 밀었다."}, {"s": "q:ug_hongmae", "t": "조사원님은 밥 하실 줄 아시죠? 원정 다니시면서 끼니는 지어 드셨을 거잖아요. 한 번 지으면 세 그릇이 나오니까, 세 번만 지어 주세요. 아홉 그릇이면 줄 선 분들 다 드리고도 남아요."}, {"s": null, "t": "줄 맨 끝에서 덕배가 손을 번쩍 들었다."}, {"s": "q:sx_mk_gukbap", "t": "나도 줄 섰어. 나도. 이름은 아까 댔으니까 밥만 주면 돼."}, {"s": null, "t": "묵창댁이 부뚜막에서 국자를 치켜들었다. 그러다 홍매댁 손에 들린 탄 냄비를 보고 혀를 끌끌 찼다."}, {"s": "q:sx_mk_jumak", "t": "조사원, 솥은 못 빌려줘도 불은 빌려줄게. 내 아궁이에 대고 지어. 그 냄비는 버리고."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_1', 3, '택호', '야령초 나물밥을(를) 만든다, 야령초 나물밥을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "craft", "items": ["herb_rice"], "n": 9}], "give": {"herb_rice": 9}}'::jsonb, '[{"s": null, "t": "나물밥을 그릇마다 퍼 담자 술청이 금세 고소한 냄새로 찼다. 홍매댁이 문간에 서서 한 사람씩 그릇을 건네고 장부에 붓을 댔다."}, {"s": null, "t": "우물가 아낙이 그릇을 받아 들고 잠깐 망설이다가 「온새미」라고 이름을 댔다. 홍매댁이 「우물가」 옆에 그 세 글자를 적고 붓을 멈췄다."}, {"s": "q:ug_hongmae", "t": "온새미. 스무 해를 「우물가」라고 불렀는데, 이렇게 고운 이름이었네요."}, {"s": null, "t": "이름을 대는 사람마다 홍매댁이 소리 내어 한 번 따라 부르고 장부에 적었다. 따라 부를 때마다 손님들이 멋쩍게 웃으며 고개를 끄덕였다."}, {"s": null, "t": "마지막 그릇이 나가자 희수가 장부를 넘겨받아 명부와 한 줄씩 맞춰 보았다. 그러다 맨 끝 줄에서 손가락을 멈췄다."}, {"s": "q:mk_hisu", "t": "한 줄이 비었어요. 이 주막 사람 줄이요. 홍매댁 님하고 묵창댁 님."}, {"s": null, "t": "홍매댁이 앞치마를 털다 말고 눈을 끔뻑였다."}, {"s": "q:ug_hongmae", "t": "그건 택호잖아요. 이름이 아니라…… 어머."}, {"s": null, "t": "홍매댁이 부뚜막 쪽을 돌아보았다. 묵창댁도 국자를 든 채 홍매댁을 보고 있었다. 두 사람의 입이 동시에 벌어졌다."}, {"s": "q:sx_mk_jumak", "t": "너…… 이름이 뭐였지?"}, {"s": null, "t": "홍매댁은 대답 대신 되물었다. 목소리가 반쯤 갈라져 있었다."}, {"s": "q:ug_hongmae", "t": "언니야말로요. 스무 해를 한 솥 옆에서 살았는데요."}, {"s": null, "t": "술청에 남아 있던 손님들이 숟가락을 멈추고 두 사람을 번갈아 보았다. 덕배가 나물밥을 입에 문 채 껄껄 웃었다."}, {"s": "q:sx_mk_gukbap", "t": "우리 나루 사람들이 다 그래. 다 그래. 먹비가 이름을 지우니까 아예 안 불렀지."}, {"s": null, "t": "묵창댁이 국자를 솥에 꽂고 성큼성큼 술청으로 넘어왔다. 한 뼘도 넘어오지 말라던 선반 앞이었다."}, {"s": null, "t": "묵창댁이 홍매댁의 귀에 대고 무언가를 말했다. 홍매댁도 묵창댁의 귀에 대고 무언가를 말했다."}, {"s": null, "t": "희수가 붓을 들고 기다렸지만 두 사람은 장부 쪽으로 돌아서지 않았다. 홍매댁이 볼을 붉힌 채 희수에게 손을 내저었다."}, {"s": "q:ug_hongmae", "t": "서리님, 그건 이따가요. 해 지고 나서 서로 불러 보고, 금빛이 닿으면 그때 적어 주세요."}, {"s": null, "t": "그날 밤 나는 주막 객방 문틈으로 술청을 내다보았다. 화로 앞에 두 사람이 마주 앉아 있었다. 홍매댁이 먼저 작게 무언가를 불렀고, 그 입김이 금빛 실로 엉겨 묵창댁의 가슴께에 닿았다."}, {"s": null, "t": "묵창댁은 한참 제 가슴을 손바닥으로 누르고 있었다. 그러다 국자도 없이 맨손으로 홍매댁의 등을 툭 쳤다. 이번에는 묵창댁이 불렀고, 금빛이 홍매댁에게로 건너갔다."}, {"s": null, "t": "이튿날 아침 희수가 장부 맨 끝 줄에 두 이름을 적었다. 나는 그 줄을 들여다보지 않았다. 희수가 장부를 덮고 나를 보았다."}, {"s": "q:mk_hisu", "t": "지름길이 열리면 철벽 고찰에서 장작이 들어온대요. 그 장부도 이름으로 적을 거예요. 다온이도 다음 장날엔 나루에 온다고 했고요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mk_2', 'side', '뒷이야기·묵창 나루', '고찰로 가는 길', '묵창 나루와 철벽 고찰 사이에 지름길이 났다. 다온이 홍매댁의 먹 꾸러미를 메고 혼자 고찰까지 가겠다고 나서고, 희수는 몰래 고갯길을 치워 달라고 부탁한다. 고찰 방명록에는 모서리가 접힌 채인 장이 하나 있다.', 'mukchang_ferry', 50, '{mdq_17,ep_mk_1}'::text[], null, 1521, '[]'::jsonb, true, null, null)
