delete from public.world_quest_steps where quest_id = 'ep_mk_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_2', 1, '혼자 가는 심부름', '혼자 가는 심부름', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "그사이 빙혼곡 고갯길에 「철벽 고찰 반나절」이라는 새 이정표가 섰다. 나루 사람들은 그 길을 지름길이라고 불렀다."}, {"s": null, "t": "주막 평상에서 다온이 보따리 끈을 묶고 있었다. 흑련 장부고에 가 있던 다온은 장날에 맞춰 나루 집에 돌아와 있었다. 보따리 안에는 기름종이로 싼 먹 덩이가 여럿 들어 있었다."}, {"s": null, "t": "처마 밑 기둥에는 월하가 기대 서서 오른손으로 엽전을 튕기고 있었다. 엽전이 손등에서 미끄러져 떨어지자, 다온이 고개도 들지 않고 주워 월하 손에 올려 주었다."}, {"s": null, "t": "월하가 엽전을 받아 쥐고 나를 보며 턱으로 다온을 가리켰다."}, {"s": "q:mk_wolha", "t": "왔어요, 조사원. 꼬맹이가 오늘 혼자 길 떠난대요. 말려도 안 들어요."}, {"s": null, "t": "다온이 보따리를 등에 메어 보며 턱을 치켜들었다."}, {"s": "q:mk_daon", "t": "혼자 가는 거 아니에요, {이름} 님. 길은 혼자지만 고찰엔 혜각 스님이 계시잖아요. 홍매댁 아주머니가 고찰에 먹을 보내기로 했대요."}, {"s": null, "t": "술청 문간에서 홍매댁이 앞치마를 털며 나왔다. 손에 접은 편지 한 장이 들려 있었다."}, {"s": "q:ug_hongmae", "t": "고찰 방명록에 쓸 먹이 떨어졌대요. 지난 동지에 손님이 하도 많이 왔다나요. 묵창 갈대 먹은 먹비에도 안 번지니까 고찰에서 제일 반가워한대요. 대신 고찰에선 장작을 보내 주기로 했어요."}, {"s": "q:ug_hongmae", "t": "빙혼곡 넘는 데 사흘 걸리던 길이 반나절이 됐잖아요. 그 길도 조사원님들이 나루 일에 손을 보태서 다졌대요. 그러니 이 편지는 꼭 조사원님 앞에서 보내고 싶었어요."}, {"s": null, "t": "다온이 보따리 끈을 한 번 더 조였다. 손끝이 조금 떨렸지만 목소리는 또렷했다."}, {"s": "q:mk_daon", "t": "빙혼곡 이정표 이제 다 읽혀요. 서당에서 배웠으니까요. 지름길로 가면 반나절이래요. 저 혼자 갈 수 있어요."}, {"s": null, "t": "구석 서안에서 희수가 명부를 덮고 일어섰다. 희수는 다온의 머리를 한 번 쓰다듬고, 나를 문밖으로 데리고 나갔다."}, {"s": "q:mk_hisu", "t": "조사원. 말린다고 들을 아이가 아니에요. 그런데 빙혼곡 고갯마루엔 아직 설원 늑대가 돌아요."}, {"s": "q:mk_hisu", "t": "다온이보다 먼저 가서 길을 좀 치워 주세요. 다온이는 모르게요. 알면 저한테 화낼 거예요. ……저 아이 화내면 오래가요."}, {"s": null, "t": "처마 밑의 월하가 엽전을 쥔 채 휘파람을 휘익 불었다. 우리 이야기를 다 들은 얼굴이었다."}, {"s": "q:mk_wolha", "t": "서리님, 꼬맹이 몰래 하는 일이면 나도 입 다물죠. 값은 나중에 국밥 한 그릇."}, {"s": null, "t": "희수가 월하를 흘겨보았다. 그러면서도 고개는 작게 끄덕였다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_2', 2, '고갯마루 이정표', '설원 늑대을(를) 물리친다', '{"at": ["frost_valley"], "tasks": [{"t": "win", "m": ["g_frost_valley"], "n": 8}]}'::jsonb, '[{"s": null, "t": "마지막 늑대가 눈밭으로 달아나자 고갯마루가 조용해졌다. 나는 새 이정표 옆 바위에 걸터앉아 숨을 골랐다. 소매에 늑대 털이 허옇게 붙어 있었다."}, {"s": null, "t": "한참 뒤 고갯길 아래에서 뽀드득뽀드득 눈 밟는 소리가 올라왔다. 다온이 보따리를 메고 한 걸음씩 올라오고 있었다. 볼이 새빨갰다."}, {"s": null, "t": "다온이 이정표 앞에서 멈춰 글자를 소리 내어 읽었다. 그러다 바위 위의 나를 보고 입을 떡 벌렸다."}, {"s": "q:mk_daon", "t": "{이름} 님! 왜 여기 있어요?"}, {"s": null, "t": "다온의 눈이 내 소매에 붙은 늑대 털로 내려갔다. 다온이 보따리를 내려놓고 허리에 두 손을 얹었다."}, {"s": "q:mk_daon", "t": "몰래 치웠죠! 서리님이 시켰죠! 혼자 간다고 했잖아요!"}, {"s": null, "t": "나는 나도 고찰에 볼일이 있어서 먼저 왔다고 했다. 다온이 눈을 가늘게 뜨고 나를 한참 노려보았다."}, {"s": "q:mk_daon", "t": "무슨 볼일이요?"}, {"s": null, "t": "나는 대답하지 못했다. 다온이 콧김을 흥 내뿜더니, 슬그머니 고갯길 아래를 돌아보았다. 길가에 문패 없는 오두막이 웅크리고 있었다."}, {"s": "q:mk_daon", "t": "……사실 저 오두막 앞에서 좀 무서웠어요. 서당 갈 때 늑대가 나왔던 데라서요. 그래서 이정표만 보고 왔어요. 「철벽 고찰 반나절」, 「철벽 고찰 반나절」 하고 외우면서요."}, {"s": null, "t": "다온이 바위로 기어 올라와 내 옆에 바짝 붙어 앉았다. 내 소매의 늑대 털을 하나씩 떼어 주는 손이 바빴다."}, {"s": "q:mk_daon", "t": "그러니까 반은 혼자 온 거예요. 반은 혼자 왔으니까, 나머지 반은 같이 가도 돼요. 그래야 셈이 맞아요."}, {"s": null, "t": "나는 그 셈은 누구한테 배웠느냐고 물었다. 다온이 늑대 털을 후 불어 날리며 히죽 웃었다."}, {"s": "q:mk_daon", "t": "아저씨요. 아저씨는 엽전은 자꾸 떨어뜨려도 셈은 안 틀려요."}, {"s": null, "t": "다온이 보따리를 다시 메고 고갯마루 너머를 가리켰다. 눈 덮인 산자락 아래로 고찰 지붕이 보였다."}, {"s": "q:mk_daon", "t": "혜각 스님이 빙어국 끓여 놓는대요. 가서 먹고 하룻밤 자고 가요. 내일 아침에 장작 짐을 받아야 하니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_2', 3, '접힌 모서리', '철벽 고찰에 간다, 철벽 고찰에서 쉰다', '{"at": ["iron_monastery"], "tasks": [{"t": "travel", "r": ["iron_monastery"], "n": 1}, {"t": "rest", "r": ["iron_monastery"], "n": 1}]}'::jsonb, '[{"s": null, "t": "고찰 부엌에서 수좌 혜각이 빙어국 두 그릇을 내왔다. 손목에 염주를 감은 채 국자를 쥐고 있었다. 다온이 보따리를 풀어 먹 덩이를 하나씩 꺼내 놓자 혜각이 그 위로 몸을 숙였다."}, {"s": "north_league:hyegak", "t": "허허, 맹 사람이 나루 손님을 데려왔군요. 아니, 손님이 맹 사람을 데려왔다고 해야겠지요. 앞장선 건 이 아이니까요.", "fac": "north_league", "spec": 1, "grp": 1}, {"s": "north_league:hyegak", "t": "허허, 나루 손님이 둘이나 왔군요. 아니, 하나가 하나를 데려왔다고 해야겠지요. 앞장선 건 이 아이니까요.", "fac_not": "north_league", "spec": 2, "grp": 1}, {"s": null, "t": "다온이 어깨를 으쓱하고 빙어국을 후후 불었다. 한 숟갈 떠먹더니 눈이 동그래졌다."}, {"s": "q:mk_daon", "t": "맛있어요! 나루 생선국이랑 달라요. 스님, 이거 묵창댁 아주머니한테 알려 줘도 돼요?"}, {"s": null, "t": "혜각이 웃으며 일어나 대웅전 구석에서 두꺼운 방명록 한 권을 들고 왔다. 표지가 손때로 반질반질했다."}, {"s": "north_league:hyegak", "t": "알려 주셔도 됩니다. 그 대신 먹 값으로 하나 받지요. 나루에서 처음 오신 손님이니 방명록에 이름을 남기고 가세요."}, {"s": null, "t": "다온이 붓을 쥐고 방명록을 넘기다가 한 장에서 손을 멈췄다. 그 장의 오른쪽 위 모서리가 반듯하게 접혀 있었다. 그 장에는 「정청 정리관 다녀감. 차가 좋았소.」라고 적혀 있었다."}, {"s": null, "t": "다온이 그 글씨를 한참 내려다보았다. 붓을 쥔 손이 무릎 위로 내려갔다."}, {"s": "q:mk_daon", "t": "……이거, 곶감 준 아저씨예요?"}, {"s": null, "t": "혜각이 염주를 한 알 굴리고 고개를 끄덕였다."}, {"s": "north_league:hyegak", "t": "소승은 그 모서리를 그 뒤로 한 번도 펴지 못했습니다. 다시 와서 펼쳐 보겠다는 뜻 같아서요. 그분은 다시 오지 않으셨지요."}, {"s": null, "t": "나는 그 사람이 장부 모서리를 접던 까닭을 다온에게 들려주었다. 다음 장을 넘기기 싫어서 접는다고 했었다. 그 사람의 장부에는 다음 장마다 다음 해에 거둘 이름이 적혀 있었다."}, {"s": null, "t": "다온은 문턱의 곶감을 발끝으로 밀어내던 그날처럼 입을 꾹 다물었다. 그러다 접힌 모서리를 손톱으로 조심조심 폈다."}, {"s": "q:mk_daon", "t": "이제 다음 장에는 거둘 이름이 없잖아요. 그러니까 넘겨도 돼요."}, {"s": null, "t": "다온이 장을 넘기고 빈 장 맨 위에 붓을 댔다. 「묵창 나루 다온 다녀감. 빙어국이 좋았어요.」 획 하나 흔들리지 않은 글씨였다."}, {"s": null, "t": "혜각이 그 줄을 오래 들여다보았다. 혜각은 국자를 내려놓고 염주를 두 손으로 모아 쥐었다."}, {"s": "north_league:hyegak", "t": "허허. 이 장부터는 소승도 편히 넘기겠습니다. 장작은 내일 아침 행자들 편에 지름길로 보내지요."}, {"s": null, "t": "다온이 붓을 내려놓고 나를 보며 씩 웃었다. 볼에 빙어국 김이 서려 있었다."}, {"s": "q:mk_daon", "t": "돌아갈 때도 반은 혼자 갈래요. 그리고 {이름} 님, 고찰엔 서신 받는 데가 있대요. 나루엔 없잖아요. 나루에도 생기면 좋겠어요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mk_3', 'side', '뒷이야기·묵창 나루', '나루 창고와 서신', '나루 선창 옆 옛 서리 곳간이 창고가 되고, 물건 서신을 받는 곳도 생겼다. 창이 먹비에 새는 창고를 함께 고치는 사이 나루 사람들이 칸마다 제 이름을 붙이고, 다온 앞으로 나루에서 받는 첫 물건 서신이 온다.', 'mukchang_ferry', 50, '{mdq_17,ep_mk_2}'::text[], null, 1522, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:mukjeok", "stage": 3}'::jsonb where quest_id = 'ep_mk_3';
delete from public.world_quest_steps where quest_id = 'ep_mk_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_3', 1, '새는 창고', '새는 창고', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "그사이 선창 옆 옛 서리 곳간에 새 지붕이 얹혔다. 문간에는 「나루 창고」라는 나무패가 걸렸고, 그 옆에 「서신 받는 곳」이라는 작은 패가 하나 더 달렸다."}, {"s": null, "t": "곳간 안에서 희수가 명부 궤짝을 두 팔로 끌어안고 서 있었다. 궤짝을 내려놓을 자리를 찾는 눈치였다. 천장 들보에서 먹빛 빗물이 똑, 똑 떨어졌다."}, {"s": "q:mk_hisu", "t": "조사원, 마침 오셨어요. 명부 궤짝을 이제야 주막 바닥에서 옮기나 했는데…… 창이 새요."}, {"s": null, "t": "희수가 턱으로 곳간 벽을 가리켰다. 창살 사이 창호지가 먹비에 녹아 너덜너덜했다. 창 아래 바닥에 검은 물이 고여 있었다."}, {"s": "q:mk_hisu", "t": "나루 넓히는 일에 물건을 넘겨 주신 분들 덕에 지붕까지는 얹었대요. 창은 나루 사람들 손으로 하라고 남겨 둔 모양이에요."}, {"s": null, "t": "뒤따라 들어온 다온이 희수 품의 궤짝을 보고 킥킥 웃었다."}, {"s": "q:mk_daon", "t": "서리님, 그 궤짝 {이름} 님이 앉아 있던 거잖아요. 서리님이 국 안 먹는다고 버틸 때요."}, {"s": null, "t": "희수가 궤짝을 끌어안은 채 귀 끝을 붉혔다. 대답 대신 창 쪽으로 몸을 돌렸다."}, {"s": "q:mk_hisu", "t": "창부터 새로 달아야겠어요. 노을 영감님 말로는 먹비 창호는 먹비 흑단으로 살을 대고 빈칸 한지를 발라야 안 녹는대요. 흑단은 결이 곧아서 비틀리지 않는다고요."}, {"s": null, "t": "선창에서 노를 손질하던 사공 노을 영감이 곳간 문간에 와 섰다. 영감은 손톱으로 창틀을 긁어 보고 혀를 찼다."}, {"s": "q:sx_mk_sagong", "t": "살은 내가 다듬어 주겠네. 흑단 두 토막이면 되네. 한지는 벌판 서리 짐에서 나오는 걸로 두 장. 나는 눈이 침침해서 종이는 못 바르네."}, {"s": null, "t": "다온이 손을 번쩍 들었다."}, {"s": "q:mk_daon", "t": "종이는 제가 바를게요! 아니, {이름} 님이 발라요. 저는 옆에서 풀 그릇 들고 있을게요."}, {"s": null, "t": "희수가 궤짝을 바닥 마른 자리에 겨우 내려놓고 허리를 폈다."}, {"s": "q:mk_hisu", "t": "흑단은 먹비 숲에, 한지는 빈칸 벌판에 있어요. 그동안 저는 창고 칸마다 붙일 이름패를 쓰고 있을게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_3', 2, '이름 붙은 칸', '먹비 숲에서 먹비 흑단을(를) 모은다, 빈칸 벌판에서 빈칸 한지을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["meokbi_ebony"], "r": ["meokbi_forest"], "n": 2}, {"t": "gather", "items": ["blank_hanji"], "r": ["blank_field"], "n": 2}]}'::jsonb, '[{"s": null, "t": "흑단과 한지를 들고 돌아오니 곳간 앞이 왁자했다. 나루 사람들이 저마다 보따리를 들고 줄을 서 있었다. 창고가 생겼다는 말이 하룻밤 새 나루를 한 바퀴 돈 모양이었다."}, {"s": null, "t": "홍매댁이 줄 맨 앞에서 술동이를 끌어안고 목을 길게 뺐다."}, {"s": "q:ug_hongmae", "t": "조사원님, 창은 언제 달아요? 비 새는 창고에 제 술을 맡길 순 없잖아요."}, {"s": null, "t": "곳간 안에서는 희수가 칸마다 붓으로 무언가를 적고 있었다. 벽을 따라 짠 나무 칸마다 작은 패가 하나씩 붙어 있었다."}, {"s": "q:mk_hisu", "t": "칸마다 맡긴 분 이름을 붙이고 있어요. 사는 자리로 붙이면 이사 가실 때 헷갈리니까요. 맡기실 분은 이름을 대세요."}, {"s": null, "t": "줄 선 사람들이 서로 눈치를 보다가 피식피식 웃었다. 홍매댁이 술동이를 고쳐 안으며 어깨를 쭉 폈다."}, {"s": "q:ug_hongmae", "t": "이름 대는 건 우리 주막에서 다들 연습했잖아요. 나물밥 먹으면서요. 제가 먼저 댈게요."}, {"s": null, "t": "노을 영감이 흑단을 받아 칼로 창살을 깎기 시작했다. 사각사각 대팻밥이 영감 발치에 쌓였다. 다온이 풀 그릇을 들고 내 곁에 쪼그려 앉았다."}, {"s": "q:mk_daon", "t": "{이름} 님, 이 창 다 만들면 서신도 진짜 이리로 와요? 물건도 와요? 고찰 서신 받는 데처럼요?"}, {"s": null, "t": "희수가 칸 패를 적던 붓을 멈추고 다온을 돌아보았다."}, {"s": "q:mk_hisu", "t": "와. 창고 문 연 날부터 물건 서신도 여기서 받을 수 있어. 대신 창이 새면 서신이 다 젖겠지."}, {"s": null, "t": "다온이 풀 그릇을 내 손에 덥석 쥐여 주었다."}, {"s": "q:mk_daon", "t": "그럼 빨리 만들어요. 젖으면 안 돼요."}, {"s": null, "t": "노을 영감이 깎아 낸 창살을 무릎 위에 맞춰 보더니 나에게 내밀었다. 손끝이 조금 떨렸다."}, {"s": "q:sx_mk_sagong", "t": "살 맞추고 종이 바르는 건 조사원 손이 낫겠네. 창틀은 내가 붙잡고 있겠네."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_3', 3, '첫 서신', '먹비 창호을(를) 만든다, 먹비 창호을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "craft", "items": ["hf_window_meokbi"], "n": 1}], "give": {"hf_window_meokbi": 1}}'::jsonb, '[{"s": null, "t": "노을 영감이 내가 짠 먹비 창호를 곳간 벽에 끼워 맞췄다. 영감이 창틀을 손바닥으로 탁탁 두드리자 창호지가 팽팽하게 울렸다. 그날 밤 먹비가 내렸지만 곳간 바닥에는 물 한 방울 고이지 않았다."}, {"s": null, "t": "이튿날 아침 「서신 받는 곳」 패 아래에 작은 꾸러미 하나가 놓여 있었다. 겉에 꾹꾹 눌러 쓴 글씨로 「묵창 나루 다온」이라고 적혀 있었다."}, {"s": null, "t": "다온이 꾸러미를 두 손으로 들고 한참 서 있었다. 뜯지도 못하고 겉에 적힌 제 이름만 손가락으로 따라 그었다."}, {"s": "q:mk_daon", "t": "나루로 온 서신은 처음이에요. 지금까진 장부고에서 제가 보내기만 했거든요."}, {"s": null, "t": "처마 밑에서 엽전을 굴리던 월하가 다가와 꾸러미를 기웃거렸다."}, {"s": "q:mk_wolha", "t": "누가 보냈는데? 흑련 셈꾼이면 뜯지 마, 꼬맹아. 그 사람들은 꾸러미에도 이자를 붙여."}, {"s": null, "t": "다온이 월하를 흘겨보고 매듭을 풀었다. 안에서 엿 두 가락과 접은 종이 한 장이 나왔다. 다온이 종이를 펴 소리 내어 읽었다."}, {"s": "q:mk_daon", "t": "「다온아. 백골 장터 엿이야. 하나는 너, 하나는 아저씨. 아저씨가 엽전 떨어뜨려서 속상해하면 엿 물려 줘. 오른손으로 꾹꾹 눌러 썼어. 단비.」"}, {"s": null, "t": "종이 맨 아래에는 반듯한 글씨로 한 줄이 더 적혀 있었다. 다온이 그 줄을 읽다가 웃음을 터뜨렸다."}, {"s": "q:mk_daon", "t": "「짐 수 — 엿 둘. 틀림없음. 여운비.」"}, {"s": null, "t": "월하가 엿 한 가락을 받아 들고 코끝을 찡그렸다. 그러면서도 엿을 소중하게 품에 넣었다."}, {"s": "q:mk_wolha", "t": "엿 장수 장부를 호송대장이 쓰는구나. 셈은 틀림없겠네."}, {"s": null, "t": "다온은 남은 엿 한 가락을 다시 종이에 싸서 창고 맨 아래 칸에 넣었다. 그 칸 패에는 희수의 반듯한 글씨로 「다온」이라고 적혀 있었다."}, {"s": "q:mk_daon", "t": "바로 안 먹을래요. 창고에 넣어 두고 하루에 한 번씩 꺼내 볼래요. 처음 받은 거니까요."}, {"s": null, "t": "희수가 그 칸 문을 닫아 주며 다온의 어깨를 짚었다. 그러고는 곳간 밖 선창을 내다보았다. 낯선 장사꾼 둘이 배에서 짐을 내리고 있었다."}, {"s": "q:mk_hisu", "t": "창고가 생기니 바깥 장사꾼들이 먼저 냄새를 맡네요. 다음엔 거래소를 세워 달라는 청이 올 거예요. 의뢰 게시판도요."}, {"s": null, "t": "희수가 붓대를 만지작거리며 한숨을 푹 쉬었다. 다온이 그 얼굴을 올려다보고 키득거렸다."}, {"s": "q:mk_hisu", "t": "……게시판 글씨는 또 제가 쓰게 되겠죠."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mk_4', 'side', '뒷이야기·묵창 나루', '의뢰 게시판', '나루에 거래소 천막과 마구간, 조사원 의뢰 게시판이 섰다. 나루 사람들의 의뢰를 대신 적어 주기만 하던 희수가 처음으로 제 의뢰를 붙이고, 낚시를 배우러 간 먹비 숲에서 출납 인장을 잃어버린다.', 'mukchang_ferry', 50, '{mdq_17,ep_mk_3}'::text[], null, 1523, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:mukjeok", "stage": 4}'::jsonb where quest_id = 'ep_mk_4';
delete from public.world_quest_steps where quest_id = 'ep_mk_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_4', 1, '머리글', '머리글', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "그사이 선창 어귀에 거래소 천막이 섰다. 그 옆 말뚝에는 고찰 지름길로 넘어온 나귀 두 마리가 매였다. 주막 앞 벽에는 노을 영감이 먹비 흑단으로 짠 새 게시판이 걸렸다."}, {"s": null, "t": "희수가 게시판 앞 걸상에 올라서서 붓을 들고 있었다. 판 맨 위에 「조사원 의뢰」 넉 자를 쓰는 중이었다. 획마다 정청 서식처럼 반듯했다."}, {"s": null, "t": "아래에서 올려다보던 홍매댁이 고개를 갸웃했다."}, {"s": "q:ug_hongmae", "t": "서리님, 글씨가 너무 관청 같아요. 저걸 보면 다들 외상 독촉장인 줄 알겠어요."}, {"s": null, "t": "희수가 붓을 든 채 홍매댁을 내려다보았다. 입술을 살짝 깨물었다."}, {"s": "q:mk_hisu", "t": "……정청 서식체밖에 못 써요. 이것도 연습한 거예요."}, {"s": null, "t": "게시판에는 벌써 의뢰 쪽지가 여럿 붙어 있었다. 「먹비 흑단 구함 — 덕배」, 「빈칸 한지 열 장 — 묵창댁」, 「나귀 먹일 짚 — 마구간」. 쪽지 글씨는 모두 희수의 글씨였다."}, {"s": null, "t": "다온이 쪽지들을 하나씩 소리 내어 읽다가 희수의 소매를 잡아당겼다."}, {"s": "q:mk_daon", "t": "서리님, 이거 다 서리님이 대신 써 준 거죠? 서리님 의뢰는 없어요?"}, {"s": null, "t": "희수가 걸상에서 내려오다 말고 멈칫했다."}, {"s": "q:mk_hisu", "t": "나는…… 부탁할 게 없어."}, {"s": null, "t": "홍매댁이 다온과 눈을 맞추더니 앞치마에 손을 닦고 희수의 팔짱을 꼈다."}, {"s": "q:ug_hongmae", "t": "거짓말. 지난번에 노을 영감님 선창에서 낚시하시는 걸 한참 보고 계셨잖아요. 제가 다 봤어요. 손님 눈길은 제가 하나도 안 놓쳐요."}, {"s": null, "t": "희수의 귀 끝이 붉어졌다. 희수는 한참 붓대를 만지작거리다가 빈 쪽지 한 장을 집어 들었다."}, {"s": null, "t": "희수가 쪽지에 천천히 「낚시 가르쳐 줄 분 — 보수는 국 한 그릇(제가 끓이지는 못합니다) — 희수」라고 적었다. 이번 글씨는 반듯하지 않고 조금 흔들렸다."}, {"s": null, "t": "희수가 그 쪽지를 게시판 맨 귀퉁이에 붙였다. 나는 붙이자마자 그 쪽지를 떼어 손에 쥐었다."}, {"s": null, "t": "희수가 걸상 위에서 얼굴이 빨개진 채 나를 내려다보았다."}, {"s": "q:mk_hisu", "t": "조사원이 떼실 줄 알았어요. 그래서 붙인 거예요. 먹비 숲 물가는 고기가 잘 문대요. 저는 낚싯대를 쥐어 본 적이 없어요. 옆에서 보면서 배울게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_4', 2, '잃어버린 인장', '먹비 숲에서 낚시를 한다', '{"at": ["meokbi_forest"], "tasks": [{"t": "fish", "r": ["meokbi_forest"], "n": 3}]}'::jsonb, '[{"s": null, "t": "먹비 숲 물가에서 희수는 내 옆에 쪼그려 앉아 찌만 들여다보았다. 세 번째로 낚싯대를 넘겨받았을 때 찌가 쑥 가라앉았다."}, {"s": "q:mk_hisu", "t": "무, 물었어요! 조사원, 이거 어떻게…… 당겨요? 감아요?"}, {"s": null, "t": "나는 희수의 손 위에 내 손을 얹고 함께 줄을 감았다. 손바닥만 한 물고기가 물 위로 펄떡 튀어 올랐다. 희수가 낚싯대를 놓칠 뻔하다가 두 손으로 꽉 붙들었다."}, {"s": null, "t": "물고기를 바구니에 넣자 희수가 두 손을 털며 벌떡 일어섰다. 처음 보는 큰 웃음이었다."}, {"s": "q:mk_hisu", "t": "제가 잡았어요. 정청에 들어간 뒤로 붓만 쥐고 살았는데, 이런 게 손에 남네요. 아직도 손바닥에서 퍼덕이는 것 같아요."}, {"s": null, "t": "희수가 버릇처럼 허리춤을 더듬었다. 그 손이 그대로 굳었다."}, {"s": "q:mk_hisu", "t": "인장이…… 없어요. 출납 인장이요. 늘 여기 차고 다니는데."}, {"s": null, "t": "희수의 얼굴에서 핏기가 싹 가셨다. 희수가 바구니를 엎을 듯이 뒤지고, 쪼그려 앉아 물가 자갈을 손으로 헤쳤다."}, {"s": "q:mk_hisu", "t": "나루 명부에 찍는 인장이에요. 그게 없으면 다온이 줄도, 창고 칸도, 아무것도……"}, {"s": null, "t": "나는 희수의 어깨를 붙잡아 일으켰다. 희수가 숨을 크게 한 번 들이쉬고 내 소매를 붙잡았다. 손이 덜덜 떨리고 있었다."}, {"s": "q:mk_hisu", "t": "물고기가 올라왔을 때 벌떡 일어섰어요. 그때 끈이 끊어졌나 봐요. 덩굴 쪽으로…… 굴러간 것 같아요."}, {"s": null, "t": "희수가 물가 너머 흑단 덩굴 숲을 보았다. 먹비에 젖은 덩굴들이 바람도 없는데 스르르 움직였다."}, {"s": "q:mk_hisu", "t": "같이 찾아 주세요. 혼자 찾으면 이 손이 떨려서 못 찾을 거예요. 이런 일은…… 처음이라서요."}, {"s": null, "t": "나는 희수에게 낚싯대를 도로 쥐여 주고 덩굴 쪽은 내가 앞장서겠다고 했다. 희수가 낚싯대를 두 손으로 꼭 끌어안고 고개를 끄덕였다."}, {"s": "q:mk_hisu", "t": "낚싯대는 안 놓칠게요. 인장은 놓쳤어도요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_4', 3, '본전', '먹비 숲에서 실마리를 찾는다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "clue", "r": ["meokbi_forest"], "n": 1}]}'::jsonb, '[{"s": null, "t": "인장은 물가 흑단 덩굴 뿌리 사이에 끼어 있었다. 덩굴 하나가 반짝이는 인장 끈을 휘감고 있다가, 내가 다가가자 스르르 풀고 숲속으로 물러났다."}, {"s": null, "t": "나루로 돌아오는 내내 희수는 인장을 두 손으로 감싸 쥐고 있었다. 주막 문간에 들어서서야 희수의 어깨가 아래로 툭 떨어졌다."}, {"s": null, "t": "평상에 앉아 있던 다온이 벌떡 일어나 희수에게 달려왔다."}, {"s": "q:mk_daon", "t": "서리님! 낚시 했어요? 몇 마리요?"}, {"s": null, "t": "희수가 바구니를 내밀었다. 물고기는 한 마리였다. 다온이 바구니 안을 들여다보고 눈을 동그랗게 떴다."}, {"s": "q:mk_daon", "t": "한 마리요? 하루 종일요?"}, {"s": null, "t": "처마 밑에서 엽전을 굴리던 월하가 킥 웃었다. 엽전이 또 손등에서 미끄러졌고, 다온이 고개도 돌리지 않고 주워 월하 손에 쥐여 주었다."}, {"s": "q:mk_wolha", "t": "한 마리 잡고 인장 잃어버렸다가 도로 찾아왔다는 얼굴이네. 셈으로 치면 본전이에요, 서리님."}, {"s": null, "t": "희수가 월하를 노려보았다. 그러다 참지 못하고 웃음을 터뜨렸다. 웃다가 인장을 쥔 손등으로 눈가를 꾹 눌렀다."}, {"s": "q:mk_hisu", "t": "본전 맞아요. 아니, 남았어요. 처음으로…… 놀았으니까요."}, {"s": null, "t": "홍매댁이 바구니에서 물고기를 꺼내 부뚜막으로 가져갔다. 둘이 한참 소곤대더니 묵창댁이 국자를 번쩍 들었다."}, {"s": "q:sx_mk_jumak", "t": "서리님 보수는 내가 끓여 준다! 국 한 그릇! 이번엔 식기 전에 먹어!"}, {"s": null, "t": "희수는 대답 대신 게시판 앞으로 가서 제 쪽지를 다시 붙였다. 그 아래에 「다음엔 인장을 주막에 맡기고 감.」이라는 한 줄을 덧붙여 적었다."}, {"s": null, "t": "거래소 천막 쪽에서 바깥 장사꾼 하나가 월하에게 값을 묻고 있었다. 월하는 엽전을 튕기며 장사꾼 쪽으로 걸어가다 말고 나를 돌아보았다."}, {"s": "q:mk_wolha", "t": "거래소 셈은 내가 좀 봐 줘야겠네. 거둠꾼은 그만뒀어도 값 매기는 눈은 안 그만뒀거든요."}, {"s": null, "t": "선창 쪽에서는 노을 영감이 나귀 고삐를 쥐고 투덜거리며 걸어왔다. 나귀가 영감의 노 자루를 우물우물 씹고 있었다."}, {"s": "q:sx_mk_sagong", "t": "다들 나귀 타고 고찰 가겠다니 내 배는 누가 타나. 낙성 날엔 새 배 한 척 띄울 걸세. 나루가 넓어지면 배도 하나는 늘어야지."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_mk_5', 'side', '뒷이야기·묵창 나루', '넓어진 나루', '묵창 나루 넓히기가 끝나는 날. 나루 말뚝마다 먹등을 달고 이름 적은 한지를 빨래처럼 넌다. 노을 영감의 새 배가 뜨고, 월하는 빈 한지를 들고 서 있다가 엽전을 떨어뜨린다.', 'mukchang_ferry', 50, '{mdq_17,ep_mk_4}'::text[], null, 1524, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "c:mukjeok", "stage": 5}'::jsonb where quest_id = 'ep_mk_5';
delete from public.world_quest_steps where quest_id = 'ep_mk_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_5', 1, '줄에 널 한지', '줄에 널 한지', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "그사이 선창 대장간 화덕에 처음으로 불이 제대로 붙었다. 노을 영감이 새로 벼린 쇠못을 한 움큼 쥐고, 선창 끝에 엎어 놓은 새 배 쪽으로 걸어갔다."}, {"s": null, "t": "선창 말뚝 사이에는 굵은 줄이 여러 가닥 걸려 있었다. 다온이 줄 아래를 뛰어다니며 말뚝 수를 세고 있었다."}, {"s": "q:mk_daon", "t": "{이름} 님! 오늘 낙성이에요. 말뚝마다 먹등을 달고, 줄에는 이름 적은 한지를 널 거예요. 빨래처럼요. 나루 사람 이름 다요."}, {"s": null, "t": "희수가 명부를 품에 안고 선창으로 나왔다. 명부 갈피마다 종이쪽지가 삐죽삐죽 끼워져 있었다."}, {"s": "q:mk_hisu", "t": "나루 사람이 백열둘이에요. 외상 장부 덕에 이름은 다 모았어요. 그런데 한지가 모자라요. 창고에 있던 걸 다 꺼냈는데도 쉰 장이 비어요."}, {"s": null, "t": "처마 밑에서 엽전을 튕기던 월하가 줄을 올려다보며 혀를 찼다."}, {"s": "q:mk_wolha", "t": "빈칸 벌판 서리 짐을 통째로 털어 와야겠네. 하루 다녀와서는 쉰 장 못 채워요. 조사원, 며칠 묵을 셈으로 다녀와요. 꼬맹이가 줄 다 널 때까지 내가 말뚝 지킬게."}, {"s": null, "t": "다온이 월하를 돌아보며 눈을 가늘게 떴다."}, {"s": "q:mk_daon", "t": "아저씨는 맨날 지키기만 해요. 오늘은 한지 너는 것도 해요."}, {"s": null, "t": "선창 끝에서 노을 영감이 새 배 밑창에 쇠못을 땅땅 박다가 고개를 들었다."}, {"s": "q:sx_mk_sagong", "t": "해 지기 전에 밑창을 다 박아야 하네. 한지 널 줄은 내 배 돛대에도 하나 걸게."}, {"s": null, "t": "대장간 쪽에서 묵창댁이 구멍 난 국솥을 끌어안고 나오다가 나를 보고 소리쳤다."}, {"s": "q:sx_mk_jumak", "t": "조사원! 대장간에서 솥을 바깥 값으로 때워 준대! 먼 데까지 지고 안 가도 되고! 이게 다 나루 일에 손 보탠 사람들 덕이라더라!"}, {"s": null, "t": "희수가 명부를 고쳐 안고 나를 보았다. 갈피 사이 쪽지 하나가 바람에 팔랑거렸다."}, {"s": "q:mk_hisu", "t": "한지는 넉넉히 부탁드려요. 저는 그동안 이름을 쪽지에서 한지로 옮겨 적을 준비를 할게요. 오늘은 한 줄도 틀리면 안 되니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_5', 2, '빈 한지', '빈칸 벌판에 원정을 다녀온다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "expedition", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "원정에서 돌아와 짐 보따리를 선창에 풀었다. 빈칸 한지가 두툼하게 쌓이자 나루 사람들이 우르르 몰려들었다."}, {"s": null, "t": "희수가 한지마다 이름을 하나씩 적었다. 다온이 받아 들고 소리 내어 읽은 뒤 줄에 널었다. 홍매댁은 집게를 나눠 주며 쉴 새 없이 떠들었다."}, {"s": "q:ug_hongmae", "t": "온새미네는 우물 쪽 줄, 덕배 영감님은 국밥집 앞 줄이요. 주막 줄은 맨 앞이에요. 제가 제일 먼저 이름 댄 사람이니까요."}, {"s": null, "t": "부뚜막에서 국솥을 젓던 묵창댁이 국자를 든 채 쫓아 나왔다."}, {"s": "q:sx_mk_jumak", "t": "먼저 댄 건 나거든! 네 귀에 먼저 댄 게 나야!"}, {"s": null, "t": "두 사람이 줄 앞에서 티격태격하는 사이, 월하가 혼자 줄 끝 말뚝 아래에 서 있었다. 월하 손에는 빈 한지 한 장이 들려 있었다."}, {"s": null, "t": "월하는 오른손으로 한지를 줄에 대고 왼손으로 집게를 집으려 했다. 새끼손가락 두 마디가 없는 왼손에서 집게가 자꾸 미끄러졌다."}, {"s": null, "t": "그러다 품에 넣어 둔 엽전이 짤랑 떨어져 자갈 위를 데굴데굴 굴렀다. 다온이 줄 아래로 뛰어와 엽전을 주웠다."}, {"s": null, "t": "다온은 엽전을 월하 손에 쥐여 주지 않고 한지부터 들여다보았다. 한지는 비어 있었다."}, {"s": "q:mk_daon", "t": "아저씨, 이름 안 썼어요?"}, {"s": null, "t": "월하가 빈 한지를 내려다보며 피식 웃었다. 엽전을 받으려고 내민 손이 허공에 멈춰 있었다."}, {"s": "q:mk_wolha", "t": "뭘 써. 「월하」는 호칭이고, 진짜는 꼬맹이랑 나만 알잖아. 줄에 널면 나루 사람이 다 보는데."}, {"s": null, "t": "다온이 엽전을 꼭 쥔 채 한참 생각하더니, 희수에게 붓을 빌렸다. 다온은 한지 위쪽에 「월하」 두 글자를 작게 쓰고, 그 아래를 비워 두었다."}, {"s": "q:mk_daon", "t": "위에는 다들 부르는 거, 아래는 비워 두는 거예요. 비워 둔 데는 제가 밤에 불러 줄게요. 아무한테도 안 들리게요."}, {"s": null, "t": "월하가 다온을 오래 보았다. 그러고는 엽전을 받는 대신 한지를 받아 들었다."}, {"s": "q:mk_wolha", "t": "……꼬맹이 셈은 늘 나보다 낫네."}, {"s": null, "t": "홍매댁이 집게 바구니를 끼고 줄 사이를 오가다 내 앞에 멈춰 섰다. 묵창댁과의 말다툼은 어느새 끝나 있었다."}, {"s": "q:ug_hongmae", "t": "조사원님, 오늘부터 선반에 물건을 되파시면 바깥 값으로 쳐 드려요. 조사원님 별채도 이제 나루에서 고치실 수 있고요. 배 띄우는 건 해 지고 나서래요. 원정 다녀오셨으니 그때까지 주막 객방에서 좀 쉬세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_mk_5', 3, '따순 배', '묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "해가 지자 다온이 말뚝마다 달린 먹등에 불을 붙이고 다녔다. 불이 하나씩 켜질 때마다 줄에 널린 한지가 아래에서부터 노랗게 비쳤다. 백열두 장의 이름이 강바람에 펄럭펄럭 흔들렸다."}, {"s": null, "t": "홍매댁이 덕배의 한지를 올려다보며 「덕배 영감님」 하고 불렀다. 홍매댁의 입김이 금빛 실로 엉겨 덕배의 가슴께에 닿았다."}, {"s": null, "t": "덕배가 제 가슴을 손바닥으로 문지르며 껄껄 웃었다."}, {"s": "q:sx_mk_gukbap", "t": "따뜻하네. 따뜻해. 두 번 말 안 해도 알아듣네."}, {"s": null, "t": "선창 끝에서 노을 영감이 새 배를 물가로 밀었다. 나루 사람들이 달라붙어 함께 밀자 배가 스르르 먹빛 강물 위로 미끄러졌다. 뱃머리에는 아직 아무 글자도 없었다."}, {"s": "q:sx_mk_sagong", "t": "이 배 이름은 내가 안 짓겠네. 우리 배는 할멈이 지었지. 이 배는 이 나루가 짓게."}, {"s": null, "t": "사람들이 저마다 한마디씩 떠드는 사이 다온이 희수의 소매를 잡아당겼다. 희수가 고개를 끄덕이고 붓을 다온에게 건넸다."}, {"s": null, "t": "다온이 뱃머리 앞에 쪼그려 앉아 이름 먹으로 세 글자를 적었다. 「따순 배」였다."}, {"s": "q:mk_daon", "t": "엄마 노래에 나오는 말이에요. 따순 국, 따순 손. 이 배 타는 사람은 다 따숩게 건너가라고요."}, {"s": null, "t": "묵창댁이 국자를 쥔 채 코를 훌쩍였다. 홍매댁이 앞치마로 묵창댁의 눈가를 훔쳐 주다가 제 눈가도 훔쳤다."}, {"s": null, "t": "줄 끝 말뚝 아래에서는 월하가 제 한지를 매달고 있었다. 오른손으로 집게를 꽂는 동안 엽전이 또 손등에서 미끄러져 강둑으로 굴렀다."}, {"s": null, "t": "다온이 달려가 엽전을 주웠다. 다온은 엽전을 월하 손에 돌려주지 않고 한지 귀퉁이 끈에 단단히 매달았다. 무게추가 된 엽전이 바람에 달랑달랑 흔들렸다."}, {"s": "q:mk_daon", "t": "이제 안 떨어져요. 바람이 불어도요."}, {"s": null, "t": "월하가 빈손을 내려다보다 다온의 머리를 아홉 손가락으로 헝클었다."}, {"s": "q:mk_wolha", "t": "그럼 나는 이제 뭘 튕기냐, 꼬맹아."}, {"s": null, "t": "희수가 명부를 펼쳐 맨 끝 장에 「묵창 나루 — 넓힘 마침. 여러 조사원이 손을 보탬. 배 한 척 늘어남.」이라고 한 줄을 적었다."}, {"s": null, "t": "희수가 붓을 내려놓고 나루 사람들 손에 낙성 떡을 하나씩 쥐여 주었다. 내 손에 떡을 얹을 때 희수가 아주 작게 웃었다."}, {"s": "q:mk_hisu", "t": "조사원. 오늘은 명부 안 보고 떡 먹을 거예요. 쉬는 날이니까요."}, {"s": null, "t": "그날 밤 먹빛 강 위로 먹등 불빛과 백열두 장의 이름이 함께 흔들렸다. 다온이 줄 끝 한지를 올려다보며 입술만 달싹이는 것이 보였다."}, {"s": null, "t": "소리는 들리지 않았다. 다만 다온의 입김이 금빛 실 한 올로 엉겨, 엽전 아래 빈칸을 스치고 월하의 가슴께로 가늘게 이어졌다."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_night_1', 'side', '뒷이야기·백등 야시장', '야시장 어귀의 주춧돌', '정청 본채를 명등청에 내준 정통파가 백등 야시장 어귀 옛 순라 막 자리에 청사를 세운다. 첫 주춧돌을 혼자 들다 허리를 삐끗한 교관 강두철 대신 조사원이 주춧돌에 두를 쇠를 마련한다. 주춧돌에는 옛 순라꾼들이 긁어 둔 이름이 남아 있다.', 'lantern_market', 50, '{mdq_17}'::text[], null, 1525, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:night_office", "stage": 1}'::jsonb where quest_id = 'ep_night_1';
delete from public.world_quest_steps where quest_id = 'ep_night_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_1', 1, '허리 삐끗한 교관', '허리 삐끗한 교관', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "해가 지자 백등 야시장 골목마다 등이 하나씩 켜졌다. 등 아래 좌판에서 국밥 솥이 김을 올렸고, 엿장수 가위 소리가 짤깍짤깍 골목을 건너왔다."}, {"s": null, "t": "시장 어귀 빈터에는 등 대신 횃불이 꽂혀 있었다. 잡초 사이로 네모난 돌 자국이 드문드문 드러나 있었다. 오래전에 무언가 서 있던 자리였다."}, {"s": null, "t": "빈터 한가운데서 연무청 수련생 여럿이 굵은 밧줄로 사람 몸통만 한 돌을 끌고 있었다. 맨 앞에서 밧줄을 어깨에 걸친 사내가 목청을 높였다."}, {"s": "night_office:kang", "t": "하나, 둘, 영차! 다리로 당겨라, 다리로! 팔로 당기는 놈은 내일 아침에 숟가락도 못 든다!"}, {"s": null, "t": "돌이 드르륵 끌려와 구덩이 가장자리에 멎었다. 사내가 밧줄을 내려놓더니 돌 밑에 두 손을 넣고 끙, 하고 혼자 들어 올렸다."}, {"s": null, "t": "돌이 구덩이에 쿵 내려앉는 순간 사내의 허리에서 뚝 소리가 났다. 사내가 돌을 내려놓은 자세 그대로 굳었다."}, {"s": "night_office:kang", "t": "…어? 어어? 이놈들아, 웃지 마라! 아직 안 아프다! 곧 아플 거다!"}, {"s": null, "t": "수련생들이 입을 틀어막고 어깨를 들썩였다. 나는 사내 곁으로 달려가 겨드랑이를 받쳤다. 팔괘 연무청 교관 강두철이었다."}, {"s": "night_office:kang", "t": "아이고, 하하… {등급}, 마침 잘 왔다. 우리 청사 주춧돌이 첫날부터 사람을 잡는구나. 허리 좀 받쳐 다오. 그래, 거기.", "fac": "night_office", "rank": [1, 4], "spec": 0, "grp": 1}, {"s": "night_office:kang", "t": "아이고, 하하… 판관 나리께서 오셨소? 마침 잘 오셨소. 우리 청사 주춧돌이 첫날부터 사람을 잡는구려. 공사판에선 판관도 일꾼이니 오늘은 말 좀 놓겠소! 허리 좀 받쳐 다오. 그래, 거기.", "fac": "night_office", "rank": [5, 5], "spec": 0, "grp": 1}, {"s": "night_office:kang", "t": "아이고, 하하… 조사원, 남의 집 공사판에 마침 잘 왔다. 구경 값은 손으로 받는다! 허리 좀 받쳐 다오. 그래, 거기.", "fac_not": "night_office", "spec": 2, "grp": 1}, {"s": null, "t": "나는 강두철을 빈터 가장자리 평상에 엎드리게 했다. 강두철이 엎드린 채 턱으로 빈터를 가리켰다."}, {"s": "night_office:kang", "t": "여기가 옛 순라 막 자리다. 옛날엔 도성 밤 순라가 이 막에서 등을 받아 들고 나갔지. 주춧돌 자국이 아직 남아 있더구나."}, {"s": null, "t": "나는 왜 정청이 아니라 야시장에 청사를 세우느냐고 물었다. 강두철이 엎드린 채 한 팔을 휘저었다."}, {"s": "night_office:kang", "t": "정청 본채는 이제 명등청 거다. 일곱 무리가 같이 쓰는 집에 정통파 짐만 잔뜩 쌓아 둘 수는 없잖나. 판관들이 반나절을 다투다가, 순라가 처음 나가던 데에 짓자고 정했다."}, {"s": "night_office:kang", "t": "순라꾼 대기방, 수련 마당, 우리 몫 장부를 둘 서가. 그거면 된다. 도제조 방은… 안 짓는다. 앉으실 분이 없으니까."}, {"s": null, "t": "강두철의 목소리가 그 대목에서 잠깐 낮아졌다. 강두철은 곧 헛기침을 하고 다시 목청을 돋웠다."}, {"s": "night_office:kang", "t": "문제는 저 돌이다. 옛 주춧돌이 반은 쩍쩍 갈라졌어. 쇠 띠를 둘러야 기둥을 받는다. 그런데 내가 이 꼴이니 월철을 캐러 갈 수가 없지."}, {"s": null, "t": "좌판 쪽에서 허리 굽은 노파 하나가 약 보따리를 들고 걸어왔다. 야시장 약방 할멈 고분이었다. 고분이 강두철의 허리를 손바닥으로 철썩 쳤다."}, {"s": "q:dh_gopun", "t": "그러게 혼자 들지 말라고 했수, 안 했수? 교관 나리 허리는 쉰 넘은 허리유. 고약 붙이고 사흘은 누워 있으우."}, {"s": "night_office:kang", "t": "사흘이라니! 할멈, 그사이에 기둥이 혼자 선답니까!"}, {"s": null, "t": "고분은 대꾸 없이 강두철의 저고리를 걷어 올렸다. 시커먼 고약이 허리에 철퍽 붙자 강두철이 으악 소리를 질렀다."}, {"s": null, "t": "나는 그 틈에 월철을 대신 캐 오겠다고 했다. 강두철이 고개만 돌려 나를 보았다."}, {"s": "night_office:kang", "t": "…고맙다. 들녘 바위틈에 월철 광석이 드러난 데가 있다. 넉넉히 캐 와라. 요즘 들녘 들쥐 떼가 수련생들 밧줄을 쏠아 놔서 애들이 못 나간다. 오는 길에 그놈들도 좀 쫓아 주고."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_1', 2, '쇠 띠', '잿빛 들녘에서 월철 광석을(를) 모은다, 잿빛 들녘의 요괴를 물리친다', '{"at": ["lantern_market"], "tasks": [{"t": "gather", "items": ["ore"], "r": ["field_outskirts"], "n": 6}, {"t": "win", "r": ["field_outskirts"], "n": 6}]}'::jsonb, '[{"s": null, "t": "월철 광석 자루를 내려놓자 수련생들이 우르르 몰려와 자루 속을 들여다보았다. 강두철은 아직 평상에 엎드린 채였다. 등에 붙인 고약 냄새가 빈터까지 풍겼다."}, {"s": "night_office:kang", "t": "오, 결이 곱다! 들쥐 떼는? 다 쫓았나? 그럼 내일부터는 애들이 밧줄을 새로 안 꼬아도 되겠구나."}, {"s": null, "t": "수련생 하나가 자루 곁에 쪼그려 앉아 광석을 하나 집어 들었다. 열대여섯쯤 된 앳된 얼굴이었다."}, {"s": "q:sx_ep_trainee", "t": "교관님, 이걸 어떻게 주춧돌에 둘러요? 돌에 쇠를 붙이는 법은 안 배웠는데요."}, {"s": "night_office:kang", "t": "그러니까 배우는 거다! 광석은 녹여서 주괴로 만들고, 주괴를 두들겨 띠로 편다. 띠는 달군 채로 두르고, 식으면서 조인다. 사람 허리처럼."}, {"s": null, "t": "강두철이 제 허리를 두드리다 으윽 신음을 삼켰다. 수련생이 키득 웃다가 강두철과 눈이 마주쳐 얼른 입을 다물었다."}, {"s": null, "t": "나는 주춧돌 곁으로 가서 갈라진 금을 손끝으로 쓸어 보았다. 금 사이에 오래된 글씨가 몇 자 남아 있었다. 비바람에 닳아 반쯤 지워진 사람 이름들이었다."}, {"s": null, "t": "내가 글씨를 들여다보는 것을 보고 강두철이 평상에서 고개를 쳐들었다."}, {"s": "night_office:kang", "t": "그거 봤나. 옛 순라꾼들 이름이다. 순라를 나가는 날 주춧돌에 제 이름을 긁고 나갔다더군. 돌아오면 그 옆에 금을 하나 긋고."}, {"s": "night_office:kang", "t": "내 스승님도 그러셨다. 연무청 기둥에 부순 목인 수를 칼자국으로 새긴 게 다 그 버릇에서 나온 거다. 나도 그대로 배웠고."}, {"s": null, "t": "나는 옆에 금이 없는 이름이 몇이나 되느냐고 물었다. 강두철은 한참 대답하지 않다가 고개를 돌렸다."}, {"s": "night_office:kang", "t": "…세어 보지 마라. 오늘은 세지 말고 띠를 둘러라. 다 두르면 그 이름들도 새 청사 밑에 깔린다. 깔려 있으면 밟히는 게 아니라 받치는 거다. 순라 막은 원래 그런 데였어."}, {"s": null, "t": "고분이 국밥 두 그릇을 쟁반에 받쳐 들고 왔다. 고분은 한 그릇을 평상 머리맡에, 한 그릇을 내 앞에 놓았다."}, {"s": "q:dh_gopun", "t": "교관 나리는 엎드려서 드시우. 조사원도 먹고 하우. 쇳물 붓는 사람이 빈속이면 손이 떨려."}, {"s": null, "t": "나는 국밥을 비우고 소매를 걷었다. 강두철이 엎드린 채 손가락 둘을 펴 보였다."}, {"s": "night_office:kang", "t": "주괴 둘이면 띠 둘이 나온다. 만들어서 애들한테 넘겨 줘라. 두르는 건 애들이 한다. 나는 누워서 소리나 질러 주마."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_1', 3, '첫 초롱', '월철 주괴을(를) 만든다, 월철 주괴을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "craft", "items": ["iron_ingot"], "n": 2}], "give": {"iron_ingot": 2}}'::jsonb, '[{"s": null, "t": "수련생들이 주괴를 두들겨 편 쇠 띠를 화덕에 달구었다. 둘이 집게로 띠 양 끝을 들고 주춧돌에 둘렀다."}, {"s": "night_office:kang", "t": "왼쪽! 아니, 네 왼쪽 말고 돌 왼쪽! 놓지 마라, 식을 때까지!"}, {"s": null, "t": "수련생 둘이 어깨를 부딪치며 집게를 고쳐 잡았다. 쇠가 식으면서 치이익 김을 뿜었고, 갈라진 돌이 쇠 띠 안에서 꽉 조여졌다. 마지막 띠가 제자리에 감기자 빈터에서 환호성이 터졌다."}, {"s": null, "t": "그때 시장 안쪽 상점 앞에서 고분의 언성 높은 목소리가 들려왔다. 나와 강두철이 동시에 그쪽을 돌아보았다."}, {"s": "q:dh_gopun", "t": "회춘단이랑 안신탕을 상점에 들였다고? 청사 짓는 덕에 정통파 조사원한테 판다고? 그럼 내 약방 손님은 다 어디로 가우!"}, {"s": null, "t": "상점 주인이 손사래를 치며 무어라 변명했다. 고분이 씩씩거리며 빈터로 돌아오자 강두철이 평상에서 껄껄 웃었다."}, {"s": "night_office:kang", "t": "할멈, 회춘단은 할멈 약방에서 안 짓잖습니까. 할멈 고약은 상점이 못 팔고요. 이 허리가 증인입니다!"}, {"s": "q:dh_gopun", "t": "…그건 그렇수. 내 고약은 아무도 못 흉내 내지."}, {"s": null, "t": "고분이 금세 누그러져 고약 보따리를 끌어안았다. 강두철이 그제야 평상을 짚고 천천히 일어섰다. 허리는 반쯤 굽었지만 얼굴은 환했다."}, {"s": null, "t": "등롱 장인 마일수가 장대 하나를 메고 빈터로 들어왔다. 장대 끝에 푸른 비단을 씌운 초롱 하나가 매달려 있었다."}, {"s": "q:dh_ilsu", "t": "청사가 서면 처마 끝에 청사초롱을 달아야 하오. 처마가 아직 없으니 오늘은 장대에 다는 거요. 이 청사의 첫 초롱이오."}, {"s": null, "t": "마일수가 장대를 주춧돌 곁에 세웠다. 푸른 초롱 불빛이 쇠 띠를 두른 돌 위에 내려앉았다. 반쯤 지워진 순라꾼들 이름이 불빛 아래 희미하게 떠올랐다."}, {"s": "night_office:kang", "t": "주춧돌 하나에 초롱 하나라. 아직 지붕도 없는데 벌써 청사 같구나."}, {"s": "night_office:kang", "t": "여러 조사원이 사업에 월철이며 부적을 넘겨 준 덕에 판관들이 공사를 허락했다. 그 사람들 몫까지 이 돌이 받칠 거다. 오늘 네가 두른 띠도 거기 들고."}, {"s": null, "t": "강두철이 나를 돌아보다가 이마를 찡그렸다. 다음 일이 떠오른 얼굴이었다."}, {"s": "night_office:kang", "t": "기둥이 서면 장서각에서 우리 몫 사본을 옮겨 와야 한다. 그걸 맡을 사람이 기록관인데, 기록관 손이 그리되셨으니 걱정이다. 그때도 좀 와 줄 테냐?"}, {"s": null, "t": "나는 오겠다고 했다. 강두철이 굽은 허리를 짚은 채 주춧돌 곁에 쪼그려 앉았다. 강두철은 쇠 띠 옆 돌에 손톱으로 짧은 금 하나를 그었다."}, {"s": "night_office:kang", "t": "이건 오늘 몫이다. 순라 막을 다시 연 날."}, {"s": null, "t": "수련생들이 하나둘 그 곁에 쪼그려 앉아 저마다 손톱으로 금을 그었다. 짧은 금들이 옛 이름들 곁에 나란히 늘어섰다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_night_2', 'side', '뒷이야기·본부 객사', '굳은 손의 이삿짐', '장서각이 명등청 서고가 되면서 정통파 몫 사본을 새 청사로 옮긴다. 손이 굳은 모가람이 서가 순서를 외워 부르고 곽두칠이 받아 적는다. 잃어버린 상자 둘에서 한설이 몰래 모아 둔 「신입 첫 장부」가 나오고, 야시장 사람들이 등을 들고 이삿짐 행렬을 비춘다.', 'hq_dorm', 50, '{mdq_17,ep_night_1}'::text[], null, 1526, '[]'::jsonb, true, null, null)
