update public.world_quests set open_req = '{"project": "f:night_office", "stage": 2}'::jsonb where quest_id = 'ep_night_2';
delete from public.world_quest_steps where quest_id = 'ep_night_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_2', 1, '서가 순서', '서가 순서', '{"at": ["hq_dorm"]}'::jsonb, '[{"s": null, "t": "야시장 어귀 청사에 기둥이 다 섰고, 기록관이 객사에서 기다린다는 기별이 왔다. 본부 객사로 건너가니 그사이 계절이 한 번 바뀌어 마당의 감나무 잎이 붉게 물들어 있었다."}, {"s": null, "t": "기록관 모가람은 객사 작은 방 창가에 앉아 있었다. 굳은 두 손을 무릎 위에 가지런히 얹고, 눈을 감은 채 입술만 달싹이고 있었다."}, {"s": null, "t": "모가람 앞에서 곽두칠이 붓을 들고 받아 적었다. 곽두칠의 발밑 그림자가 창으로 든 햇빛에 또렷했다."}, {"s": "night_office:mo", "t": "동쪽 셋째 서가, 위에서 둘째 칸. 「순라 일지, 열넷째 해부터 스무째 해까지」. 그다음 칸은 비었어요. 비었다고 적어요, 두칠 씨. 빈 것도 기록이에요."}, {"s": "q:md_gwak_duchil", "t": "「비었음」. 적었습니다, 기록관님."}, {"s": null, "t": "모가람이 눈을 뜨고 나를 보았다. 입꼬리가 활짝 올라갔다."}, {"s": "night_office:mo", "t": "조사원님! 마침 잘 오셨어요. 우리 짐 싸는 날이에요. 장서각에서 정통파 몫을 청사로 옮겨요.", "fac": "night_office", "spec": 1, "grp": 1}, {"s": "night_office:mo", "t": "조사원님! 마침 잘 오셨어요. 남의 세력 이삿짐이라 미안하지만, 오늘은 손이 하나라도 더 아쉬워요.", "fac_not": "night_office", "spec": 2, "grp": 1}, {"s": null, "t": "나는 왜 장서각 사본을 옮기느냐고 물었다. 모가람이 창밖 정청 쪽을 턱으로 가리켰다."}, {"s": "night_office:mo", "t": "장서각은 이제 명등청 서고예요. 일곱 세력 기록이 다 들어오니까 서가가 모자라요. 정통파 순라 일지, 연무청 수련 장부, 조사원 보고서 사본 같은 건 우리 집으로 가져가야죠."}, {"s": "night_office:mo", "t": "서가 순서는 제가 다 외워요. 서른 해를 꽂았으니까요. 꺼내는 건… 이 손으로는 못 하고요."}, {"s": null, "t": "모가람이 굳은 손등을 무릎 위에서 살짝 들어 보였다. 마디가 굽지 않는 손가락 끝이 햇빛에 하얗게 보였다."}, {"s": null, "t": "곽두칠이 붓을 멈추고 그 손을 바라보았다. 곽두칠은 아무 말도 하지 않고 붓에 먹을 다시 묻혔다."}, {"s": "night_office:mo", "t": "걱정이 하나 있어요. 지하서고 상자들에 책벌레 요괴가 알을 슬었대요. 옮기다가 그것들까지 청사로 이사 가면 큰일이에요."}, {"s": "q:md_gwak_duchil", "t": "제가 어제 내려가 보았습니다. 상자마다 갉은 자국이 있었습니다. 그리고 동쪽 서가 맨 아래 칸 상자 둘이 없어졌습니다. 기록관님 목록에는 있는데 서가에는 없습니다."}, {"s": "night_office:mo", "t": "서른 해 동안 한 번도 안 빈 칸이에요. 어디 다른 서가에 잘못 꽂혔을 거예요. 조사원님, 책벌레를 쫓으면서 그 상자 둘도 좀 찾아봐 주세요. 상자 겉에 먹으로 동그라미가 그려져 있어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_2', 2, '먹 동그라미 상자', '책벌레 요괴을(를) 물리친다, 장서각 지하서고을(를) 살핀다', '{"at": ["hq_archive"], "tasks": [{"t": "win", "m": ["g_hq_archive"], "n": 6}, {"t": "search", "r": ["hq_archive"], "n": 2}]}'::jsonb, '[{"s": null, "t": "책벌레들이 쓰러진 서가 사이는 종이 가루로 뿌옜다. 동쪽 서가 맨 끝, 배수 우물로 내려가는 계단 옆에 상자 둘이 처박혀 있었다. 상자 겉에 먹으로 그린 동그라미가 반쯤 번져 있었다."}, {"s": null, "t": "내가 상자를 끌어내는데 곽두칠이 계단 아래에서 올라왔다. 곽두칠이 상자를 보더니 얼굴이 하얘졌다."}, {"s": "q:md_gwak_duchil", "t": "그 상자… 불나던 밤에 제가 서가에서 끌어내려다 놓친 상자입니다. 봉인 서가 상자인 줄 알았습니다. 무거워서 계단에 버리고 우물로 내려갔습니다."}, {"s": null, "t": "곽두칠이 상자 앞에 무릎을 꿇고 뚜껑을 열었다. 안에는 실로 묶은 얇은 장부 수십 권이 차곡차곡 들어 있었다. 장부마다 겉장에 다른 사람 이름이 적혀 있었다."}, {"s": null, "t": "곽두칠이 장부 하나를 집어 들었다. 겉장 귀퉁이에 반듯한 글씨로 「신입 첫 장부」 네 글자가 적혀 있었다."}, {"s": "q:md_gwak_duchil", "t": "감찰관님 글씨입니다. 이건… 조사원들이 처음 올린 보고서를 묶어 둔 겁니다."}, {"s": null, "t": "나는 장부 더미를 넘겨 보았다. 귀퉁이가 해진 장부 가운데 낯익은 글씨가 있었다. 붉은 인장 일 때 내가 정청에 처음 올린 보고서였다. 귀퉁이마다 붉은 먹으로 「한 줄 더」라는 글씨가 적혀 있었다."}, {"s": "q:md_gwak_duchil", "t": "감찰관님이 이런 걸 남몰래 두셨군요. 몰랐습니다. 저는… 이걸 태울 뻔했습니다."}, {"s": null, "t": "곽두칠의 손이 떨렸다. 나는 상자 뚜껑을 덮어 주고, 태우지 않았으니 됐다고 했다. 곽두칠이 한참 상자를 내려다보다가 고개를 끄덕였다."}, {"s": null, "t": "상자 둘을 계단 위로 올리고 나서 곽두칠이 모가람의 목록을 펼쳤다. 맨 끝 줄에 무언가 더 적혀 있었다."}, {"s": "q:md_gwak_duchil", "t": "기록관님 말씀입니다. 「상자는 다 봉해서 옮겨요. 봉인 먹으로 봉해야 책벌레가 따라붙지 않아요.」 상자가 마흔둘입니다. 봉인 먹이 모자랍니다."}, {"s": "q:md_gwak_duchil", "t": "서고에 먹정과 황지가 있습니다. 조사원님 손이 저보다 빠릅니다. 저는 그동안 상자에 번호를 쓰겠습니다. 번호는 제가 제일 잘 씁니다."}, {"s": null, "t": "곽두칠이 그 말을 하고 나서 겸연쩍은 듯 뒷머리를 긁었다. 서가 벽에 비친 그림자가 그 손을 따라 움직였다."}, {"s": null, "t": "곽두칠은 상자 뚜껑마다 큰 글씨로 하나, 둘, 셋 번호를 써 나갔다. 붓끝이 한 번도 떨리지 않았다."}, {"s": null, "t": "나는 먹정과 황지를 챙겨 서고 구석 책상에 앉았다. 상자 마흔둘을 봉하려면 먹을 넉넉히 개어야 했다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_2', 3, '등 아래 행렬', '봉인 먹을(를) 만든다, 봉인 먹을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "craft", "items": ["sealing_ink"], "n": 2}], "give": {"sealing_ink": 2}}'::jsonb, '[{"s": null, "t": "봉한 상자 마흔둘이 장서각 계단 위에 줄지어 쌓였다. 수레도 없이 어떻게 나를까 하던 참에 야시장 상인들이 등을 하나씩 들고 정청 마당으로 몰려왔다."}, {"s": "q:dh_gopun", "t": "교관 나리가 짐꾼을 찾는다기에 왔수. 이 늙은이는 못 들어도 등은 들 수 있지."}, {"s": null, "t": "상인들이 상자를 둘씩 맡아 들었다. 고분과 시장 아이들은 맨 앞에서 등을 들고 길을 비췄다. 나는 제일 무거운 순라 일지 상자를 메었다."}, {"s": null, "t": "모가람은 행렬 앞쪽에서 걸었다. 두 손을 가슴 앞에 모은 채, 상자가 곁을 지나갈 때마다 번호와 서가 자리를 불렀다."}, {"s": "night_office:mo", "t": "열하나는 동쪽 둘째 서가! 열둘은 그 아래 칸! 두칠 씨, 열셋 뚜껑 봉이 떴어요. 다시 눌러요."}, {"s": "q:md_gwak_duchil", "t": "눌렀습니다, 기록관님!"}, {"s": null, "t": "정청에서 야시장까지는 반 식경 길이었다. 길가 집 처마 밑에서 사람들이 고개를 내밀고 등불 행렬을 구경했다."}, {"s": null, "t": "고분이 앞에서 걷다가 나를 돌아보았다."}, {"s": "q:dh_gopun", "t": "요새 이 동네 밤이 순해졌수. 밤에 가슴 두근거린다고 약 지으러 오던 사람이 반으로 줄었어. 청사 등불이 켜진 뒤로 다들 잠을 잘 잔다우."}, {"s": "night_office:mo", "t": "정말요? 저도 요즘 밤에 손이 덜 쑤셔요. 저는 제가 늙어서 그런 줄 알았는데."}, {"s": null, "t": "모가람이 웃으며 굳은 손을 들어 보였다. 곽두칠이 상자를 고쳐 메며 그 손을 흘끔 보았다."}, {"s": null, "t": "청사에 닿자 강두철이 새 서가 앞에서 기다리고 있었다. 허리는 다 나아 있었다. 강두철이 상자를 하나씩 받아 서가에 올렸다."}, {"s": null, "t": "마지막 상자는 먹 동그라미 상자였다. 곽두칠이 그 상자를 모가람 앞에 내려놓았다. 모가람이 굳은 손등으로 상자 겉을 쓸었다."}, {"s": "night_office:mo", "t": "감찰관님 서랍 상자네요. 이게 서고 계단에 있었어요? …다행이다. 감찰관님한테는 찾았다고만 해요. 몰래 모아 둔 줄 다 안다고 하면 귀까지 빨개지실 테니까."}, {"s": null, "t": "모가람이 상자 안의 장부 하나를 턱으로 가리켰다. 내 이름이 적힌 장부였다."}, {"s": "night_office:mo", "t": "조사원님 것도 있네요. 두칠 씨, 그거 첫 장만 소리 내서 읽어 줘요."}, {"s": null, "t": "곽두칠이 내 첫 보고서를 또박또박 읽었다. 내가 서툰 글씨로 적어 올린 첫 보고가 청사 안에 울렸다. 수련생들이 킥킥거렸고, 나는 귀가 화끈거렸다."}, {"s": "night_office:mo", "t": "처음엔 다들 이래요. 그래서 이 상자는 서가 맨 위 칸에 둘 거예요. 청사에 들어오는 사람마다 제일 먼저 보게요."}, {"s": null, "t": "강두철이 상자를 서가 맨 위 칸에 올리다가 나를 돌아보았다."}, {"s": "night_office:kang", "t": "이제 순라만 다시 돌면 된다. 그런데 옛 순라 길이 다 끊겼다. 순라청까지 길을 아는 사람이 정청에 하나 있긴 한데… 겁이 많아서 말이야."}, {"s": null, "t": "곽두칠이 그 말을 받아 적다가 붓을 멈추었다. 누구 이야기인지 다들 아는 얼굴이었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_night_3', 'side', '뒷이야기·백등 야시장', '순라 길 다시 걷기', '청사에서 옛 순라청까지 지름길이 다시 난다. 서고에서 옛 순라 지도를 베껴 외운 서리 문수가 덜덜 떨며 길잡이를 맡는다. 순라청 처마에는 순라를 마치지 못한 이들의 등불 다섯이 아직 흔들리며 타고, 문수가 찢어진 일지를 맞춰 그 이름들을 불러 준다.', 'lantern_market', 50, '{mdq_17,ep_night_2}'::text[], null, 1527, '[]'::jsonb, true, null, null)
