update public.world_quests set open_req = '{"project": "f:night_office", "stage": 3}'::jsonb where quest_id = 'ep_night_3';
delete from public.world_quest_steps where quest_id = 'ep_night_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_3', 1, '겁 많은 길잡이', '겁 많은 길잡이', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "그사이 청사에 처마가 다 올라갔다는 기별이 왔다. 야시장 어귀에 닿으니 장대에 달려 있던 첫 청사초롱이 처마 끝에 옮겨 걸려 있었고, 그 곁에 둘째 초롱이 새로 걸려 있었다."}, {"s": null, "t": "청사 앞마당에서 강두철이 순라꾼 여섯을 줄 세워 놓고 있었다. 순라꾼들 손에는 막대에 꽂은 순라 등이 하나씩 들려 있었다."}, {"s": null, "t": "줄 맨 끝에 서리 문수가 서 있었다. 문수는 순라 등 대신 두루마리 하나를 품에 꼭 끌어안고 있었다."}, {"s": "q:dh_munsu", "t": "조, 조사원님! 오셨어요! 다행이에요. 저 혼자 앞장서는 줄 알았거든요."}, {"s": "night_office:kang", "t": "{등급}, 왔구나. 오늘 청사 순라가 처음 나간다. 옛 순라 길을 따라 순라청까지. 길은 문수가 안다.", "fac": "night_office", "rank": [1, 4], "spec": 0, "grp": 1}, {"s": "night_office:kang", "t": "판관 나리, 오셨소. 오늘 청사 순라가 처음 나가오. 옛 순라 길을 따라 순라청까지요. 길은 문수가 아오.", "fac": "night_office", "rank": [5, 5], "spec": 0, "grp": 1}, {"s": "night_office:kang", "t": "조사원, 왔구나. 오늘 우리 청사 순라가 처음 나간다. 옛 순라 길을 따라 순라청까지. 길은 문수가 안다. 손님이라도 앞줄에 서 줘라.", "fac_not": "night_office", "spec": 2, "grp": 1}, {"s": null, "t": "나는 문수가 어떻게 순라 길을 아느냐고 물었다. 문수가 품속 두루마리를 반쯤 펴 보였다. 먹으로 그린 길과 등 그림이 빽빽했다."}, {"s": "q:dh_munsu", "t": "서고에서 옛 순라 지도를 베꼈거든요. 베낀 건 다 외워요. 그래서 명등청이 이 길잡이를 저한테 맡겼고요."}, {"s": "q:dh_munsu", "t": "명등청 공문이에요. 「청사에서 귀죽림·구시가지·회산·순라청·옥사·봉인고로 가는 지름길을 다시 내고, 순라청 처마에 이정표를 단다.」 그 이정표를 달고 와야 하거든요."}, {"s": null, "t": "문수가 공문을 읽다가 순라청이라는 대목에서 목소리를 낮췄다."}, {"s": "q:dh_munsu", "t": "근데요… 순라청엔 밤마다 방울 소리가 나거든요. 순라를 다 못 마친 사람들이 아직 돈대요. 저 그런 거 진짜 싫거든요."}, {"s": "night_office:kang", "t": "그러니까 순라꾼 여섯을 붙여 주는 거다! 문수 서리, 등을 들어라. 등을 든 사람한테는 귀신도 길을 비킨다."}, {"s": null, "t": "강두철이 순라 등 하나를 문수 손에 쥐여 주었다. 문수가 등을 받아 들고 덜덜 떨었다. 등불이 문수 손에서 바르르 흔들렸다."}, {"s": null, "t": "강두철이 내게 한 걸음 다가와 목소리를 조금 낮췄다."}, {"s": "night_office:kang", "t": "지름길이 났다고는 하는데, 걸어 본 사람이 아직 없다. 순라청까지 가서 처마 밑을 잘 살펴봐라. 옛 순라 등을 걸던 고리가 남아 있을 거다. 이정표는 거기에 단다.", "fac": "night_office", "rank": [1, 4], "spec": 0, "grp": 2}, {"s": "night_office:kang", "t": "지름길이 났다고는 하는데, 걸어 본 사람이 아직 없소. 순라청까지 가서 처마 밑을 잘 살펴 주시오. 옛 순라 등을 걸던 고리가 남아 있을 거요. 이정표는 거기에 걸 거요.", "fac": "night_office", "rank": [5, 5], "spec": 0, "grp": 2}, {"s": "night_office:kang", "t": "지름길이 났다고는 하는데, 걸어 본 사람이 아직 없다. 순라청까지 가서 처마 밑을 잘 살펴봐라. 옛 순라 등을 걸던 고리가 남아 있을 거다. 이정표는 거기에 단다.", "fac_not": "night_office", "spec": 2, "grp": 2}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_3', 2, '처마 밑 등불', '옛 순라청에 간다, 옛 순라청을(를) 살핀다', '{"at": ["patrol_office"], "tasks": [{"t": "travel", "r": ["patrol_office"], "n": 1}, {"t": "search", "r": ["patrol_office"], "n": 3}]}'::jsonb, '[{"s": null, "t": "청사에서 순라청까지는 생각보다 가까웠다. 귀죽림 가장자리를 끼고 돌다가 무너진 담장 틈으로 빠지는 길이었는데, 문수의 지도는 한 굽이도 틀리지 않았다. 운임을 내는 역참도, 둘러 가는 고갯길도 없었다."}, {"s": "q:dh_munsu", "t": "진짜 빨리 왔거든요. 예전엔 구시가지까지 빙 돌아서 갔대요. 지도에 그렇게 그려져 있었거든요."}, {"s": null, "t": "순라청 마당에 들어서자 문수가 내 등 뒤로 바짝 붙었다. 처마 끝에 녹슨 고리가 줄지어 박혀 있었고, 그중 다섯 개에 아직 순라 등불이 걸려 있었다."}, {"s": null, "t": "기름도 없는 낡은 등이 희미하게 타고 있었다. 바람이 불지 않는데도 등불 아래서 딸랑딸랑 방울 소리가 났다. 문수가 내 소매를 꽉 움켜쥐었다."}, {"s": "q:dh_munsu", "t": "저, 저거요! 방울 소리요! 아무도 없는데 나거든요!"}, {"s": null, "t": "방울 소리는 처마를 따라 마당을 한 바퀴 돌더니 대청 안으로 사라졌다. 순라꾼들이 등을 높이 들고 마당 네 귀퉁이에 섰다."}, {"s": null, "t": "나는 고리를 찾았으니 이정표부터 달자고 했다. 문수가 품에서 나무 이정표를 꺼냈다."}, {"s": "q:dh_munsu", "t": "이정표 글씨는 제가 썼거든요. 「청사 — 반 식경」. 글씨는 진짜 잘 쓰거든요."}, {"s": null, "t": "문수가 까치발을 들고 빈 고리에 이정표를 걸었다. 걸자마자 옆 고리의 낡은 등불이 한 번 깜빡였다. 문수가 흡 숨을 들이켜고 뒷걸음질 쳤다."}, {"s": null, "t": "나는 방울 소리를 따라 대청 안으로 들어갔다. 먼지 앉은 서안 위에 두꺼운 장부 하나가 펼쳐진 채 놓여 있었다. 마지막 장이 바람도 없이 들썩였다."}, {"s": null, "t": "문수가 내 등 뒤에서 고개만 내밀고 장부를 들여다보았다. 겉장에 「순라 일지」라고 적혀 있었다."}, {"s": "q:dh_munsu", "t": "마지막 장이 반쯤 찢어졌거든요. 앞쪽은 읽혀요. 「야시장 어귀 막에서 등 여섯을 받아 나감.」 …여기 이름이 다섯 줄 있는데, 끝에 「돌아옴」이 하나도 없거든요."}, {"s": null, "t": "문수가 손가락으로 줄을 짚어 내려가다 멈췄다. 찢어진 자리에서 글씨가 끊겨 있었다."}, {"s": "q:dh_munsu", "t": "찢어진 쪽에 그다음 일이 있었을 거예요. 이 사람들이 어디서 멈췄는지요."}, {"s": null, "t": "대청 바닥 벌어진 틈에서 무언가 사각사각 기는 소리가 났다. 관청 담을 갉아 먹던 벌레 떼가 장부 냄새를 맡고 기어 나오고 있었다."}, {"s": "q:dh_munsu", "t": "으아악! 장부요! 장부 먹어요! 조사원님, 저것들 좀요! 찢어진 쪽도 저것들이 먹었을지 몰라요!"}, {"s": null, "t": "순라꾼들이 대청 문간으로 몰려와 등으로 벌레 떼를 비추었다. 나는 문수를 서안 앞에 세워 두고 무기를 고쳐 쥐었다. 찢어진 쪽이 아직 순라청 어딘가에 남아 있다면, 그 다섯이 어디서 멈췄는지 알 수 있었다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_3', 3, '순라 마침', '관청 담 벌레 떼을(를) 물리친다, 옛 순라청에서 실마리를 찾는다', '{"at": ["patrol_office"], "tasks": [{"t": "win", "m": ["r220_patrol_2"], "n": 6}, {"t": "clue", "r": ["patrol_office"], "n": 1}]}'::jsonb, '[{"s": null, "t": "벌레 떼가 사라진 담장 틈에서 누렇게 바랜 종이 한 장이 나왔다. 찢어진 일지의 반쪽이었다. 가장자리를 벌레가 갉았지만 글씨는 남아 있었다."}, {"s": null, "t": "문수가 두 쪽을 서안 위에 맞대었다. 찢긴 자리가 꼭 맞았다. 문수가 이어진 줄을 소리 내어 읽었다."}, {"s": "q:dh_munsu", "t": "「삼경. 순라청 담 밖에서 불길. 등 다섯으로 사람들을 이끌고 나감. 담 안에 하나 남아 일지를 씀.」 …그 뒤는 없거든요."}, {"s": null, "t": "다섯 이름 아래 맨 끝에 일지를 쓴 여섯째 사람의 이름이 적혀 있었다. 그 이름에도 「돌아옴」은 없었다."}, {"s": "q:dh_munsu", "t": "다섯은 불 끄러 나가서 안 돌아오고, 남은 하나는 기다리다가 끝났나 봐요. 그래서 등이 아직 걸려 있는 거예요. 순라를 마쳤다고 아무도 안 적어 줬으니까요."}, {"s": null, "t": "해가 지고 순라청 마당에 어둠이 내렸다. 처마 끝 낡은 등불 다섯이 바람 없이 흔들렸다. 방울 소리가 다시 마당을 돌기 시작했다."}, {"s": null, "t": "문수는 등을 든 채 한참 망설였다. 그러다 일지를 가슴에 안고 마당 한가운데로 걸어 나갔다. 무릎이 덜덜 떨렸지만 걸음은 멈추지 않았다."}, {"s": "q:dh_munsu", "t": "저, 저는 서리 문수예요. 명등청에서 왔어요. 이름 부를게요. 무서워도 끝까지 부를 거예요."}, {"s": null, "t": "문수가 일지의 첫 이름을 불렀다. 문수의 입김이 흩어지지 않고 가느다란 금빛 실로 엉겼다. 실은 마당을 가로질러 처마 끝 첫째 등불에 가 닿았다."}, {"s": null, "t": "금빛이 닿자 등불 둘레가 잠깐 저녁 빛깔로 따뜻해졌다. 방울 소리가 한 번 딸랑 울리고 그쳤다. 바람도 없이 흔들리던 등불이 그 자리에서 가만히 멎었다. 불꽃은 작아졌지만 꺼지지 않고 고요하게 탔다."}, {"s": null, "t": "문수가 멎은 등불을 올려다보며 숨을 몰아쉬었다. 등을 쥔 손은 아직 떨렸지만 얼굴은 울 것처럼 환했다."}, {"s": "q:dh_munsu", "t": "멎었어요… 이름을 불러 주니까 헤매던 게 멎은 거거든요. 꺼진 게 아니라 이제 제자리에서 쉬는 거예요. 저 지금 알았거든요."}, {"s": null, "t": "문수가 둘째, 셋째 이름을 이어 불렀다. 순라꾼들도 등을 든 채 따라 불렀다. 나도 넷째와 다섯째 이름을 불렀다. 등불이 하나씩 흔들림을 멈추고 고요해졌다."}, {"s": null, "t": "마지막으로 일지를 쓴 여섯째 이름이 남았다. 문수는 그 이름을 부르기 전에 서안 앞으로 돌아가 붓을 들었다. 일지 맨 끝 줄에 문수의 반듯한 글씨가 적혔다."}, {"s": "q:dh_munsu", "t": "「다섯 돌아옴. 여섯째도 돌아옴. 순라 마침.」 …이렇게 적어 줘야 끝나는 거거든요. 감찰관님이 맨날 그러시거든요. 적지 않으면 없던 일이라고요."}, {"s": null, "t": "문수가 여섯째 이름을 불렀다. 처마의 등불 다섯이 한꺼번에 조금 밝아졌고, 대청 안 어딘가에서 마지막 방울 소리가 한 번 울렸다. 그 뒤로 순라청 마당이 고요해졌다. 처마 끝에는 흔들리지 않는 등불 다섯과 문수가 건 새 이정표가 나란히 걸렸다."}, {"s": null, "t": "돌아오는 길에 순라꾼들이 지름길 굽이마다 순라 등을 하나씩 세웠다. 귀죽림 너머로 청사 처마의 두 초롱 불빛이 보였다. 문수가 내 곁을 걸으며 쉬지 않고 말을 했다. 무서울 때 말이 많아지는 버릇이었다."}, {"s": "q:dh_munsu", "t": "근데요, 일지 끝에 한 줄 더 써도 돼요? 「청사 순라 첫날. 이상 없음. 서리 문수 — 무서웠음.」 감찰관님은 한 줄 더 쓰라고 하시는 분이니까 괜찮을 거거든요."}, {"s": null, "t": "나는 괜찮을 거라고 했다. 문수가 그제야 순라 등을 높이 들고 걸었다. 등불이 더는 떨리지 않았다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_night_4', 'side', '뒷이야기·백등 야시장', '청사 처마 등', '청사에 조사원들이 묵어 갈 방이 나고, 오래 조사원 담당 서기관이었던 연서희가 그 방을 꾸민다. 비고에 들일 「청사 처마 등」을 짜는 등롱 장인 마일수와 연서희가 등에 이름을 하나 쓸지 둘 쓸지 다툰다. 마일수의 오십 년 고집이 풀린다.', 'lantern_market', 50, '{mdq_17,ep_night_3}'::text[], null, 1528, '[]'::jsonb, true, null, null)
