delete from public.world_quest_steps where quest_id = 'ep_night_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_4', 1, '조사원 방', '조사원 방', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "그사이 청사 안쪽에 조사원들이 묵어 갈 방이 하나 났다는 기별이 왔다. 야시장에 가 보니 그 방 문 앞에 연서희가 걸레를 든 채 서 있었다. 치맛자락은 무릎까지 걷어 묶여 있었다."}, {"s": "q:m_yeon", "t": "{이름} 님! 딱 맞춰 왔네요. 이 방 제가 맡았어요. 조사원 담당 서기관 노릇을 몇 해나 한 사람이 조사원 방을 안 꾸미면 누가 꾸며요."}, {"s": null, "t": "나는 서당은 어쩌고 왔느냐고 물었다. 연서희가 걸레를 쥐어짜며 웃었다."}, {"s": "q:m_yeon", "t": "오늘은 아이들이 다 청사 구경 왔어요. 저기 마당에서 강 교관님 목인 치는 거 보고 있잖아요. 서당보다 저게 더 재밌대요."}, {"s": null, "t": "마당 쪽에서 아이들의 환호성이 터졌다. 강두철이 목인을 걷어차 쓰러뜨리고 하하 웃는 소리가 들렸다."}, {"s": null, "t": "방 안에는 새 이부자리와 서안이 놓여 있었다. 연서희가 벽 한쪽을 손바닥으로 탁탁 쳤다. 벽에 못 자국 하나만 휑하니 남아 있었다."}, {"s": "q:m_yeon", "t": "여기에 처마 등을 하나 걸 거예요. 비고에 들일 「청사 처마 등」하고 똑같은 거요. 마일수 영감님이 짜 주시기로 했는데… 영감님이랑 저랑 지금 싸우는 중이에요."}, {"s": null, "t": "방문 밖에서 헛기침 소리가 났다. 등롱 장인 마일수가 등 뼈대 하나를 들고 서 있었다."}, {"s": "q:dh_ilsu", "t": "싸우는 게 아니라 일러 주는 거요. 등에는 이름을 하나만 쓰오. 오십 년을 그렇게 했소. 등 하나에 사람 하나."}, {"s": "q:m_yeon", "t": "그러니까요. 나가는 사람 이름을 쓰면 그 사람이 돌아올 길을 등이 기억한다면서요. 그럼 기다리는 사람 이름도 같이 쓰면, 등이 둘 다 기억하잖아요."}, {"s": "q:dh_ilsu", "t": "둘을 쓰면 등이 헷갈리오."}, {"s": "q:m_yeon", "t": "등이 헷갈리는 걸 보신 적 있어요?"}, {"s": null, "t": "마일수가 입을 다물었다. 대답할 말을 고르는 얼굴이었다. 연서희가 나를 보며 눈을 찡긋했다."}, {"s": "q:dh_ilsu", "t": "…그건 나중에 정하겠소. 우선 기름부터요. 처마 등은 비를 맞으니 종이에 기름을 먹여야 하오. 연등 붕어 기름이 제일이오. 폐쇄된 연화원 못에 그놈들이 많소."}, {"s": "q:m_yeon", "t": "낚시는 {이름} 님이 해 줘요. 저는 물가에만 가면 치맛자락부터 젖거든요. 목도리 빌려 갔다가 석 달 만에 돌려준 사람이니까, 이 정도는 해 줘야죠."}, {"s": null, "t": "나는 그 목도리 이야기는 언제까지 할 거냐고 물었다. 연서희가 걸레로 내 팔을 톡 쳤다."}, {"s": "q:m_yeon", "t": "이 방에 등이 걸릴 때까지요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_4', 2, '기름 먹인 종이', '폐쇄된 연화원에서 낚시를 한다', '{"at": ["lantern_market"], "tasks": [{"t": "fish", "r": ["sealed_garden"], "n": 3}]}'::jsonb, '[{"s": null, "t": "붕어 바구니를 들고 돌아오자 마일수가 청사 처마 밑에 좌판을 펴 놓고 있었다. 좌판 위에는 월철 뼈대 둘과 황지 묶음, 등 그림을 그린 종이가 놓여 있었다."}, {"s": "q:dh_ilsu", "t": "좋은 붕어요. 배가 통통하오. 이걸 달여 기름을 내 주시오. 하나는 이 방 처마 등에, 하나는 비고에 들일 등에 쓰겠소."}, {"s": null, "t": "나는 왜 비고에 들일 등을 따로 짜느냐고 물었다. 마일수가 뼈대를 손바닥으로 굴리며 대답했다."}, {"s": "q:dh_ilsu", "t": "정통파 조사원들이 공훈을 모아 이 등을 제 집에 걸 수 있게 하는 거요. 청사 처마에 걸린 등과 같은 등을. 집에 가서도 청사를 잊지 말라는 거지."}, {"s": null, "t": "연서희가 방에서 나와 좌판 곁에 쪼그려 앉았다. 연서희의 눈길이 마일수의 손등에 머물렀다. 손가락 마디마다 오래된 불에 덴 자국이 있었다."}, {"s": "q:m_yeon", "t": "영감님, 야시장 셋째 줄에 한때 꺼졌던 등 있잖아요. 「순덕」 등이요. 그 등, 영감님 혼자 오십 년 기억하셨죠."}, {"s": "q:dh_ilsu", "t": "…누가 그 얘기를 했소."}, {"s": "q:m_yeon", "t": "다들 알아요. 영감님이 해마다 그 등 뼈대만 따로 손보시는 거요. 그래서 둘을 쓰자고 한 거예요. 혼자 기억하는 등보다 둘이 기억하는 등이 덜 외롭잖아요."}, {"s": null, "t": "마일수가 한동안 뼈대를 굴리지 않았다. 처마 밑으로 저녁 바람이 불어 황지 묶음 끝이 팔락거렸다."}, {"s": "q:dh_ilsu", "t": "순덕이가 살았을 때 내 등에는 내 이름만 있었소. 순덕이가 내 이름 옆에 제 이름을 써 넣으려다가 내가 말렸지. 등이 헷갈린다고."}, {"s": "q:dh_ilsu", "t": "그 사람이 간 뒤로, 그 사람 등에 내 이름을 써 넣을까 몇 번 생각했소. 못 썼지. 오십 년 고집이 그거요."}, {"s": null, "t": "연서희가 아무 말 없이 마일수의 손등에 제 손을 얹었다가 거두었다. 마일수가 헛기침을 하고 뼈대를 다시 들었다."}, {"s": "q:dh_ilsu", "t": "기름부터 내 주시오. 이름은… 종이가 다 마르면 정하겠소."}, {"s": null, "t": "연서희가 내 쪽으로 돌아앉아 손가락 둘을 펴 보였다. 소리는 내지 않고 입 모양으로만 「둘」이라고 말했다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_4', 3, '두 이름', '등롱 어유을(를) 만든다, 등롱 어유을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "craft", "items": ["lantern_oil"], "n": 2}], "give": {"lantern_oil": 2}}'::jsonb, '[{"s": null, "t": "마일수는 기름 먹인 황지를 처마 밑에서 하룻밤 말렸다. 이튿날 저녁, 뼈대에 종이를 바른 등 두 개가 좌판 위에 나란히 섰다. 하나는 조사원 방 처마에 걸 것, 하나는 비고에 들일 것이었다."}, {"s": null, "t": "연서희가 붓에 먹을 듬뿍 묻혀 마일수에게 내밀었다. 마일수는 붓을 받지 않고 나를 보았다."}, {"s": "q:dh_ilsu", "t": "처마 등은 청사를 드나드는 사람 몫이오. 조사원 방에 걸 첫 등이니, 조사원이 쓰시오."}, {"s": null, "t": "나는 붓을 받아 등 앞에 섰다. 마일수가 손가락으로 등 종이 위쪽을 짚었다."}, {"s": "q:dh_ilsu", "t": "위에는 나가는 사람. 당신 이름이오."}, {"s": null, "t": "나는 등 위쪽에 내 이름을 썼다. 마일수의 손가락이 아래쪽으로 내려가다 멈췄다. 연서희가 저도 모르게 숨을 죽였다."}, {"s": "q:dh_ilsu", "t": "…아래에는 기다리는 사람. 이 방을 맡은 사람이 쓰시오."}, {"s": null, "t": "연서희가 눈을 동그랗게 떴다가 웃었다. 연서희는 붓을 받아 내 이름 아래에 「연서희」 세 글자를 또박또박, 끝까지 눌러 썼다."}, {"s": "q:m_yeon", "t": "이제 {이름} 님이 오래 안 오면 이 등이 저를 볼 거예요. 그럼 제가 서신을 보낼 거고요. 석 달씩 걸리면 안 돼요."}, {"s": null, "t": "마일수가 등을 들어 조사원 방 처마 고리에 걸었다. 등롱 어유를 부은 심지에 불을 붙이자 등이 화르르 밝아졌다. 두 이름이 나란히 불빛을 받았다."}, {"s": null, "t": "강두철이 서당 아이들을 줄줄이 데리고 와 등을 올려다보았다. 강두철의 갓에는 처음 보는 갓끈이 달려 있었다. 구슬을 꿴 줄이 턱 밑에서 달랑거렸다."}, {"s": "night_office:kang", "t": "등에 이름이 둘이로군! 마일수 영감이 오십 년 법을 깼네!"}, {"s": "q:m_yeon", "t": "교관님, 그 갓끈은 또 뭐예요?"}, {"s": "night_office:kang", "t": "순라 갓끈이다! 비고에 들일 거라고 서리들이 짜 왔는데, 내가 먼저 매 보는 거다. 순라꾼은 밤길에 갓이 날아가면 안 되니까. 어떠냐, 어울리지?"}, {"s": null, "t": "아이들이 깔깔 웃었다. 강두철이 고개를 흔들자 구슬 갓끈이 짤랑거렸다. 연서희가 소매로 입을 가리고 웃었다."}, {"s": null, "t": "마일수는 웃음소리를 등지고 비고에 들일 둘째 등을 품에 안았다. 그 등에는 아직 아무 이름도 없었다."}, {"s": "q:dh_ilsu", "t": "비고 등은 이름을 비워 두겠소. 가져가는 사람이 제 집에서 둘을 쓰라고. …오늘 밤에는 셋째 줄 순덕이 등에 내 이름을 써 넣어 보겠소. 오십 년 만이오."}, {"s": null, "t": "마일수가 등을 안고 야시장 셋째 줄로 걸어갔다. 연서희는 그 뒷모습을 오래 바라보다가 내 소매를 잡아끌었다."}, {"s": "q:m_yeon", "t": "다음엔 대들보 올리는 날이래요. 감찰관님도 오실지 몰라요. 그날은 꼭 와요. 등이 보고 있으니까요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_night_5', 'side', '뒷이야기·백등 야시장', '상량문', '대들보를 올리는 날, 정청을 비울 수 없는 한설이 명등청 일 틈틈이 반 식경 길을 건너와 상량문을 쓴다. 상량문 맨 앞 「도제조」 칸을 두고 모가람과 한설이 갈린다. 지은 이들의 이름부터 옮겨 적고 대들보 곁에서 밤을 새운 뒤, 한설은 그 칸을 비워 두고 백운서를 「등잔을 지킨 사람이자 칸을 긁은 사람」으로 함께 적는다.', 'lantern_market', 50, '{mdq_17,ep_night_4}'::text[], null, 1529, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:night_office", "stage": 5}'::jsonb where quest_id = 'ep_night_5';
delete from public.world_quest_steps where quest_id = 'ep_night_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_5', 1, '상량문 빈칸', '상량문 빈칸', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "그사이 대들보를 올리는 날이 정해졌다. 야시장에 닿으니 청사 마당 한가운데 굵은 대들보가 받침목 위에 누워 있었다. 대들보 배에 상량문을 넣을 홈이 파여 있었다."}, {"s": null, "t": "마당 평상에 감찰관 한설이 앉아 있었다. 명등청 일로 정청을 비우지 못하는 한설이 낮 공문을 서리들에게 맡기고 건너와 있었다. 한설은 상량문 종이를 앞에 펴 놓고 붓을 천천히 닦고 있었다."}, {"s": null, "t": "한설 곁에서 문수가 발을 동동 굴렀다."}, {"s": "q:dh_munsu", "t": "조사원님! 감찰관님이 저렇게 붓 닦으시는 거 벌써 한 시진째거든요. 새벽 공문은 감찰관님이 직접 보셔야 해서 내일 동트면 정청에 들어가셔야 하거든요. 근데 아직 첫 줄도 못 쓰셨어요."}, {"s": "night_office:han", "t": "…조사원. 왔나. 우리 집 상량이다. 첫 줄이 안 써진다.", "fac": "night_office", "spec": 1, "grp": 1}, {"s": "night_office:han", "t": "…조사원. 남의 세력 상량에까지 와 줬군. 첫 줄이 안 써진다.", "fac_not": "night_office", "spec": 2, "grp": 1}, {"s": null, "t": "한설이 상량문 종이를 내 쪽으로 돌렸다. 해와 달을 적는 줄 아래에 「도제조」라는 머리가 있고, 그 옆이 비어 있었다."}, {"s": "night_office:han", "t": "상량문에는 그 집을 다스리는 사람 이름을 맨 먼저 쓴다. 정통파에는 도제조가 없다. 판관들은 비워 두자 하고, 기록관은 그분 이름을 쓰자 한다."}, {"s": null, "t": "곽두칠을 앞세우고 모가람이 마당으로 들어섰다. 모가람은 상량문 앞에 서서 굳은 손으로 빈칸 언저리를 가리켰다."}, {"s": "night_office:mo", "t": "도제조님 이름을 써요, 감찰관님. 이 청사는 그분 등잔 밑에서 일하던 사람들이 짓는 집이에요."}, {"s": "night_office:han", "t": "그분은 칸을 긁은 분이기도 하다. 그분이 칸을 긁은 서식에 도장을 찍은 뒤로 정리가 시작됐고, 그 정리에 내 동료 셋이 거둬졌다. 그 이름을 대들보 맨 위에 올리는 게 맞나."}, {"s": null, "t": "마당이 조용해졌다. 대들보를 받치던 수련생들까지 숨을 죽였다. 모가람의 입술이 몇 번 달싹였다가 닫혔다."}, {"s": null, "t": "한설은 다시 붓을 닦기 시작했다. 아까보다 더 천천히 닦았다."}, {"s": null, "t": "나는 한설에게, 상량문에는 다스리는 사람만 적느냐고 물었다. 한설이 붓을 멈추고 나를 보았다."}, {"s": "night_office:han", "t": "…아니. 지은 이들 이름도 적는다. 목수, 미장이, 돌 나른 사람."}, {"s": null, "t": "나는 그럼 지은 이들부터 적자고 했다. 사업에 물품을 넘긴 조사원들과 주춧돌에 쇠 띠를 두른 수련생들, 상자를 날라 준 야시장 사람들과 처마 등을 짠 장인이 다 지은 이였다. 도제조 칸은 그다음에 정해도 늦지 않다고 했다."}, {"s": null, "t": "한설이 한참 나를 보다가 붓을 내려놓았다. 입가가 아주 조금 풀렸다."}, {"s": "night_office:han", "t": "그래. 지은 이들부터. 문수 서리, 사업 장부에서 물품을 넘긴 조사원 이름을 다 옮겨 와라. 하나도 빠짐없이."}, {"s": "q:dh_munsu", "t": "다, 다요? 수백 명이거든요!"}, {"s": "night_office:han", "t": "그러니까 조사원도 같이 옮겨라. 다 옮기거든 오늘 밤은 다들 대들보 곁에서 쉰다. 상량 전날 밤은 원래 그렇게 하는 거다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_5', 2, '대들보 곁의 밤', '자율 활동을 끝까지 마친다, 백등 야시장에서 쉰다', '{"at": ["lantern_market"], "tasks": [{"t": "idle", "n": 1, "k": "research"}, {"t": "rest", "r": ["lantern_market"], "n": 1}]}'::jsonb, '[{"s": null, "t": "이름을 옮기는 일은 해 질 녘에야 끝났다. 문수가 옮긴 종이와 내가 옮긴 종이를 합치니 손가락 한 마디 두께가 되었다. 문수가 그 묶음을 끌어안고 마당에 털썩 주저앉았다."}, {"s": "q:dh_munsu", "t": "팔이 제 것 같지 않거든요. 근데요, 이름이 이렇게 많을 줄 몰랐거든요. 정통파 아닌 분들도 엄청 많아요. 흑련, 북령, 수향… 다 있거든요."}, {"s": null, "t": "한설이 묶음을 받아 한 장씩 넘겼다. 한설은 이름 하나하나를 눈으로 따라 읽었다. 그동안 붓은 한 번도 닦지 않았다."}, {"s": "night_office:han", "t": "…이만큼이 이 집을 지었군. 정통파 혼자 지은 집이 아니다."}, {"s": null, "t": "강두철이 마당에 모닥불을 피웠다. 수련생들이 잿더미에 고구마를 묻었고, 고분이 막걸리 한 동이를 이고 왔다. 연서희는 서당 아이들을 재우고 돌아와 모닥불 가에 앉았다."}, {"s": "night_office:kang", "t": "상량 전날 밤은 대들보 곁에서 새우는 거다. 대들보가 혼자 자면 외로워서 집이 삐뚤게 선다. 내 스승님 말씀이다."}, {"s": "q:dh_gopun", "t": "교관 나리 스승님은 별 말씀을 다 하셨구먼."}, {"s": null, "t": "모가람이 모닥불 가에 앉아 굳은 손을 불 쪽으로 내밀었다. 곽두칠이 모가람의 소매가 불에 닿지 않게 걷어 올려 주었다."}, {"s": null, "t": "밤이 깊어지자 한설이 모닥불에서 떨어져 대들보 곁으로 갔다. 나는 막걸리 두 잔을 들고 따라갔다. 한설은 잔 하나를 받아 대들보 위에 올려놓았다."}, {"s": "night_office:han", "t": "이건 도제조님 몫이다. …나는 아직 그분을 어떻게 불러야 할지 모르겠다."}, {"s": null, "t": "나는 대답 대신 내 잔을 그 잔 곁에 놓았다. 한설이 대들보를 손바닥으로 쓸었다. 거친 나뭇결이 손바닥에 걸렸다."}, {"s": "night_office:han", "t": "그분은 마지막에 「정청에는 내 이름을 부를 사람이 없네」 하셨다. 단비가 먼저 불렀고 우리가 따라 불렀다. 나도 불렀다. 그날 나는 감찰관이 아니라 그냥 사람으로 불렀다."}, {"s": "night_office:han", "t": "상량문에 올리는 건 그날과 다르다. 정통파가 이 집 이름으로 그분을 부르는 거고, 그걸 적는 건 감찰관 붓이다. 감찰관은 좋은 것만 적으면 안 된다."}, {"s": null, "t": "한설은 평상으로 돌아가 다시 붓을 들었다. 이번에는 닦지 않았다. 한설은 상량문 빈칸 옆에 작은 글씨로 무언가를 길게 적어 내려갔다. 나는 그 글씨를 읽지 않고 모닥불 곁으로 돌아갔다."}, {"s": null, "t": "연서희가 잿더미에서 고구마 하나를 꺼내 내 손에 쥐여 주었다. 강두철은 대들보에 등을 기댄 채 코를 골고 있었다."}, {"s": "q:m_yeon", "t": "감찰관님 뭐 쓰세요?"}, {"s": null, "t": "나는 모른다고 했다. 연서희가 고개를 끄덕이고 더 묻지 않았다. 모닥불 불티가 대들보 쪽으로 날아갔다."}, {"s": null, "t": "동이 틀 무렵 한설이 붓을 놓고 나를 불렀다. 밤을 새운 눈이 붉었다."}, {"s": "night_office:han", "t": "나는 새벽 공문을 보러 정청에 다녀오겠다. 해 질 녘에 다시 오마."}, {"s": null, "t": "한설이 일어서다 말고 대들보를 돌아보았다."}, {"s": "night_office:han", "t": "조사원. 그때까지 대들보에 걸 명등 등롱 둘을 지어 다오. 하나는 대들보 머리에, 하나는 빈칸 몫이다. 등도에서 쓰는 그 등롱으로."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_night_5', 3, '대들보 오르는 날', '명등 등롱을(를) 만든다, 명등 등롱을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "craft", "items": ["myeongdeung_lamp"], "n": 2}], "give": {"myeongdeung_lamp": 2}}'::jsonb, '[{"s": null, "t": "야시장 등이 하나씩 켜지는 시각에 상량이 시작되었다. 수련생 여덟이 밧줄을 잡았고, 강두철이 기둥 위에 올라 소리를 맞췄다."}, {"s": "night_office:kang", "t": "하나, 둘, 올려라! 허리 말고 다리! 오늘은 나도 허리 안 쓴다!"}, {"s": null, "t": "대들보가 영차 소리에 맞춰 조금씩 들렸다. 대들보 머리에 매단 명등 등롱이 흔들리며 마당을 비췄다. 야시장 상인들과 서당 아이들이 마당 가장자리에 빙 둘러섰다."}, {"s": null, "t": "대들보가 기둥 위에 쿵 얹히자 박수가 터졌다. 강두철이 기둥 위에서 두 팔을 번쩍 들었다."}, {"s": null, "t": "해 질 녘에 정청에서 돌아온 한설이 상량문 두루마리를 들고 사다리를 올랐다. 한설은 홈에 두루마리를 넣기 전에 마당을 내려다보며 두루마리를 펼쳤다."}, {"s": "night_office:han", "t": "상량문이다. 감찰관이 읽는다. 다 같이 듣고 기억해라."}, {"s": "night_office:han", "t": "「백등 야시장 어귀 옛 순라 막 자리에 정통파 청사를 세운다. 지은 이 — 사업에 물품을 넘긴 조사원들, 주춧돌을 두른 연무청 수련생들, 상자를 나른 야시장 사람들, 처마 등을 짠 등롱 장인 마일수.」"}, {"s": null, "t": "한설은 장부에서 옮긴 이름을 하나도 빼지 않고 읽어 내려갔다. 이름이 불릴 때마다 마당 가의 누군가가 손을 들었다. 제 이름이 아닌데 손을 드는 사람도 있었다. 아들 이름이라고, 옆집 사람 이름이라고 했다."}, {"s": null, "t": "마지막 이름까지 읽은 한설이 잠깐 숨을 골랐다. 두루마리 맨 끝이 남아 있었다. 「도제조」 머리 옆 빈칸과, 그 옆에 어젯밤 한설이 적은 작은 글씨였다."}, {"s": "night_office:han", "t": "「도제조 — 빈칸으로 둔다. 다스릴 사람이 아니라 부를 사람이 앉을 자리다.」"}, {"s": "night_office:han", "t": "「다만 이 집 첫 등잔 밑에서 일한 사람 하나를 적는다. 도제조 백운서. 삼백 년 동안 등잔을 지켰고, 그 등잔 밑에서 칸을 긁었다. 둘 다 적는다. 둘 다 잊지 않는다.」"}, {"s": null, "t": "마당이 숨을 죽였다. 모가람이 굳은 손을 가슴 앞에 모았다. 곽두칠이 붓을 든 채 고개를 숙였다. 문수는 입술을 꾹 깨물고 있었다."}, {"s": null, "t": "한설이 두루마리를 대들보 홈에 넣고 사다리에서 내려왔다. 한설은 평상 위의 둘째 명등 등롱을 들어 대들보 아래에 세웠다. 등롱 겉에 이름 종이가 붙어 있었다. 「백운서」 세 글자였다."}, {"s": null, "t": "한설이 등롱 앞에서 그 이름을 불렀다. 감찰관의 목소리였다. 한설의 입김이 금빛 실로 엉겨 등롱의 이름 종이에 닿았다. 기름 한 방울 붓지 않은 등롱에 화르르 불이 붙었다."}, {"s": null, "t": "모가람이 따라 불렀다. 강두철이 기둥 위에서 목청껏 불렀다. 연서희와 문수와 곽두칠이 불렀고, 나도 불렀다. 마당 가의 야시장 사람들까지 그 이름을 따라 불렀다. 금빛 실이 여러 가닥 겹치자 등롱 불빛이 대들보까지 환하게 올라갔다."}, {"s": null, "t": "마일수가 사다리를 타고 올라가 처마 끝에 셋째 청사초롱을 걸었다. 수련생 둘이 지붕 양 끝에 「夜行局」 세 글자를 쓴 깃발을 하나씩 꽂았다. 깃발 둘이 밤바람에 펄럭였다."}, {"s": null, "t": "고분이 이고 온 떡 시루를 강두철이 받아 열었다. 낙성 떡 김이 마당에 피어올랐다. 강두철이 떡을 집어 내 손에 먼저 쥐여 주었다."}, {"s": "night_office:kang", "t": "첫 떡은 지은 이 몫이다! 혼자 지은 사람은 없으니, 이름 적힌 사람이면 아무나 먼저 먹는 게 법이다!"}, {"s": null, "t": "한설은 떡을 받지 않고 대들보를 올려다보았다. 새 등롱 불빛이 상량문 홈을 비추고 있었다."}, {"s": "night_office:han", "t": "오늘 밤 안에 정청으로 돌아간다. 명등청 일이 밀렸다. …조사원, 이 집에 들르거든 그 등롱을 봐 줘라. 이름이 하나라, 불러 줄 사람이 자주 와야 한다."}, {"s": null, "t": "나는 들르겠다고 했다. 한설이 고개를 끄덕이고 붓을 꺼내 닦기 시작했다. 이번에는 아주 빠르게 닦았다. 문수가 그 손을 보고 내 귀에 대고 속삭였다."}, {"s": "q:dh_munsu", "t": "저렇게 빨리 닦으시는 건 처음 봐요. 기분 좋으시다는 거거든요."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_north_1', 'side', '뒷이야기·철벽 고찰', '장작 패는 수좌', '겨울채비 첫 단계가 차서 산문 좌판에 대구탕과 철벽 비약이 들어온 늦가을, 수좌 혜각이 겨울 장작을 패며 도끼를 빼앗으려 덤비는 행자들을 차례로 눕힌다. 막내 행자 봉수는 장작 하나 제대로 못 패면서 썰매를 따라 산을 내려가고 싶어 한다.', 'iron_monastery', 50, '{mdq_17}'::text[], null, 1530, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:north_league", "stage": 1}'::jsonb where quest_id = 'ep_north_1';
delete from public.world_quest_steps where quest_id = 'ep_north_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_1', 1, '도끼 빼앗기', '도끼 빼앗기', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "늦가을 철벽 고찰은 아침부터 쩍, 쩍 장작 패는 소리로 시끄러웠다. 산문 안 마당에 통나무가 산처럼 쌓여 있었고, 그 앞에서 수좌 혜각이 소매를 걷어붙이고 도끼를 휘두르고 있었다."}, {"s": null, "t": "혜각 둘레에 행자 셋이 빙 둘러서 있었다. 셋은 눈짓을 주고받더니 한꺼번에 혜각의 도끼를 향해 달려들었다."}, {"s": null, "t": "혜각은 웃는 얼굴 그대로 도끼를 내려놓았다. 소매가 한 번 휙 돌았고, 다음 순간 행자 셋이 낙엽 더미 위에 나란히 벌렁 누워 있었다."}, {"s": "north_league:hyegak", "t": "허허, 오늘도 소승이 장작을 다 패야겠군요. 도끼를 빼앗는 사람이 그날 장작을 다 패기로 했는데 말입니다."}, {"s": null, "t": "누운 행자 둘은 끙 소리를 내며 일어나 물러났다. 맨 작은 행자 하나만 낙엽을 털지도 않고 다시 혜각 앞에 섰다. 열다섯 남짓, 볼이 바람에 빨갛게 튼 아이였다."}, {"s": "q:sx_ep_bongsu", "t": "한 번 더요, 수좌님! 이번엔 진짜 빼앗을 거예요!"}, {"s": "north_league:hyegak", "t": "봉수 행자는 어제도 그 말을 했고 그제도 그 말을 했지요. 허허."}, {"s": null, "t": "혜각이 그제야 산문 쪽을 보고 나를 알아보았다. 혜각이 도끼 자루를 어깨에 걸치며 껄껄 웃었다."}, {"s": "north_league:hyegak", "t": "허허, 손님이 또 오셨군요. 마침 잘 오셨습니다. 고찰 법은 아시지요? 산문 넘은 분은 일부터 하고 밥을 드십니다.", "fac_not": "north_league", "spec": 2, "grp": 1}, {"s": "north_league:hyegak", "t": "허허, 우리 식구가 겨울채비 철에 딱 맞춰 돌아왔군요. 식구는 일부터 하고 밥을 먹습니다. 아시지요?", "fac": "north_league", "spec": 1, "grp": 1}, {"s": null, "t": "나는 장작이 왜 이렇게 많이 필요하냐고 물었다. 혜각이 통나무 더미를 턱으로 가리켰다."}, {"s": "north_league:hyegak", "t": "올겨울은 눈이 언제 올지 아무도 모릅니다. 호송대장이 백골 장터로 내려간 뒤로 「내일은 눈」을 맞히는 사람이 없어서요. 그 사람이 한마디 하면 산문 장작이 미리 쌓였는데, 이젠 그냥 일찍부터 넉넉히 쌓아 두는 수밖에요."}, {"s": "north_league:hyegak", "t": "그래도 올해는 형편이 낫습니다. 겨울채비 사업에 여러 조사원님들이 월철 주괴며 가공 부적목이며 노정 건량을 실어다 주셔서, 겨울 양식 창고가 가을에 벌써 찼어요. 남는 손으로 공양간 대구탕을 단지에 담아 산문 좌판에 내놓았습니다. 호송대가 눈길에서 먹던 철벽 비약도요."}, {"s": null, "t": "혜각이 산문 쪽 좌판을 가리켰다. 김이 오르는 대구탕 단지 곁에 검은 약병들이 나란히 놓여 있었다. 산 아래에서 올라온 나무꾼 둘이 대구탕을 한 사발씩 사 들고 후후 불었다."}, {"s": "north_league:hyegak", "t": "소승이 끓인 국을 돈 내고 사 드시는 걸 보니 기분이 묘합니다. 허허."}, {"s": "q:sx_ep_bongsu", "t": "수좌님, 손님한테 일 시키실 거면 제가 같이 갈게요! 장작 해 오는 건 저도 잘해요!"}, {"s": "north_league:hyegak", "t": "패는 건 못 해도 해 오는 건 잘하지요, 우리 봉수 행자는."}, {"s": null, "t": "봉수가 볼을 부풀렸다. 혜각이 웃으며 나를 보았다."}, {"s": "north_league:hyegak", "t": "고찰 아궁이는 연기가 적은 부적목만 땝니다. 사당 위패에 그을음이 앉지 않게요. 설피골 숲에 쓰러진 부적목이 많으니 여섯 짐만 모아 와 주세요. 오는 길에 얼음 못에서 빙어도 좀 낚아 주시고요. 오늘 저녁은 빙어국입니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_1', 2, '나뭇결', '설피골에서 부적목을(를) 모은다, 설피골에서 낚시를 한다', '{"at": ["iron_monastery"], "tasks": [{"t": "gather", "items": ["wood"], "r": ["snow_hollow"], "n": 6}, {"t": "fish", "r": ["snow_hollow"], "n": 3}]}'::jsonb, '[{"s": null, "t": "부적목 여섯 짐과 빙어를 지고 산문에 들어서자, 봉수가 마당 한가운데에서 도끼를 붙들고 낑낑대고 있었다. 혜각은 공양간에 들어가고 없었다."}, {"s": null, "t": "봉수가 도끼를 높이 들어 통나무를 내리찍었다. 퍽, 도끼날이 나무 한가운데 박혀 꼼짝도 하지 않았다. 봉수가 도끼 자루에 매달려 발을 동동 굴렀다."}, {"s": "q:sx_ep_bongsu", "t": "왜 안 쪼개져! 수좌님은 쩍쩍 잘만 쪼개시는데!"}, {"s": null, "t": "나는 짐을 내려놓고 봉수 곁에 쪼그려 앉았다. 통나무 단면에 갈라진 금이 가늘게 나 있었다. 나는 봉수에게 금이 난 데를 보라고 했다. 나무는 제가 갈라지고 싶은 데로 갈라진다고 했다."}, {"s": "q:sx_ep_bongsu", "t": "금이요? …여기요? 이 실금이요?"}, {"s": null, "t": "봉수가 박힌 도끼를 겨우 빼내어, 이번에는 금에 맞춰 내리찍었다. 쩍, 통나무가 두 쪽으로 갈라져 양쪽으로 툭 넘어졌다."}, {"s": null, "t": "봉수가 도끼를 든 채 갈라진 나무를 한참 내려다보았다. 그러다 나를 보며 이가 다 보이게 웃었다."}, {"s": "q:sx_ep_bongsu", "t": "됐어요! 됐어요, 조사원님! 수좌님! 수좌님, 보셨어요?"}, {"s": null, "t": "공양간 문이 드르륵 열리고 혜각이 국자를 든 채 고개를 내밀었다. 그 뒤에서 맹주 석진악이 지팡이를 짚고 나왔다."}, {"s": "north_league:hyegak", "t": "허허, 봤습니다. 다음 장작부터는 소승이 덜 패도 되겠군요."}, {"s": "north_league:seok", "t": "조사원한테 배운 도끼질이구먼. 남한테 배운 걸 부끄러워하지 말게. 나도 혜각한테 배웠네."}, {"s": "north_league:hyegak", "t": "맹주님은 소승한테 도끼질을 배우신 적이 없습니다. 눕는 법을 배우셨지요."}, {"s": "north_league:seok", "t": "이 사람이."}, {"s": null, "t": "석진악이 혀를 차며 지팡이 끝으로 혜각의 발등을 툭 건드렸다. 혜각은 웃으며 국자를 고쳐 쥐었다. 공양간에서 빙어국 끓는 냄새가 마당까지 퍼져 나왔다."}, {"s": null, "t": "혜각이 빙어를 받아 들고 하나하나 배를 눌러 보았다. 흡족한 얼굴이었다."}, {"s": "north_league:hyegak", "t": "빙어국은 소승이 끓이겠습니다. 다만 일이 하나 더 있어요. 내일 새벽에 썰매꾼들이 설피골로 겨울 보급을 받으러 내려가는데, 길에서 먹을 매운탕 단지를 들려 보내고 싶습니다. 소승 손은 빙어국에 묶였으니, 조사원님이 세 단지만 끓여 주시겠어요?"}, {"s": "q:sx_ep_bongsu", "t": "수좌님, 썰매꾼들 내려갈 때 저도 따라가면 안 돼요? 장작 쪼갰잖아요!"}, {"s": "north_league:hyegak", "t": "한 개 쪼갰지요. 허허. 그 얘기는 저녁 공양 때 맹주님께 여쭤 보세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_1', 3, '비어 있는 앞자리', '매운탕을(를) 만든다, 매운탕을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "craft", "items": ["spicy_stew"], "n": 3}], "give": {"spicy_stew": 3}}'::jsonb, '[{"s": null, "t": "끓인 매운탕 단지 셋을 썰매꾼들 짐 곁에 내려놓자, 혜각이 뚜껑을 열어 냄새를 맡고 고개를 끄덕였다."}, {"s": null, "t": "저녁 공양은 대웅전 처마 아래 길게 놓인 상에서 했다. 빙어국 사발에서 김이 무럭무럭 올랐고, 투명한 빙어들이 국물 위에 은빛으로 떠 있었다."}, {"s": null, "t": "행자들과 썰매꾼들이 상 양쪽에 앉아 후루룩 국을 마셨다. 봉수는 숟가락을 쥔 채 맹주 쪽만 흘끔거렸다."}, {"s": "q:sx_ep_bongsu", "t": "맹주님. 내일 썰매 따라 내려가도 돼요? 장작도 쪼갤 줄 알아요. 조사원님한테 배웠어요."}, {"s": null, "t": "석진악이 빙어국을 한 숟갈 떠먹고 천천히 사발을 내려놓았다."}, {"s": "north_league:seok", "t": "썰매 길에 누구를 데려갈지는 앞에 서는 사람이 정하네. 그게 북령 호송대 법이야."}, {"s": "q:sx_ep_bongsu", "t": "그럼 앞에 서는 사람이 누군데요?"}, {"s": null, "t": "상 둘레가 조용해졌다. 썰매꾼들이 서로 얼굴을 보다가 숟가락을 내려놓았다. 석진악이 산 아래 남쪽 하늘을 오래 보았다."}, {"s": "north_league:seok", "t": "…운비가 장터로 내려간 뒤로 그 자리가 비었네. 눈이 그리되고 나서, 앞자리는 남한테 넘기겠다더군. 넘길 사람은 아직 안 정했어."}, {"s": null, "t": "썰매꾼 하나가 사발에 코를 박고 국만 마셨다. 혜각이 그 썰매꾼을 흘끗 보더니 빙그레 웃으며 염주를 한 알 넘겼다."}, {"s": "north_league:hyegak", "t": "허허, 앞자리 얘기는 첫 얼음이 얼 때쯤 다시 하시지요. 오늘은 빙어국이 식습니다."}, {"s": null, "t": "봉수가 입을 삐죽 내밀고 국을 마셨다. 나는 봉수의 사발에 내 몫 빙어 두 마리를 건져 넣어 주었다. 봉수가 눈을 동그랗게 떴다."}, {"s": "q:sx_ep_bongsu", "t": "…이거 왜 주세요?"}, {"s": null, "t": "나는 봉수에게 장작을 쪼갠 몫이라고 했다. 봉수가 빙어를 후루룩 삼키고 배시시 웃었다."}, {"s": "q:sx_ep_bongsu", "t": "내일도 쪼갤게요. 열 개 쪼개면 열 마리예요?"}, {"s": "north_league:hyegak", "t": "허허, 그 셈이면 고찰 빙어가 남아나질 않겠습니다."}, {"s": null, "t": "처마 아래로 바람이 불어와 등잔불이 흔들렸다. 혜각이 고개를 들어 하늘 냄새를 맡더니 고개를 갸웃했다."}, {"s": "north_league:hyegak", "t": "눈 냄새가 나는 것도 같고 아닌 것도 같고. 호송대장이 있으면 한마디로 알았을 텐데요."}, {"s": null, "t": "산문 좌판 쪽에서 나무꾼들이 빈 대구탕 사발을 돌려주고 산을 내려가는 소리가 났다. 고찰의 첫 겨울채비는 그렇게 빙어국 냄새 속에서 저물었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_north_2', 'side', '뒷이야기·철벽 고찰', '앞에 서는 사람', '첫 얼음이 언 날 보급 썰매가 설피골로 내려간다. 호송대장 자리를 내려놓은 여운비가 단비와 함께 백골 장터에서 올라와 앞자리를 썰매꾼 억보에게 넘긴다. 억보는 앞만 보겠다고 하고, 조사원은 맨 뒤 줄을 잡는다.', 'iron_monastery', 50, '{mdq_17,ep_north_1}'::text[], null, 1531, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:north_league", "stage": 2}'::jsonb where quest_id = 'ep_north_2';
delete from public.world_quest_steps where quest_id = 'ep_north_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_2', 1, '넘기는 날', '넘기는 날', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "그사이 산 위에 첫 얼음이 얼었다. 철벽 고찰 우물 둘레에 살얼음이 끼었고, 산문 마당에는 보급 썰매 넷이 줄지어 서 있었다."}, {"s": null, "t": "맨 앞 썰매 곁에서 썰매꾼 하나가 썰매 줄을 몇 번이고 고쳐 매고 있었다. 지난번 공양 때 사발에 코를 박고 국만 마시던 그 썰매꾼이었다. 줄을 맨 손이 덜덜 떨려 매듭이 자꾸 풀렸다."}, {"s": null, "t": "그때 산문 밖에서 짤랑짤랑 방울 소리가 올라왔다. 고개를 돌리자 여운비와 단비가 돌계단을 오르고 있었다."}, {"s": null, "t": "단비는 여운비의 왼쪽에서 오른손으로 방울 달린 엿 보따리를 흔들었다. 여운비는 오른 뺨을 바람 쪽으로 조금 내민 채 걸었다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님! 여기 계실 줄 알았어요. 맹주님이 대장님을 부르셨다길래 엿 장사 하루 쉬고 따라왔어요. 대장님 혼자 오면 고갯길에 엿 냄새가 안 나서 심심해하실 것 같아서요."}, {"s": "north_league:yeo", "t": "심심해한 적 없소."}, {"s": "red_moon_cult:danbi", "t": "어젯밤에 세 번 물어보셨잖아요. 단비, 고개 바람이 어떠냐고요."}, {"s": null, "t": "여운비는 대꾸하지 않고 썰매 쪽으로 걸어갔다. 귀 끝이 빨개져 있었다. 하얗게 바랜 오른 눈과 뺨의 흰 줄이 첫 얼음 빛 아래에서 더 희게 보였다."}, {"s": "north_league:yeo", "t": "당신도 왔구려. 오늘은 썰매 길을 남한테 넘기는 날이오. 구경을 왔다면 구경하시오. 다만 줄 하나는 잡아야 할 거요.", "fac_not": "north_league", "spec": 2, "grp": 1}, {"s": "north_league:yeo", "t": "당신도 왔구려. 북령 패 찬 사람이 넘기는 날에 와 주니 덜 쓸쓸하오. 줄 하나는 잡아 주시오.", "fac": "north_league", "spec": 1, "grp": 1}, {"s": null, "t": "여운비가 떨리는 손으로 매듭을 고치던 썰매꾼 앞에 섰다. 썰매꾼이 벌떡 일어나 허리를 굽혔다."}, {"s": "q:sx_ep_eokbo", "t": "대, 대장님!"}, {"s": "north_league:yeo", "t": "대장이라고 부르지 마시오. 오늘부터 대장은 당신이오, 억보."}, {"s": null, "t": "억보의 얼굴이 하얗게 질렸다. 둘레의 썰매꾼들이 웅성웅성 술렁였다."}, {"s": "q:sx_ep_eokbo", "t": "저는 안 됩니다. 저는 오 년 넘게 대장님 뒤만 따라다녔습니다. 칭찬도 한 번 못 들었고요. 바람도 못 읽습니다."}, {"s": "north_league:yeo", "t": "나는 이제 바람을 눈으로 못 읽소. 볼로 읽으면 늦소. 앞에 선 사람이 늦으면 뒤가 다 묻히오."}, {"s": null, "t": "여운비가 버릇처럼 칼자루 끝으로 손을 가져갔다가 도로 내렸다."}, {"s": "north_league:yeo", "t": "당신이 내 뒤에서 무엇을 했는지 나는 아오. 썰매가 미끄러지면 맨 먼저 줄을 잡은 게 당신이었소. 내가 서른 걸음 물리라 하면 맨 마지막 썰매를 끌고 물러난 것도 당신이었고."}, {"s": null, "t": "억보가 입을 다물었다. 석진악이 산문 처마 아래에서 지팡이를 짚고 서서 그 모습을 보고 있었다."}, {"s": "north_league:seok", "t": "억보. 운비가 정했으면 정한 걸세. 길에서 보세."}, {"s": null, "t": "억보가 침을 꿀꺽 삼키고 썰매 줄을 움켜쥐었다. 그때 썰매 뒤에서 봉수가 장작 한 아름을 안고 쪼르르 달려 나왔다."}, {"s": "q:sx_ep_bongsu", "t": "억보 아저씨! 아니, 대장님! 저도 데려가 주세요. 앞에 서는 사람이 정한다고 맹주님이 그러셨어요!"}, {"s": null, "t": "억보가 봉수를 내려다보다가 여운비를 돌아보았다. 여운비는 고개를 돌려 산 아래만 보았다. 억보는 혼자 정해야 했다."}, {"s": "q:sx_ep_eokbo", "t": "…장작 썰매 하나 맡아라. 미끄러지면 놓고 피해라. 줄은 손목에 감지 말고."}, {"s": null, "t": "여운비의 입꼬리가 아주 조금 움직였다. 줄을 손목에 감지 말라는 것은, 언젠가 이 산에서 여운비가 내게 했던 말이었다."}, {"s": null, "t": "나는 억보에게 맨 뒤 줄은 내가 잡겠다고 했다. 억보가 나를 보았다."}, {"s": "q:sx_ep_eokbo", "t": "맨 뒤요? 조사원님이요? …그럼 저는 앞만 보면 되는 겁니까?"}, {"s": null, "t": "나는 그렇다고 했다. 등 뒤는 내가 보겠다고 했다. 억보가 천천히 고개를 끄덕였다."}, {"s": "q:sx_ep_eokbo", "t": "그럼 설피골 썰매 길부터 쓸어야 합니다. 지난주부터 고개 밑에 늑대 떼가 내려와 있습니다. 놈들은 늘 뒤에서 물어뜯습니다. 대장님이 그러셨습니다."}, {"s": "north_league:yeo", "t": "…대장이라고 부르지 말래도."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_2', 2, '쉼막의 밤', '설피골에 간다, 설피골의 요괴를 물리친다', '{"at": ["snow_hollow"], "tasks": [{"t": "travel", "r": ["snow_hollow"], "n": 1}, {"t": "win", "r": ["snow_hollow"], "n": 8}]}'::jsonb, '[{"s": null, "t": "설피골 썰매 길은 허리까지 눈이 쌓여 있었다. 늑대 떼가 썰매 꽁무니로 덤벼들 때마다 내 {직업:호위=방패가/월궁=화살이/퇴마=방울 소리가/의무=부채가/봉인=금강령이/암영=단도가/조련=화살과 동무가/*=무기가} 뒤를 막았다."}, {"s": null, "t": "마지막 늑대가 깨갱 비명을 지르며 눈 속으로 달아나자, 골짜기에 바람 소리만 남았다. 휘이잉, 눈가루가 옆으로 날렸다."}, {"s": null, "t": "골짜기 어귀에 못 보던 움막 하나가 서 있었다. 통나무로 벽을 세우고 지붕에 솔가지를 두껍게 덮은 쉼막이었다. 처마 밑에 마른 짚단과 약초 단지가 가지런히 쌓였고, 굴뚝으로 연기가 가늘게 올랐다."}, {"s": "q:sx_ep_eokbo", "t": "겨울채비 사업이 둘째 단계를 넘기고 고찰에서 지은 쉼막입니다. 고개마다 하나씩요. 여러 조사원님들이 넘겨준 청령단이며 농축 약초액이 저 단지에 들어 있습니다. 썰매꾼이 언 몸으로 들어오면 약 한 사발 먹고 몸을 녹이고 가라고요."}, {"s": "red_moon_cult:danbi", "t": "어머, 짚단도 있어요. 대장님, 짚단은 왜요?"}, {"s": "north_league:yeo", "t": "고개 너머 산골 사람들이 겨울 신을 삼을 짚이오. 고찰이 올해는 짚도 넉넉히 거뒀다 하오. …예전엔 짚이 모자라 맨발로 눈길을 걷는 아이들도 있었소."}, {"s": null, "t": "단비가 짚단을 쓰다듬다가 여운비를 보았다. 여운비는 쉼막 처마 아래에서 오른 뺨을 골짜기 쪽으로 내밀고 있었다."}, {"s": null, "t": "그 밤 우리는 쉼막에서 묵었다. 화로에 불을 지피자 언 손끝이 따끔따끔 풀렸다. 봉수는 혜각이 싸 준 주먹밥을 먹자마자 짚단 위에 쓰러져 잠들었다."}, {"s": null, "t": "억보는 쉼막 문간에 앉아 잠을 이루지 못했다. 썰매 줄 매듭을 풀었다 맸다 하는 소리가 밤새 이어졌다. 여운비가 그 곁에 앉았다."}, {"s": "north_league:yeo", "t": "내일 아침 바람은 어떻겠소."}, {"s": "q:sx_ep_eokbo", "t": "모르겠습니다. 대장님은 붉은 술을 보고 아셨는데, 저는…"}, {"s": "north_league:yeo", "t": "술만 봐서는 늦소. 술은 바람이 지나간 뒤에 날리니까. 볼로 바람을 읽게 되고서야 알았소. 술이 날리기 전에 귀가 먼저 시려지는 쪽이 있다는 걸. 당신은 내 뒤에서 오 년을 그 바람을 맞았으니 귀가 먼저 알 거요."}, {"s": null, "t": "억보가 손을 멈추고 제 귀를 만졌다. 문틈으로 찬 바람이 들어와 억보의 왼쪽 귀를 스치고 지나갔다."}, {"s": "q:sx_ep_eokbo", "t": "…왼쪽이 시립니다."}, {"s": "north_league:yeo", "t": "그럼 북쪽 바람이오. 내일은 눈이 안 오겠소."}, {"s": null, "t": "단비가 이불을 뒤집어쓴 채 성한 오른쪽 귀만 내밀고 킥킥 웃었다."}, {"s": "red_moon_cult:danbi", "t": "들었어요. 내일 눈 안 와요. 대장님 볼이랑 억보 씨 귀랑 제 귀가 셋 다 그래요."}, {"s": null, "t": "억보가 그제야 웃었다. 웃음 끝에 숨을 길게 내쉬고 나를 보았다."}, {"s": "q:sx_ep_eokbo", "t": "조사원님. 내일 고개 비탈이 가파릅니다. 썰매 넷을 줄로 이어 끌어 올리는데, 맨 뒤 줄을 맡아 주십시오. 저는 앞만 보겠습니다. 뒤는… 돌아보지 않겠습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_2', 3, '세 번 돌아본 사람', '설피골에 원정을 다녀온다', '{"at": ["iron_monastery"], "tasks": [{"t": "expedition", "r": ["snow_hollow"], "n": 1}]}'::jsonb, '[{"s": null, "t": "고개 비탈에서 셋째 썰매가 한 번 미끄러졌다. 끼이익, 썰매가 비탈 아래로 쏠리자 봉수가 장작 썰매 줄을 놓고 옆으로 데굴데굴 굴렀다. 억보가 일러 준 대로였다."}, {"s": null, "t": "나는 맨 뒤에서 미끄러지는 썰매 줄을 등에 걸고 눈밭에 발을 박았다. 줄이 팽팽하게 당겨지며 어깨를 파고들었다."}, {"s": null, "t": "앞에서 억보가 고개를 홱 돌렸다. 돌아보지 않겠다던 사람이었다."}, {"s": "q:sx_ep_eokbo", "t": "잡았습니까! 조사원님, 잡으셨습니까!"}, {"s": null, "t": "나는 잡았으니 앞을 보라고 소리쳤다. 억보가 이를 악물고 다시 앞을 보았다. 썰매꾼들이 한꺼번에 줄을 당기자 셋째 썰매가 덜컹 비탈 위로 올라왔다."}, {"s": null, "t": "해 질 녘 썰매 넷은 무사히 철벽 고찰 마당에 닿았다. 혜각이 웃으며 마중을 나왔고, 석진악이 산문 처마 아래에서 썰매를 하나하나 세었다."}, {"s": "north_league:hyegak", "t": "허허, 넷 다 왔군요. 장작 썰매까지 다섯이네요. 봉수 행자가 장작 썰매를 끌고 왔다고요?"}, {"s": "q:sx_ep_bongsu", "t": "한 번 놓쳤어요. 근데 놓으라고 해서 놓은 거예요!"}, {"s": null, "t": "억보는 썰매 줄을 쥔 채 마당 한가운데 서 있었다. 줄을 놓는 법을 잊은 사람 같았다. 여운비가 억보 앞에 섰다."}, {"s": "q:sx_ep_eokbo", "t": "대… 여운비 님. 죄송합니다. 세 번 돌아봤습니다. 앞에 선 사람은 뒤를 안 돌아본다고 하셨는데요."}, {"s": "north_league:yeo", "t": "그런 말은 한 적 없소."}, {"s": "q:sx_ep_eokbo", "t": "예?"}, {"s": "north_league:yeo", "t": "나는 뒤를 늘 봤소. 뒤에 선 사람이 다 있는지 보느라. 다 있으면 앞을 봤지. 당신은 세 번 돌아보고, 세 번 다 다시 앞을 봤소."}, {"s": null, "t": "여운비가 억보의 손에서 썰매 줄을 받아 썰매 위에 감아 놓았다. 썰매 짐을 묶는 북령 매듭이었다."}, {"s": "north_league:yeo", "t": "짐도 다 왔고 사람도 다 왔소. 그거면 됐소."}, {"s": null, "t": "억보가 고개를 숙였다. 어깨가 조금 떨렸다. 둘레의 썰매꾼들이 와아 소리를 지르며 억보의 등을 퍽퍽 두드렸다."}, {"s": "q:md_sledder", "t": "억보가 칭찬 들었어! 대장님한테 칭찬 들었다고!"}, {"s": "north_league:yeo", "t": "칭찬 아니오."}, {"s": "red_moon_cult:danbi", "t": "대장님, 「그거면 됐소」는 칭찬이에요. 「나쁘지 않소」 다음으로 센 거요. 제가 다 세어 놨어요."}, {"s": null, "t": "여운비가 단비를 흘겨보았다. 단비는 여운비의 왼쪽에 서서 엿 하나를 억보 손에 쥐여 주었다."}, {"s": null, "t": "석진악이 지팡이를 짚고 다가와 억보의 어깨에 큰 손을 얹었다. 그 손은 금방 떨어졌다."}, {"s": "north_league:seok", "t": "다음 썰매는 자네가 정하게. 누굴 데려갈지, 언제 떠날지."}, {"s": null, "t": "여운비와 단비는 고찰에서 하룻밤을 묵고 이튿날 아침 장터로 내려갔다. 산문 앞에서 여운비가 걸음을 멈추고 오른 뺨을 산 위쪽으로 돌렸다."}, {"s": "north_league:yeo", "t": "서쪽 바람이오. 사흘은 맑겠소. …억보한테는 말하지 마시오. 제 귀로 알게 두시오."}, {"s": null, "t": "단비가 여운비의 왼쪽으로 쪼르르 달려가 섰다. 두 사람이 돌계단을 내려가는 동안, 단비의 방울 소리가 산 아래까지 오래 들렸다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_north_3', 'side', '뒷이야기·철벽 고찰', '서리솔 지름길', '겨울채비 셋째 단계로 고찰에서 설피골·서리솔 고개·빙혼곡·천경호로 가는 눈길이 다져지고, 길마다 붉은 천을 단 장대가 선다. 무릎이 성치 않은 맹주 석진악이 다져진 길을 제 발로 걸어 보겠다고 나서고, 고갯마루에서 눈에 묻힌 옛 호송대 길표 돌을 찾는다.', 'iron_monastery', 50, '{mdq_17,ep_north_2}'::text[], null, 1532, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:north_league", "stage": 3}'::jsonb where quest_id = 'ep_north_3';
delete from public.world_quest_steps where quest_id = 'ep_north_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_3', 1, '장대 끝 붉은 천', '장대 끝 붉은 천', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "그사이 서리솔 고개로 가는 길이 다져졌다. 산문 앞에서 내려다보니, 하얀 산허리를 따라 서른 걸음마다 장대가 하나씩 꽂혀 있었다. 장대 끝마다 붉은 천 조각이 매달려 펄럭였다."}, {"s": null, "t": "산문 처마 아래에서 석진악이 털신을 신고 있었다. 혜각이 그 곁에 쪼그려 앉아 맹주의 무릎에 두꺼운 무명 감발을 감아 주었다."}, {"s": "north_league:hyegak", "t": "맹주님, 무릎이 그 모양이신데 고개까지 걸어가시겠다고요. 소승이 업어 드릴까요?"}, {"s": "north_league:seok", "t": "업히는 건 죽어서 할 걸세."}, {"s": null, "t": "석진악이 감발 감긴 무릎을 두 손으로 탁탁 쳤다. 그러고 나서 나를 보고 턱을 들었다."}, {"s": "north_league:seok", "t": "자네, 서리솔 고개에서 두 번 헤맸다지. 감찰관 편지를 들고 처음 올라오던 날 말일세. 이제는 헤맬 일이 없을 걸세. 같이 걸어 보세.", "fac_not": "north_league", "spec": 2, "grp": 1}, {"s": "north_league:seok", "t": "자네, 서리솔 고개에서 두 번 헤맸다지. 산문 패를 차고도 헤맸다니 내가 다 부끄러웠네. 이제는 헤맬 일이 없을 걸세. 같이 걸어 보세.", "fac": "north_league", "spec": 1, "grp": 1}, {"s": null, "t": "나는 맹주가 그걸 어떻게 아시느냐고 물었다. 석진악이 혜각을 흘겨보았고, 혜각이 염주를 굴리며 딴청을 피웠다."}, {"s": "north_league:hyegak", "t": "허허, 호송대장이 지난번에 그러더군요. 그 손님이 고개에서 두 번 헤매고 와서도 썰매 줄은 끝까지 안 놓더라고요."}, {"s": "north_league:seok", "t": "겨울채비가 셋째 단계를 넘겼네. 여러 조사원들이 넘겨준 강화 부적목으로 장대를 깎고, 응축 영핵으로 골짜기 얼음 다리를 받쳤지. 이제 고찰에서 설피골·서리솔 고개·빙혼곡·천경호까지 노정패 한 닢 안 받고 다니네. 길이 다져지니 걸음도 반나절이 줄었어."}, {"s": "north_league:seok", "t": "장대 끝 붉은 천은 운비 생각을 한 걸세. 호송대 사람들은 칼자루에 술을 달고 다녔지. 이제는 길이 술을 달고 섰어. 누구든 그 천 날리는 쪽만 보면 바람을 알게."}, {"s": null, "t": "산문 앞에 봉수와 억보가 장대 다발을 지고 서 있었다. 봉수는 제 키보다 긴 장대를 어깨에 메고 휘청휘청 비틀거렸다."}, {"s": "q:sx_ep_bongsu", "t": "맹주님, 고갯마루에 아직 장대가 다섯 개 모자라요! 억보 대장님이 저희더러 박으래요!"}, {"s": "q:sx_ep_eokbo", "t": "그런데 장대 밑동을 다질 솔가지가 모자랍니다. 고개 솔숲에서 송진 묻은 솔가지를 좀 모아 주십시오. 송진이 얼면 장대가 눈바람에도 안 쓰러집니다."}, {"s": "north_league:seok", "t": "길은 내가 앞서겠네. 다리가 성할 때 걸어 둬야지."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_3', 2, '고갯마루', '서리솔 고개에 간다, 서리솔 고개에서 채집한다', '{"at": ["frost_pine_pass"], "tasks": [{"t": "travel", "r": ["frost_pine_pass"], "n": 1}, {"t": "gather", "r": ["frost_pine_pass"], "n": 4}]}'::jsonb, '[{"s": null, "t": "다져진 눈길은 발이 푹푹 빠지지 않았다. 석진악은 지팡이를 짚고 한 걸음 한 걸음 천천히 올랐다. 숨이 차면 장대 하나를 짚고 서서 붉은 천을 올려다보았다."}, {"s": null, "t": "솔가지를 모아 오자 억보와 봉수가 고갯마루 빈자리에 장대를 박았다. 밑동에 솔가지를 둘러 송진으로 굳히자, 장대 끝 붉은 천이 바람을 받아 동쪽으로 쭉 뻗었다."}, {"s": "q:sx_ep_bongsu", "t": "동쪽이요! 바람이 동쪽으로 가요! 맹주님, 저도 바람 읽었어요!"}, {"s": "north_league:seok", "t": "천이 동쪽으로 날리면 바람은 서쪽에서 오는 걸세."}, {"s": "q:sx_ep_bongsu", "t": "…아."}, {"s": null, "t": "봉수가 귀까지 빨개졌다. 억보가 웃음을 참다가 결국 쿡 웃었고, 봉수가 억보의 옆구리를 꾹 찔렀다."}, {"s": null, "t": "석진악이 고갯마루 바위에 털썩 걸터앉았다. 감발 감긴 무릎을 주무르며 고개 아래 하얀 골짜기를 내려다보았다."}, {"s": "north_league:seok", "t": "내가 자네들 나이 때는 이 고개를 하루에 두 번 넘었네. 그때는 길표가 장대가 아니라 돌이었어. 호송대가 고개를 한 번 넘을 때마다 길표 돌에 칼로 홈을 하나씩 팠지."}, {"s": null, "t": "석진악이 지팡이 끝으로 눈 덮인 비탈 여기저기를 짚었다. 아무리 짚어도 돌은 걸리지 않았다."}, {"s": "north_league:seok", "t": "그 돌이 이 근처 어디 묻혔을 걸세. 눈이 해마다 쌓이니 이젠 어디 있는지도 모르겠어. 북령 호송대가 이 고개를 넘은 수가 다 거기 새겨져 있는데."}, {"s": "q:sx_ep_eokbo", "t": "맹주님, 그 돌에 여운비 님 홈도 있습니까?"}, {"s": "north_league:seok", "t": "있겠지. 그 애가 처음 호송을 나간 날부터 판 홈이 있을 걸세. 그 애 집안 사람들 것도."}, {"s": null, "t": "나는 그 돌을 찾아보겠다고 했다. 석진악이 무릎을 짚고 일어서려다 도로 주저앉았다. 혜각이 감아 준 감발이 무릎에서 반쯤 풀려 있었다."}, {"s": "north_league:seok", "t": "그럼 부탁하세. 나는 여기서 장대나 보고 있겠네. 다리가 그만 쉬라는구먼."}, {"s": null, "t": "봉수가 석진악 곁에 쪼그려 앉아 풀린 감발을 다시 감았다. 서툰 손이었지만 석진악은 아무 말 없이 무릎을 내주었다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_3', 3, '잇는 홈', '서리솔 고개을(를) 살핀다', '{"at": ["frost_pine_pass"], "tasks": [{"t": "search", "r": ["frost_pine_pass"], "n": 3}]}'::jsonb, '[{"s": null, "t": "길표 돌은 고갯마루에서 남쪽으로 쉰 걸음쯤 떨어진 비탈 아래 묻혀 있었다. 눈을 손으로 헤치자 사람 허리만 한 돌기둥이 드러났다. 돌 표면에는 칼로 판 홈이 빽빽하게 줄지어 있었다."}, {"s": null, "t": "억보와 둘이서 돌을 고갯마루로 굴려 올렸다. 봉수가 뒤에서 밀며 끙차, 끙차 소리를 맞췄다."}, {"s": null, "t": "석진악이 돌 앞에 무릎을 꿇고 앉아 장갑을 벗었다. 맨손으로 홈을 하나하나 더듬었다. 위쪽 홈은 비바람에 닳아 손톱자국처럼 얕았고, 아래로 갈수록 깊고 또렷했다."}, {"s": "north_league:seok", "t": "여기 이 깊은 홈이 내 걸세. 열여섯 살 때. 처음이라 칼에 힘을 너무 줘서 이렇게 깊어."}, {"s": null, "t": "석진악의 손가락이 아래로 내려가다 한 줄에서 멈췄다. 가늘고 곧은 홈이 일정한 간격으로 길게 이어진 줄이었다."}, {"s": "north_league:seok", "t": "…운비 걸세. 그 애는 홈도 반듯하게 팠구먼. 바람만 보는 줄 알았더니 돌도 봤어."}, {"s": null, "t": "줄의 마지막 홈 뒤에는 빈자리가 남아 있었다. 석진악이 그 빈자리를 엄지로 한참 문질렀다."}, {"s": null, "t": "억보가 허리춤의 작은 칼을 뽑았다가 머뭇거렸다. 석진악이 억보를 올려다보았다."}, {"s": "north_league:seok", "t": "뭘 기다리나. 지난번 썰매 넷, 자네가 앞에서 넘겼잖나."}, {"s": "q:sx_ep_eokbo", "t": "여운비 님 줄 끝에 파도 됩니까? 제 줄은 따로 없는데요."}, {"s": "north_league:seok", "t": "줄은 새로 시작하는 게 아니라 잇는 걸세. 그 애가 거기서 멈췄으니 자네가 거기서 잇게."}, {"s": null, "t": "억보가 칼끝을 돌에 대었다. 사각, 첫 홈은 비뚤었다. 억보가 이를 악물고 한 번 더 그었다. 둘째 홈은 반듯했다."}, {"s": null, "t": "봉수가 억보 어깨너머로 홈을 들여다보더니 제 가슴을 손가락으로 가리켰다."}, {"s": "q:sx_ep_bongsu", "t": "저는요? 저도 장작 썰매 끌었어요!"}, {"s": "north_league:seok", "t": "자네는 아직 고개를 한 번밖에 안 넘었네. 열 번 넘거든 파게."}, {"s": "q:sx_ep_bongsu", "t": "열 번이요? …그럼 겨울 다 가요!"}, {"s": null, "t": "석진악이 껄껄 웃었다. 웃음소리가 고갯마루 바람을 타고 산 아래로 굴러 내려갔다. 석진악은 길표 돌을 새 장대 곁에 세우게 한 뒤 지팡이를 짚고 일어섰다."}, {"s": "north_league:seok", "t": "내려가세. 내려가면 할 일이 하나 있어. 산문 큰 북 말일세. 지난 장마에 가죽이 터졌네. 올겨울에는 그 북이 울어야 하는데."}, {"s": null, "t": "나는 북이 왜 꼭 울어야 하냐고 물었다. 석진악이 장대 끝 붉은 천을 올려다보았다."}, {"s": "north_league:seok", "t": "북령맹이 처음 맹을 맺던 날부터 산문 아홉 곳 사람들을 불러 모으던 북이야. 눈이 깊어 길이 막히면 그 북을 쳤지. 북 소리가 닿는 데까지는 아무도 혼자 겨울을 나지 않는다고."}, {"s": "north_league:seok", "t": "올해는 그 북이 꼭 울어야 할 것 같네. 까닭은… 메우다 보면 생각이 나겠지."}, {"s": null, "t": "고개를 내려오는 길, 장대마다 붉은 천이 서쪽에서 불어오는 바람에 동쪽으로 날렸다. 봉수가 장대 하나를 지날 때마다 「서쪽 바람」 하고 중얼거렸다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_north_4', 'side', '뒷이야기·철벽 고찰', '맹약을 알리던 북', '겨울채비 넷째 단계로 비고에 작은 북과 털모자를 들이는 무렵, 맹주 석진악이 터진 산문 큰 북을 새 가죽으로 메운다. 옛 가죽 안쪽에서 누군가 몰래 적어 둔 이름들이 나오고, 석진악은 새 가죽에도 이름을 새길지 조사원에게 묻는다.', 'iron_monastery', 50, '{mdq_17,ep_north_3}'::text[], null, 1533, '[]'::jsonb, true, null, null)
