update public.world_quests set open_req = '{"project": "f:north_league", "stage": 4}'::jsonb where quest_id = 'ep_north_4';
delete from public.world_quest_steps where quest_id = 'ep_north_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_4', 1, '터진 북', '터진 북', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "그사이 대웅전 앞마당에 산문 큰 북이 내려와 있었다. 소 한 마리를 통째로 앉혀도 남을 만한 북통이었다. 붉은 칠이 벗겨진 북통 위로 가죽이 한가운데부터 쭉 찢어져 있었다."}, {"s": null, "t": "석진악이 북통 앞에 앉아 찢어진 가죽을 걷어 내고 있었다. 오래된 가죽은 손이 닿자마자 바스락 부서졌다. 혜각이 곁에서 부서진 가죽 조각을 한 장도 버리지 않고 광주리에 주워 담았다."}, {"s": "north_league:hyegak", "t": "허허, 맹주님. 그 북 가죽은 소승이 행자 때 갈아 끼운 겁니다. 서른 해 넘게 버텼으니 할 만큼 했지요."}, {"s": "north_league:seok", "t": "서른 해 동안 몇 번 울렸나."}, {"s": "north_league:hyegak", "t": "눈 때문에 세 번, 적월 때문에 한 번. 그리고 맹주님이 약주 드시고 한 번."}, {"s": "north_league:seok", "t": "그건 세지 말게."}, {"s": null, "t": "석진악이 혀를 차고 나를 보았다. 손에 묻은 가죽 부스러기를 툭툭 털었다."}, {"s": "north_league:seok", "t": "자네 왔구먼. 마침 손이 필요했네. 북을 메울 가죽이 모자라.", "fac_not": "north_league", "spec": 2, "grp": 1}, {"s": "north_league:seok", "t": "자네 왔구먼. 북령 북은 북령 식구 손으로 메우는 게 법일세. 손 좀 빌리세.", "fac": "north_league", "spec": 1, "grp": 1}, {"s": "north_league:seok", "t": "겨울채비가 넷째 단계를 넘겼네. 여러 조사원들이 넘겨준 회춘단이며 강철 단조 망치 몫으로 비고에 새 물건 둘을 들이기로 했어. 하나는 이 큰 북을 본떠 줄여 메운 「설산 맹약 북」이고, 하나는 산 아래 아낙들이 뜨는 「눈길 털모자」일세. 눈길 걷는 사람 귀가 얼지 말라고."}, {"s": "north_league:hyegak", "t": "비고는 본래 호송대장 자리인데 장터에 가 있으니, 맹주님이 손수 들이십니다. 맹주님 손으로 메운 북이라고 하면 비고에서 아무도 공훈을 안 깎으려 들 겁니다."}, {"s": "north_league:seok", "t": "큰 북부터 메워야 작은 북도 메우지. 요수 가죽을 칠액에 재우고 영사 실타래로 엮은 강화 요수 가죽 두 장이면 되네. 무두질을 잘못하면 첫 울림에 터지니 조심해서 지어 주게."}, {"s": null, "t": "그사이 봉수가 광주리 곁에 쪼그려 앉아 부서진 옛 가죽 조각을 들여다보았다. 가죽 안쪽에 먹으로 쓴 글자 몇이 희미하게 남아 있었다."}, {"s": "q:sx_ep_bongsu", "t": "맹주님, 여기 뭐가 써 있어요. 이름 같은데요."}, {"s": null, "t": "석진악이 봉수 손에서 가죽 조각을 받아 들고 한참 보았다. 혜각의 염주 굴리던 손이 멈췄다."}, {"s": "north_league:seok", "t": "…산문을 지키다 간 사람들 이름이야. 지난번 가죽을 메울 때 누가 몰래 안쪽에 적어 둔 걸세. 나도 몰랐네."}, {"s": "north_league:hyegak", "t": "허허, 소승입니다. 행자 때요. 북 칠 때마다 그 사람들도 함께 울리라고요. 맹주님한테 들키면 혼날까 봐 안쪽에 적었지요."}, {"s": null, "t": "석진악이 혜각을 오래 보았다. 혜각은 웃는 얼굴 그대로 염주를 한 알 넘겼다."}, {"s": "north_league:seok", "t": "…새 가죽에도 적을지는 메우면서 생각하세. 가죽부터 지어 주게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_4', 2, '가죽 위의 손', '강화 요수 가죽을(를) 만든다, 강화 요수 가죽을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "craft", "items": ["reinforced_leather"], "n": 2}], "give": {"reinforced_leather": 2}}'::jsonb, '[{"s": null, "t": "지은 강화 요수 가죽 두 장을 건네자, 석진악이 그것을 북통 위에 펴 놓고 손바닥으로 쓸어 보았다. 가죽이 손 아래에서 팽팽하게 울렸다."}, {"s": "north_league:seok", "t": "좋은 가죽일세. 자네 손이 무두질을 아는구먼."}, {"s": null, "t": "혜각이 큰 솥에 물을 끓이다가 고개를 갸웃했다. 솥 안에는 아직 아무것도 없었다."}, {"s": "north_league:hyegak", "t": "맹주님, 아교는 어쩌시렵니까. 가죽을 북통에 붙이려면 부레풀이 있어야지요. 소승이 말려 둔 부레는 지난 장마에 다 곰팡이가 슬었습니다."}, {"s": "north_league:seok", "t": "천경호 백어 부레가 제일이지. 얼음 밑 백어는 부레가 두꺼워서 풀이 질기네. 자네, 천경호에 가서 줄 좀 드리워 주겠나. 길은 다져 놨으니 반나절이면 갈 걸세."}, {"s": null, "t": "나는 고개를 끄덕이고, 떠나기 전에 석진악에게 새 가죽에 이름을 새길지 정했느냐고 물었다. 석진악이 가죽 위에 손을 얹은 채 오래 생각했다."}, {"s": "north_league:seok", "t": "혜각처럼 안쪽에 적어 두면 북이 울 때마다 그 이름들이 함께 운다지. 듣기엔 좋은 말이야. …자네 생각은 어떤가. 이름 부르는 일은 자네가 우리보다 잘 아니 묻네."}, {"s": null, "t": "나는 석진악에게, 북은 이름을 대신 지고 우는 것이 아니라 사람을 불러 모으는 것이 아니냐고 했다. 이름은 그 북 소리를 듣고 모인 사람들이 소리 내어 불러 주는 편이 맞겠다고 했다."}, {"s": null, "t": "석진악의 손이 가죽 위에서 멈췄다. 솥 앞에서 혜각이 허허 웃었다."}, {"s": "north_league:hyegak", "t": "소승이 서른 해 전에 몰래 한 짓이 들통나는 날이군요. 북한테 이름을 맡겨 둔 셈이었으니까요. 흑련이 이름 맡던 것처럼요."}, {"s": "north_league:seok", "t": "…가죽엔 아무것도 안 새기세. 대신 법을 하나 정하지. 이 북을 치는 사람은 칠 때마다 한 사람 이름을 소리 내어 부르네. 북채 한 번에 이름 하나. 옛 가죽 안쪽 이름들은 혜각이 외워 두었다가 부르고."}, {"s": "north_league:hyegak", "t": "허허, 소승 외울 게 늘었습니다."}, {"s": null, "t": "봉수가 북통 곁에서 고개를 번쩍 들었다."}, {"s": "q:sx_ep_bongsu", "t": "저도 쳐도 돼요? 저도 이름 부를 수 있어요!"}, {"s": "north_league:seok", "t": "백어부터 잡아 오게. 풀이 없으면 북도 없네."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_4', 3, '첫 울림', '천경호에서 낚시를 한다', '{"at": ["iron_monastery"], "tasks": [{"t": "fish", "r": ["sky_lake"], "n": 3}]}'::jsonb, '[{"s": null, "t": "천경호에서 낚아 온 백어로 혜각이 부레풀을 쑤었다. 솥에서 비린 냄새가 끈적하게 올라왔고, 봉수가 코를 쥔 채 솥을 저었다."}, {"s": null, "t": "풀을 바른 가죽을 북통에 씌우고 사흘을 말렸다. 억보와 썰매꾼들이 밧줄로 가죽을 당기면, 석진악이 쇠못을 하나하나 박았다. 탕, 탕, 망치 소리가 산문에 울렸다."}, {"s": null, "t": "나흘째 해 질 녘, 새 가죽을 씌운 큰 북이 대웅전 앞에 다시 세워졌다. 그 곁에는 같은 가죽 남은 것으로 메운 작은 북 몇 개가 놓였다. 비고에 들일 북이었다. 산 아래 아낙들이 떠 보낸 털모자 꾸러미도 그 곁에 쌓였다."}, {"s": null, "t": "석진악이 북채를 들었다. 하늘이 붉게 저물어 가고 있었고, 산문 마당에 모인 행자와 썰매꾼들이 숨을 죽였다."}, {"s": null, "t": "석진악이 북채를 높이 들어 내리쳤다. 두웅, 낮고 깊은 소리가 가슴께를 울리며 산 아래로 굴러 내려갔다."}, {"s": "north_league:seok", "t": "혜각."}, {"s": null, "t": "석진악의 입김이 흩어지지 않았다. 해 진 하늘 아래에서 입김이 금빛 실로 엉기더니, 북 소리를 따라가듯 반짝이며 공중을 건너 혜각의 가슴께에 가 닿았다."}, {"s": null, "t": "혜각이 염주를 쥔 채 제 가슴을 내려다보았다. 실이 닿은 자리에 손을 대자, 늘 웃던 얼굴이 잠깐 굳었다."}, {"s": "north_league:hyegak", "t": "…허허. 맹주님이 소승 이름을 부르신 게 몇 해 만입니까. 늘 수좌, 수좌 하시더니."}, {"s": "north_league:seok", "t": "북채 한 번에 이름 하나라고 했잖나. 첫 이름은 여기 있는 사람으로 했네. 다음부터는 자네가 외운 이름들일세."}, {"s": null, "t": "석진악이 북채를 봉수에게 내밀었다. 봉수가 두 손으로 북채를 받아 들고 북 앞에 섰다. 팔이 바들바들 떨렸다."}, {"s": "q:sx_ep_bongsu", "t": "…누구 불러요?"}, {"s": "north_league:seok", "t": "자네가 정하게."}, {"s": null, "t": "봉수가 마당을 둘러보다가 억보와 눈이 마주쳤다. 봉수가 북채를 힘껏 내리치자 둥, 북이 울었다."}, {"s": "q:sx_ep_bongsu", "t": "억보 대장님!"}, {"s": null, "t": "봉수의 입김은 금빛이 되지 않고 하얗게 흩어졌다. 봉수가 어리둥절해서 제 입가를 만졌다. 혜각이 껄껄 웃었다."}, {"s": "north_league:hyegak", "t": "대장님은 이름이 아니라 호칭이지요. 호칭으로는 안 닿습니다."}, {"s": "q:sx_ep_bongsu", "t": "아! 억보! 억보 아저씨!"}, {"s": null, "t": "이번에는 가는 금빛 실 한 올이 봉수의 입에서 나가 억보의 가슴께에 닿았다. 억보는 제 가슴을 짚고 멍하니 서 있다가, 썰매꾼들이 놀리는 소리에 귀까지 빨개졌다."}, {"s": null, "t": "산 아래에서 횃불 몇 개가 고찰 쪽으로 올라오는 것이 보였다. 북 소리를 듣고 산골 사람들이 무슨 일인가 하여 올라오고 있었다. 석진악이 그 불빛들을 내려다보며 지팡이를 짚었다."}, {"s": "north_league:seok", "t": "봐라. 북이 울면 사람이 오네. 이름은 온 사람들이 부르면 되고."}, {"s": null, "t": "그 밤 고찰 마당에는 산골 사람들이 모여 차례로 북을 쳤다. 북 소리 한 번에 이름 하나씩이었다. 혜각은 북 곁에 서서, 옛 가죽 안쪽에 적었던 이름을 하나씩 외워 불렀다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_north_5', 'side', '뒷이야기·철벽 고찰', '첫눈', '겨울채비가 다 끝난 날, 철벽 고찰 담을 따라 장작더미와 횃불이 늘어서고 산문에 설산 능선 무늬 깃발이 오른다. 여운비와 단비가 낙성 엿을 지고 올라오고, 모두 목인 줄 앞에서 첫눈을 기다린다.', 'iron_monastery', 50, '{mdq_17,ep_north_4}'::text[], null, 1534, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:north_league", "stage": 5}'::jsonb where quest_id = 'ep_north_5';
delete from public.world_quest_steps where quest_id = 'ep_north_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_5', 1, '설산 능선 깃발', '설산 능선 깃발', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "겨울채비가 다 끝나는 날, 철벽 고찰 담을 따라 장작더미가 키보다 높이 쌓였다. 장작더미 사이사이에 횃불 꽂이가 박혔고, 산문 지붕 위로 새 깃대가 섰다."}, {"s": null, "t": "깃대 끝에서 흰 깃발이 펄럭였다. 하얀 천 위에 푸른 실로 설산 능선이 굽이굽이 수놓였고, 능선 끝마다 붉은 실로 작은 점이 박혔다. 고갯길 장대 끝 붉은 천과 같은 빛깔이었다."}, {"s": null, "t": "산문 앞 좌판에서는 혜각이 낙성 떡을 썰고 있었다. 떡판에서 김이 무럭무럭 오르자 산 아래에서 올라온 사람들이 줄을 섰다."}, {"s": "north_league:hyegak", "t": "허허, 손님. 오늘은 일 안 시키겠습니다. 낙성 날은 떡부터 드시는 겁니다. 고찰 법이 하루쯤 바뀌어도 부처님은 뭐라 안 하십니다.", "fac_not": "north_league", "spec": 2, "grp": 1}, {"s": "north_league:hyegak", "t": "허허, 우리 식구. 오늘은 일 안 시키겠습니다. 낙성 날은 떡부터 먹는 겁니다. 식구는 두 개요.", "fac": "north_league", "spec": 1, "grp": 1}, {"s": "north_league:hyegak", "t": "겨울채비가 다섯째 단계까지 다 찼습니다. 여러 조사원님들이 넘겨준 대환단이며 강철 주괴며, 산문에 다 쌓아 놓으면 장작더미만 할 겁니다. 그 몫으로 담에 장작을 올리고 횃불을 박고, 맹약 깃발을 새로 지어 올렸지요."}, {"s": "north_league:hyegak", "t": "설산 능선 무늬는 맹주님이 손수 그리셨습니다. 그림 솜씨는 장작 패는 솜씨만 못하시지만요."}, {"s": null, "t": "산문 처마 아래에서 석진악이 헛기침을 했다. 혜각은 못 들은 척 떡만 썰었다."}, {"s": null, "t": "돌계단 아래에서 방울 소리가 짤랑짤랑 올라왔다. 단비가 엿 항아리를 오른팔에 끼고 올라왔고, 여운비가 단비의 오른쪽에서 엿 짐을 등에 지고 걸었다."}, {"s": "red_moon_cult:danbi", "t": "수좌님! 낙성 엿 가져왔어요! 대장님이 짐 수 세어서 딱 백 개예요!"}, {"s": "north_league:yeo", "t": "아흔아홉이오. 하나는 오는 길에 당신이 먹었소."}, {"s": "red_moon_cult:danbi", "t": "맛을 봐야 팔죠."}, {"s": null, "t": "여운비가 엿 짐을 좌판 곁에 내려놓고 산문 위 깃발을 올려다보았다. 남은 왼 눈으로 깃발을 오래 보다가, 오른 뺨을 바람 쪽으로 돌렸다."}, {"s": "north_league:yeo", "t": "맹주님. 오늘 밤 눈이 오겠습니다. 볼이 그렇게 말합니다."}, {"s": "north_league:seok", "t": "억보도 아침에 그러더군. 왼쪽 귀가 시리다고."}, {"s": null, "t": "여운비의 입꼬리가 아주 조금 올라갔다. 단비가 그것을 보고 여운비의 옆구리를 쿡 찔렀다."}, {"s": "north_league:hyegak", "t": "그럼 오늘 밤은 다들 산문에서 첫눈을 맞으시지요. 산 아래 사람들도 다 묵어 갈 텐데, 내일 내려갈 때 먹을 건량이 모자랍니다. 조사원님, 노정 건량 여섯만 넘겨 주시겠습니까. 떡은 소승이 썰겠습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_5', 2, '목인 줄 앞', '노정 건량을(를) 넘긴다', '{"at": ["iron_monastery"], "give": {"travel_ration": 6}}'::jsonb, '[{"s": null, "t": "노정 건량을 건네자 혜각이 그것을 떡 바구니 곁에 쌓았다. 해가 지자 담을 따라 박힌 횃불에 하나둘 불이 붙었다."}, {"s": null, "t": "장작더미 사이로 횃불이 줄지어 타오르자 고찰 담이 붉게 둘러졌다. 산 아래에서 보면 산 위에 불의 띠가 걸린 것처럼 보일 것 같았다."}, {"s": null, "t": "마당 한가운데에서는 봉수가 큰 북을 쳤다. 둥, 북 소리 한 번에 봉수가 이름 하나씩을 불렀고, 산골 아이들이 봉수 뒤에 줄을 서서 차례를 기다렸다."}, {"s": "q:sx_ep_bongsu", "t": "단비!"}, {"s": null, "t": "금빛 실 한 올이 횃불 사이를 건너 단비의 가슴께에 닿았다. 실은 단비의 오른쪽에서 왔고, 단비는 그쪽 귀로 봉수의 목소리를 또렷이 들었다. 단비가 오른손으로 가슴을 누르고 깔깔 웃었다."}, {"s": "red_moon_cult:danbi", "t": "봉수 행자님, 다음엔 우리 대장님도 불러 주세요! 여운비요!"}, {"s": null, "t": "단비는 엿 항아리를 든 채 마당을 돌며 아이들 손에 엿을 하나씩 쥐여 주었다. 먹빛으로 굳은 왼손은 항아리 손잡이에 걸쳐만 두고, 엿은 오른손으로만 집었다."}, {"s": null, "t": "여운비는 사당 뒤 연무장 목인 줄 앞에 서 있었다. 집안마다 늘어선 짚 목인 가운데 여씨 집안 줄의 목인 하나에 「여사온」 세 글자가 새겨져 있었다. 봄에 여운비가 새긴 글씨였다."}, {"s": null, "t": "나는 여운비 곁으로 가서 섰다. 여운비가 목인 쪽을 본 채 입을 열었다."}, {"s": "north_league:yeo", "t": "겨울채비 내내 한 번밖에 못 와 봤소. 장터 엿 짐 수를 세느라. 억보한테 앞자리를 넘기고 나니, 고찰에 올 핑계가 없어졌소."}, {"s": null, "t": "나는 여운비에게 핑계가 없어도 오면 되지 않느냐고 했다. 여운비가 나를 돌아보았다."}, {"s": "north_league:yeo", "t": "…당신은 늘 그렇게 쉽게 말하오. 그래서 오늘 왔소. 단비가 「핑계 없이 가 봐요」 하길래."}, {"s": null, "t": "연무장 어귀에서 단비가 엿 항아리를 흔들며 우리를 불렀다. 석진악과 혜각, 억보와 봉수가 그 뒤를 따라 목인 줄 앞으로 왔다."}, {"s": "north_league:seok", "t": "다들 여기 있었구먼. 눈은 여기서 맞세. 산문을 지키던 사람들 앞에서."}, {"s": "north_league:hyegak", "t": "허허, 그럼 소승은 화로를 들고 오겠습니다. 첫눈 맞다가 맹주님 무릎이 얼면 안 되니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_north_5', 3, '첫눈', '철벽 고찰에서 쉰다', '{"at": ["iron_monastery"], "tasks": [{"t": "rest", "r": ["iron_monastery"], "n": 1}]}'::jsonb, '[{"s": null, "t": "자정이 지나도록 눈은 오지 않았다. 혜각이 가져온 화로에서 숯이 빨갛게 숨을 쉬었고, 봉수는 석진악의 무릎을 베고 꾸벅꾸벅 졸았다."}, {"s": "red_moon_cult:danbi", "t": "대장님, 볼이 틀린 거 아니에요?"}, {"s": "north_league:yeo", "t": "볼은 틀리지 않소. 늦을 뿐이오."}, {"s": null, "t": "그 말이 끝나자마자 여운비가 오른 뺨을 하늘로 들었다. 억보가 거의 같은 때에 왼쪽 귀를 손으로 감쌌다."}, {"s": null, "t": "차가운 것 하나가 내 손등에 톡 내려앉았다. 고개를 들자 횃불 빛 속으로 하얀 눈송이가 하나, 둘 내려오더니, 이내 셀 수 없이 사르르 쏟아지기 시작했다."}, {"s": null, "t": "단비가 오른손을 펴 눈을 받았다. 고개를 기울여 오른쪽 귀로 한참 무언가를 듣다가 눈을 동그랗게 떴다."}, {"s": "red_moon_cult:danbi", "t": "들려요. 눈 오는 소리요. 장작더미에 앉는 소리랑 목인에 앉는 소리가 달라요."}, {"s": null, "t": "봉수가 벌떡 일어나 눈을 맞으며 연무장을 빙빙 돌았다."}, {"s": "q:sx_ep_bongsu", "t": "눈이다! 첫눈이에요! 맹주님, 첫눈!"}, {"s": null, "t": "억보가 뛰어다니는 봉수를 붙잡아 털모자를 씌웠다. 산 아래 아낙들이 떠 보낸 털모자였다."}, {"s": null, "t": "석진악이 화로 곁에서 천천히 일어나 목인 줄을 둘러보았다. 집안마다의 목인 어깨 위로 눈이 하얗게 쌓여 갔다."}, {"s": "north_league:seok", "t": "북령은 백 년 동안 「다시는」을 맹세로 삼았네. 다시는 잃지 않겠다고. 그 맹세 때문에 입에 안 올리고 묻어 둔 이름도 많았지."}, {"s": null, "t": "석진악이 여씨 집안 줄 목인의 어깨에서 눈을 손바닥으로 털어 냈다. 가슴께의 「여사온」 세 글자가 다시 드러났다."}, {"s": "north_league:seok", "t": "올해 깃발에는 그 말을 안 넣었네. 능선만 그렸지. 산은 「다시는」이라고 하지 않아. 해마다 눈을 맞고, 해마다 녹이고, 또 맞을 뿐이야."}, {"s": null, "t": "혜각이 염주를 굴리며 하늘을 올려다보았다. 눈송이가 혜각의 민머리 위에 내려앉아 금방 녹았다."}, {"s": "north_league:hyegak", "t": "허허, 그럼 올겨울 맹세는 무엇으로 하실 겁니까."}, {"s": "north_league:seok", "t": "맹세는 안 하네. 같이 날 뿐이지."}, {"s": null, "t": "여운비가 목인 줄 앞에서 고개를 숙였다. 단비가 여운비의 왼쪽에 와서 섰다. 여운비의 오른 뺨에 눈송이가 내려앉았다가 녹아 흘렀다."}, {"s": "north_league:yeo", "t": "…나쁘지 않습니다, 맹주님."}, {"s": null, "t": "석진악이 껄껄 웃었다. 웃음소리가 눈 내리는 밤 마당에 오래 퍼졌다. 담을 따라 늘어선 횃불 위로 설산 능선 깃발이 눈을 맞으며 펄럭였다."}, {"s": null, "t": "새벽녘, 산 아래 사람들이 노정 건량을 품에 넣고 눈길을 내려갔다. 다져진 길 위로 장대 끝 붉은 천들이 눈을 털며 날렸다. 맨 앞에는 억보가 섰고, 맨 뒤에는 봉수가 장작 썰매를 끌고 따라갔다."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_red_1', 'side', '뒷이야기·백골 장터', '무너진 제단 돌', '백골 장터 제단 맨 윗단 돌이 빠지고, 혼자 그 돌을 든 대호법 사마겸이 아랫면의 글씨를 읽지 못해 단비를 부른다. 돌 밑에는 백 년 전 셈에서 나온 축문이 새겨져 있었다. 단비가 사당 골목의 원래 축문을 새기자고 하고, 사마겸은 처음으로 글자를 배운다.', 'bone_market', 50, '{mdq_17}'::text[], null, 1535, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:red_moon_cult", "stage": 1}'::jsonb where quest_id = 'ep_red_1';
delete from public.world_quest_steps where quest_id = 'ep_red_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_1', 1, '돌을 든 거한', '돌을 든 거한', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "백골 장터는 한낮에도 붉었다. 천막마다 붉은 천이 늘어졌고, 짐승 뼈를 엮은 풍경이 모래바람에 달그락달그락 울었다."}, {"s": null, "t": "장터 공터 북쪽 끝에 붉은 돌로 쌓은 제단이 있었다. 맨 윗단 돌 하나가 무너져 모래에 반쯤 박혀 있었다. 교도들이 그 둘레에 둘러서서 웅성거렸다."}, {"s": null, "t": "무너진 돌 앞에서 거한 하나가 웃통을 벗고 있었다. 팔뚝에 붉은 문신이 굽이쳤다. 대호법 사마겸이었다. 사마겸이 돌 밑에 두 팔을 넣고 끙, 하고 혼자 들어 올렸다."}, {"s": null, "t": "돌이 사마겸의 가슴께까지 올라오자 교도들이 와아 소리를 질렀다. 사마겸은 돌을 든 채 아랫면을 들여다보더니 그대로 굳었다."}, {"s": null, "t": "돌 아랫면에 글씨가 빽빽이 새겨져 있었다. 사마겸이 눈을 가늘게 뜨고 글자를 노려보았다. 입술이 달싹였지만 소리는 나오지 않았다."}, {"s": "red_moon_cult:sama", "t": "…단비! 단비 어디 있느냐! 이리 와서 이것 좀 읽어라!"}, {"s": null, "t": "장터 어귀 엿판에서 단비가 고개를 들었다. 단비는 사마겸의 고함을 오른쪽 귀로 듣고 몸을 돌렸다. 엿판 곁에서 장부를 적던 여운비가 먼저 일어섰다."}, {"s": "north_league:yeo", "t": "대호법이 부르오. 엿판은 내가 보겠소."}, {"s": "red_moon_cult:danbi", "t": "대장님이 엿을 팔면 손님이 다 도망가요. 같이 가요."}, {"s": null, "t": "단비가 여운비의 소매를 잡아끌고 제단으로 왔다. 사마겸의 팔이 부들부들 떨리고 있었다. 단비가 고개를 꺾어 돌 아랫면을 들여다보았다."}, {"s": "red_moon_cult:danbi", "t": "대호법님, 일단 내려놓으세요. 팔 떨리는 거 다 보여요."}, {"s": "red_moon_cult:sama", "t": "안 떨린다. 읽어라."}, {"s": null, "t": "단비가 한숨을 쉬고 오른손 검지로 글자를 짚어 갔다. 다 읽기도 전에 단비의 얼굴에서 웃음기가 사라졌다."}, {"s": "red_moon_cult:danbi", "t": "서약 끝 구절이에요. 「거둔 이름을 받아 힘으로 삼는다.」 백 년 전 셈에서 나온 거예요. 제가 열네 살에 외운 거랑 똑같아요."}, {"s": null, "t": "사마겸이 돌을 모래 위에 쿵 내려놓았다. 교도들의 웅성거림이 뚝 그쳤다. 사마겸이 그제야 제단 앞에 선 나를 보았다."}, {"s": "red_moon_cult:sama", "t": "조사원. 마침 왔구나. 보았느냐. 우리가 쉰 해 동안 절하던 돌이다. 그 밑에 저게 있었다.", "fac_not": "red_moon_cult", "spec": 2, "grp": 1}, {"s": "red_moon_cult:sama", "t": "교도. 마침 왔구나. 보았느냐. 우리가 쉰 해 동안 절하던 돌이다. 그 밑에 저게 있었다.", "fac": "red_moon_cult", "rank": [1, 2], "spec": 0, "grp": 1}, {"s": "red_moon_cult:sama", "t": "{등급}께서 마침 오셨군. 보셨소? 우리가 쉰 해 동안 절하던 돌이오. 그 밑에 저게 있었소.", "fac": "red_moon_cult", "rank": [3, 4], "spec": 0, "grp": 1}, {"s": "red_moon_cult:sama", "t": "장로님, 마침 오셨습니다. 보셨습니까. 우리가 쉰 해 동안 절하던 돌입니다. 그 밑에 저게 있었습니다.", "fac": "red_moon_cult", "rank": [5, 5], "spec": 0, "grp": 1}, {"s": null, "t": "여운비가 돌 둘레를 한 바퀴 돌았다. 여운비는 오른 볼을 바람 쪽으로 돌린 채 한참 서 있다가 입을 열었다."}, {"s": "north_league:yeo", "t": "서쪽에서 바람이 세게 드오. 모래가 이쪽 단만 깎았소. 무너진 게 아니라 닳아서 빠진 거요."}, {"s": "red_moon_cult:danbi", "t": "대장님, 볼로 그런 것까지 읽어요?"}, {"s": "north_league:yeo", "t": "…눈으로 볼 때보다 정확하오."}, {"s": null, "t": "단비가 입술을 비죽이며 웃었다. 단비는 돌을 다시 내려다보다가 사마겸을 돌아보았다."}, {"s": "red_moon_cult:danbi", "t": "대호법님, 이 돌 그대로 도로 올리지 마요. 다들 또 이 구절 위에 절하게 돼요. 아랫면을 깎아 내고, 붉은 사당 골목 벽에 있던 원래 축문을 새겨요. 「거둔 이름은 달빛 아래 보내되, 그 이름으로 힘을 삼지 않는다.」 그거요."}, {"s": "red_moon_cult:sama", "t": "새기는 건 내가 하마. 글자는 네가 그려라. …돌 깎을 정은 대장간에 있다. 문제는 새긴 자리에 부을 붉은 칠이다. 주사가 모자란다."}, {"s": null, "t": "사마겸이 나를 보았다. 입을 열었다가 도로 다물었다. 무엇을 부탁하는 데 익숙하지 않은 얼굴이었다."}, {"s": "red_moon_cult:sama", "t": "…적사 황무지 바위틈에 주사가 난다. 그런데 요즘 그 바위틈에 전갈이 들끓어 교도들이 못 들어간다. 단비, 네가 말해라."}, {"s": "red_moon_cult:danbi", "t": "대호법님은 부탁하는 법을 못 배우셨어요. {이름} 님, 적사 황무지에 가서 주사 좀 캐다 주세요. 전갈도 좀 쫓아 주시고요. 이 돌은 대호법님 손으로 새기게 하고 싶어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_1', 2, '글자 배우는 손가락', '적사 황무지에서 주사 광물을(를) 모은다, 붉은 전갈을(를) 물리친다', '{"at": ["bone_market"], "tasks": [{"t": "gather", "items": ["cinnabar"], "r": ["red_plain"], "n": 4}, {"t": "win", "m": ["g_red_plain"], "n": 6}]}'::jsonb, '[{"s": null, "t": "주사 광물 자루를 내려놓으니 사마겸이 끌로 돌 아랫면을 다 깎아 놓고 기다리고 있었다. 옛 구절이 있던 자리는 매끈한 붉은 돌이 되어 있었다."}, {"s": null, "t": "단비가 깎인 돌 위에 숯으로 새 축문을 그렸다. 먹빛으로 굳은 왼손은 무릎에 얹고 오른손만 썼다. 여운비가 곁에서 돌을 붙잡아 주었다."}, {"s": "red_moon_cult:sama", "t": "그 글자가 「삼지」냐. 「않는다」는 어디냐."}, {"s": "red_moon_cult:danbi", "t": "여기요. 대호법님, 끌로 새기기 전에 한 번 읽어 보셔야죠. 따라 하세요. 「거둔 이름은.」"}, {"s": "red_moon_cult:sama", "t": "…거둔 이름은."}, {"s": null, "t": "사마겸이 돌 앞에 쪼그려 앉아 손가락으로 글자를 하나씩 짚었다. 굵은 손가락 하나가 글자 셋을 한꺼번에 덮었다. 천막 그늘에서 교도들이 몰래 키득거렸다."}, {"s": "red_moon_cult:sama", "t": "웃는 놈은 내일 수련굴 백 바퀴다."}, {"s": null, "t": "웃음소리가 뚝 그쳤다. 단비가 입을 가리고 어깨를 떨었다."}, {"s": null, "t": "나는 사마겸에게 글을 어디서 배웠느냐고 물었다. 사마겸은 내 쪽을 보지 않고, 손가락을 글자에 얹은 채 돌에 대고 말하듯 대답했다."}, {"s": "red_moon_cult:sama", "t": "제대로 배운 적이 없다. 큰 글자를 반쯤 겨우 읽는다. 흑사단에 있을 때는 칼만 배웠지. 형제들 이름도 글자로는 모르고 소리로만 외웠다."}, {"s": "red_moon_cult:sama", "t": "교에 와서도 마찬가지였다. 장부가 오면 읽는 건 늘 무녀들 몫이었고, 나는 그걸 크게 따라 부르는 일만 했다."}, {"s": null, "t": "단비가 웃음을 거두고 사마겸을 보았다. 여운비는 돌을 붙든 손을 놓지 않은 채 말없이 고개를 숙였다."}, {"s": "red_moon_cult:danbi", "t": "그럼 이 축문은 대호법님이 처음으로 혼자 읽고 새기는 글이 되겠네요. 제가 끝까지 가르쳐 드릴게요."}, {"s": "red_moon_cult:sama", "t": "…흥. 가르쳐라. 대신 남한테 말하지 마라."}, {"s": null, "t": "여운비가 고개를 들었다. 하얗게 바랜 오른 눈 쪽 볼이 천막 쪽으로 기울어 있었다."}, {"s": "north_league:yeo", "t": "대호법. 장터 사람들이 벌써 다 보고 있소."}, {"s": null, "t": "사마겸이 천막 쪽을 돌아보았다. 교도들이 일제히 고개를 돌렸다. 사마겸이 이마를 짚었다."}, {"s": "red_moon_cult:sama", "t": "됐다. 주사는 갈아서 칠액에 개어야 한다. 그런데 장터 칠장이가 장 보러 서쪽으로 나가서 칠액이 없다. 글자마다 붉은 칠이 고루 먹으려면 둘은 있어야 하는데."}, {"s": null, "t": "사마겸이 말끝을 흐리며 나를 흘끔 보았다. 이번에도 부탁하는 말은 끝내 입 밖으로 나오지 않았다. 단비가 웃음을 참으며 내 쪽으로 몸을 기울였다."}, {"s": "red_moon_cult:danbi", "t": "제가 또 대신 말씀드릴게요. 칠액 둘만 개어 주세요, {이름} 님. 대호법님이 글자 하나 안 건너뛰고 칠하시게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_1', 3, '새로 올린 돌', '칠액을(를) 만든다, 칠액을(를) 넘긴다', '{"at": ["bone_market"], "tasks": [{"t": "craft", "items": ["lacquer"], "n": 2}], "give": {"lacquer": 2}}'::jsonb, '[{"s": null, "t": "주사 가루를 갠 칠액은 피처럼 붉었다. 사마겸은 끌로 판 글자마다 붓으로 그 칠을 메웠다. 붓질은 서툴렀지만 한 획도 건너뛰지 않았다."}, {"s": null, "t": "칠이 마르자 사마겸이 돌을 들어 제단 맨 윗단에 올렸다. 이번에는 글자가 위로 오게 놓았다. 돌이 제자리에 쿵 앉았다."}, {"s": null, "t": "단비가 제단 앞에 섰다. 단비는 방울을 꺼내 오른손으로 쥐었다가, 흔들지 않고 도로 넣었다."}, {"s": "red_moon_cult:danbi", "t": "저는 이제 무녀가 아니라서, 제가 외면 축문이 아니라 그냥 엿장수 노랫소리예요. 대호법님이 글로 읽어 주세요. 크게요. 제 오른쪽에서요."}, {"s": null, "t": "사마겸이 단비의 오른쪽에 섰다. 거한은 숨을 크게 들이켜고 손가락으로 돌 위 글자를 짚어 가며 읽었다. 한 글자마다 한 번씩 손가락이 멈췄다."}, {"s": "red_moon_cult:sama", "t": "거둔… 이름은… 달빛 아래… 보내되. 그 이름으로… 힘을… 삼지 않는다."}, {"s": null, "t": "사마겸의 목소리가 장터 끝까지 울렸다. 천막 사이에서 교도들이 하나둘 나와 제단 앞에 섰다. 아무도 웃지 않았다."}, {"s": null, "t": "단비가 눈을 감고 오른쪽 귀로 그 소리를 들었다. 단비의 입가가 천천히 풀렸다."}, {"s": "red_moon_cult:danbi", "t": "잘 들렸어요. 대호법님 목소리가 커서, 오른쪽으로만 들어도 다 들려요."}, {"s": "red_moon_cult:sama", "t": "칭찬이냐, 놀리는 거냐."}, {"s": "red_moon_cult:danbi", "t": "둘 다요."}, {"s": null, "t": "여운비가 엿판으로 돌아가 장부에 한 줄을 적었다. 나는 무엇을 적었느냐고 물었다. 여운비가 장부를 내 쪽으로 기울여 보였다."}, {"s": "north_league:yeo", "t": "「오늘 엿 넷 팔림. 대호법이 축문 읽음.」 짐 수만 적는 장부지만, 이건 적어 둬야 할 것 같았소."}, {"s": null, "t": "그때 장터 상점 쪽에서 비명 같은 소리가 났다. 상점 천막 앞에서 교도들이 코를 막고 우르르 물러서고 있었다. 단비가 그쪽을 보더니 웃음을 터뜨렸다."}, {"s": "red_moon_cult:danbi", "t": "상점 언니가 삭힌 홍어를 들였대요. 사업에 물건 넘긴 분들 덕에 장터 상점에 새 물건이 둘 들어왔거든요. 맹호 비약이랑 저 홍어요. 교도들만 살 수 있대요."}, {"s": "north_league:yeo", "t": "…바람이 이쪽으로 부오."}, {"s": null, "t": "여운비가 코를 막고 엿판 한쪽 끝을 들었다. 단비가 깔깔 웃으며 반대쪽 끝을 오른손으로 들었다. 두 사람이 엿판을 바람 반대쪽으로 옮겼다."}, {"s": null, "t": "사마겸은 웃지 않고 제단을 올려다보고 있었다. 거한의 이마가 찡그려져 있었다."}, {"s": "red_moon_cult:sama", "t": "축문은 새로 올렸다. 그런데 이제 제단에 무엇을 올리지? 이름은 안 올린다. 그럼 빈 제단 앞에 절을 하나."}, {"s": null, "t": "아무도 대답하지 못했다. 교도들이 서로 얼굴만 보았다. 모래바람이 새 축문 위를 쓸고 지나갔다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_red_2', 'side', '뒷이야기·백골 장터', '제단에 무엇을 올리나', '빈 제단에 무엇을 올릴지를 두고 장터가 한 달째 시끄럽다. 교주 월화가 대낮의 공터에 나와 장터 사람들과 함께 모래 위에 앉는다. 서문 폐성벽 순례꾼들의 보따리에서 답을 찾아, 첫 상은 장터에서 가장 흔한 풀로 지은 나물밥으로 올리고 내려서 다 함께 나눈다.', 'bone_market', 50, '{mdq_17,ep_red_1}'::text[], null, 1536, '[]'::jsonb, true, null, null)
