update public.world_quests set open_req = '{"project": "f:red_moon_cult", "stage": 2}'::jsonb where quest_id = 'ep_red_2';
delete from public.world_quest_steps where quest_id = 'ep_red_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_2', 1, '공터의 다툼', '공터의 다툼', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "빈 제단을 두고 장터가 한 달째 시끄럽다는 소문을 듣고 백골 장터에 갔다. 공터에 닿기도 전에 언성 높은 소리가 들려왔다."}, {"s": null, "t": "제단 앞에 교도들이 두 패로 갈라서 있었다. 한 패는 손바닥을 칼로 긋는 시늉을 했고, 다른 패는 향 묶음을 흔들었다."}, {"s": "q:sx_ep_follower", "t": "입교할 때 피 한 방울을 달에 바쳤소! 제단엔 피를 올려야 적월이오!"}, {"s": "q:sx_ep_marketwife", "t": "피는 무슨 피유! 장터 제단이면 장터 물건을 올려야지요! 우리 집 육포가 제일 좋다니까요!"}, {"s": null, "t": "엿판에서 단비가 팔짱을 끼고 그 꼴을 보고 있었다. 단비 오른쪽에 여운비가 장부를 들고 서 있었다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님, 오셨어요? 저거 보세요. 한 달째 저래요. 어제는 누가 제단에 생선 대가리를 올렸다가 대호법님한테 쫓겨났어요."}, {"s": "north_league:yeo", "t": "그 생선은 내가 치웠소. 바람이 엿판 쪽으로 불어서."}, {"s": null, "t": "다툼이 한창일 때 장터 맨 안쪽 천막의 붉은 천이 걷혔다. 교주 월화가 걸어 나왔다. 면사포를 쓰지 않은 얼굴이었다. 오른쪽 절반에 앉은 잿빛 금이 한낮 햇빛을 받았다."}, {"s": null, "t": "공터가 쥐 죽은 듯 조용해졌다. 교주가 천막 밖으로, 그것도 대낮의 공터로 나오는 것을 장터 사람들은 처음 보았다. 교도들이 허겁지겁 무릎을 꿇었다."}, {"s": "red_moon_cult:wolhwa", "t": "일어나라. 무릎 꿇을 일이 아니다. 나도 앉으러 나왔다."}, {"s": null, "t": "월화가 제단 앞 모래 위에 그대로 앉았다. 교주의 자리도 방석도 없었다. 사마겸이 천막에서 방석을 들고 뛰어나오다 멈춰 섰다. 월화가 손짓으로 방석을 물렸다."}, {"s": "red_moon_cult:wolhwa", "t": "교도, 너도 앉아라. 오늘은 다 같이 앉아서 정한다.", "fac": "red_moon_cult", "rank": [1, 4], "spec": 0, "grp": 1}, {"s": "red_moon_cult:wolhwa", "t": "장로, 자네도 앉게. 오늘은 장로 자리가 따로 없네.", "fac": "red_moon_cult", "rank": [5, 5], "spec": 0, "grp": 1}, {"s": "red_moon_cult:wolhwa", "t": "그대도 앉아라. 장터 일에는 손님 자리가 따로 없다.", "fac_not": "red_moon_cult", "spec": 2, "grp": 1}, {"s": null, "t": "나는 월화 곁에 앉았다. 단비와 여운비가 그 옆에, 사마겸이 맨 끝에 앉았다. 교도들과 장터 사람들이 머뭇거리다가 하나둘 모래 위에 엉덩이를 붙였다."}, {"s": "red_moon_cult:wolhwa", "t": "피는 안 올린다. 입교 때 받던 피 한 방울도 이제는 받지 않는다. 달은 피를 먹지 않는다. 그건 백 년 전 셈이 만든 말이다."}, {"s": "red_moon_cult:wolhwa", "t": "그렇다고 빈 제단을 둘 수도 없지. 그래서 묻는다. 요즘 장터 둘레가 어떠냐."}, {"s": null, "t": "장터 아낙 하나가 손을 번쩍 들었다."}, {"s": "q:sx_ep_marketwife", "t": "요새 상처가 빨리 아물어요, 교주님. 서문 폐성벽 순례길 다녀온 사람들이 모래에서 별것이 다 나온다고들 해요. 다들 제단 덕이라던데요."}, {"s": "red_moon_cult:wolhwa", "t": "제단 덕이 아니다. 여러 조사원이 사업에 짐을 날라 준 덕이다. 달이 한 일이라고 하면 또 셈을 시작하게 된다."}, {"s": null, "t": "월화가 나를 보았다. 반쪽 얼굴에 피곤한 웃음이 떠올랐다."}, {"s": "red_moon_cult:wolhwa", "t": "서문 폐성벽에 순례꾼들이 쉬어 가는 막이 있다. 교도를 보내면 교주 듣기 좋은 말만 하고 돌아올 게다. 그대가 가서, 그들이 무엇을 들고 다니고 무엇을 바라는지 듣고 오너라."}, {"s": "red_moon_cult:wolhwa", "t": "오는 길에 들에서 야령초도 좀 뜯어 오너라. 이 장터 둘레에서 제일 흔한 풀이다. 흔한 것부터 생각해 보자."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_2', 2, '순례꾼의 보따리', '서문 폐성벽을(를) 살핀다, 서문 폐성벽에서 야령초을(를) 모은다', '{"at": ["bone_market"], "tasks": [{"t": "search", "r": ["west_gate"], "n": 3}, {"t": "gather", "items": ["herb"], "r": ["west_gate"], "n": 4}]}'::jsonb, '[{"s": null, "t": "서문 폐성벽 무너진 성루 아래에서 순례꾼들의 막을 찾았다. 그들의 이야기를 들고 장터로 돌아오니 월화는 아직 제단 앞 모래 위에 앉아 있었다. 밤새 그 자리를 지킨 얼굴이었다."}, {"s": null, "t": "나는 순례꾼들 보따리에 무엇이 들었는지 이야기했다. 주먹밥과 마른 무, 집에서 구운 떡, 아이가 그린 달 그림이 들어 있었다. 달에 바칠 것은 아무도 들고 있지 않았고, 모두 장터에서 나눠 먹을 것뿐이었다."}, {"s": "red_moon_cult:wolhwa", "t": "…나눠 먹을 것이라."}, {"s": "red_moon_cult:sama", "t": "순례꾼들은 원래 그렇습니다, 교주님. 먼 길을 오는 사람은 제 먹을 것보다 남 줄 것을 더 싸 옵니다. 저도 흑사단에 있을 때 그랬습니다."}, {"s": null, "t": "월화가 사마겸을 돌아보았다. 사마겸이 제 말에 놀란 듯 헛기침을 했다."}, {"s": "red_moon_cult:danbi", "t": "그럼 그거 하면 되잖아요. 제단에는 장터 사람들이 저마다 나눠 먹을 걸 한 가지씩 올리고, 절 한 번 하고, 내려서 다 같이 먹는 거예요. 달한테 주는 게 아니라 달 아래서 나누는 거요."}, {"s": "q:sx_ep_marketwife", "t": "육포도 돼요?"}, {"s": "red_moon_cult:danbi", "t": "육포도 돼요. 생선 대가리는 안 되고요."}, {"s": null, "t": "공터에 웃음이 퍼졌다. 여운비만 웃지 않고 장부에 무언가를 적었다."}, {"s": "north_league:yeo", "t": "「생선 대가리 안 됨.」 적어 두겠소. 또 올리는 사람이 있을 테니."}, {"s": null, "t": "월화가 오래 웃었다. 웃을 때마다 반쪽 얼굴의 금이 조금씩 접혔다. 웃음을 그친 월화가 나를 보았다."}, {"s": "red_moon_cult:wolhwa", "t": "첫 상은 무엇으로 올릴꼬. 피도 이름도 아니고, 장터에서 가장 흔한 풀로 짓는 밥이면 좋겠구나. 뜯어 온 야령초로 나물밥을 지어 다오. 셋이면 된다. 하나는 제단에, 하나는 순례꾼 막에, 하나는… 우리 몫이다."}, {"s": "red_moon_cult:danbi", "t": "엿은요?"}, {"s": "red_moon_cult:wolhwa", "t": "엿은 네가 올려라. 너는 이제 무녀가 아니라 장사꾼이니, 장사꾼 몫으로."}, {"s": null, "t": "단비가 입을 벌렸다가 웃음을 터뜨렸다. 여운비는 장부 끝에 「엿 하나, 제단 몫. 값 안 받음.」이라고 적었다."}, {"s": null, "t": "사마겸이 천막으로 들어가 무 한 다발을 들고 나왔다. 거한은 무를 모래 위에 내려놓고 칼집에서 작은 칼을 뽑았다."}, {"s": "red_moon_cult:sama", "t": "내 몫은 이거다. 수련굴 앞에서 깎아 먹던 무다. 다른 건 가진 게 없다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_2', 3, '달 아래 나누는 상', '야령초 나물밥을(를) 만든다, 야령초 나물밥을(를) 넘긴다', '{"at": ["bone_market"], "tasks": [{"t": "craft", "items": ["herb_rice"], "n": 3}], "give": {"herb_rice": 3}}'::jsonb, '[{"s": null, "t": "해 질 녘 제단 위에 첫 상이 차려졌다. 맨 가운데 내가 지은 야령초 나물밥 한 그릇이 놓였고, 그 옆에 단비의 엿 하나와 장터 아낙의 육포, 사마겸이 깎은 무 한 접시가 놓였다."}, {"s": null, "t": "장터 사람들도 저마다 한 가지씩 들고 와 제단 아랫단에 놓았다. 뼈 감정사 노파는 말린 대추 한 줌을, 아이들은 모래로 빚은 달을 올렸다. 제단 둘레가 금세 장날 좌판처럼 북적였다."}, {"s": null, "t": "월화가 제단 앞에 섰다. 월화는 허리를 깊이 숙였다가 일어서서 장터 사람들을 돌아보았다. 교주가 절하는 모습을 교도들은 처음 보았다."}, {"s": "red_moon_cult:wolhwa", "t": "적월은 이제 달에게 바치지 않는다. 달 아래에서 나눈다. 오늘 이 상에 이름은 하나도 오르지 않았다. 그래도 상이 꽉 찼구나."}, {"s": null, "t": "사마겸이 제단에서 나물밥 그릇을 내려 월화 앞에 놓았다. 월화가 수저를 들어 한 숟갈 뜨고 그릇을 옆 교도에게 넘겼다. 그릇은 사람에서 사람으로 공터를 한 바퀴 돌았다."}, {"s": "q:sx_ep_follower", "t": "교주님이 장터 밥을 드시는구려…"}, {"s": "q:sx_ep_marketwife", "t": "우리 육포도 드셔요, 교주님!"}, {"s": null, "t": "월화가 육포를 받아 오래 씹었다. 장터 아낙이 감격해 눈물을 훔쳤다. 사마겸이 그 꼴을 보며 콧김을 내뿜었는데, 입꼬리가 올라가 있었다."}, {"s": null, "t": "단비는 제단 아랫단에 앉아 엿 꾸러미를 아이들에게 돌렸다. 여운비가 단비의 오른쪽에 앉아 아이들 수를 셌다."}, {"s": "north_league:yeo", "t": "아이 스물셋. 엿 스물둘. 하나 모자라오."}, {"s": "red_moon_cult:danbi", "t": "제 몫 주면 되죠. 대장님, 장부에 「무녀 몫 없음」이라고 적지 마요. 저 이제 무녀 아니에요."}, {"s": "north_league:yeo", "t": "…「엿장수 몫 없음」이라고 적겠소."}, {"s": null, "t": "단비가 오른손으로 여운비의 어깨를 툭 쳤다. 여운비는 피하지 않았다."}, {"s": null, "t": "밤이 내려앉자 월화가 나물밥 마지막 그릇을 들고 나에게 왔다. 「우리 몫」이라던 그릇이었다. 월화가 그릇을 내 앞에 놓고 곁에 앉았다."}, {"s": "red_moon_cult:wolhwa", "t": "장터 둘레가 순해진 것도, 오늘 상을 차린 것도 다 남의 손이 보탠 일이로구나. 적월은 오래 남의 것으로 강해졌다. 이제 남의 손을 빌리고 고맙다고 말하는 걸 배워야겠다. …고맙다."}, {"s": null, "t": "월화는 그 말을 하고 오래 입을 다물었다. 고맙다는 말을 하는 데 익숙하지 않은 얼굴이었다. 나는 수저를 들어 월화와 나물밥을 나누어 먹었다."}, {"s": "red_moon_cult:sama", "t": "교주님. 순례꾼 막에서 하나 더 들었습니다. 제단터까지 가는 옛 순례 길이 다시 트인다고들 합니다. 제단터 기둥에는 옛 서약 실이 아직 묶여 있을 겁니다."}, {"s": "red_moon_cult:wolhwa", "t": "그 실은 누군가 풀어야겠구나. …단비가 그 길을 잘 알지."}, {"s": null, "t": "엿을 돌리던 단비의 손이 멈추었다. 여운비가 단비 쪽으로 고개를 돌렸다. 단비는 대답하지 않고 남은 엿 하나를 제 입에 넣었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_red_3', 'side', '뒷이야기·백골 장터', '붉은 들 지름길', '장터에서 적월 제단터까지 옛 순례 길이 지름길로 트인다. 단비와 여운비가 앞장서 제단터 돌기둥에 묶인 서약 실 매듭을 풀러 간다. 단비는 열네 살에 묶은 제 매듭을 여운비가 잡아 준 실 끝으로 끊고, 여운비는 볼로 바람을 읽어 붉은 달 밤마다 울던 북소리의 까닭을 찾는다.', 'bone_market', 50, '{mdq_17,ep_red_2}'::text[], null, 1537, '[]'::jsonb, true, null, null)
