update public.world_quests set open_req = '{"project": "f:red_moon_cult", "stage": 3}'::jsonb where quest_id = 'ep_red_3';
delete from public.world_quest_steps where quest_id = 'ep_red_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_3', 1, '쉬는 엿판', '쉬는 엿판', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "그사이 장터에서 적월 제단터까지 순례 길이 다시 트였다는 기별이 왔다. 백골 장터에 가 보니 단비의 엿판에 「오늘 쉼」이라고 쓴 나무패가 걸려 있었다. 여운비의 글씨였다."}, {"s": null, "t": "단비는 엿판 뒤에서 봇짐을 싸고 있었다. 봇짐에는 엿 꾸러미와 작은 칼 하나가 들어갔다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님, 오셨네요. 오늘 제단터 가요. 지름길이 났대요. 예전엔 모래 언덕을 빙 돌아갔는데 이제 곧장 간대요. 운임 내는 역참도 안 거치고요."}, {"s": "red_moon_cult:danbi", "t": "{등급}님은 그 길 처음이시죠? 순례 길은 무녀들만 걸었거든요. 이제 아무나 걸어도 돼요.", "fac": "red_moon_cult", "spec": 1, "grp": 1}, {"s": "red_moon_cult:danbi", "t": "남의 세력 성지 가는 길인데 같이 가 주시는 거예요? 대장님만 데려가면 제가 얘기할 사람이 없거든요.", "fac_not": "red_moon_cult", "spec": 2, "grp": 1}, {"s": "north_league:yeo", "t": "나는 사람이 아니오?"}, {"s": "red_moon_cult:danbi", "t": "대장님은 바람 읽느라 말을 안 하시잖아요."}, {"s": null, "t": "여운비가 대꾸 없이 칼을 허리에 찼다. 칼자루 끝의 붉은 술이 달랑거렸지만 여운비는 그쪽을 보지 않았다. 여운비는 볼을 바람 쪽으로 돌려 한참 서 있었다."}, {"s": "north_league:yeo", "t": "남서풍이오. 오후엔 모래가 일어나겠소. 해 오르기 전에 떠나야 하오."}, {"s": null, "t": "나는 제단터에 가서 무엇을 하느냐고 물었다. 단비가 봇짐 끈을 오른손과 이로 묶다가 고개를 들었다."}, {"s": "red_moon_cult:danbi", "t": "제단터 돌기둥마다 붉은 실이 묶여 있어요. 서약 실이요. 무녀가 첫 서약을 하면 제단터 기둥에 실을 하나 묶거든요. 제 것도 거기 있어요. …다 풀어야죠. 이제 서약은 안 하니까요."}, {"s": null, "t": "단비는 그 말을 하고 엿 하나를 입에 넣었다. 여운비가 말없이 단비의 오른쪽으로 걸음을 옮겼다."}, {"s": null, "t": "사마겸이 장터 어귀까지 따라 나왔다. 거한이 단비의 봇짐을 들어 보더니 너무 가볍다며 혀를 찼다."}, {"s": "red_moon_cult:sama", "t": "제단터에는 핏달 박쥐가 들끓는다. 서약이 끊긴 뒤로 제물 냄새를 못 맡아 더 사나워졌어. 호송대장, 가거든 길목부터 치시오. 무녀를 다치게 하면…"}, {"s": "red_moon_cult:danbi", "t": "저 무녀 아니에요, 대호법님."}, {"s": "red_moon_cult:sama", "t": "…엿장수를 다치게 하면 장터 밖으로 던지겠소."}, {"s": null, "t": "단비가 깔깔 웃으며 봇짐을 메었다. 여운비가 한 걸음 앞서 지름길 어귀로 걸어갔다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_3', 2, '바람이 가리키는 기둥', '적월 제단터에 간다, 핏달 박쥐을(를) 물리친다', '{"at": ["crimson_altar"], "tasks": [{"t": "travel", "r": ["crimson_altar"], "n": 1}, {"t": "win", "m": ["r71_altar_1"], "n": 6}]}'::jsonb, '[{"s": null, "t": "지름길은 붉은 모래 언덕을 가로질러 곧게 뻗어 있었다. 순례꾼들이 세워 둔 붉은 천 장대가 오 리마다 하나씩 꽂혀 있었다. 해가 중천에 오르기 전에 제단터 돌기둥이 보였다."}, {"s": null, "t": "제단터는 넓은 붉은 벌판이었다. 사람 키 두 배쯤 되는 돌기둥 수십 개가 둥글게 서 있었다. 기둥마다 검게 마른 핏자국이 엉겨 있었고, 허리께에 붉은 실 매듭이 빼곡히 묶여 있었다."}, {"s": null, "t": "박쥐들이 쓰러진 뒤 벌판이 조용해졌다. 바람만 기둥 사이를 휘휘 지나갔다. 그 바람 끝에 둥, 둥, 북소리가 섞여 들렸다."}, {"s": "red_moon_cult:danbi", "t": "들려요? 북소리요. 오른쪽에서요. 제단터엔 아무도 없는데."}, {"s": null, "t": "단비가 오른쪽 귀를 소리 나는 쪽으로 돌렸다. 여운비는 볼을 바람 쪽으로 돌렸다. 두 사람이 동시에 같은 기둥을 가리켰다. 벌판 가장 안쪽에 반쯤 기운 기둥이었다."}, {"s": "red_moon_cult:danbi", "t": "대장님도 저기요?"}, {"s": "north_league:yeo", "t": "바람이 저 기둥에서 꺾이오. 소리도 거기서 나는 것 같소."}, {"s": null, "t": "나는 두 사람과 함께 그 기둥으로 걸어갔다. 단비가 기둥 둘레의 실 매듭을 손끝으로 하나씩 훑었다. 매듭마다 작은 나무패가 달려 있었는데, 나무패에는 날짜만 새겨져 있었다."}, {"s": "red_moon_cult:danbi", "t": "이름은 안 새겨요. 서약에 쓴 이름은 태워 버리니까요. 날짜만 남겨요. 그날 무녀가 하나 생겼다는 거요."}, {"s": null, "t": "단비의 손이 한 매듭에서 멈추었다. 단비는 나무패의 날짜를 오래 들여다보았다. 열 해 전 겨울 날짜였다."}, {"s": "red_moon_cult:danbi", "t": "…제 거예요. 열네 살 때."}, {"s": null, "t": "단비가 품에서 작은 칼을 꺼냈다. 칼을 매듭에 대려다가 손을 멈추었다. 먹빛으로 굳은 왼손으로는 매듭을 잡을 수가 없었다. 단비는 오른손에 칼을 쥔 채 한참 서 있었다."}, {"s": null, "t": "여운비가 말없이 다가와 매듭 아래 실 끝을 손가락으로 잡았다. 단비가 여운비를 올려다보았다."}, {"s": "north_league:yeo", "t": "잡고 있겠소. 끊으시오."}, {"s": null, "t": "단비가 칼을 댔다. 묵은 실이 툭 끊어졌다. 나무패가 단비의 손바닥에 떨어졌다. 단비는 그것을 꼭 쥐고 눈을 감았다."}, {"s": null, "t": "그사이에도 북소리는 멎지 않았다. 둥, 둥 하는 소리는 기둥 뒤쪽에서 났다. 나는 기둥 뒤로 돌아가 보았다. 모래 속에 둥근 무언가가 반쯤 묻혀 있었다."}, {"s": "north_league:yeo", "t": "남은 매듭이 수백이오. 오늘 안에 다 못 푸오. 여기서 하룻밤 묵읍시다. 그 소리 나는 것부터 파 보시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_3', 3, '바람 든 북', '적월 제단터에서 실마리를 찾는다, 적월 제단터에서 쉰다', '{"at": ["crimson_altar"], "tasks": [{"t": "clue", "r": ["crimson_altar"], "n": 1}, {"t": "rest", "r": ["crimson_altar"], "n": 1}]}'::jsonb, '[{"s": null, "t": "모래 속에서 파낸 것은 커다란 북이었다. 가죽 한쪽이 찢어져 있었고, 북테에 붉은 실 한 가닥이 감겨 있었다. 실 끝에 매단 나무패가 바람에 흔들릴 때마다 남은 가죽을 둥, 둥 두드렸다."}, {"s": null, "t": "여운비가 북 앞에 쪼그려 앉아 볼을 모래 가까이 낮췄다. 한참을 그러고 있다가 일어섰다."}, {"s": "north_league:yeo", "t": "서쪽 언덕 틈으로 바람이 모여 이 기둥 뒤로 빠지오. 바람이 실을 흔들고, 실이 패를 흔들고, 패가 북을 치는 거요. 붉은 달 뜨는 밤에 북이 운다는 소문도 이걸 거요. 그런 밤엔 서풍이 세니까."}, {"s": "red_moon_cult:danbi", "t": "대장님… 그걸 볼로 다 읽었어요?"}, {"s": "north_league:yeo", "t": "눈으로 볼 땐 술만 봤소. 볼로 읽으니 바람이 어디서 꺾이는지까지 느껴지오."}, {"s": null, "t": "단비가 여운비를 한참 보다가 고개를 숙였다. 웃는지 우는지 알 수 없는 얼굴이었다."}, {"s": null, "t": "해가 지자 우리는 기둥 사이에 모닥불을 피웠다. 단비와 여운비는 밤이 깊도록 기둥을 돌며 남은 매듭을 풀었다. 여운비가 실 끝을 잡으면 단비가 끊었다. 나는 떨어진 나무패를 주워 봇짐에 담았다."}, {"s": null, "t": "다 풀고 나서 셋이 모닥불 가에 앉았다. 단비가 엿을 셋으로 나눠 하나씩 쥐여 주었다. 붉은 벌판 위에 별이 촘촘히 떠 있었다."}, {"s": "red_moon_cult:danbi", "t": "이 나무패들, 장터 제단 아랫단에 걸면 어때요? 날짜만 있는 패요. 그날 누가 무녀가 됐고 그 무녀가 누구 이름을 태웠는지는 모르지만… 날짜라도 남아 있으면 동짓밤에 그해를 부를 수 있잖아요."}, {"s": "north_league:yeo", "t": "날짜는 이름이 아니오. 금빛은 안 나올 거요."}, {"s": "red_moon_cult:danbi", "t": "알아요. 그래도 교주님 다발이랑 날짜를 맞춰 보면, 그해 다발을 펼 때 어느 장부터 읽을지는 알잖아요."}, {"s": null, "t": "여운비는 대답 대신 모닥불에 나뭇가지 하나를 넣었다. 불티가 파르르 올랐다. 여운비가 불빛 너머로 단비를 보았다."}, {"s": "north_league:yeo", "t": "내일 돌아갈 때는 당신이 앞에 서시오. 이 길은 당신이 아는 길이오. 나는 오른쪽에서 따라가겠소."}, {"s": "red_moon_cult:danbi", "t": "대장님은 맨날 오른쪽이래."}, {"s": "north_league:yeo", "t": "당신이 잘 듣는 쪽이 오른쪽이오."}, {"s": null, "t": "단비가 아무 말 없이 여운비의 어깨에 머리를 기댔다. 여운비는 몸을 굳혔다가 천천히 풀었다. 나는 모닥불을 지키며 두 사람이 잠들 때까지 별을 보았다."}, {"s": null, "t": "이튿날 아침 우리는 찢어진 북을 장대에 꿰어 메고 지름길로 돌아왔다. 모래 언덕을 곧장 가로지르는 길이라 돌아오는 길은 올 때보다도 짧게 느껴졌다. 장터 어귀에서 사마겸이 북을 받아 들고 찢어진 가죽을 오래 쓸었다."}, {"s": "red_moon_cult:sama", "t": "이건 내가 메우마. 북은 제단 곁에 둔다. 이제 붉은 달 밤이 아니라 사람 모이는 날 치는 북으로."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_red_4', 'side', '뒷이야기·백골 장터', '붉은 향로', '비고에 들일 「월식 제단 향로」를 장터 놋쇠장이 놋단이 붓는다. 이름 종이를 태우던 옛 향로는 사마겸이 부숴 버렸다. 새 향로에 무슨 무늬를 넣을지 묻는 놋단에게, 사마겸이 「강한 것」 대신 무엇을 섬길지 처음으로 말한다. 그 사이 단비는 「붉은 달 행전」을 여운비에게 둘러 본다.', 'bone_market', 50, '{mdq_17,ep_red_3}'::text[], null, 1538, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:red_moon_cult", "stage": 4}'::jsonb where quest_id = 'ep_red_4';
delete from public.world_quest_steps where quest_id = 'ep_red_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_4', 1, '부서진 향로', '부서진 향로', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "그사이 장터 대장간에서 비고에 들일 향로를 붓는다는 소식이 들려왔다. 백골 장터 대장간에 가 보니 화덕 앞에 앞치마를 두른 아낙 하나가 쇳물 국자를 들고 서 있었다. 장터 놋쇠장이 놋단이었다."}, {"s": null, "t": "놋단은 튄 불똥을 맨손으로 탁탁 털어 냈다. 팔뚝에 덴 자국이 별자리처럼 흩어져 있었다."}, {"s": "q:sx_ep_notdan", "t": "왔어? 사업에 물건 넘긴 사람들 덕에 비고에 새 물건을 들인대. 「월식 제단 향로」. 제단에 놓을 큰 향로랑 꼭 같은 걸 작게 부어서, 교도들 집에도 하나씩 들이게 한대."}, {"s": "q:sx_ep_notdan", "t": "근데 틀이 없어. 옛 향로는 대호법이 지난달에 부숴 버렸거든."}, {"s": null, "t": "나는 왜 부쉈느냐고 물었다. 놋단이 국자 끝으로 화덕 구석을 가리켰다. 부서진 향로 조각들이 쌓여 있었다. 조각마다 그을음이 시커멓게 앉아 있었다."}, {"s": "q:sx_ep_notdan", "t": "그 향로가 서약 때 이름 종이를 태우던 거였대. 대호법이 그걸 보더니 한 손으로 쾅 내려쳤어. 아무 말도 안 하고."}, {"s": null, "t": "대장간 문간에 사마겸이 서 있었다. 사마겸은 팔짱을 낀 채 부서진 조각들을 내려다보고 있었다."}, {"s": "red_moon_cult:sama", "t": "놋단. 새 향로에는 이름 태우는 구멍을 내지 마라. 향만 피우게."}, {"s": "q:sx_ep_notdan", "t": "알아요, 대호법님. 그럼 무늬는 뭘로 넣어요? 옛것은 붉은 달이었는데."}, {"s": null, "t": "사마겸은 대답하지 못했다. 대장간에는 화덕 불만 우르르 소리를 냈다."}, {"s": "q:sx_ep_notdan", "t": "아무튼 틀부터 짜야 돼. 그런데 바탕 쇠가 모자라. 유리협곡 바위에 월철이 섞인 데가 있거든. 협곡 바람에 식은 쇠라 깨 보면 붉은 결이 돈다고 놋쇠장이들끼리 말해."}, {"s": null, "t": "단비가 엿판을 여운비에게 맡기고 대장간으로 고개를 들이밀었다."}, {"s": "red_moon_cult:danbi", "t": "유리협곡이요? 거기 유리 매가 사람 정수리를 쪼잖아요. 놋단 아줌마가 지난번에 머리 쥐어뜯긴 데요."}, {"s": "q:sx_ep_notdan", "t": "그러니까 내가 안 가는 거야. 조사원, 좀 캐다 줘. 매도 좀 쫓아 주고."}, {"s": null, "t": "놋단이 국자를 어깨에 메고 씩 웃었다. 사마겸은 그때까지도 부서진 조각에서 눈을 떼지 못하고 있었다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_4', 2, '무엇을 섬기나', '유리협곡에서 월철 광석을(를) 모은다, 유리 매을(를) 물리친다', '{"at": ["bone_market"], "tasks": [{"t": "gather", "items": ["ore"], "r": ["glass_canyon"], "n": 6}, {"t": "win", "m": ["g_glass_canyon"], "n": 6}]}'::jsonb, '[{"s": null, "t": "월철 광석 자루를 내려놓자 놋단이 광석 하나를 망치로 톡 쳐서 깨 보았다. 깨진 면에 붉은 결이 실처럼 돌았다."}, {"s": "q:sx_ep_notdan", "t": "이거야, 이거. 협곡 쇠는 이래서 좋아."}, {"s": null, "t": "대장간 한쪽에서 단비가 붉은 천을 무릎에 펴 놓고 바느질을 하고 있었다. 오른손 하나로 바늘을 쥐고, 천은 무릎으로 눌렀다. 여운비가 곁에서 실 끝을 잡아 주었다."}, {"s": null, "t": "나는 무엇을 짓느냐고 물었다. 단비가 바늘을 든 채 씩 웃었다."}, {"s": "red_moon_cult:danbi", "t": "「붉은 달 행전」이요. 이것도 비고에 들인대요. 제사 날 교도들이 정강이에 두르는 거예요. 대장님 거부터 지어 보는 중이에요."}, {"s": "north_league:yeo", "t": "나는 교도가 아니오."}, {"s": "red_moon_cult:danbi", "t": "장부 적는 사람도 제사 날엔 둘러야 해요. 장터 법이에요. 방금 제가 만들었어요."}, {"s": null, "t": "여운비는 한숨을 쉬면서도 실 끝을 놓지 않았다. 놋단이 그 꼴을 보고 낄낄 웃었다."}, {"s": null, "t": "사마겸은 대장간 문턱에 걸터앉아 무를 깎고 있었다. 길게 이어지던 무 껍질이 툭 끊어졌다. 사마겸은 끊어진 껍질을 한참 내려다보았다."}, {"s": null, "t": "나는 사마겸 곁에 앉았다. 사마겸이 깎던 무 한 조각을 내게 내밀었다."}, {"s": "red_moon_cult:sama", "t": "놋단이 무늬를 묻더군. 붉은 달 대신 뭘 넣느냐고. 나는 평생 강한 것을 섬겼다. 달이 강하니 달을, 교주님이 강하니 교주님을. 요기를 삼키면 강해진다니 요기를."}, {"s": "red_moon_cult:sama", "t": "그런데 장터 제단에 축문을 새기던 날 알았다. 강하다는 놈이 축문 한 줄을 혼자 못 읽더군."}, {"s": null, "t": "사마겸이 무를 한 입 베어 물었다. 아삭 소리가 났다. 거한은 한참 씹다가 말을 이었다."}, {"s": "red_moon_cult:sama", "t": "흑사단 형제들 가운데 내가 이름을 아는 이가 서른여덟이다. 소리로만 외웠다. 월식성에서 그 이름들이 바쳐질 때도 나는 외우고 있었다. 글자로는 못 적어도 내 입으로는 아직 부를 수 있다."}, {"s": "red_moon_cult:sama", "t": "그러니 이제 그걸 섬기겠다. 나 말고는 부를 사람이 없는 이름들. 그 이름들을 내가 들고 가겠다."}, {"s": null, "t": "대장간이 조용해졌다. 단비의 바늘이 멈췄고, 여운비가 실 끝을 쥔 채 고개를 들었다. 놋단은 쇳물 국자를 내려놓았다."}, {"s": "q:sx_ep_notdan", "t": "…그럼 무늬는 달이 아니라 이름 자리로 해요. 향로 둘레에 빈칸을 둘러 새길게요. 집집마다 제가 부를 이름을 적어 넣게."}, {"s": null, "t": "사마겸이 놋단을 보았다. 거한은 무 조각을 쥔 채 고개를 한 번 끄덕였다."}, {"s": "q:sx_ep_notdan", "t": "그럼 틀은 내가 짜고, 첫 본은 조사원이 부어 줘. 바탕 향로가 하나 있어야 그걸로 틀을 떠. 그 쇠로 청동 향로 하나면 돼."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_4', 3, '빈칸 두른 향로', '청동 향로을(를) 만든다, 청동 향로을(를) 넘긴다', '{"at": ["bone_market"], "tasks": [{"t": "craft", "items": ["hf_surf_incense"], "n": 1}], "give": {"hf_surf_incense": 1}}'::jsonb, '[{"s": null, "t": "놋단은 내가 부은 청동 향로를 모래 틀에 묻어 본을 떴다. 쇳물이 틀로 흘러 들어가며 치이익 김을 뿜었다. 대장간 안이 붉은 빛으로 가득 찼다."}, {"s": null, "t": "쇳물이 식자 놋단이 틀을 깼다. 새 향로가 모래 속에서 나왔다. 둘레에 손바닥만 한 빈 네모 칸이 여섯 개 둘러 새겨져 있었다."}, {"s": "q:sx_ep_notdan", "t": "됐다. 비고 향로 첫 본이야. 이름은 「월식 제단 향로」 그대로 두래. 교주님이 그러시더라. 달은 원망하지 않고 기억할 뿐이라고. 기억하는 향로라고 생각하면 된대."}, {"s": null, "t": "단비가 바느질을 마친 붉은 행전을 들고 왔다. 여운비가 마지못해 그것을 정강이에 두르고 서 있었다. 붉은 천이 하얗게 바랜 칼집과 영 어울리지 않았다."}, {"s": "red_moon_cult:danbi", "t": "어때요? 대장님 진짜 잘 어울려요."}, {"s": "north_league:yeo", "t": "…바람이 행전 속으로 드오."}, {"s": "red_moon_cult:danbi", "t": "그럼 바람 읽기 더 좋잖아요."}, {"s": null, "t": "놋단이 배를 잡고 웃었다. 여운비는 귀 끝을 붉힌 채 행전을 풀지 않았다."}, {"s": null, "t": "해가 지자 사마겸이 새 향로를 두 손으로 받쳐 들고 제단 앞으로 갔다. 단비가 향을 하나 꽂아 주었다. 향 연기가 가늘게 올라갔다."}, {"s": null, "t": "사마겸이 향로 앞에 무릎을 꿇었다. 한참 숨을 고르더니 흑사단 형제의 이름을 하나 불렀다. 거한의 목소리가 처음으로 떨렸다."}, {"s": null, "t": "사마겸의 입김이 금빛으로 엉겼다. 실은 아주 가늘었다. 가슴에 닿을 사람을 찾듯 허공을 맴돌던 실이 향 연기에 감겨 함께 올라갔다. 연기가 잠깐 금빛으로 물들었다가 밤하늘로 흩어졌다."}, {"s": null, "t": "사마겸이 고개를 들어 흩어지는 금빛을 보았다. 거한의 어깨가 조금 내려앉았다."}, {"s": "red_moon_cult:danbi", "t": "닿을 데가 없어서 그래요. 달 앞에 바쳐진 이름이라서요. …그래도 금빛은 나왔어요. 대호법님이 그 이름을 다 아시니까요."}, {"s": null, "t": "사마겸이 고개를 끄덕이고 다음 이름을 불렀다. 그다음, 또 그다음 이름을 불렀다. 서른여덟 번째 이름까지 금빛은 매번 향 연기를 타고 올라갔다. 사마겸은 한 번도 쉬지 않았다."}, {"s": null, "t": "마지막 이름을 부르고 나서 사마겸이 향로 둘레의 빈칸 하나를 손가락으로 쓸었다. 글자를 새길 줄 모르는 손가락이었다."}, {"s": "red_moon_cult:sama", "t": "이 칸에는 단비가 적어 다오. 「흑사단」. 그 세 글자만. 나머지는 내 입에 있다."}, {"s": null, "t": "단비가 놋단의 정을 빌려 오른손으로 「흑사단」 세 글자를 새겼다. 한 획마다 사마겸이 따라 읽었다. 이번에는 손가락이 글자 위에서 멈추지 않았다."}, {"s": "north_league:yeo", "t": "대호법. 그 글자는 이제 읽으시오."}, {"s": "red_moon_cult:sama", "t": "…흑사단. 읽었다."}, {"s": null, "t": "사마겸이 일어나 향로를 제단 가운데 올렸다. 향로 둘레의 남은 빈칸 다섯이 향불 빛을 받았다. 놋단이 국자를 어깨에 메고 중얼거렸다."}, {"s": "q:sx_ep_notdan", "t": "다음엔 깃발이랑 제등이래. 사업이 다 차는 날 장대에 단대. 그날은 장터가 미어터지겠다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_red_5', 'side', '뒷이야기·백골 장터', '월식 무늬 깃발', '장터 제단 고치기가 마지막 단계까지 찬다. 장대마다 월식 무늬 깃발이 오르고 제단 꼭대기에 달 모양 제등이 걸린다. 월화는 제단이 꼭 공터를 바라보게 앉아 있다는 것을 알아보고, 동짓밤 백 년 치 다발을 부를 자리가 그 공터임을 모두에게 말한다. 낙성 날의 첫 불은 그 자리에 선 산 사람들의 이름으로 켠다.', 'bone_market', 50, '{mdq_17,ep_red_4}'::text[], null, 1539, '[]'::jsonb, true, null, null)
