update public.world_quests set open_req = '{"project": "f:red_moon_cult", "stage": 5}'::jsonb where quest_id = 'ep_red_5';
delete from public.world_quest_steps where quest_id = 'ep_red_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_5', 1, '물드는 천', '물드는 천', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "장터 제단 고치는 사업이 마지막 단계까지 찼다는 방이 장터 곳곳에 붙었다. 백골 장터에 닿으니 장대마다 붉은 천을 걸 줄이 매여 있었다."}, {"s": null, "t": "공터 한가운데서 장터 아낙들이 커다란 물감 솥 둘레에 둘러앉아 천을 물들이고 있었다. 놋단이 솥을 저었고, 단비가 젖은 천을 오른손으로 건져 장대 줄에 널었다. 천마다 반쯤 먹힌 달 무늬가 물들어 있었다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님! 오늘 낙성이에요. 아니, 내일이요. 물감이 모자라서 하루 밀렸어요."}, {"s": "red_moon_cult:danbi", "t": "{등급}님 댁에도 바탕 무늬가 내려온대요. 「월식 무늬」요. 사업을 다 채운 상이래요.", "fac": "red_moon_cult", "spec": 1, "grp": 1}, {"s": "red_moon_cult:danbi", "t": "남의 세력 잔치지만 꼭 오셔야 해요. 제단 돌 올릴 때부터 계셨잖아요.", "fac_not": "red_moon_cult", "spec": 2, "grp": 1}, {"s": null, "t": "놋단이 솥 바닥을 긁어 보더니 이마를 찡그렸다."}, {"s": "q:sx_ep_notdan", "t": "물감이 바닥났어. 주사를 더 갈아야 해. 장터 둘레 주사는 다 캐 버렸고. 제단터 기둥 아래 붉은 흙에 주사가 섞여 있다던데, 지름길이 났으니 다녀올 만하지?"}, {"s": null, "t": "여운비가 엿판 뒤에서 장부를 접으며 나섰다."}, {"s": "north_league:yeo", "t": "제단터 길은 내가 아오. 다만 오늘은 엿판을 지켜야 하오. 단비가 물감 묻은 손으로 엿판을 만지면 엿판에 붉은 손자국이 남을 거요."}, {"s": "red_moon_cult:danbi", "t": "벌써 남겼어요."}, {"s": null, "t": "단비가 붉게 물든 오른손을 펴 보였다. 엿판 귀퉁이에 손자국이 하나 찍혀 있었다. 여운비는 한숨을 쉬고 장부에 「붉은 손자국 하나」라고 적었다."}, {"s": null, "t": "공터 북쪽에서 쿵, 쿵 북소리가 울렸다. 사마겸이 새 가죽을 메운 북을 제단 곁에 세우고 소리를 맞춰 보고 있었다. 제단터에서 메고 온 그 북이었다."}, {"s": "red_moon_cult:sama", "t": "소리가 좋다. 내일은 이 북으로 사람을 모은다. 붉은 달 밤이 아니라 낙성 날에."}, {"s": "q:sx_ep_marketwife", "t": "대호법님, 그 북 치는 날 우리 육포도 상에 올려요?"}, {"s": "red_moon_cult:sama", "t": "올려라. 생선 대가리만 아니면 된다."}, {"s": null, "t": "나는 제단터로 다녀오겠다고 했다. 놋단이 빈 자루를 던져 주었다."}, {"s": "q:sx_ep_notdan", "t": "넉넉히. 깃발 여덟에 제등 하나 몫이야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_5', 2, '제단이 바라보는 곳', '적월 제단터에서 주사 광물을(를) 모은다, 주사 광물을(를) 넘긴다', '{"at": ["bone_market"], "tasks": [{"t": "gather", "items": ["cinnabar"], "r": ["crimson_altar"], "n": 4}], "give": {"cinnabar": 4}}'::jsonb, '[{"s": null, "t": "주사 자루를 받은 놋단이 맷돌에 주사를 갈았다. 붉은 가루가 솥에 들어가자 물감이 다시 피처럼 진해졌다. 아낙들이 남은 천을 한꺼번에 물들였다."}, {"s": null, "t": "월화가 천막에서 나와 공터를 걸었다. 교주가 천막 밖을 걷는 모습에 이제 장터 사람들은 놀라지 않았다. 아이들이 월화의 옷자락 뒤를 졸졸 따라다녔다."}, {"s": null, "t": "월화가 제단 앞 공터 한가운데에서 멈춰 섰다. 월화는 발밑의 모래를 오래 내려다보았다."}, {"s": "red_moon_cult:wolhwa", "t": "여기였지. 그 의식을 한 자리가. 붉은 실 일곱 가닥이 이 모래 위에 깔렸었다."}, {"s": null, "t": "단비가 물감 묻은 손을 앞치마에 닦으며 월화 곁으로 왔다. 단비의 눈이 모래 위를 따라갔다. 오른손이 저도 모르게 들리지 않는 왼쪽 귀께로 올라갔다. 여운비가 엿판을 두고 와서 말없이 단비의 오른쪽에 섰다."}, {"s": "red_moon_cult:wolhwa", "t": "백 년 치 다발을 동짓밤마다 이 공터에서 부르기로 했다. 그런데 제단을 고치고 보니, 제단이 꼭 이 공터를 바라보고 앉아 있구나. 옛사람들은 여기서 이름을 바치려고 제단을 이쪽으로 앉혔을 게다."}, {"s": "red_moon_cult:danbi", "t": "이제는 반대로 쓰면 되죠. 제단이 보고 있는 데서 부르는 거예요. 바치는 게 아니라요."}, {"s": "red_moon_cult:wolhwa", "t": "그래. 올 동지에는 다발을 이 공터에 펴 놓고 첫해부터 부르마. 제단 앞이니 장터 어디서든 보일 게다."}, {"s": null, "t": "월화가 나를 돌아보았다. 반쪽 얼굴의 잿빛 금 위로 저녁 해가 비쳤다."}, {"s": "red_moon_cult:wolhwa", "t": "제단 꼭대기에 달 모양 제등을 하나 건다. 테는 놋단이 짜 두었다. 속에 넣을 등이 없구나. 등도에서 쓰는 명등 등롱은 기름 없이도 이름을 비춘다지. 그 등롱을 둘 지어 다오. 하나는 제등 속에, 하나는 이 공터 한가운데에 둔다."}, {"s": null, "t": "나는 명등 등롱을 짓겠다고 했다. 월화가 고개를 끄덕이고 공터 모래 위에 손바닥을 한 번 얹었다가 들었다."}, {"s": "red_moon_cult:sama", "t": "교주님, 제등 속 등롱에는 무슨 이름을 붙입니까?"}, {"s": "red_moon_cult:wolhwa", "t": "아직 붙이지 않는다, 겸. 동짓밤에 다발에서 꺼낸 이름을 붙일 거다. 그때까지는 부를 날을 기다리는 등이다."}, {"s": "red_moon_cult:sama", "t": "그럼 공터 등롱은요. 내일 첫 불은 누구 이름으로 켭니까."}, {"s": "red_moon_cult:wolhwa", "t": "그건 내일 보면 안다."}, {"s": null, "t": "월화가 그 말만 하고 천막으로 돌아갔다. 사마겸이 고개를 갸웃하며 나를 보았다. 나도 모른다는 뜻으로 고개를 저었다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_red_5', 3, '낙성', '명등 등롱을(를) 만든다, 명등 등롱을(를) 넘긴다', '{"at": ["bone_market"], "tasks": [{"t": "craft", "items": ["myeongdeung_lamp"], "n": 2}], "give": {"myeongdeung_lamp": 2}}'::jsonb, '[{"s": null, "t": "해 질 녘에 사마겸이 북을 둥, 둥, 둥 쳤다. 북소리가 장터 끝까지 퍼졌다. 천막 사이에서 사람들이 쏟아져 나와 공터를 메웠다. 서문 폐성벽에서 온 순례꾼들도 보였다."}, {"s": null, "t": "장대마다 붉은 깃발이 올라갔다. 깃발 여덟이 저녁 바람에 한꺼번에 펄럭였다. 반쯤 먹힌 달 무늬가 바람을 받을 때마다 차오르는 것처럼 보였다."}, {"s": null, "t": "놋단과 사마겸이 사다리를 타고 올라가 제단 꼭대기에 달 모양 제등을 걸었다. 둥근 테에 붉은 천을 씌우고 속에 명등 등롱 하나를 넣은 등이었다. 이름 종이가 없는 등롱은 아직 어두웠다."}, {"s": null, "t": "월화가 제단 앞에 섰다. 단비와 여운비, 사마겸이 그 곁에 섰다. 나는 공터 한가운데 놓인 다른 등롱 곁에 섰다."}, {"s": "red_moon_cult:wolhwa", "t": "장터 제단을 다 고쳤다. 축문은 새로 새겼고, 상은 장터가 차렸고, 향로에는 빈칸을 둘렀고, 깃발은 장터 아낙들이 물들였다. 적월이 혼자 고친 것은 하나도 없다. 여러 조사원이 날라 준 짐으로 고쳤다."}, {"s": "red_moon_cult:wolhwa", "t": "동짓밤 등은 다발에서 꺼낸 이름으로 켠다. 오늘 첫 불은 산 사람 이름으로 켠다. 여기 선 사람들 이름이다. 저마다 제 이름을 종이에 적어 저 등롱에 붙여라. 글을 모르면 옆 사람이 적어 줘라."}, {"s": null, "t": "장터 사람들이 공터 등롱 앞에 줄을 섰다. 놋단이 아이들 이름을 대신 적어 주었다. 단비는 여운비의 이름을, 여운비는 단비의 이름을 적었다."}, {"s": null, "t": "사마겸은 종이를 든 채 한참 서 있다가 단비에게 내밀었다."}, {"s": "red_moon_cult:sama", "t": "적어 다오. …아니다. 내가 적겠다. 글자를 가르쳐 다오."}, {"s": null, "t": "단비가 사마겸의 굵은 손을 잡고 「사마겸」 세 글자를 함께 썼다. 비뚤비뚤한 글자였다. 사마겸이 그 종이를 등롱 맨 아래에 붙였다."}, {"s": null, "t": "나도 내 이름을 적어 등롱에 붙였다. 등롱 겉이 이름 종이로 빼곡해졌다."}, {"s": "red_moon_cult:wolhwa", "t": "이제 옆 사람 이름을 불러라. 한 사람도 빠지지 않게."}, {"s": null, "t": "공터 여기저기서 이름이 불렸다. 놋단이 아이의 이름을, 아이가 제 어미의 이름을, 장터 아낙이 순례꾼의 이름을 불렀다. 단비가 여운비를 불렀고, 여운비가 단비를 불렀다. 사마겸은 큰 목소리로 놋단의 이름을 불렀다."}, {"s": null, "t": "저녁 공터 위로 금빛 입김 수십 가닥이 엇갈렸다. 실은 사람과 사람 사이를 오가며 가슴께마다 닿았다. 그 빛이 등롱에 붙은 종이들을 스치자, 기름 한 방울 없는 등롱에 화르르 불이 붙었다. 등롱 불빛이 공터 모래를 저녁 빛깔로 물들였다."}, {"s": null, "t": "단비가 내 이름을 불렀다. 금빛 실이 내 가슴께에 닿았다. 따뜻했다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님은 제가 불렀어요. 대장님도 제가 불렀고요. 이 공터에 안 불린 사람 없어요."}, {"s": null, "t": "월화가 제단 꼭대기의 어두운 달 제등을 올려다보았다. 성한 왼쪽 눈가가 붉었다."}, {"s": "red_moon_cult:wolhwa", "t": "저 제등은 올 동지에 켠다. 다발 첫해부터. 그때도 오거라."}, {"s": null, "t": "사마겸이 다시 북을 쳤다. 놋단과 아낙들이 낙성 떡 시루를 열었다. 하얀 김이 붉은 깃발 사이로 피어올랐다. 단비가 오른손으로 떡 하나를 집어 여운비 입에 넣었고, 여운비는 피하지 않았다."}, {"s": null, "t": "나는 떡을 받아 들고 공터를 돌아보았다. 붉은 깃발이 펄럭였고, 제단이 공터를 내려다보고 있었다. 이제 그 제단 앞에서는 이름을 바치는 대신 부를 것이었다."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_river_1', 'side', '뒷이야기·구름나루', '선창 말뚝', '구름나루 선창의 썩은 말뚝 스물넷을 갈아 박는다. 사업 첫 몫으로 상점에 청정수와 장어 보양탕이 들어온 날, 매향은 말뚝 값을 셈하고 노들 영감은 말뚝마다 거기 매이던 배 이름을 새긴다.', 'river_ferry', 50, '{mdq_17}'::text[], null, 1540, '[]'::jsonb, true, null, null)
