update public.world_quests set open_req = '{"project": "f:river_alliance", "stage": 1}'::jsonb where quest_id = 'ep_river_1';
delete from public.world_quest_steps where quest_id = 'ep_river_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_1', 1, '선창이 이를 가는 날', '선창이 이를 가는 날', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "구름나루 선창에 아침 안개가 낮게 깔려 있었다. 안개 속에서 나무 메가 쿵, 쿵 떨어지는 소리와 뱃사람들의 구령이 번갈아 울렸다."}, {"s": null, "t": "선창 가장자리의 말뚝 몇 개가 뽑혀 판자 위에 누워 있었다. 물에 잠겼던 아랫도리가 시커멓게 썩어서, 손가락으로 누르면 푹 들어갔다."}, {"s": null, "t": "뽑힌 말뚝 곁에는 노들 영감이 쪼그려 앉아 있었다. 영감은 곰방대를 입에 문 채 숯 조각으로 말뚝 머리에 무언가를 적고 있었다."}, {"s": "river_alliance:nodeul", "t": "허허, 조사원 왔구먼. 마침 잘 왔네. 오늘은 이 선창이 이를 가는 날이거든."}, {"s": null, "t": "나는 선창이 이를 간다는 게 무슨 말이냐고 물었다. 영감이 숯 묻은 손가락으로 썩은 말뚝을 톡톡 두드렸다."}, {"s": "river_alliance:nodeul", "t": "말뚝이 선창 이빨이지. 쉰 해를 버틴 놈들이라 다 삭았어. 지난겨울엔 거룻배 하나가 이걸 붙들고 있다가 말뚝째 떠내려갈 뻔했네."}, {"s": null, "t": "영감이 숯으로 적은 글씨를 내 쪽으로 돌려 보였다. 「방울호」 세 글자였다. 옆에 누운 말뚝 머리에는 「늦물이」가 적혀 있었다."}, {"s": "river_alliance:nodeul", "t": "말뚝마다 거기 매이던 배가 있었네. 이건 방울호 자리, 저건 늦물이 자리. 썩은 말뚝을 버리기 전에 배 이름이라도 새 말뚝에 옮겨 적어 두려고 이러고 있네."}, {"s": null, "t": "선창 위쪽 장부방 처마 밑에서 주판 소리가 탁탁탁 빠르게 울렸다. 행수 매향이 장부를 옆구리에 끼고 계단을 내려오며 주판알을 튕기고 있었다."}, {"s": "river_alliance:maehyang", "t": "영감님, 이름 적는 건 좋은데 셈이 먼저예요. 썩은 말뚝이 스물넷이에요. 새 말뚝 스물넷에 쇠테 스물넷, 박는 일꾼 품삯까지 하면……."}, {"s": null, "t": "매향이 셈을 하다 말고 상점 쪽을 흘끗 보았다. 상점 앞에 새 궤짝 둘이 내려져 있었고, 상점지기가 뚜껑을 열어 병과 단지를 하나씩 꺼내 늘어놓고 있었다."}, {"s": "river_alliance:maehyang", "t": "참, 이것부터 보세요. 연맹 식구들이랑 여러 조사원이 영초 차며 수향 갈대며 사업에 넘겨준 몫이 첫 단계를 채웠어요. 그 값으로 염등촌 약방에서 청정수를, 연화늪 장어집에서 장어 보양탕을 들여왔고요. 오늘부터 연맹 사람한테는 상점에서 하루 다섯 개씩 팔아요.", "fac": "river_alliance", "spec": 1, "grp": 1}, {"s": "river_alliance:maehyang", "t": "참, 이것부터 보세요. 연맹 식구들이랑 여러 조사원이 사업에 몫을 넘겨줘서 첫 단계가 찼어요. 다른 세력 분들까지 도와주셨고요. 그 값으로 염등촌 약방에서 청정수를, 연화늪 장어집에서 장어 보양탕을 들여왔어요. 다만 연맹 장부에 오른 사람한테만 파는 물건이라, 조사원님께는 못 팔아요. 그건 미안해요.", "fac_not": "river_alliance", "spec": 2, "grp": 1}, {"s": null, "t": "장어 보양탕 단지 뚜껑 틈으로 진한 국물 냄새가 새어 나왔다. 말뚝을 뽑던 뱃사람들이 메를 내려놓고 단지 쪽으로 코를 킁킁거렸다."}, {"s": "river_alliance:maehyang", "t": "보양탕은 말뚝 다 박고 나서예요! 지금 먹으면 품삯에서 깔 거예요."}, {"s": null, "t": "뱃사람들이 투덜거리며 메를 다시 들었다. 노들 영감이 곰방대를 빼 들고 껄껄 웃었다."}, {"s": "river_alliance:nodeul", "t": "행수가 셈하는 걸 보면 이 나루가 안 망한 까닭을 알겠네. 그런데 조사원, 말뚝감이 모자라네. 물에 박는 나무는 아무거나 쓰면 한 해를 못 가."}, {"s": null, "t": "매향이 장부를 펴 들고 선창 끝 물살 쪽을 손가락으로 가리켰다."}, {"s": "river_alliance:maehyang", "t": "장부방 창고 나무로 스물하나는 되는데, 물살 센 끝자리 셋이 모자라요. 거기는 연화늪 부적목이라야 해요. 늪물을 먹고 자라서 잘 안 썩거든요. 그걸 베어다 수지를 먹여 강화 부적목으로 다듬으면 열 해는 버텨요."}, {"s": null, "t": "매향이 주판알 하나를 탁 올리며 나를 보았다. 그 셈 안에 내 몫까지 이미 들어가 있는 얼굴이었다."}, {"s": "river_alliance:maehyang", "t": "일꾼들은 말뚝 뽑느라 손이 없어요. 조사원님, 연화늪에서 부적목을 해다가 다듬는 것까지 해 주시겠어요? 품삯은 보양탕 한 그릇이에요. 이건 제 몫에서 낼게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_1', 2, '배 이름을 새기는 칼', '천엽 연화늪에서 부적목을(를) 모은다, 강화 부적목을(를) 만든다, 강화 부적목을(를) 넘긴다', '{"at": ["river_ferry"], "tasks": [{"t": "gather", "items": ["wood"], "r": ["lotus_marsh"], "n": 4}, {"t": "craft", "items": ["reinforced_lumber"], "n": 3}], "give": {"reinforced_lumber": 3}}'::jsonb, '[{"s": null, "t": "강화 부적목 셋을 등에 지고 선창으로 돌아오자 해가 중천에 올라 있었다. 안개가 걷힌 강물이 햇빛을 받아 반짝반짝 빛났다."}, {"s": null, "t": "창고 나무로 깎은 말뚝 스물하나는 벌써 거의 다 박혀 있었다. 뱃사람 둘이 말뚝을 세워 붙들면, 다른 하나가 사다리에 올라 메를 내리쳤다. 쿵, 메가 떨어질 때마다 말뚝이 한 뼘씩 강바닥으로 파고들었다."}, {"s": null, "t": "매향이 내 등의 나무를 손바닥으로 쓸어 보고 고개를 끄덕였다. 수지가 고르게 먹었는지 보는 손길이었다."}, {"s": "river_alliance:maehyang", "t": "잘 다듬으셨네요. 그건 저녁 물때까지 들고 계세요. 끝자리 셋은 물이 빠져야 박을 수 있거든요."}, {"s": null, "t": "노들 영감은 판자 위에 앉아 박힌 말뚝 머리마다 칼끝으로 옛 배 이름을 새기고 있었다. 방울호, 늦물이, 쌍노, 순풍 하는 이름들이 하나씩 나무에 박혔다. 영감의 칼끝은 이름 하나를 새길 때마다 한참씩 멈췄다."}, {"s": null, "t": "나는 영감 곁에 앉아 늦물이는 어떤 배였냐고 물었다. 영감이 칼밥을 후 불어 날렸다."}, {"s": "river_alliance:nodeul", "t": "내 동무 배였네. 물때를 늘 늦게 타서 늦물이라 불렀지. 사공은 나보다 먼저 물에 갔고. 배 이름을 새겨 두면 그 사공 얼굴도 같이 떠오르거든. 배 이름 뒤에는 늘 사공이 따라오는 법이야."}, {"s": null, "t": "선창 끝에서 그물을 깁던 개동 영감이 바늘을 멈추고 이쪽을 돌아보았다. 개동 영감이 그물을 무릎에 둔 채 열여덟째 말뚝을 턱으로 가리켰다."}, {"s": "q:sx_md_gaedong", "t": "그 자리는 장부방 거룻배 자리였구먼. 내가 사환일 적에 날마다 거기다 배를 맸지. 매듭을 잘못 지어서 도방 어른한테 꿀밤을 맞던 자리야."}, {"s": null, "t": "노들 영감이 칼을 멈추고 개동 영감 쪽으로 고개를 돌리며 껄껄 웃었다."}, {"s": "river_alliance:nodeul", "t": "허허, 개동이 꿀밤 맞던 자리라. 그것도 새겨 둘까?"}, {"s": null, "t": "개동 영감이 그물 바늘을 내저으며 얼굴을 붉혔다."}, {"s": "q:sx_md_gaedong", "t": "그건 새기지 말게. 부끄러운 건 장부에도 안 적는 법이구먼."}, {"s": null, "t": "뱃사람들이 와르르 웃었다. 매향은 웃음을 참으며 주판을 튕기다 알 하나를 잘못 올렸고, 얼른 도로 내렸다."}, {"s": null, "t": "그때 주막 문이 열리고 주모 달래가 앞치마에 손을 닦으며 나왔다. 달래는 선창을 둘러보며 일꾼들 머릿수부터 셌다."}, {"s": "q:sn_dalrae", "t": "일곱, 여덟, 아홉에 손님까지 열이오. 말뚝 박은 날엔 그 아래서 고기를 낚아 일꾼들을 먹이는 게 이 나루 법이오. 보양탕 한 단지로는 열 사람 배를 못 채우오."}, {"s": null, "t": "매향이 주판을 멈추고 달래를 돌아보았다. 달래가 매향보다 먼저 손을 내저었다."}, {"s": "q:sn_dalrae", "t": "행수님 셈에는 안 넣어도 되오. 고기는 강이 내고, 굽는 건 내가 하니. 손님, 새 말뚝 아래 줄 좀 담가 주시오. 고기는 새 나무 그늘로 먼저 모이니 금방 올라올 거요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_1', 3, '스물넷째 자리', '구름나루에서 낚시를 한다, 강화 부적목을(를) 넘긴다', '{"at": ["river_ferry"], "tasks": [{"t": "fish", "r": ["river_ferry"], "n": 3}], "give": {"reinforced_lumber": 3}}'::jsonb, '[{"s": null, "t": "저녁 물때가 되자 강물이 선창 아래로 한 자쯤 빠져나갔다. 물살 센 끝자리 바닥이 드러났고, 나는 다듬어 온 강화 부적목 셋을 매향에게 넘겼다."}, {"s": null, "t": "마지막 셋은 내가 메를 쥐었다. 뱃사람 둘이 말뚝을 붙들어 주었고, 메를 내리칠 때마다 손바닥이 얼얼하게 울렸다. 쿵, 쿵, 쿵 메 소리가 선창을 흔들었다. 스물셋째 말뚝까지 박고 나자 팔이 덜덜 떨렸다."}, {"s": null, "t": "노들 영감이 스물넷째 말뚝 머리에 칼끝을 대려다 손을 멈췄다. 그 말뚝 자리만은 영감이 숯으로 적어 둔 글씨가 없었다."}, {"s": "river_alliance:nodeul", "t": "여기는 매이던 배가 없었네. 나루를 넓힐 때 새로 낸 자리라. 조사원, 자네가 정하게. 요즘 이 선창에 자주 와서 쉬다 가는 건 자네가 데려간 연화 거북 아닌가."}, {"s": null, "t": "나는 거북은 말뚝에 매어 두는 짐승이 아니라고 했다. 영감이 곰방대를 문 채 어깨를 들썩였다."}, {"s": "river_alliance:nodeul", "t": "매이든 안 매이든, 와서 쉬다 가는 자리면 된 거지. 「연화 거북」이라 새기겠네. 늪 사람들이 이걸 보면 그놈을 보내고 섭섭해하던 게 좀 풀리겠구먼."}, {"s": null, "t": "영감이 네 글자를 새기는 동안 마지막 메질이 끝났다. 말뚝 스물넷이 선창을 따라 가지런히 늘어섰고, 말뚝 머리마다 새 칼자국이 저녁 햇빛에 하얗게 드러났다."}, {"s": null, "t": "선창 한가운데에 달래가 화로를 걸고 내가 낚은 고기를 구웠다. 지글지글 기름이 숯에 떨어질 때마다 치익 연기가 올랐다. 매향이 장어 보양탕 단지를 열어 일꾼들 그릇에 한 국자씩 떠 주었다."}, {"s": "river_alliance:maehyang", "t": "조사원님 몫이에요. 아까 약속한 품삯이요."}, {"s": null, "t": "매향이 내 그릇에 국자를 두 번 기울였다. 일꾼들 그릇보다 한 국자가 더 들어갔다. 내가 그릇을 내려다보자 매향이 시치미를 떼고 주판을 튕겼다."}, {"s": "river_alliance:maehyang", "t": "끝자리 셋은 물살이 세서 품이 곱절이에요. 셈이 그래요."}, {"s": null, "t": "노들 영감이 보양탕을 한 모금 마시고 길게 숨을 내쉬었다. 영감은 줄지어 선 말뚝을 하나씩 눈으로 짚어 나갔다."}, {"s": "river_alliance:nodeul", "t": "이빨을 다 갈았구먼. 이제 큰 배가 와서 붙어도 안 흔들리겠어. 연맹 장부에 다 적어 두게, 행수. 몫을 넘겨준 사람들 덕에 상점엔 보양탕이 들어오고 선창엔 새 이가 났다고."}, {"s": null, "t": "매향이 주판을 내려놓고 장부 끝장을 펴 보였다."}, {"s": "river_alliance:maehyang", "t": "벌써 적었어요. 셈 끝에 한 줄 더요. 「말뚝 스물넷. 이름 스물셋, 거북 하나.」"}, {"s": null, "t": "개동 영감이 그물 바늘로 열여덟째 말뚝을 가리키며 혀를 찼다. 꿀밤 맞던 자리가 새겨지지 않아 다행이라는 얼굴이었다."}, {"s": "q:sx_md_gaedong", "t": "거북은 새기고 꿀밤은 안 새기니, 이 나루도 셈이 공평하구먼."}, {"s": null, "t": "선창에 다시 웃음이 터졌다. 강물이 차오르며 새 말뚝 아랫도리를 찰랑찰랑 적셨고, 나는 그 소리를 들으며 따뜻한 국물을 마저 비웠다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_river_2', 'side', '뒷이야기·구름나루', '물가의 등 장대', '사업이 둘째 단계를 채우자 연맹은 구름나루 둘레 물가마다 등을 단 장대를 세운다. 장대 아래엔 뱃사람이 쉬어 갈 자리가 생기고, 불빛을 꺼리는 물귀들은 뱃길에서 물러난다. 청파가 처음으로 남의 배 노를 잡는다.', 'river_ferry', 50, '{mdq_17,ep_river_1}'::text[], null, 1541, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:river_alliance", "stage": 2}'::jsonb where quest_id = 'ep_river_2';
delete from public.world_quest_steps where quest_id = 'ep_river_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_2', 1, '장대 백스무 개', '장대 백스무 개', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "선창 말뚝을 갈고 몇 주가 지났다. 그사이 구름나루 선창에는 장대가 산처럼 쌓였다. 사람 키 세 배쯤 되는 곧은 장대마다 꼭대기에 쇠고리가 박혀 있었다."}, {"s": null, "t": "장대 더미 너머로 연맹의 큰 배가 물 위에 떠 있었다. 비단 차양 아래 도방 진소랑이 장부 한 권을 무릎에 펴 놓고 붓으로 무언가를 그리고 있었다. 주판은 탁자 끝에 엎어져 있었다."}, {"s": "river_alliance:jin", "t": "조사원님, 오셨어요? 연맹 일이니 연맹 사람이 와 주셔야죠. 이리 와서 이것 좀 보세요.", "fac": "river_alliance", "spec": 1, "grp": 1}, {"s": "river_alliance:jin", "t": "어머, 조사원님. 말뚝 박던 날 메를 쥐셨다면서요? 매향이 품삯을 한 국자 더 얹었다고 자랑하더라고요. 이리 와서 이것 좀 보세요.", "fac_not": "river_alliance", "spec": 2, "grp": 1}, {"s": null, "t": "진소랑이 장부를 내 쪽으로 돌렸다. 구름나루를 가운데에 두고 연화늪·염등촌·수경루로 이어지는 물길이 그려져 있었다. 물길을 따라 작은 동그라미가 점점이 찍혀 있었다."}, {"s": "river_alliance:jin", "t": "동그라미 하나가 장대 하나예요. 백스무 개. 물가마다 등을 단 장대를 세울 거예요. 사업이 둘째 단계를 채운 덕에 그 값이 나왔거든요. 몫을 넘겨준 조사원들 셈으로 장대 하나하나를 세운다고 생각하시면 돼요."}, {"s": null, "t": "나는 장대에 등을 다는 까닭을 물었다. 진소랑이 붓끝으로 연화늪 쪽 동그라미를 톡 찍었다."}, {"s": "river_alliance:jin", "t": "물귀들은 불빛을 꺼려요. 물가에 불이 줄지어 서 있으면 뱃길 가까이 안 붙어요. 그리고 장대 밑에는 판자를 깔고 청정수 단지를 둘 거예요. 사공이 노를 쉬고 목을 축이는 자리요. 노 젓는 사람은 쉴 데가 있어야 오래 저어요."}, {"s": null, "t": "그때 장대 더미 뒤에서 쿨럭쿨럭 쇳소리 섞인 기침이 들렸다. 청파가 장대 하나를 어깨에 메고 비틀비틀 걸어 나왔다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님! 오셨어요? 도방님이 장대 세운다고 서신을 보내셔서 등도에서 올라왔어요. 저 이거 벌써 스무 개 날랐어요!"}, {"s": null, "t": "청파가 장대를 내려놓다가 또 기침을 했다. 진소랑이 붓을 내려놓고 청파를 흘겨보았다."}, {"s": "river_alliance:jin", "t": "청파야, 너는 나르지 말랬지. 노들 영감님 배를 맡으랬잖아. 영감님 허리가 시원찮으셔서 노는 네가 저어야 해."}, {"s": null, "t": "청파가 그 말에 눈을 동그랗게 떴다. 기침을 삼키며 제 손바닥을 내려다보았다."}, {"s": "q:sn_cheongpa", "t": "영감님 배요? 저 남의 배 노는 처음 잡아요. 잠수꾼은 노를 안 잡거든요. 늘 줄만 잡았지. 노들 영감님 배는 나루에서 제일 오래된 배인데…… 망가뜨리면 어떡해요."}, {"s": null, "t": "선창 끝에서 노들 영감이 허리를 짚고 일어섰다. 영감이 곰방대로 제 배를 가리켰다."}, {"s": "river_alliance:nodeul", "t": "쉰 해 묵은 배가 네 손에 망가질 것 같으면 진작 망가졌다. 걱정 말고 타라. 노는 내가 뱃머리에서 일러 주마."}, {"s": null, "t": "진소랑이 붓을 들어 장부의 연화늪 쪽 동그라미를 다시 짚었다. 이번엔 내 쪽을 보았다."}, {"s": "river_alliance:jin", "t": "첫 장대는 연화늪에 세울 거예요. 거기 물귀가 제일 많거든요. 장대 세울 물가에 연화 수귀들이 떼로 붙어 있다니, 조사원님이 먼저 쫓아 주세요. 청파는 장대를 싣고 뒤따라가고요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_2', 2, '빙글빙글 도는 배', '천엽 연화늪에 간다, 천엽 연화늪의 요괴를 물리친다', '{"at": ["lotus_marsh"], "tasks": [{"t": "travel", "r": ["lotus_marsh"], "n": 1}, {"t": "win", "r": ["lotus_marsh"], "n": 6}]}'::jsonb, '[{"s": null, "t": "연화늪 물가의 수귀들을 다 쫓아내자 늪 위로 물안개가 낮게 깔렸다. 넓은 연잎들이 물 위에 겹겹이 떠 있었고, 연밥 물새가 연잎 사이를 콕콕 쪼며 걸어 다녔다."}, {"s": null, "t": "안개 속에서 노 젓는 소리가 첨벙, 첨벙 가까워졌다. 노들 영감의 배가 나타났는데, 앞으로 오지 않고 제자리에서 빙글빙글 돌고 있었다."}, {"s": "river_alliance:nodeul", "t": "왼 노만 젓지 말고 오른 노도 저어라! 배가 맷돌이냐!"}, {"s": null, "t": "청파가 노 두 자루를 허우적거리며 뱃머리 쪽에 소리쳤다."}, {"s": "q:sn_cheongpa", "t": "영감님, 노가 두 개면 팔도 두 개라 헷갈린다고요!"}, {"s": null, "t": "청파가 두 노를 한꺼번에 첨벙 물에 꽂았다. 배가 그제야 똑바로 미끄러져 와서 물가 진흙에 쿵 하고 이물을 박았다. 노들 영감이 뱃머리에서 엉덩방아를 찧었다."}, {"s": null, "t": "나는 물가로 뛰어가 영감을 일으켜 세웠다. 영감이 허리를 문지르며 껄껄 웃었다."}, {"s": "river_alliance:nodeul", "t": "허허, 배를 대긴 댔구먼. 대는 게 아니라 박은 거지만."}, {"s": null, "t": "청파가 얼굴이 빨개져서 뱃전을 붙잡고 기침을 했다. 기침이 멎자 청파는 배에 실린 장대를 하나씩 물가로 넘겨주었다."}, {"s": null, "t": "장대를 세우는 일은 셋이 했다. 내가 진흙에 구덩이를 파면 청파가 장대를 세웠고, 노들 영감이 장대가 곧은지 한쪽 눈을 감고 쟀다. 장대 아래에는 판자 두 장을 깔고 청정수 단지를 놓았다."}, {"s": null, "t": "장대 다섯 개를 세웠을 때였다. 청파가 배에 실린 단지를 다 내려놓더니 고개를 갸웃했다. 청파가 단지 뚜껑을 하나씩 열어 보다가 얼굴이 하얗게 질렸다."}, {"s": "q:sn_cheongpa", "t": "어…… 영감님. 이거 다 청정수예요. 등에 넣을 기름 단지를 안 싣고 왔어요."}, {"s": null, "t": "노들 영감이 단지 하나를 들여다보고는 청파의 이마를 손가락으로 꾹 눌렀다."}, {"s": "river_alliance:nodeul", "t": "쉬어 갈 물은 넉넉한데 불이 없구먼. 사공이 목은 축이는데 앞이 안 보이겠어."}, {"s": null, "t": "청파가 고개를 푹 숙였다. 나는 늪에 붕어가 많으니 기름을 짜면 되지 않겠냐고 했다. 노들 영감이 고개를 끄덕였다."}, {"s": "river_alliance:nodeul", "t": "늪 붕어로 짠 등롱 어유가 장대 등에는 제일이네. 연기가 덜 나고 오래 타지. 조사원, 기름을 짜 주게. 우리는 그동안 장대를 마저 세우겠네. 해가 지기 전에 불을 넣어야 오늘 밤 사공들이 덕을 보지."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_2', 3, '물 위의 불빛', '등롱 어유을(를) 만든다, 등롱 어유을(를) 넘긴다', '{"at": ["lotus_marsh"], "tasks": [{"t": "craft", "items": ["lantern_oil"], "n": 3}], "give": {"lantern_oil": 3}}'::jsonb, '[{"s": null, "t": "등롱 어유를 단지에 담아 오자 장대 열두 개가 물가를 따라 서 있었다. 청파가 장대 꼭대기 등마다 기름을 붓고 심지를 세웠다."}, {"s": null, "t": "해가 지자 노들 영감이 첫 등에 불을 붙였다. 불빛 하나가 물 위에 노랗게 번졌다. 둘째, 셋째 등이 차례로 켜지자 물가를 따라 불빛 한 줄이 늪 안쪽까지 이어졌다."}, {"s": null, "t": "늪 가운데 연잎 그늘에서 번들거리던 눈들이 하나둘 물속으로 가라앉았다. 장대 불빛이 닿는 물가에는 수귀 하나 얼씬하지 않았다."}, {"s": null, "t": "연밭에서 일하던 아낙 하나가 장대 아래 판자에 와 앉았다. 아낙은 청정수 단지에서 물을 한 바가지 떠 마시고 길게 숨을 내쉬었다. 그러고는 우리 쪽에 고개를 꾸벅 숙이고 다시 연밭으로 돌아갔다."}, {"s": null, "t": "청파가 장대 아래 판자에 털썩 앉아 노를 무릎에 가로놓았다. 손바닥에 물집이 두 개 잡혀 있었다. 나는 청파 곁에 앉아 그 손에 청정수를 조금 부어 주었다."}, {"s": "q:sn_cheongpa", "t": "따가워요. …그래도 좋아요. 노를 저으니까 물이 위에서 보여요."}, {"s": null, "t": "나는 위에서 보는 물은 어떠냐고 물었다. 청파가 불빛이 번진 수면을 오래 내려다보았다."}, {"s": "q:sn_cheongpa", "t": "물 밑에선 손에 잡히는 것만 하나씩 알았어요. 문패 하나, 등롱 종이 한 장. 조용해서 좋았어요. 그런데 물 위에선 불빛이 한꺼번에 다 보이네요. 저 장대 하나하나가 누가 넘겨준 몫이라고 도방님이 그러셨잖아요. 그럼 불빛 하나가 사람 하나예요."}, {"s": null, "t": "청파가 말을 마치고 쿨럭쿨럭 기침을 했다. 기침 끝에 청파가 조금 웃었다."}, {"s": "q:sn_cheongpa", "t": "숨이 짧아서 잠수는 못 하는데, 노는 숨이 짧아도 저어지더라고요. 쉬었다 저으면 돼요. 저 장대 밑에서 쉬면서요."}, {"s": null, "t": "노들 영감이 뱃전에 기대 곰방대에 불을 붙였다. 연기가 등불 사이로 천천히 흩어졌다."}, {"s": "river_alliance:nodeul", "t": "물가에 불이 서면 사공이 쉬어 간다. 그게 나루가 할 일이지. 청파야, 돌아갈 때도 네가 저어라."}, {"s": null, "t": "청파가 노를 끌어안은 채 눈을 동그랗게 떴다."}, {"s": "q:sn_cheongpa", "t": "또요? 아까 박은 거 보셨잖아요."}, {"s": null, "t": "노들 영감이 곰방대 연기를 후 내뿜으며 대꾸했다."}, {"s": "river_alliance:nodeul", "t": "박았으니 저어야지. 한 번 박은 놈은 두 번은 안 박는 법이다."}, {"s": null, "t": "청파가 눈을 끔뻑이다가 노를 꼭 쥐었다. 장대 등불이 물 위에 길게 비쳐, 구름나루 쪽으로 가는 뱃길이 환하게 드러나 있었다."}]'::jsonb, '{"gil": 400}'::jsonb)
