update public.world_quests set open_req = '{"project": "f:river_alliance", "stage": 3}'::jsonb where quest_id = 'ep_river_3';
delete from public.world_quest_steps where quest_id = 'ep_river_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_3', 1, '기름 단지 여섯', '기름 단지 여섯', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "한여름이었다. 구름나루 선창 판자가 햇볕에 달아 발바닥이 뜨거웠다. 강 건너 물가마다 장대 등이 줄지어 서 있었고, 장대 아래 판자에서 뱃사람들이 웃통을 벗고 낮잠을 자고 있었다."}, {"s": null, "t": "선창 끝 거룻배에 매향이 기름 단지를 싣고 있었다. 단지마다 새끼줄로 단단히 묶여 있었다. 매향은 단지 하나를 실을 때마다 장부에 동그라미를 쳤다."}, {"s": null, "t": "거룻배 고물에는 청파가 노를 쥐고 앉아 있었다. 청파의 노 젓는 자리 옆에 진소랑이 쪼그려 앉아 청파 머리에 삿갓을 씌워 주고 있었다."}, {"s": "river_alliance:jin", "t": "조사원님, 오늘 뱃길이 열려요. 사업이 셋째 단계를 채워서요. 장대 등이 연화늪·염등촌·수경루를 지나 만조의 갑문까지 다 이어졌거든요. 이제 밤에도 물길을 질러 갈 수 있어요."}, {"s": "river_alliance:jin", "t": "이 뱃길로 가면 연맹 사람은 노정패를 안 내요. 길도 훨씬 빠르고요. 연맹 식구들이 넘겨준 몫으로 낸 길이니, 식구들이 먼저 덕을 봐야죠.", "fac": "river_alliance", "spec": 1, "grp": 1}, {"s": "river_alliance:jin", "t": "이 뱃길은 연맹 식구들이 넘겨준 몫으로 낸 길이라 식구들한테 먼저 덕이 가요. 그래도 첫 배에는 조사원님이 타 주셨으면 해요. 말뚝 박던 날 메를 쥐신 분이니까요.", "fac_not": "river_alliance", "spec": 2, "grp": 1}, {"s": null, "t": "나는 기름 단지는 어디로 가는 것이냐고 물었다. 매향이 새끼줄 매듭을 잡아당겨 보며 대답했다."}, {"s": "river_alliance:maehyang", "t": "염등촌이요. 해마다 제가 손수 실어 보내는 기름이에요. 염전 사람들은 밤에 소금을 구워서 등이 많이 들어요. 연맹 일이 아무리 바빠도 이 기름만은 제가 챙겨요. 셈에 안 넣고요."}, {"s": null, "t": "셈에 안 넣는다는 말에 진소랑이 매향을 흘끗 보았다. 매향은 그 눈길을 모른 척하고 마지막 단지를 실었다."}, {"s": "river_alliance:jin", "t": "청파가 몰 거예요. 노들 영감님한테 노를 배운 뒤로 장대 등 사이를 날마다 오갔거든요. 이번엔 연맹 거룻배를 통째로 맡겼어요. 첫 길이니 제대로 가 봐야죠."}, {"s": null, "t": "청파가 삿갓을 고쳐 쓰고 노를 들어 보였다. 손바닥 물집은 굳은살이 되어 있었다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님, 이번엔 안 박을게요. 진짜로요."}, {"s": null, "t": "진소랑이 청파의 삿갓 끈을 턱 밑에서 단단히 묶어 주었다."}, {"s": "river_alliance:jin", "t": "박아도 돼. 배는 고치면 되니까. 대신 너는 다치지 마. 숨찬 날엔 노를 조사원님께 넘기고."}, {"s": null, "t": "그때 매향이 품에서 서신 한 장을 꺼냈다. 염등촌 소금 냄새가 밴 종이였다."}, {"s": "river_alliance:maehyang", "t": "염등촌에서 온 서신이에요. 염전 끝 소금 더미에 매복귀가 또 붙고, 소금 게들이 가마 아궁이까지 기어든대요. 기름을 내려도 일할 수가 없다고요. 조사원님, 배가 닿거든 그것들부터 좀 쫓아 주세요. 기름은 제가 내릴게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_3', 2, '하얀 염전', '염등촌에 간다, 염등촌의 요괴를 물리친다', '{"at": ["salt_village"], "tasks": [{"t": "travel", "r": ["salt_village"], "n": 1}, {"t": "win", "r": ["salt_village"], "n": 8}]}'::jsonb, '[{"s": null, "t": "매복귀와 소금 게들이 염전 끝으로 물러나자 염등촌이 한눈에 들어왔다. 바다 쪽으로 염전이 바둑판처럼 펼쳐져 있었다. 칸마다 바닷물이 얕게 고여 햇빛에 하얗게 바래 가고 있었다."}, {"s": null, "t": "바람에 짠 내가 실려 왔다. 혀끝이 저절로 짭짤해졌다. 염전 사이 둑길에는 소금 더미가 하얀 봉분처럼 늘어서 있었다."}, {"s": null, "t": "둑길에서 염전 일꾼 하나가 고무래를 쥔 채 달려왔다. 소금기에 허옇게 튼 손으로 매향의 손을 덥석 잡았다."}, {"s": "q:sn_okbun", "t": "행수님! 올해도 손수 오셨네요……. 매복귀를 쫓아 주신 분은 저분이죠? 고맙습니다. 이제 가마에 불을 넣을 수 있겠어요……."}, {"s": null, "t": "옥분이 내게 고개를 꾸벅 숙였다. 그러고는 거룻배에 실린 기름 단지를 보고 눈을 크게 떴다."}, {"s": "q:sn_okbun", "t": "이번엔 배가 왜 이렇게 빨리 왔어요? 전에는 꼬박 하루 걸리던 물길을 반나절 만에 왔네요……."}, {"s": null, "t": "청파가 뱃전에서 벌떡 일어나 손을 번쩍 들었다."}, {"s": "q:sn_cheongpa", "t": "지름길이 열렸거든요! 이제 장대 불만 따라오면 밤에도 와요. 제가 몰았어요!"}, {"s": null, "t": "청파가 가슴을 폈다가 기침을 했다. 옥분이 청파의 등을 두드려 주며 매향을 돌아보았다."}, {"s": "q:sn_okbun", "t": "행수님, 이 기름 말이에요……. 해마다 셈에 안 넣으신다고 들었어요. 마을 어른들이 그러는데, 행수님 장부 맨 뒷장에 우리 마을 뱃사람 이름이 셋 적혀 있대요. 소금배 타고 나갔다가 안 돌아온 사람들이요……."}, {"s": null, "t": "매향의 주판 튕기던 손이 멈췄다. 매향은 장부를 품에 끌어안고 잠시 염전 쪽을 보았다."}, {"s": "river_alliance:maehyang", "t": "연맹 일 하다 물에 잠긴 사람들은 다 그 장에 적어요. 그 셋은 제가 행수가 된 첫해에 나간 배였고요. 기름은…… 그냥 셈이 안 되는 몫이에요. 그래서 셈에 안 넣어요."}, {"s": null, "t": "옥분이 매향의 손을 한 번 더 꼭 쥐었다가 놓았다. 매향은 단지를 내리는 일꾼들 쪽으로 돌아서서 다시 주판을 튕겼다. 탁탁 튕기는 소리가 아까보다 조금 느렸다."}, {"s": null, "t": "청파가 거룻배에 올라 바다 쪽 물길을 바라보았다. 장대 등이 염전 둑을 따라 바다 끝까지 점점이 이어져 있었다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님, 장대가 저기까지 가요. 만조의 갑문까지요. 뱃길 끝까지 가 봐야 길이 이어진 거잖아요. 갑문에 물때 표석이 있대요. 노들 영감님이 그 표석 눈금을 보고 오라고 하셨어요. 새 뱃길 장부에 물때를 적어야 한대요."}, {"s": null, "t": "매향이 장부를 덮고 청파 쪽으로 고개를 끄덕였다."}, {"s": "river_alliance:maehyang", "t": "다녀오세요. 표석 눈금은 저도 알아야 해요. 물때를 모르면 뱃길 셈이 안 서거든요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_3', 3, '물때 표석', '만조의 갑문에 간다, 만조의 갑문을(를) 살핀다', '{"at": ["tide_gate"], "tasks": [{"t": "travel", "r": ["tide_gate"], "n": 1}, {"t": "search", "r": ["tide_gate"], "n": 2}]}'::jsonb, '[{"s": null, "t": "만조의 갑문은 바다를 가로막고 선 돌벽이었다. 거대한 나무 문짝 두 짝이 쇠사슬에 매달려 있었고, 문짝 아래로 바닷물이 우르르 밀려들었다가 빠져나갔다."}, {"s": null, "t": "갑문 돌벽을 따라 두 번 살피자 물에 반쯤 잠긴 표석이 나왔다. 사람 키만 한 돌기둥에 눈금이 빼곡하게 새겨져 있었다. 눈금마다 작은 글씨로 물때가 적혀 있었다."}, {"s": null, "t": "청파가 표석 앞 계단에 엎드려 눈금을 하나씩 손끝으로 짚었다. 짚을 때마다 입술이 달싹이며 숫자를 셌다."}, {"s": "q:sn_cheongpa", "t": "사리 때 여기, 조금 때 여기……. {이름} 님, 지금 물이 둘째 눈금까지 와 있어요. 곧 만조예요. 이 표석, 증조할아버지 장부에도 그려져 있던 거랑 똑같아요."}, {"s": null, "t": "청파가 허리춤에서 작은 공책을 꺼냈다. 매향에게 받은 새 뱃길 장부였다. 청파가 붓끝을 바닷물에 적셔 먹을 갠 뒤 눈금을 옮겨 그렸다."}, {"s": null, "t": "바닷물이 차오르는 소리가 점점 커졌다. 문짝 아래로 물이 솟구치며 쏴아아 흰 거품을 뿜었다. 청파가 붓을 멈추고 그 물을 오래 보았다."}, {"s": null, "t": "나는 청파 곁에 앉아 물에 들어가고 싶으냐고 물었다. 청파가 고개를 저었다."}, {"s": "q:sn_cheongpa", "t": "아니요. 이상하죠? 전에는 물만 보면 들어가고 싶었는데. 지금은 위에서 보는 게 좋아요. 물이 어디서 와서 어디로 가는지 보여요. 밑에 있을 땐 그게 안 보였어요."}, {"s": "q:sn_cheongpa", "t": "그리고 숨 쉴 때마다 기침이 나니까, 저는 이제 천천히 가야 하잖아요. 천천히 가니까 장대 등이 하나씩 다 보이더라고요. 염전 둑에서 낮잠 자던 아저씨도 보이고요."}, {"s": null, "t": "청파가 쿨럭 기침을 하고 웃었다. 나는 청파가 그린 눈금 옆에 오늘 물때와 날짜를 적어 넣어 주었다. 청파가 공책을 들여다보고 고개를 끄덕였다."}, {"s": "q:sn_cheongpa", "t": "됐다. 이제 이 뱃길은 장부에 있어요. 장부에 있으면 다음 사람도 와요."}, {"s": null, "t": "청파가 공책을 품에 넣고 갑문 난간에 등을 기댔다. 바닷바람에 삿갓이 날아갈 뻔하자 내가 삿갓 끈을 붙잡아 주었다."}, {"s": "q:sn_cheongpa", "t": "고마워요. …{이름} 님은 또 제 줄을 잡아 주시네요. 전엔 물 밑으로 내려가는 줄이었는데, 이번엔 물 위에서요."}, {"s": null, "t": "갑문 꼭대기에도 장대 하나가 서 있었다. 청파가 거룻배에 남겨 둔 기름 단지 하나를 들고 올라가 장대 등에 기름을 부었다. 매향이 셈에 안 넣고 하나를 더 실어 보낸 단지였다."}, {"s": null, "t": "해가 바다 끝으로 기울었다. 청파가 갑문 꼭대기 등에 불을 붙이자, 구름나루 쪽으로 늘어선 장대 등들이 멀리서 하나씩 화답하듯 켜졌다. 뱃길이 불빛으로 이어져 있었다."}, {"s": "q:sn_cheongpa", "t": "내일은 해 뜨자마자 돌아가요. 이번엔 제가 키 잡고 {이름} 님은 주무세요. 노 저을 숨은 아껴 뒀거든요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_river_4', 'side', '뒷이야기·구름나루', '물빛 저고리', '사업이 넷째 단계를 채우자 연맹 비고에 새 물건 둘을 들이기로 한다. 진소랑이 주판을 내려놓고 바늘을 들어 「뱃사공 저고리」를 짓고, 노들 영감과 청파는 갈아 낸 옛 말뚝으로 「나룻배 노 걸이」를 짠다.', 'river_ferry', 50, '{mdq_17,ep_river_3}'::text[], null, 1543, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:river_alliance", "stage": 4}'::jsonb where quest_id = 'ep_river_4';
delete from public.world_quest_steps where quest_id = 'ep_river_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_4', 1, '바늘에 찔린 도방', '바늘에 찔린 도방', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "가을바람이 강을 따라 내려와 선창 장대 등을 흔들었다. 연맹 큰 배 비단 차양 아래에서 진소랑이 무명 한 필을 무릎에 펼쳐 놓고 바늘을 쥐고 있었다."}, {"s": null, "t": "바늘이 천을 한 번 뚫고 나올 때마다 진소랑의 얼굴이 찡그려졌다. 탁자 끝에는 주판이 엎어져 있었고, 매향이 그 곁에 서서 진소랑의 손을 불안하게 내려다보고 있었다."}, {"s": "river_alliance:jin", "t": "아야."}, {"s": null, "t": "매향이 얼른 손을 뻗어 진소랑의 바늘 쥔 손을 붙잡았다."}, {"s": "river_alliance:maehyang", "t": "도방님, 셋째예요. 손가락을 셋째 찌르셨어요. 저한테 주세요, 제가 할게요."}, {"s": null, "t": "진소랑이 매향의 손을 살짝 밀어내며 고개를 저었다."}, {"s": "river_alliance:jin", "t": "안 돼. 이건 내가 해야 해."}, {"s": null, "t": "진소랑이 찔린 손가락을 입에 물었다가 나를 보고 웃었다. 늘 값을 깎을 때 짓던 웃음이 아니라 조금 쑥스러운 웃음이었다."}, {"s": "river_alliance:jin", "t": "조사원님, 꼴이 우습죠? 사업이 넷째 단계를 채워서 연맹 비고에 새 물건 둘을 들이게 됐어요. 하나는 뱃사공 저고리, 하나는 나룻배 노 걸이예요. 저고리는 제가 짓겠다고 했어요."}, {"s": "river_alliance:jin", "t": "비고 물건은 연맹 식구가 공훈으로 들이는 거잖아요. 식구들이 몫을 넘겨 채운 단계니까, 식구들이 입을 저고리는 도방이 지어야 셈이 맞아요.", "fac": "river_alliance", "spec": 1, "grp": 1}, {"s": "river_alliance:jin", "t": "비고 물건은 연맹 식구들이 공훈으로 들이는 거라 조사원님께는 못 드려요. 그래도 몫을 넘겨 도와주신 분들 덕에 채운 단계니까, 짓는 걸 보시는 건 셈에 넣어 드릴게요.", "fac_not": "river_alliance", "spec": 2, "grp": 1}, {"s": null, "t": "나는 도방이 손수 저고리를 짓는 까닭을 물었다. 진소랑이 바늘을 천에 꽂아 두고 강물 쪽을 보았다."}, {"s": "river_alliance:jin", "t": "우리 집은 동짓날 밥상에 밥그릇을 하나 더 놓아요. 할머니 때부터요. 누구 거냐고 물으면 「다음 배 몫」이래요. 저는 그 그릇을 볼 때마다 생각했어요. 다음 배 타는 사람은 무얼 입고 올까."}, {"s": "river_alliance:jin", "t": "그래서 저고리도 하나는 다음 배 몫으로 짓고 싶었어요. 뱃사공들이 노를 저을 때 입는 물빛 저고리요. 물빛은 연화늪 수향 갈대를 삶아 물들여야 나요."}, {"s": null, "t": "매향이 진소랑의 바늘을 흘끗 보더니 한숨을 쉬고 주판을 집어 들었다. 셈을 시작하는 손이었다."}, {"s": "river_alliance:maehyang", "t": "저고리 열 벌에 갈대가 한 짐, 실은 영사 실타래로 꼬아야 뱃일에 안 터져요. 실은 제가 셈하고, 갈대는…… 조사원님, 연화늪에서 수향 갈대를 꺾어다 실까지 꼬아 주시겠어요? 도방님 손가락이 열 개라도 실 꼬다가는 다 찔리시겠어요."}, {"s": null, "t": "진소랑이 바늘을 든 채 매향을 흘겨보았다."}, {"s": "river_alliance:jin", "t": "매향."}, {"s": null, "t": "매향은 주판알만 내려다보며 시치미를 뗐다."}, {"s": "river_alliance:maehyang", "t": "셈이 그래요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_4', 2, '그물 바늘과 옛 말뚝', '천엽 연화늪에서 수향 갈대을(를) 모은다, 영사 실타래을(를) 만든다, 영사 실타래을(를) 넘긴다', '{"at": ["river_ferry"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["lotus_marsh"], "n": 4}, {"t": "craft", "items": ["spirit_thread"], "n": 3}], "give": {"spirit_thread": 3}}'::jsonb, '[{"s": null, "t": "갈대를 지고 돌아오자 선창 화로에 큰 솥이 걸려 있었다. 매향이 갈대를 솥에 넣고 삶자 물이 서서히 푸르스름하게 변했다. 진소랑이 무명을 솥에 담갔다 건지자 천이 강물 빛으로 물들어 있었다."}, {"s": null, "t": "물들인 천을 장대에 널어 말리는 동안 진소랑은 다시 바늘을 쥐었다. 이번에는 곁에 개동 영감이 앉아 있었다. 영감은 그물 바늘을 쥔 손으로 진소랑의 바늘 쥔 손을 고쳐 잡아 주었다."}, {"s": "q:sx_md_gaedong", "t": "바늘은 끝으로 밀지 말고 손바닥으로 밀게. 그물이든 저고리든 바늘은 손바닥이 미는 거구먼. 도방은 주판만 튕겨서 손끝에만 힘이 들어가 있어."}, {"s": null, "t": "진소랑이 영감 말대로 바늘을 밀었다. 바늘이 천을 쑥 뚫고 나왔다. 진소랑이 눈을 동그랗게 떴다."}, {"s": "river_alliance:jin", "t": "어머, 안 찔렸어요."}, {"s": null, "t": "매향이 그 모습을 보고 주판을 슬그머니 내려놓았다. 매향은 물들인 천 한 자락을 집어 들어 제 소매에 대 보았다."}, {"s": "river_alliance:maehyang", "t": "도방님, 저도 한 벌만요. 값은 셈해서 낼게요."}, {"s": null, "t": "진소랑이 바늘땀을 마저 뜨며 매향 쪽은 보지도 않고 대답했다."}, {"s": "river_alliance:jin", "t": "행수는 셈부터 하니까 맨 나중이야."}, {"s": null, "t": "개동 영감이 그물 바늘로 제 무릎을 툭 치며 끼어들었다."}, {"s": "q:sx_md_gaedong", "t": "여든 해 그물을 기웠는데 그 정도는 가르쳐야지. 값은 안 받겠구먼."}, {"s": null, "t": "선창 반대쪽에서는 톱질 소리가 슥삭슥삭 울렸다. 노들 영감과 청파가 말뚝 박던 날 뽑아낸 옛 말뚝을 눕혀 놓고 썩은 데를 잘라 내고 있었다. 성한 윗도리만 남기자 말뚝 머리마다 노들 영감이 숯으로 적었던 배 이름이 그대로 남아 있었다."}, {"s": "river_alliance:nodeul", "t": "노 걸이는 이 나무로 짤 거네. 방울호, 늦물이, 쌍노……. 이 배들을 매던 나무에 이제 노를 걸어 두면, 배는 없어도 노는 제자리를 찾겠지."}, {"s": null, "t": "청파가 톱을 내려놓고 「늦물이」라고 적힌 나무를 손바닥으로 쓸었다. 청파가 노들 영감을 돌아보았다."}, {"s": "q:sn_cheongpa", "t": "영감님 동무 배였죠? 이건 제가 다듬을게요. 노 걸이 맨 윗단에 올려요."}, {"s": null, "t": "노들 영감이 대답 대신 청파의 삿갓을 툭 쳤다. 청파가 끌을 쥐고 나무를 깎기 시작했는데, 첫 끌질에 끌이 미끄러져 나무 대신 판자를 팠다."}, {"s": "river_alliance:nodeul", "t": "끌날이 다 죽었구먼. 쉰 해 쓴 끌이니 그럴 만도 하지. 대패도 그렇고 톱도 그래. 연장부터 손봐야 노 걸이가 제 모양이 나겠어."}, {"s": null, "t": "노들 영감이 연장 자루를 통째로 내 앞에 내려놓았다. 끌·대패·톱이 녹슨 채 뒤엉켜 있었다."}, {"s": "river_alliance:nodeul", "t": "조사원, 실타래는 도방님께 드리고, 이 연장들을 좀 갈고 닦아 주게. 날이 서야 이 늙은 나무들이 안 갈라지네. 시간은 좀 걸려도 서두르지 말게. 나무가 기다려 줄 거야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_4', 3, '비고에 든 두 가지', '자율 활동을 끝까지 마친다, 영사 실타래을(를) 넘긴다', '{"at": ["river_ferry"], "tasks": [{"t": "idle", "n": 1, "k": "maintenance"}], "give": {"spirit_thread": 3}}'::jsonb, '[{"s": null, "t": "연장을 다 갈아 돌려주자 노들 영감이 끌날을 엄지로 쓸어 보고 흐뭇하게 웃었다. 그 끌로 청파가 다듬은 나무들이 짜 맞춰져 노 걸이가 되었다. 맨 윗단에 「늦물이」가, 그 아래로 다른 배 이름들이 층층이 박혀 있었다."}, {"s": null, "t": "진소랑의 저고리도 다 지어졌다. 장대에 걸린 물빛 저고리 열 벌이 강바람에 펄럭였다. 실밥이 삐뚤삐뚤한 것도 있었지만, 개동 영감이 손을 잡아 준 뒤로 지은 것들은 바늘땀이 고르게 박혀 있었다."}, {"s": null, "t": "매향이 비고 문을 열고 노 걸이를 벽에 세웠다. 노들 영감이 오래 쓴 노 셋을 노 걸이에 하나씩 걸었다. 노마다 손잡이가 손 모양으로 닳아 있었다."}, {"s": "river_alliance:maehyang", "t": "비고 장부에 적을게요. 「나룻배 노 걸이 하나. 뱃사공 저고리.」"}, {"s": "river_alliance:maehyang", "t": "이제 연맹 식구들은 공훈으로 이 둘을 들일 수 있어요. 노 걸이는 별채에 세우면 되고, 저고리는 입고 노를 저으면 되고요. 조사원님도 공훈이 모이면 오세요.", "fac": "river_alliance", "spec": 1, "grp": 1}, {"s": "river_alliance:maehyang", "t": "연맹 식구들이 공훈으로 들이는 물건이에요. 조사원님은 대신 오늘 이걸 제일 먼저 보신 분으로 장부 귀퉁이에 적어 둘게요. 셈에는 안 들어가는 줄이지만요.", "fac_not": "river_alliance", "spec": 2, "grp": 1}, {"s": null, "t": "진소랑이 저고리 한 벌을 걷어 들고 청파에게 다가갔다. 청파의 어깨에 저고리를 대어 보더니 웃음을 터뜨렸다. 소매가 청파 손등을 다 덮고도 한 뼘이 남았다."}, {"s": "q:sn_cheongpa", "t": "도방님, 이거 노들 영감님 몸에 맞춘 거죠?"}, {"s": null, "t": "진소랑이 소매 끝을 접어 올려 주며 생긋 웃었다."}, {"s": "river_alliance:jin", "t": "너 크라고 크게 지은 거야. 셈해 보니 한 해면 맞아."}, {"s": null, "t": "청파가 소매를 걷어 올리며 투덜댔지만 저고리를 벗지는 않았다. 노들 영감이 그 꼴을 보고 껄껄 웃었고, 개동 영감은 그물 바늘로 소맷부리 끝을 한 땀 집어 올려 주었다."}, {"s": null, "t": "진소랑은 남은 저고리 가운데 하나를 따로 개어 품에 넣었다. 다른 것들보다 바늘땀이 가장 고른 벌이었다. 나는 그건 누구 몫이냐고 물었다."}, {"s": "river_alliance:jin", "t": "다음 배 몫이요. 동짓날 밥그릇 옆에 개어 둘 거예요. 오는 사람이 누구든, 젖은 옷 말고 이걸 입게요."}, {"s": null, "t": "노들 영감이 노 걸이 맨 윗단의 늦물이 노를 손바닥으로 쓸었다. 영감이 문득 고개를 들어 진소랑을 보았다."}, {"s": "river_alliance:nodeul", "t": "도방님, 뱃길 고치는 일이 다 끝나는 날엔 큰 배를 띄우시겠지. 그날 맨 마지막 노는 내가 젓게 해 주시게. 이 나루 오십 년 노를 저었으니, 그 정도 셈은 해 주시겠지."}, {"s": null, "t": "진소랑이 웃으며 주판의 붉은 알을 톡 튕겼다. 값을 깎을 때의 손짓이었지만, 이번엔 아무것도 깎지 않았다."}, {"s": "river_alliance:jin", "t": "그 셈은 안 깎을게요. 맨 마지막 노는 영감님 거예요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_river_5', 'side', '뒷이야기·구름나루', '첫 뱃길 띄우기', '사업이 다섯째 단계를 채워 고친 뱃길이 낙성한다. 물길 무늬 깃발을 단 연맹 큰 배가 처음 물길에 오르고, 구름나루 선창엔 돛배와 등 단 장대가 빼곡하다. 수향에서는 배를 띄우는 날 맨 마지막 노를 그 나루에서 가장 오래 노를 저은 사람이 젓는다.', 'river_ferry', 50, '{mdq_17,ep_river_4}'::text[], null, 1544, '[]'::jsonb, true, null, null)
