update public.world_quests set open_req = '{"project": "f:river_alliance", "stage": 5}'::jsonb where quest_id = 'ep_river_5';
delete from public.world_quest_steps where quest_id = 'ep_river_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_5', 1, '물길 무늬 깃발', '물길 무늬 깃발', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "늦가을 맑은 아침이었다. 구름나루 선창은 발 디딜 틈이 없었다. 말뚝 스물넷마다 돛배가 매여 있었고, 강 건너 물가에는 장대 등이 끝도 없이 늘어서 있었다."}, {"s": null, "t": "선창 한가운데 연맹 큰 배가 새 돛을 올리고 있었다. 돛대 끝에서 큰 깃발 하나가 바람에 펄럭였다. 푸른 바탕에 굽이굽이 흐르는 물길 무늬가 하얗게 수놓여 있었다."}, {"s": null, "t": "깃발 아래 갑판에서 매향이 장부를 들고 무언가를 세고 있었다. 매향이 나를 보고 손짓했다."}, {"s": "river_alliance:maehyang", "t": "조사원님! 오늘이 낙성이에요. 뱃길 고치기가 다섯째 단계까지 다 찼어요. 저 깃발 무늬가 이번 사업 무늬예요. 물길 무늬요."}, {"s": "river_alliance:maehyang", "t": "연맹 식구들은 오늘부터 이 물길 무늬를 바탕 무늬로 쓸 수 있어요. 조사원님 바탕에도 넣어 보세요. 몫을 넘긴 식구들 모두의 무늬예요.", "fac": "river_alliance", "spec": 1, "grp": 1}, {"s": "river_alliance:maehyang", "t": "무늬는 연맹 식구들 몫이라 조사원님 바탕엔 못 넣어 드려요. 그래도 오늘 깃발은 맨 앞에서 보세요. 도와주신 다른 세력 분들 셈도 이 깃발에 다 들어 있으니까요.", "fac_not": "river_alliance", "spec": 2, "grp": 1}, {"s": null, "t": "진소랑이 선실에서 나와 갑판 난간을 짚었다. 진소랑은 강물을 내려다보며 손가락으로 난간을 톡톡 두드렸다. 셈이 잘 안 맞을 때 하던 버릇이었다."}, {"s": "river_alliance:jin", "t": "큰 배는 띄우기 전에 첫 뱃길을 먼저 다녀오는 법이에요. 사람 몇이 작은 배로 물길 끝까지 가서 물이 순한지 보고 오는 거죠. 이번 첫 뱃길은 용잠 수궁 물길이에요. 지름길이 수궁 앞까지 이어졌거든요."}, {"s": null, "t": "나는 왜 하필 용잠 수궁이냐고 물었다. 진소랑이 웃으며 나를 보았다."}, {"s": "river_alliance:jin", "t": "수향 배가 제일 많이 못 돌아온 물길이 거기예요. 역린이 물길을 잠그던 해엔 열한 척이 돌아오지 못했죠. 그 물길에 백 년 만에 처음 불을 들고 들어간 사람이 조사원님이시고요. 그러니 첫 뱃길은 조사원님이 앞장서 주셔야 셈이 맞아요."}, {"s": null, "t": "갑판 아래에서 쿨럭 기침 소리가 났다. 물빛 저고리를 입은 청파가 소매를 둘둘 걷어 올린 채 작은 배의 노를 쥐고 있었다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님, 제가 태워 드릴게요! 수궁 물길은 제가 장대 등 따라 몇 번 다녀왔어요. 이번엔 안 박아요. 진짜로요."}, {"s": null, "t": "노들 영감이 판자 위에서 곰방대를 빼 들고 청파를 내려다보았다."}, {"s": "river_alliance:nodeul", "t": "지난번에도 진짜라더니 갑문 계단에 이물을 긁었다지."}, {"s": null, "t": "노들 영감이 선창 판자에 앉아 곰방대를 문 채 말했다. 청파의 얼굴이 빨개졌다. 매향이 장부에 무언가를 적으며 고개를 끄덕였다."}, {"s": "river_alliance:maehyang", "t": "긁은 건 맞아요. 셈에 넣어 놨어요."}, {"s": null, "t": "청파가 매향을 원망스럽게 올려다보다가 기침을 했다. 진소랑이 웃음을 참으며 내 쪽으로 몸을 돌렸다."}, {"s": "river_alliance:jin", "t": "청파가 긁은 셈은 제가 갚을게요. 조사원님은 물길만 봐 주세요. 수궁 앞 물이 순하면 내일 아침에 띄울 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_5', 2, '낙성 전날 밤', '용잠 수궁에 간다, 용잠 수궁에 원정을 다녀온다', '{"at": ["river_ferry"], "tasks": [{"t": "travel", "r": ["sunken_palace"], "n": 1}, {"t": "expedition", "r": ["sunken_palace"], "n": 1}]}'::jsonb, '[{"s": null, "t": "청파의 배로 용잠 수궁까지 내려가 물길 끝을 한 바퀴 돌고 구름나루로 돌아오자 해가 저물어 있었다. 수궁 앞 물은 순했고, 장대 등은 물길을 따라 수궁 문 앞까지 하나도 꺼지지 않고 서 있었다. 진소랑이 내 이야기를 듣고 그제야 난간을 두드리던 손가락을 멈췄다."}, {"s": "river_alliance:jin", "t": "물이 순하다니 내일 띄울게요. 고생하셨어요."}, {"s": null, "t": "밤이 되자 구름나루로 배가 하나둘 모여들었다. 염등촌 소금배가 왔고, 연화늪 연밭 배가 왔다. 강 하류에서는 작은 거룻배 하나가 노를 첨벙첨벙 저으며 올라왔다."}, {"s": null, "t": "거룻배를 몰고 온 젊은 뱃사람이 노를 지팡이처럼 짚고 선창에 뛰어올랐다. 등도 남문 수로 선착에서 짐을 나르는 삿대였다."}, {"s": "q:sx_md_satdae", "t": "청파야! 큰 배 띄운다며! 등도에서 이틀 저어 왔어. 장대 등 덕에 밤에도 왔다니까!"}, {"s": null, "t": "청파가 삿대를 보고 펄쩍 뛰다가 기침을 했다. 삿대가 청파의 등을 두드리며 물빛 저고리 소매를 잡아당겼다."}, {"s": "q:sx_md_satdae", "t": "이게 그 도방님이 지었다는 저고리야? 소매가 왜 이렇게 길어. 너 키 안 크면 이거 평생 걷고 다녀야겠다."}, {"s": null, "t": "청파가 소매를 걷어붙이며 삿대를 노려보았다."}, {"s": "q:sn_cheongpa", "t": "클 거야! 도방님이 한 해면 맞는댔어!"}, {"s": null, "t": "선창 한쪽에서는 달래가 화로 셋을 걸고 생선을 굽고 있었다. 개동 영감은 큰 배 밧줄에 매듭을 하나씩 짓고 있었다. 배가 다시 뜨면 식구들이 밧줄에 매듭을 하나씩 지어 주는 것이 수향 법이었다."}, {"s": "q:sx_md_gaedong", "t": "조사원도 하나 짓게. 다시는 땅에 앉지 말라는 매듭이구먼. 매듭 수가 많을수록 배가 오래 간다지."}, {"s": null, "t": "나는 개동 영감이 가르쳐 주는 대로 매듭 하나를 지었다. 영감이 그것을 당겨 보고 고개를 끄덕였다. 매듭을 잘못 지어 꿀밤을 맞던 사환이, 여든이 넘어 남의 매듭을 봐 주고 있었다."}, {"s": null, "t": "진소랑이 선창으로 내려와 상자 하나를 열었다. 상자 안에 떡이 가지런히 쌓여 있었다. 진소랑이 떡을 하나씩 집어 뱃사람들에게 나눠 주었다."}, {"s": "river_alliance:jin", "t": "낙성 떡이에요. 사업에 몫을 넘겨준 사람들한테 돌리는 떡이요. 넘겨준 갈대 한 줌, 차 한 잔이 다 모여서 말뚝이 되고 장대가 되고 이 큰 배가 됐어요. 연맹 장부로는 다 셈이 안 되는 몫이에요."}, {"s": null, "t": "노들 영감은 모두가 떠드는 동안 혼자 큰 배 고물에 앉아 있었다. 맨 마지막 노가 걸릴 자리를 손바닥으로 몇 번이고 쓸었다."}, {"s": "river_alliance:nodeul", "t": "내일 해 뜨면 띄우네. 오늘 밤은 다들 선창에서 자게. 물소리 들으면서 자는 게 뱃사람한테는 제일 좋은 잠이야. 자네도 그렇게 하게, 조사원."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_river_5', 3, '맨 마지막 노', '구름나루에서 쉰다', '{"at": ["river_ferry"], "tasks": [{"t": "rest", "r": ["river_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "선창 판자에 누워 물소리를 들으며 잤다. 동이 트자 진소랑이 큰 배 갑판 위에서 징을 울렸다. 둥, 소리가 강 위로 멀리 퍼졌다."}, {"s": null, "t": "큰 배 양옆으로 노가 열둘 걸려 있었다. 수향 뱃사람들이 차례로 올라 노를 하나씩 잡았다. 염등촌 사람이 잡고, 연화늪 사람이 잡고, 삿대가 잡았다. 열한째 노는 청파가 잡았다. 청파는 기침을 꾹 참으며 노 손잡이를 두 손으로 감쌌다."}, {"s": null, "t": "열둘째 노 자리만 비어 있었다. 노들 영감이 허리를 짚고 천천히 갑판으로 올라섰다. 영감이 노 걸이에서 늦물이 노를 내려 들고 왔다. 영감은 그 노를 맨 마지막 자리에 걸었다."}, {"s": "river_alliance:nodeul", "t": "이 나루 오십 년이네. 처음 노를 잡던 날 내 앞에서 노를 저은 사람이 이 늦물이 사공이었지. 오늘은 내가 맨 뒤에서 젓겠네. 앞에서 젓는 젊은것들 등을 보면서."}, {"s": null, "t": "진소랑이 징을 한 번 더 울렸다. 노 열둘이 한꺼번에 첨벙 물에 꽂혔다. 큰 배가 몸을 흔들며 말뚝에서 떨어져 나왔다."}, {"s": null, "t": "배가 강 한가운데로 미끄러져 나가자 선창의 돛배들이 하나둘 돛을 올리고 뒤따랐다. 물길 무늬 깃발이 맨 앞에서 펄럭였고, 그 뒤로 돛배들의 흰 돛과 장대 등의 불빛이 강을 따라 길게 이어졌다."}, {"s": null, "t": "나는 선창 끝에 서서 그 모습을 보았다. 개동 영감이 내 곁에서 그물 바늘을 쥔 채 강을 보고 있었다."}, {"s": "q:sx_md_gaedong", "t": "이 나루가 이렇게 꽉 찬 건 여든 해 만에 처음이구먼. 내가 사환일 적에도 이렇진 않았어."}, {"s": null, "t": "강굽이를 한 바퀴 돌아온 큰 배가 선창으로 돌아왔다. 노들 영감이 맨 마지막 노를 거두어 무릎에 올려놓았다. 영감의 이마에 땀이 송골송골 맺혀 있었다."}, {"s": null, "t": "청파가 노를 놓고 영감에게 달려가다가 기침을 했다. 기침이 멎자 청파가 영감 곁에 쪼그려 앉았다."}, {"s": "q:sn_cheongpa", "t": "영감님, 이제 노 안 저으세요? 이게 마지막이에요?"}, {"s": null, "t": "노들 영감이 땀을 훔치다 말고 껄껄 웃음을 터뜨렸다."}, {"s": "river_alliance:nodeul", "t": "허허, 무슨 소리냐. 맨 마지막 노라고 했지, 내 마지막 노라고 했냐. 내일도 거룻배는 내가 젓는다. 큰 배 맨 뒷자리는 그냥 늙은이 몫으로 하나 둔 거지."}, {"s": null, "t": "청파가 입을 벌렸다가 깔깔 웃었다. 갑판 위 뱃사람들이 따라 웃었고, 매향이 장부에 무언가를 적었다."}, {"s": "river_alliance:maehyang", "t": "「맨 마지막 노, 노들 영감. 다음 해에도.」 적었어요."}, {"s": null, "t": "진소랑이 갑판 난간에 기대어 선창을 내려다보았다. 이번엔 손가락으로 난간을 두드리지 않았다."}, {"s": "river_alliance:jin", "t": "조사원님, 고마워요. 몫을 넘겨준 사람들, 메를 쥐어 준 사람들, 갈대를 꺾어다 준 사람들……. 다 이 배에 타 있어요. 장부로는 셈이 안 되지만요."}, {"s": null, "t": "노들 영감이 늦물이 노를 노 걸이에 도로 걸며 곰방대에 불을 붙였다. 연기가 깃발 쪽으로 흩어졌다."}, {"s": "river_alliance:nodeul", "t": "떠났다 돌아오는 배가 제일 반가운 법이지. 오늘 이 배는 떠났다가 돌아왔으니, 이 나루는 오늘 제일 반가운 날이구먼."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_south_1', 'side', '뒷이야기·잔불촌', '공동 부엌 화덕', '잔불촌 공동 부엌의 화덕이 무너져, 부엌 어멈 복례는 맨땅에 돌 셋을 괴고 밥을 짓고 있다. 사업 첫 몫으로 상점에 어유 등잔과 갈치조림을 내놓기로 한 날, 복례가 망국 때부터 지킨 불씨를 새 화덕으로 옮긴다.', 'ember_village', 50, '{mdq_17}'::text[], null, 1545, '[]'::jsonb, true, null, null)
