update public.world_quests set open_req = '{"project": "f:southern_remnant", "stage": 1}'::jsonb where quest_id = 'ep_south_1';
delete from public.world_quest_steps where quest_id = 'ep_south_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_1', 1, '돌 셋 위의 솥', '돌 셋 위의 솥', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "이른 봄이었다. 잔불촌 어귀에 들어서자 숯 냄새가 먼저 코끝에 닿았다. 마을 한가운데 큰 화로는 여느 때처럼 타고 있었고, 아이들이 그 둘레에서 언 손을 녹이고 있었다."}, {"s": null, "t": "화로 뒤편 공동 부엌은 지붕만 남은 헛간이었다. 기둥 사이에 흙더미가 무너져 있었다. 화덕이었던 자리였다."}, {"s": null, "t": "흙더미 옆 맨땅에 돌 셋이 괴어져 있었고, 그 위에 큰 솥 하나가 얹혀 있었다. 부엌 어멈 복례가 돌 사이에 부지깽이를 넣어 불을 들쑤시고 있었다. 연기가 솥 둘레로 새어 나와 어멈의 눈을 자꾸 찔렀다."}, {"s": null, "t": "복례가 콜록콜록 기침을 하며 연기를 손으로 내저었다."}, {"s": "q:sn_bokrye", "t": "이 연기 좀 보구려. 손님이 왔는데 눈물 바람이라니."}, {"s": null, "t": "복례가 소매로 눈가를 훔치며 나를 보았다. 그러고는 치마폭 곁에 놓인 질그릇 단지를 손바닥으로 덮었다. 단지 뚜껑 틈으로 작은 붉은빛이 새어 나왔다."}, {"s": "q:sn_bokrye", "t": "지난겨울 서리에 흙이 들떠서 화덕이 주저앉았소. 서른 해 가까이 쓴 화덕이니 그럴 만도 하지. 그 뒤로는 돌 셋 위에 솥을 올려 마을 밥을 짓고 있소."}, {"s": null, "t": "나는 복례의 손이 덮고 있는 단지를 보았다. 내 눈길을 알아챈 복례가 뚜껑을 살짝 들어 보여 주었다. 숯 한 덩이 속에 콩알만 한 불씨가 붉게 숨 쉬고 있었다."}, {"s": "q:sn_bokrye", "t": "나라가 망하던 밤에 성에서 들고 나온 불씨요. 그 뒤로 한 번도 안 꺼졌지. 화덕이 무너지던 밤에 이것부터 단지에 옮겨 담았소. 맨땅에 오래 두면 불씨가 서러워해."}, {"s": null, "t": "공동 부엌 맞은편 상점 앞에 새 궤짝 둘이 내려져 있었다. 궤짝 하나에는 놋 등잔이 가지런히 담겨 있었고, 다른 하나는 비어 있었다. 복례가 빈 궤짝을 턱으로 가리키며 혀를 찼다."}, {"s": "q:sn_bokrye", "t": "거점 사업이 첫 단계를 채웠다더구려. 남명 끈 찬 사람들이 주괴며 숯이며 넘겨준 덕이지. 그 몫으로 상점에 어유 등잔이랑 갈치조림을 들이기로 했소. 남명 사람한테는 하루 다섯씩 판다오.", "fac": "southern_remnant", "spec": 1, "grp": 1}, {"s": "q:sn_bokrye", "t": "거점 사업이 첫 단계를 채웠다더구려. 남명 사람들이랑 여러 조사원이 주괴며 숯이며 넘겨준 덕이지. 그 몫으로 상점에 어유 등잔이랑 갈치조림을 들이기로 했소. 남명 끈 찬 사람한테만 파는 물건이라 손님한테는 못 팔지만, 첫 솥 맛은 보여 주리다.", "fac_not": "southern_remnant", "spec": 2, "grp": 1}, {"s": "q:sn_bokrye", "t": "등잔은 재의 해안 어부들이 짜 온 기름으로 만들어 들였소. 그런데 갈치조림은 이 부엌에서 조려 내야 하는데, 돌 셋 위에서는 불이 고르질 않아 국물이 다 눌어붙는구려."}, {"s": null, "t": "솥 둘레를 기웃거리던 아낙 하나가 복례 곁에 와서 쪼그려 앉았다. 갈매를 어릴 때부터 「갈매야」 하고 부르던 머루댁이었다. 머루댁이 무너진 흙더미를 손으로 쥐어 보고 혀를 끌끌 찼다."}, {"s": "q:sx_md_meoru", "t": "어멈, 이 흙은 다 죽었어. 화덕은 불씨 고개 붉은 흙이라야 안 갈라져. 차돌도 몇 개 박아야 하고."}, {"s": null, "t": "복례가 부지깽이를 쥔 채 머루댁을 흘겨보았다."}, {"s": "q:sn_bokrye", "t": "누가 그걸 몰라서 이러고 있나. 고개까지 다녀올 다리가 없어서지."}, {"s": null, "t": "복례와 머루댁이 동시에 나를 보았다. 둘이 짠 것도 아닌데 눈길이 똑같았다."}, {"s": "q:sn_bokrye", "t": "조사원, 불씨 고개에 가서 화덕 쌓을 흙과 돌을 좀 해다 주구려. 새 화덕 첫 불에 쓸 정련 숯도 조금. 고개 숯가마 둘레에 묵은 숯이 굴러다닐 거요. 땔감은 손님이 해 와도 불은 내 불이니, 불은 걱정 마시구려."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_1', 2, '불씨를 옮기는 손', '불씨 고개에서 채집한다, 불씨 고개에서 정련 숯을(를) 모은다', '{"at": ["ember_village"], "tasks": [{"t": "gather", "r": ["ember_pass"], "n": 4}, {"t": "gather", "items": ["charcoal"], "r": ["ember_pass"], "n": 3}]}'::jsonb, '[{"s": null, "t": "붉은 흙과 차돌, 숯을 지고 돌아오자 공동 부엌 앞에 마을 아이들이 모여 있었다. 머루댁이 아이들을 줄 세워 흙 이기는 일을 시키고 있었다."}, {"s": "q:sx_md_meoru", "t": "발로 꾹꾹 밟아! 춤추라는 게 아니야, 밟으라고!"}, {"s": null, "t": "아이들이 깔깔거리며 흙을 밟았다. 흙이 발가락 사이로 삐져나올 때마다 비명 같은 웃음이 터졌다. 나는 이긴 흙을 한 덩이씩 받아 무너진 자리에 화덕 벽을 쌓았고, 복례는 내가 쌓은 벽 틈마다 차돌을 박았다."}, {"s": null, "t": "해가 기울 무렵 화덕 벽이 무릎 높이까지 올라왔다. 대장간 쪽에서 젊은 대장장이 하나가 쇠로 된 솥걸이를 들고 왔다. 쇠불이었다."}, {"s": "q:sn_soebul", "t": "어멈, 솥걸이요. 예전 것은 녹이 슬어서…… 창고에 있던 걸 닦아 왔어요."}, {"s": null, "t": "쇠불은 솥걸이를 화덕 위에 걸쳐 놓고는 금세 돌아섰다. 복례가 쇠불의 등을 보다가 나를 돌아보았다."}, {"s": "q:sn_bokrye", "t": "새로 두드린 게 아니라 닦아 온 거라는구려. 저 애가 망치를 안 든 지 오래요. 장군님 가신 뒤로."}, {"s": null, "t": "복례는 그 말만 하고 더 잇지 않았다. 대신 치마폭 곁의 불씨 단지를 두 손으로 들어 올렸다."}, {"s": "q:sn_bokrye", "t": "이제 옮기리다. 조사원, 바람 쪽에 좀 서 주구려."}, {"s": null, "t": "나는 바람이 불어오는 쪽에 서서 소매를 펼쳤다. 복례가 단지 뚜껑을 열고 숯 덩이째 불씨를 집게로 집어 올렸다. 그 순간 고개 쪽에서 바람이 휘익 불어왔다."}, {"s": null, "t": "불씨가 바람에 깜빡깜빡 흔들렸다. 붉은빛이 콩알만 하던 것이 좁쌀만큼 줄어들었다. 아이들이 흙 밟던 발을 멈추고 숨을 죽였다. 머루댁이 저도 모르게 두 손을 모았다."}, {"s": "q:sn_bokrye", "t": "쉿…… 쉿, 서러워 마라. 새 집이다. 새 집이야."}, {"s": null, "t": "복례가 불씨를 화덕 바닥 마른 숯 위에 내려놓고 두 손으로 둥글게 감쌌다. 나는 복례의 손 위로 몸을 숙여 바람을 막았다. 숨 몇 번을 쉬는 동안 아무도 움직이지 않았다."}, {"s": null, "t": "바람이 잦아들었다. 손 틈으로 불씨가 다시 붉게 부풀었고, 곁의 숯에 불이 옮겨붙어 타닥타닥 소리를 냈다. 아이들이 와 하고 소리를 질렀다."}, {"s": "q:sx_md_meoru", "t": "됐다! 됐어! 어멈, 됐어!"}, {"s": null, "t": "복례가 손을 거두고 한참 화덕 속을 들여다보았다. 불빛에 비친 얼굴이 젖어 있었다. 연기 때문은 아니었다."}, {"s": "q:sn_bokrye", "t": "성에서 들고 나오던 밤에도 이렇게 바람이 불었소. 그때 우리 어머니가 지금 조사원처럼 바람 쪽에 서 주셨지. 서른 해 만에 처음으로 남의 등 뒤에서 불을 옮겨 보는구려."}, {"s": null, "t": "복례가 솥걸이에 솥을 걸고 소매를 걷었다. 목소리가 금세 부엌 어멈 목소리로 돌아왔다."}, {"s": "q:sn_bokrye", "t": "자, 첫 솥은 갈치조림이오. 그런데 내 손은 불 지키느라 비어 있질 않으니, 조사원이 조려 주구려. 셋이오. 둘은 상점에 첫 물건으로 올리고, 하나는 대장간에 보낼 거요. 저 애가 요새 밥을 통 안 먹어."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_1', 3, '첫 솥', '갈치조림을(를) 만든다, 갈치조림을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "craft", "items": ["hairtail_braise"], "n": 3}], "give": {"hairtail_braise": 3}}'::jsonb, '[{"s": null, "t": "갈치조림 세 그릇을 내려놓자 공동 부엌에 매콤하고 들큼한 냄새가 가득 찼다. 아이들이 그릇 둘레에 우르르 몰려들었다가 머루댁에게 뒷덜미를 잡혀 끌려 나갔다."}, {"s": "q:sx_md_meoru", "t": "너희 건 저녁이야! 저건 상점 거라고!"}, {"s": null, "t": "복례가 두 그릇을 상점 빈 궤짝에 넣었다. 상점지기가 궤짝을 진열대에 올리고, 어유 등잔 궤짝 옆에 나란히 놓았다. 상점지기가 등잔 하나에 불을 붙이자 진열대가 노랗게 밝아졌다."}, {"s": "q:sn_bokrye", "t": "이제 상점에 내놓을 게 다 갖춰졌소. 몫을 넘겨준 사람들 덕이오. 남명은 받은 건 꼭 갚는 땅이니, 이 부엌에서 조리는 갈치조림 한 그릇 한 그릇이 다 그 갚음이라 여기구려."}, {"s": null, "t": "남은 한 그릇을 들고 나는 복례를 따라 대장간으로 갔다. 대장간은 조용했다. 풀무에는 먼지가 앉아 있었고, 모루 위에는 아무것도 없었다. 벽에는 두 동강 난 칼 한 자루가 걸려 있었다."}, {"s": null, "t": "쇠불이 모루 앞 걸상에 앉아 빈손을 내려다보고 있었다. 복례가 그 앞에 그릇을 내려놓았다."}, {"s": "q:sn_bokrye", "t": "먹어라. 첫 솥이다. 새 화덕에서 조린 거야."}, {"s": null, "t": "쇠불이 그릇을 내려다보다가 고개를 저었다."}, {"s": "q:sn_soebul", "t": "어멈, 저는 배가 안 고파서……."}, {"s": null, "t": "복례가 쇠불의 손에 젓가락을 쥐여 주었다."}, {"s": "q:sn_bokrye", "t": "배는 안 고파도 입은 있잖니. 조사원이 조린 거다. 남이 해 온 밥을 남기는 건 남명 예법이 아니야."}, {"s": null, "t": "쇠불이 앞치마 끈을 고쳐 매고 젓가락을 들었다. 갈치 한 점을 입에 넣고 한참 씹다가, 또 한 점을 넣었다. 그릇이 비는 동안 쇠불은 한 번도 고개를 들지 않았다."}, {"s": "q:sn_soebul", "t": "……맵네요. 장군님은 매운 걸 못 드셨는데."}, {"s": null, "t": "쇠불이 빈 그릇을 내려놓고 벽에 걸린 칼을 올려다보았다. 복례는 그 눈길을 따라 칼을 보다가 아무 말 없이 빈 그릇을 챙겨 들었다."}, {"s": "q:sn_soebul", "t": "조사원님, 조림 잘하시네요. 장군님도 매운 것만 아니면 좋아하셨을 거예요."}, {"s": null, "t": "나는 다음엔 덜 맵게 조리겠다고 했다. 쇠불이 처음으로 입꼬리를 조금 올렸다."}, {"s": null, "t": "대장간을 나서며 복례가 나에게만 들리게 말했다. 화덕 불빛이 저 멀리 공동 부엌에서 붉게 새어 나오고 있었다."}, {"s": "q:sn_bokrye", "t": "한 그릇 다 비웠으니 반은 된 거요. 나머지 반은 저 애가 망치를 들어야 되지. 그날도 조사원이 와 주면 좋겠구려. 그날은 내가 곱절로 조려 줄 테니."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_south_2', 'side', '뒷이야기·잔불촌', '쇠불의 대장간', '사업이 둘째 단계를 채우자 남명 땅 파수막마다 쇠 화로를 놓고 파수꾼 방패에 쇠테를 두르기로 한다. 장무현이 떠난 뒤 망치를 들지 못하던 대장장이 쇠불이, 장무현이 망치를 들 때 집게를 잡아 준 조사원과 함께 다시 풀무를 돌린다.', 'ember_village', 50, '{mdq_17,ep_south_1}'::text[], null, 1546, '[]'::jsonb, true, null, null)
