update public.world_quests set open_req = '{"project": "f:southern_remnant", "stage": 2}'::jsonb where quest_id = 'ep_south_2';
delete from public.world_quest_steps where quest_id = 'ep_south_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_2', 1, '금 간 방패', '금 간 방패', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "공동 부엌 화덕을 놓고 몇 주가 흘렀다. 그사이 화덕 연기는 날마다 올랐지만 대장간 굴뚝은 여전히 식어 있었다."}, {"s": null, "t": "대장간 앞에 남명 파수꾼 하나가 방패를 들고 서 있었다. 나무 방패 가장자리가 쩍 갈라져 있었고, 쇠테가 반쯤 떨어져 덜렁거렸다."}, {"s": "q:md_south_watch", "t": "쇠불, 이거 좀 봐 줘. 어젯밤 고개에서 숯검정 개미 떼를 막다가 이렇게 됐어. 주혈 광산 쪽 파수막은 더 해. 화로가 꺼져서 다들 밤새 이만 덜덜 떨었다고."}, {"s": null, "t": "쇠불은 대장간 안 모루 앞에 앉아 있었다. 파수꾼이 내민 방패를 받아 들고 갈라진 자리를 손끝으로 쓸었지만, 망치에는 손을 대지 않았다."}, {"s": null, "t": "대장간 문간에 무녀 소이가 서 있었다. 소이가 나를 알아보고 고개를 숙였다."}, {"s": "southern_remnant:soi", "t": "조사원님, 마침 와 주셨사옵니다. 거점 사업이 둘째 단계를 채웠사온데, 그 몫으로 남명 땅 파수막마다 쇠 화로를 하나씩 놓고, 파수꾼 방패마다 새 쇠테를 두르기로 하였사옵니다. 몸을 녹일 불과 덜 다칠 방패이옵니다."}, {"s": "southern_remnant:soi", "t": "불씨 고개, 재의 해안, 주혈 광산, 혈엽림, 흑조 균열, 무명 고도까지이옵니다. 몫을 넘겨준 분들의 셈으로 마련한 쇠와 숯은 다 모였사옵니다. 다만……."}, {"s": null, "t": "소이가 말끝을 흐리며 대장간 안을 보았다. 쇠불이 방패를 무릎에 올려놓은 채 움직이지 않고 있었다."}, {"s": "southern_remnant:soi", "t": "두드릴 사람이 망치를 들지 못하고 있사옵니다."}, {"s": null, "t": "쇠불이 그 말을 들었는지 고개를 들었다. 앞치마 끈을 풀었다가 다시 맸다. 그러고는 제 오른손을 펴 보였다. 손가락이 가늘게 떨리고 있었다."}, {"s": "q:sn_soebul", "t": "조사원님, 부끄럽지만 이렇습니다. 장군님 가신 날부터 망치만 쥐면 손이 떨려요. 장군님이 칼 말고 쟁기를 벼리라 하신 뒤로 저는 늘 장군님 말씀을 듣고 두드렸거든요. 이제 말씀해 주실 분이 없으니까…… 무얼 두드려야 할지를 모르겠어요."}, {"s": null, "t": "쇠불이 벽에 걸린 두 동강 난 칼을 올려다보았다. 칼자루의 망국 군부 문장이 닳아 있었다."}, {"s": "q:sn_soebul", "t": "그래도 쇠가 눈앞에 있으면 해 볼게요. 쇠가 없다는 핑계까지 있으면 저는 영영 못 들 것 같아서요. 창고 쇠는 화로 짜는 데 다 들어가요. 방패 쇠테는 주혈 광산 월철이라야 바닷바람에 안 삭고요."}, {"s": null, "t": "모루 곁에 서 있던 파수꾼이 방패를 고쳐 들며 거들었다."}, {"s": "q:md_south_watch", "t": "광산 갱도에 원령이 또 끓어서 광부들이 못 들어간대. 쇠를 캐려면 그것들부터 쫓아야 해."}, {"s": null, "t": "쇠불이 방패를 모루 옆에 세워 두고 나를 보았다. 떨리는 손을 앞치마에 문질러 닦고 있었다."}, {"s": "q:sn_soebul", "t": "조사원님, 주혈 광산에 다녀와 주시겠어요? 갱도 원령을 쫓고 월철 광석을 좀 캐다 주세요. 그동안 저는 풀무 먼지라도 털어 놓을게요. 그건 손이 떨려도 할 수 있으니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_2', 2, '집게를 잡은 손', '주혈 광산의 요괴를 물리친다, 주혈 광산에서 월철 광석을(를) 모은다', '{"at": ["ember_village"], "tasks": [{"t": "win", "r": ["crimson_mine"], "n": 6}, {"t": "gather", "items": ["ore"], "r": ["crimson_mine"], "n": 4}]}'::jsonb, '[{"s": null, "t": "월철 광석 자루를 대장간 바닥에 내려놓자 쇠불이 벌떡 일어섰다. 풀무에 앉았던 먼지는 말끔히 털려 있었고, 화덕에는 숯이 가득 들어 있었다."}, {"s": null, "t": "쇠불이 광석 하나를 들어 불빛에 비춰 보았다. 붉은 결이 굵게 박힌 좋은 쇠였다."}, {"s": "q:sn_soebul", "t": "좋은 쇠예요. 광부들이 들으면 샘내겠어요."}, {"s": null, "t": "쇠불이 풀무 손잡이를 내게 내밀었다. 나는 손잡이를 잡고 밀었다 당겼다. 쉭, 쉭 바람이 들어갈 때마다 화덕 숯이 붉게 일어섰다. 쇠불이 떨어져 덜렁거리던 파수꾼 방패의 헌 쇠테를 떼어 불 속에 넣었다."}, {"s": "q:sn_soebul", "t": "새 쇠테를 감기 전에 헌 것부터 펴 볼게요. 손이 기억하는지 보려고요."}, {"s": null, "t": "헌 쇠테가 불 속에서 붉게 달아올랐다. 쇠불이 집게로 집어 모루에 올리려다 멈칫했다. 오른손에 망치를 쥐니 왼손의 집게가 떨렸고, 쇠테가 모루 위에서 자꾸 미끄러졌다."}, {"s": null, "t": "나는 풀무를 놓고 쇠불 곁으로 가 집게를 받아 쥐었다. 달군 쇠테를 모루 위에 단단히 붙들었다. 쇠불이 나를 돌아보았다."}, {"s": "q:sn_soebul", "t": "……장군님이 그러셨어요. 재의 바다 일 때 등대 쇠틀을 벼리시면서, 조사원 하나가 집게를 잡아 줬다고요. 팔이 하나라 쇠를 붙들 손이 없었는데 손이 잘 맞더라고요. 그게 조사원님이셨죠? 그 말씀을 하시면서 웃으셨어요. 장군님이 웃는 걸 그날 처음 봤어요."}, {"s": null, "t": "쇠불이 망치를 들어 올렸다. 첫 망치는 쇠테 옆 모루를 땅 하고 때렸다. 불똥이 튀었다. 쇠불이 이를 악물고 다시 들어 올렸다."}, {"s": null, "t": "둘째 망치가 쇠테 한가운데에 땅 하고 떨어졌다. 셋째, 넷째 망치가 땅, 땅, 땅 이어졌다. 망치 소리가 점점 고르게 박자를 찾았다. 쇠불의 손은 더는 떨리지 않았다."}, {"s": null, "t": "대장간 문간에 하나둘 사람들이 모여들었다. 망치 소리를 듣고 달려온 마을 사람들이었다. 복례가 앞치마 차림 그대로 사람들 사이에 서 있었다."}, {"s": "q:sn_bokrye", "t": "들리오? 대장간에서 소리가 나오."}, {"s": null, "t": "쇠불이 펴진 쇠테를 물통에 넣었다. 치이익, 하얀 김이 확 올라왔다. 김 너머로 쇠불의 얼굴이 젖어 있었다. 땀인지 눈물인지 알 수 없었다."}, {"s": "q:sn_soebul", "t": "손이 기억하네요. 장군님은 안 계신데, 손이 장군님 박자를 기억해요."}, {"s": null, "t": "쇠불이 앞치마로 얼굴을 쓱 닦고 광석 자루를 내려다보았다. 목소리가 대장장이 목소리로 돌아와 있었다."}, {"s": "q:sn_soebul", "t": "이제 새 쇠테를 감을 차례예요. 파수막 화로 몸통도 두드려야 하고요. 풀무는 쇠테 달구는 데 계속 써야 하니, 광석을 주괴로 녹이는 건 조사원님이 해 주시겠어요? 넷이면 쇠테 열둘에 화로 넷이 나와요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_2', 3, '쟁기 날과 쇠테', '월철 주괴을(를) 만든다, 월철 주괴을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "craft", "items": ["iron_ingot"], "n": 4}], "give": {"iron_ingot": 4}}'::jsonb, '[{"s": null, "t": "월철 주괴 넷을 넘기자 쇠불은 사흘 동안 대장간을 떠나지 않았다. 망치 소리가 새벽부터 밤까지 잔불촌 골목을 울렸다. 복례가 끼니마다 화덕에서 밥을 날라 왔고, 쇠불은 이번엔 한 그릇도 남기지 않았다."}, {"s": null, "t": "사흘째 저녁, 대장간 앞에 새 쇠테를 두른 방패 열둘과 작은 쇠 화로 넷이 나란히 놓였다. 쇠테는 붉은 결이 고르게 펴져 있었고, 화로마다 바람구멍이 송송 뚫려 있었다."}, {"s": null, "t": "남명 파수꾼이 방패 하나를 집어 팔에 끼고 주먹으로 두드려 보았다. 퉁, 묵직한 소리가 났다."}, {"s": "q:md_south_watch", "t": "이거면 개미 떼가 아니라 들소가 받아도 안 갈라지겠다. 화로는 오늘 밤 고개 파수막부터 놓을게. 밤새 불 곁에서 손 녹이며 서 있을 수 있겠어."}, {"s": null, "t": "파수꾼이 방패를 내려놓고 쇠불의 어깨를 툭 쳤다. 쇠불이 비틀하자 파수꾼이 껄껄 웃었다."}, {"s": "q:md_south_watch", "t": "대장장이가 이렇게 말라서 어디 쓰나. 어멈 밥 좀 더 먹어라. 망치 소리 사흘 들으니까 마을이 다 살아난 것 같더라."}, {"s": null, "t": "소이가 화로 하나를 들여다보고 바람구멍에 손을 대 보았다. 소이의 얼굴에 웃음 비슷한 것이 스쳤다."}, {"s": "southern_remnant:soi", "t": "파수막마다 이 화로가 놓이면, 밤을 지키는 이가 덜 춥고 덜 다치겠사옵니다. 몫을 넘겨준 분들께 소녀가 노래로 갚겠사옵니다."}, {"s": null, "t": "쇠불이 벽에서 두 동강 난 칼을 내렸다. 나는 쇠불이 그 칼을 녹이려는 줄 알고 숨을 들이켰다. 쇠불은 칼을 모루 위에 올려놓지 않았다. 칼을 다시 벽에 걸고, 그 바로 아래에 무언가를 하나 더 걸었다."}, {"s": null, "t": "새로 두드린 쟁기 날이었다. 날 끝이 불빛을 받아 반짝였다."}, {"s": "q:sn_soebul", "t": "장군님이 그러셨어요. 그 쇠로 칼을 벼리지 말고 아이들 쟁기 날로 쓰라고. 나라는 칼로 지켜지지 않았다고, 남은 건 밭을 가는 손이라고요. 그때는 그 말씀이 서운했는데, 이제 알 것 같아요."}, {"s": "q:sn_soebul", "t": "방패 쇠테는 밭 가는 손을 지키는 거예요. 화로는 그 손을 녹이는 거고요. 칼은 이제 장군님 걸로 두고, 저는 이걸 두드릴게요."}, {"s": null, "t": "쇠불이 칼과 쟁기 날 앞에서 허리를 깊이 숙였다. 문간에 모여 있던 마을 사람들도 따라 고개를 숙였다. 복례가 소매로 눈가를 훔쳤다."}, {"s": null, "t": "고개를 든 쇠불이 나를 보고 앞치마 끈을 고쳐 맸다. 쑥스러운 듯 웃고 있었다."}, {"s": "q:sn_soebul", "t": "조사원님, 집게 잡아 주셔서 고마웠어요. 다음에 또 오시면 조사원님 장비도 봐 드릴게요. 값은 안 받고요. 장군님 몫까지 갚아야 하니까요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_south_3', 'side', '뒷이야기·잔불촌', '불씨 고개 길', '사업이 셋째 단계를 채우자 잔불촌에서 불씨 고개·재의 해안·주혈 광산으로 가는 지름길이 다져진다. 보름을 맞아 잔불촌에 온 갈매와 서하람이 새 길로 장무현의 무덤에 들러 하룻밤을 보낸다.', 'ember_village', 50, '{mdq_17,ep_south_2}'::text[], null, 1547, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:southern_remnant", "stage": 3}'::jsonb where quest_id = 'ep_south_3';
delete from public.world_quest_steps where quest_id = 'ep_south_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_3', 1, '보름날 아침', '보름날 아침', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "늦여름이었다. 잔불촌 어귀 돌담 밖으로 새 길 하나가 고개 쪽으로 곧게 뻗어 있었다. 길가마다 쇠 화로가 놓인 파수막이 서 있었고, 화로 연기가 길을 따라 가늘게 올라갔다."}, {"s": null, "t": "마을 큰 화로 앞에서 갈매가 부지깽이로 숯을 고르고 있었다. 갈매 곁에는 서하람이 담요를 무릎에 덮고 앉아 화로 쪽으로 손바닥을 펴고 있었다. 보름이라 갈매가 관성대에서 내려온 날이었다."}, {"s": "southern_remnant:galmae", "t": "{이름}, 왔어? 마침 잘 왔어. 오늘 할배한테 갈 거야."}, {"s": null, "t": "갈매가 부지깽이로 어귀 쪽 새 길을 가리켰다. 서하람이 그 소리를 따라 고개를 돌렸다."}, {"s": "q:r71_seoharam", "t": "길이 새로 났대요. 소이 님이 그러는데, 고개까지 반나절이면 간대요. 전에는 꼬박 하루였잖아요."}, {"s": null, "t": "화로 뒤에서 소이가 걸어 나왔다. 소이가 새 길 쪽을 보며 두 손을 가슴께에 모았다."}, {"s": "southern_remnant:soi", "t": "거점 사업이 셋째 단계를 채웠사옵니다. 잔불촌에서 불씨 고개, 재의 해안, 주혈 광산, 구등대 군도, 혈엽림, 흑조 균열까지 길을 다지고 파수막마다 불을 놓았사옵니다. 남명 분들은 이 길로 가시면 노정패를 내지 않으셔도 되고, 걸음도 훨씬 줄어드옵니다.", "fac": "southern_remnant", "spec": 1, "grp": 1}, {"s": "southern_remnant:soi", "t": "거점 사업이 셋째 단계를 채웠사옵니다. 잔불촌에서 불씨 고개, 재의 해안, 주혈 광산, 구등대 군도, 혈엽림, 흑조 균열까지 길을 다지고 파수막마다 불을 놓았사옵니다. 몫을 넘겨 도와주신 다른 땅 분들 덕도 크옵니다.", "fac_not": "southern_remnant", "spec": 2, "grp": 1}, {"s": null, "t": "갈매가 부지깽이를 화로에 걸쳐 두고 일어섰다. 갈매는 새 길을 한참 노려보다가 입을 비죽 내밀었다."}, {"s": "southern_remnant:galmae", "t": "할배는 이 길을 한 번도 못 걸어 봤어. 할배 살아 있을 땐 고개 가려면 바위를 타야 했거든. 이제야 길이 나다니."}, {"s": null, "t": "서하람이 갈매의 소매를 찾아 쥐었다. 갈매가 소매를 빼지 않고 서하람의 손을 제 팔에 걸어 주었다."}, {"s": "q:r71_seoharam", "t": "그러니까 오늘 걸어서 말씀드려요. 길이 났다고요. 관측 기록처럼요. 오늘 날씨, 오늘 길."}, {"s": null, "t": "그때 고개 쪽 새 길에서 남명 파수꾼 하나가 뛰어왔다. 숨을 헐떡이며 소이 앞에 멈춰 섰다."}, {"s": "q:md_south_watch", "t": "무녀님, 고개 셋째 굽이 파수막 화로가 엎어졌습니다! 불티 도깨비들이 화로 불을 뜯어 먹겠다고 몰려들어서요. 쇠불이 새로 두드린 화로인데……."}, {"s": null, "t": "갈매가 허리춤의 칼을 고쳐 찼다. 서하람을 돌아보며 목소리를 낮췄다."}, {"s": "southern_remnant:galmae", "t": "잠꾸러기, 너는 내 뒤에서 걸어. 돌 하나 있으면 말해 줄게. {이름}, 고개 가는 길에 그것들부터 치우자. 할배 무덤 가는 길이 불티로 시끄러우면 할배가 싫어해."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_3', 2, '소나무 아래 두 봉분', '불씨 고개에 간다, 불씨 고개의 요괴를 물리친다', '{"at": ["ember_pass"], "tasks": [{"t": "travel", "r": ["ember_pass"], "n": 1}, {"t": "win", "r": ["ember_pass"], "n": 6}]}'::jsonb, '[{"s": null, "t": "불티 도깨비들을 쫓아내고 엎어진 화로를 바로 세우자 고갯마루가 조용해졌다. 늙은 소나무 아래 작은 봉분 둘이 나란히 있었다. 하나는 장무현 어머니의 무덤이었고, 하나는 장무현의 옷과 신을 묻은 봉분이었다."}, {"s": null, "t": "봉분 위에는 솔잎이 수북이 덮여 있었다. 누가 다녀갔는지 봉분 앞에 국수 한 그릇이 놓여 있었다. 국수는 말라 있었다."}, {"s": null, "t": "갈매가 서하람을 이끌어 봉분 앞에 앉혔다. 서하람이 손을 뻗어 솔잎을 더듬었다. 손끝이 마른 국수 그릇에 닿자 서하람이 고개를 갸웃했다."}, {"s": "q:r71_seoharam", "t": "그릇이 있어요. 누가 다녀갔나 봐요."}, {"s": null, "t": "갈매가 그릇을 들여다보고 픽 웃었다. 웃음 끝이 조금 떨렸다."}, {"s": "southern_remnant:galmae", "t": "복례 어멈이야. 굵게 썬 걸 보니까. 할배 국수는 어멈이 제일 잘 흉내 내."}, {"s": null, "t": "갈매가 마른 국수 그릇을 옆으로 치우고 봉분 앞에 털썩 앉았다. 나는 조금 떨어져 앉아 고개 아래쪽 길을 살폈다."}, {"s": "southern_remnant:galmae", "t": "할배. 길이 났어. 잔불촌에서 여기까지 반나절이야. 파수막마다 쇠불이 두드린 화로가 있어. 쇠불이 다시 망치를 들었대. 할배가 말한 쟁기 날도 두드렸고."}, {"s": "southern_remnant:galmae", "t": "그리고 어멈 화덕도 새로 놓았어. 불씨는 안 꺼졌어. 할배가 걱정할까 봐 말해 주는 거야."}, {"s": null, "t": "갈매는 봉분에 대고 한참 말을 멈췄다. 솔잎 사이로 바람이 지나가며 쏴아 소리를 냈다. 서하람이 그 소리 쪽으로 얼굴을 들었다."}, {"s": "q:r71_seoharam", "t": "바람이 소나무를 지나가요. 갈매 씨, 장군님도 이 소리를 들으셨을까요?"}, {"s": null, "t": "갈매가 소나무 꼭대기를 올려다보며 짧게 대답했다."}, {"s": "southern_remnant:galmae", "t": "들었겠지. 할배 어릴 때부터 있던 나무래."}, {"s": null, "t": "해가 고개 너머로 넘어가자 갈매가 봉분 앞에 작은 불을 피웠다. 그러고는 무릎을 끌어안고 앉아 나를 돌아보았다."}, {"s": "southern_remnant:galmae", "t": "오늘은 여기서 잘 거야. 할배 곁에서 하룻밤. {이름}, 등은 네가 봐 줘. 밤엔 고개에 짐승이 다녀. 나는 할배랑 얘기 좀 더 할게."}, {"s": null, "t": "나는 고개를 끄덕이고 불을 등지고 앉았다. 서하람이 담요를 펴서 갈매의 어깨와 제 어깨를 함께 덮었다."}, {"s": "q:r71_seoharam", "t": "저는 그냥 들을게요. 두 사람 얘기요. 관측은 원래 듣는 거니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_3', 3, '고개에서 보이는 바다', '불씨 고개에서 쉰다', '{"at": ["ember_pass"], "tasks": [{"t": "rest", "r": ["ember_pass"], "n": 1}]}'::jsonb, '[{"s": null, "t": "밤이 깊었을 때 갈매가 봉분을 향해 「…장무현」 하고 작게 불렀다. 금빛 입김 한 가닥이 엉겨 봉분 위로 날아가 솔잎 사이 흙 속으로 스며들었다. 나는 손을 뻗어 그 자리를 짚어 보았다. 솔잎 밑 흙이 손바닥에 미지근했다."}, {"s": null, "t": "갈매는 그 뒤로 아무 말도 하지 않았다. 서하람이 갈매의 어깨에 기대 잠들었다. 졸려서 자는 잠이 아니라 고단해서 자는 잠이었다. 나는 불이 꺼지지 않게 밤새 장작을 넣었다."}, {"s": null, "t": "새벽녘 고갯마루에 안개가 걷혔다. 소나무 너머로 고개 아래가 훤히 내려다보였다. 새 길이 고개를 넘어 남쪽으로 구불구불 이어졌고, 그 끝에 잿빛 바다가 펼쳐져 있었다."}, {"s": null, "t": "갈매가 일어나 그 바다를 오래 보았다. 서하람이 갈매의 소매를 잡고 따라 일어섰다."}, {"s": "q:r71_seoharam", "t": "바다 냄새가 나요. 짠 바람이요. 저쪽이 재의 해안이죠?"}, {"s": null, "t": "갈매가 바다 쪽을 손가락으로 가리키다가, 서하람이 못 본다는 걸 떠올리고 그 손을 서하람의 손등에 얹었다."}, {"s": "southern_remnant:galmae", "t": "응. 새 길이 저기까지 이어졌어. 고개에서 해안까지 한 줄로."}, {"s": null, "t": "갈매가 소나무 둥치에 손바닥을 댔다. 목소리가 낮았다."}, {"s": "southern_remnant:galmae", "t": "할배가 나 어릴 때 이 고개를 업고 올라온 적이 있어. 바다를 보여 준다고. 근데 그날 안개가 껴서 아무것도 안 보였어. 나는 울었고, 할배는 다음에 또 오자고 했어. 다음은 끝내 없었지."}, {"s": null, "t": "서하람이 갈매의 손을 더듬어 찾아 쥐었다. 서하람은 아무 말도 하지 않고 바다 쪽으로 얼굴만 돌렸다."}, {"s": "southern_remnant:galmae", "t": "오늘은 보여. 바다가 다 보여, 할배. 잿빛인데 물결이 하얗게 부서져. 해가 그 위로 올라와."}, {"s": null, "t": "서하람이 갈매의 손을 꼭 쥔 채 고개를 끄덕였다."}, {"s": "q:r71_seoharam", "t": "저도 알 것 같아요. 짠 바람이 볼에 닿는 쪽이 바다죠. 장군님도 오늘은 보셨을 거예요."}, {"s": null, "t": "갈매가 콧방귀를 뀌다가 눈가를 손등으로 쓱 닦았다. 그러고는 새 길 가에 돌 하나를 주워 올려놓았다. 나도 그 위에 돌 하나를 얹었다. 서하람이 손끝으로 더듬어 셋째 돌을 얹었다."}, {"s": "southern_remnant:galmae", "t": "남명은 처음 난 길에 돌을 쌓아. 지나가는 사람이 하나씩 얹으라고. 할배가 못 걸어 본 길이니까, 이 돌탑은 할배 몫이야."}, {"s": null, "t": "갈매가 서하람의 팔을 제 팔에 걸고 새 길을 따라 고개를 내려가기 시작했다. 한 걸음 앞서 걸으며 서하람에게 일러 주었다."}, {"s": "southern_remnant:galmae", "t": "돌 하나, 발 앞에. 이제 평평해. 이 길은 계단이 없어. 쇠불 녀석이 계단을 다 깎아 놨대. 너 같은 잠꾸러기도 넘어지지 말라고."}, {"s": null, "t": "서하람이 갈매의 팔에 매달린 채 키득거렸다."}, {"s": "q:r71_seoharam", "t": "잠꾸러기는 넘어져도 자니까 괜찮아요."}, {"s": null, "t": "갈매가 서하람의 팔을 제 쪽으로 홱 당겼다. 입꼬리는 웃고 있었다."}, {"s": "southern_remnant:galmae", "t": "시끄러. 걸어."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_south_4', 'side', '뒷이야기·잔불촌', '꺼지지 않는 작은 화덕', '사업이 넷째 단계를 채우자 남명 비고에 「잔불 화덕」과 「불씨 두건」을 들이기로 한다. 복례와 쇠불이 작은 화덕을 빚고 머루댁이 화덕지기 두건을 깁는 동안, 소이는 재의 해안에서 옛 화덕 노래의 빠진 한 소절을 찾는다.', 'ember_village', 50, '{mdq_17,ep_south_3}'::text[], null, 1548, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:southern_remnant", "stage": 4}'::jsonb where quest_id = 'ep_south_4';
delete from public.world_quest_steps where quest_id = 'ep_south_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_4', 1, '빠진 한 소절', '빠진 한 소절', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "초가을 밤이었다. 소이의 불씨 창고는 공동 부엌 뒤 낮은 흙집이었다. 벽마다 재의 바다에서 건진 기와 조각과 깨진 그릇이 선반에 올려져 있었고, 물건마다 작은 종이 쪽지가 매달려 있었다."}, {"s": null, "t": "창고 마당에서는 복례와 쇠불이 쪼그려 앉아 흙을 빚고 있었다. 무릎 높이만 한 작은 화덕이었다. 쇠불이 쇠테를 대 보면 복례가 흙을 덧붙였다. 마루 끝에서는 머루댁이 불그스름한 천을 무릎에 펴고 바느질을 하고 있었다."}, {"s": "southern_remnant:soi", "t": "조사원님, 와 주셨사옵니다. 거점 사업이 넷째 단계를 채워 남명 비고에 새 물건 둘을 들이게 되었사옵니다. 작은 잔불 화덕과 불씨 두건이옵니다. 남명 분들은 공훈으로 들이실 수 있사옵니다.", "fac": "southern_remnant", "spec": 1, "grp": 1}, {"s": "southern_remnant:soi", "t": "조사원님, 와 주셨사옵니다. 거점 사업이 넷째 단계를 채워 남명 비고에 새 물건 둘을 들이게 되었사옵니다. 작은 잔불 화덕과 불씨 두건이옵니다. 남명 분들이 공훈으로 들이는 것이라 드리지는 못하오나, 몫을 넘겨 도와주신 덕은 잊지 않겠사옵니다.", "fac_not": "southern_remnant", "spec": 2, "grp": 1}, {"s": null, "t": "부엌 쪽에서 복례가 흙 묻은 손을 털며 일어섰다."}, {"s": "q:sn_bokrye", "t": "큰 화덕은 마을 밥을 짓고, 이건 집집마다 들고 갈 화덕이오. 파수막에도 두고 별채에도 두고. 불씨는 내 화덕에서 나눠 줄 거요."}, {"s": null, "t": "쇠불이 흙 묻은 손으로 쇠테를 화덕 허리에 둘러 보며 고개를 갸웃했다."}, {"s": "q:sn_soebul", "t": "어멈, 허리가 너무 굵어요. 이러면 쇠테가 안 맞아요."}, {"s": null, "t": "복례가 흙을 한 줌 더 덧붙이며 콧방귀를 뀌었다."}, {"s": "q:sn_bokrye", "t": "쇠테를 늘려라. 화덕은 배가 불러야 불이 안 꺼지는 법이다."}, {"s": null, "t": "머루댁이 바늘을 멈추고 천을 펼쳐 보였다. 이마를 감싸고 뒤로 묶는 두건이었다. 가장자리에 불씨 모양의 붉은 실 수가 놓여 있었다. 머루댁이 천을 털며 어깨를 으쓱했다."}, {"s": "q:sx_md_meoru", "t": "화덕지기는 앞머리를 태워 먹기 일쑤라서 이걸 썼어. 어멈도 젊을 땐 앞머리를 세 번 태웠대."}, {"s": null, "t": "복례가 흙 덩이를 탁 내려놓으며 머루댁을 돌아보았다."}, {"s": "q:sn_bokrye", "t": "네 번이다. 셈 좀 똑바로 해라."}, {"s": null, "t": "쇠불이 웃음을 참느라 쇠테를 떨어뜨렸다. 소이가 선반에서 기와 조각 하나를 내려 손바닥에 올렸다. 기와 안쪽에 칼끝으로 긁은 글씨가 있었다."}, {"s": "southern_remnant:soi", "t": "작은 화덕을 처음 피우는 날에는 화덕지기 노래를 불러야 하옵니다. 소녀가 아는 노래는 이 기와에 적힌 것까지이옵니다. 「불 지키는 이 잠들지 마오, 먼 길 간 이 돌아올 적에, 언 손 녹일 불 하나 남겨 두오.」"}, {"s": "southern_remnant:soi", "t": "그런데 이 노래는 한 소절이 더 있었다 하옵니다. 소녀의 스승님은 그 소절을 기와 두 장에 나눠 적어 두셨는데, 한 장은 재의 바다 난파선 둘레에 흘러가 버렸사옵니다. 그 뒤로 다들 그 소절 없이 불렀사옵니다."}, {"s": null, "t": "나는 그 기와를 찾으면 되겠냐고 물었다. 소이가 고개를 끄덕이다가 복례를 돌아보았다."}, {"s": "q:sn_bokrye", "t": "기와를 찾으러 가는 김에 바닷고기도 좀 낚아 오구려. 작은 화덕에 처음 올리는 건 바닷고기라야 하오. 그게 남명 법이야. 성을 버리고 이 바닷가로 내려온 밤에 처음 먹은 게 바닷고기였다니."}, {"s": null, "t": "소이가 기와를 품에 안고 내 쪽으로 한 걸음 다가왔다."}, {"s": "southern_remnant:soi", "t": "재의 해안 난파선 둘레를 살펴 주시옵소서. 기와 귀퉁이에 불씨 그림이 있사옵니다. 그 그림이 짝이옵니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_4', 2, '기와 두 장', '재의 해안에서 실마리를 찾는다, 재의 해안에서 낚시를 한다', '{"at": ["ember_village"], "tasks": [{"t": "clue", "r": ["ash_coast"], "n": 1}, {"t": "fish", "r": ["ash_coast"], "n": 2}]}'::jsonb, '[{"s": null, "t": "재의 해안 난파선 옆구리 모래 속에서 기와 조각 한 장을 찾아 들고 왔다. 귀퉁이에 불씨 그림이 긁혀 있었다. 낚은 바닷고기는 복례에게 넘겼다."}, {"s": null, "t": "소이가 두 기와를 나란히 맞대었다. 깨진 자리가 딱 들어맞았다. 소이가 등잔을 가까이 대고 새 기와의 글씨를 손끝으로 짚어 가며 읽었다."}, {"s": "southern_remnant:soi", "t": "「불 지키는 이 혼자 앉지 마오, 불 곁에 앉은 이 이름 불러 주오, 불은 부르는 소리로 타오르니.」"}, {"s": null, "t": "소이의 목소리가 끝에서 떨렸다. 소이가 기와를 무릎에 내려놓고 한참 아무 말도 하지 않았다."}, {"s": "southern_remnant:soi", "t": "……혼자 앉지 마오. 장군님께는 이 소절이 없었사옵니다. 장군님은 칠십 해를 그 걸상에 혼자 앉으셨사옵니다. 소녀가 이 소절을 진작 찾았더라면……."}, {"s": null, "t": "복례가 흙 묻은 손으로 소이의 어깨를 짚었다. 복례는 말을 고르는 사람처럼 잠시 입을 다물었다가 열었다."}, {"s": "q:sn_bokrye", "t": "진작 찾았으면 장군님이 들으셨을 것 같으냐. 그 고집에. 이제 찾았으니 이제부터 부르면 되오. 지금 걸상엔 돌아가며 앉잖니."}, {"s": null, "t": "머루댁이 바늘을 쥔 손으로 두건 천을 들어 보였다."}, {"s": "q:sx_md_meoru", "t": "그 소절, 두건 안쪽에 수놓을게. 화덕지기들이 이마에 대고 다니게."}, {"s": null, "t": "소이가 머루댁을 돌아보고 고개를 깊이 숙였다. 나는 맞붙인 기와를 천에 싸서 소이의 무릎 위에 올려 주었다."}, {"s": null, "t": "소이가 고개를 끄덕이며 눈가를 소매로 눌렀다. 그 사이 쇠불은 작은 화덕에 쇠테를 다 둘러 놓고, 쇠테 겉을 손바닥으로 쓸며 얼굴을 찌푸렸다."}, {"s": "q:sn_soebul", "t": "쇠테가 맨쇠라 바닷바람에 금방 삭겠어요. 바닷가 파수막에 둘 수도 있잖아요. 칠을 먹여야 해요. 칠액을 세 번 입히면 열 해는 안 삭아요."}, {"s": null, "t": "쇠불이 제 손을 내려다보았다. 쇳가루와 흙이 뒤범벅이었다."}, {"s": "q:sn_soebul", "t": "제 손으로 칠을 개면 쇳가루가 섞여서요. 조사원님, 칠액을 좀 개어 주시겠어요? 세 번 입힐 만큼요. 머루댁 두건이 다 될 때까지는 칠이 마를 거예요."}, {"s": null, "t": "머루댁이 바늘을 놀리며 코웃음을 쳤다."}, {"s": "q:sx_md_meoru", "t": "내 두건은 오늘 밤이면 다 돼. 칠보다 내가 빨라."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_4', 3, '화덕지기 노래', '칠액을(를) 만든다, 칠액을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "craft", "items": ["lacquer"], "n": 3}], "give": {"lacquer": 3}}'::jsonb, '[{"s": null, "t": "칠액을 넘기자 쇠불이 작은 화덕 쇠테에 세 번 칠을 입혔다. 밤이 이슥해서야 칠이 마르자 쇠테가 검붉게 윤이 났다. 머루댁의 두건도 다 지어져 마루 끝에 곱게 개어져 있었다."}, {"s": null, "t": "복례가 공동 부엌 화덕에서 불씨 한 점을 떼어 질그릇에 담아 왔다. 망국 때부터 지켜 온 그 불씨에서 나눈 불이었다. 복례가 작은 화덕 앞에 무릎을 꿇고 앉았다."}, {"s": "q:sn_bokrye", "t": "이 불은 나눠도 안 줄어드오. 나누면 둘이 되지. 서른 해를 지켜 보니 그렇더구려."}, {"s": null, "t": "복례가 불씨를 작은 화덕 숯 위에 내려놓았다. 숯에 불이 옮겨붙어 타닥타닥 소리를 냈다. 쇠불이 화덕 위에 작은 석쇠를 걸었고, 복례가 내가 낚아 온 바닷고기를 올렸다. 지글지글 기름이 숯에 떨어졌다."}, {"s": null, "t": "소이가 맞붙인 기와 두 장을 무릎에 올리고 노래를 불렀다. 낮고 느린 목소리였다."}, {"s": "southern_remnant:soi", "t": "「불 지키는 이 잠들지 마오, 먼 길 간 이 돌아올 적에, 언 손 녹일 불 하나 남겨 두오. 불 지키는 이 혼자 앉지 마오, 불 곁에 앉은 이 이름 불러 주오, 불은 부르는 소리로 타오르니.」"}, {"s": null, "t": "노래가 끝나자 복례가 「소이」 하고 소이의 이름을 불렀다. 금빛 입김 한 가닥이 엉겨 소이의 가슴께에 닿았다. 소이가 놀란 얼굴로 제 가슴께에 손을 얹었다."}, {"s": "q:sn_bokrye", "t": "노래에 그렇게 나오잖니. 불 곁에 앉은 이 이름을 불러 주라고."}, {"s": null, "t": "쇠불이 복례의 이름을 불렀고, 머루댁이 쇠불의 이름을 불렀다. 나는 머루댁의 이름을 불렀다. 작은 화덕 둘레로 금빛 실 몇 가닥이 엇갈려 날았다. 화덕의 불이 그 사이에서 환하게 타올랐다."}, {"s": null, "t": "머루댁이 개어 둔 두건을 집어 들고 복례 머리에 씌웠다. 복례가 손사래를 쳤지만 머루댁은 매듭을 단단히 묶었다."}, {"s": "q:sx_md_meoru", "t": "첫 두건은 어멈 거야. 앞머리 네 번 태운 사람 거."}, {"s": null, "t": "복례가 두건 매듭을 더듬어 보며 코웃음을 쳤다."}, {"s": "q:sn_bokrye", "t": "다섯 번이다. 하나는 너도 모르지."}, {"s": null, "t": "마당에 웃음이 터졌다. 쇠불이 석쇠에서 구운 생선을 한 점씩 떼어 사람들 손바닥에 올려 주었다. 내 손바닥에도 뜨거운 생선 한 점이 놓였다."}, {"s": "q:sn_soebul", "t": "첫 불에 구운 거예요. 바닷고기라 짭조름해요. 어멈 말로는 이걸 먹어야 화덕이 우리를 식구로 쳐 준대요."}, {"s": null, "t": "소이가 작은 화덕과 두건 하나를 불씨 창고 선반에 나란히 올려놓았다. 화덕 앞에 매단 쪽지에는 「잔불 화덕 · 불씨 두건 · 화덕지기 노래 두 소절」이라고 적혀 있었다."}, {"s": "southern_remnant:soi", "t": "이제 비고에 들일 물건이 갖춰졌사옵니다. 남명 분들이 이 화덕을 들여가시면, 그 불도 이 불에서 나눈 불이옵니다. 혼자 앉지 마시라는 소절도 함께 들려 보내겠사옵니다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_south_5', 'side', '뒷이야기·잔불촌', '불씨 무늬', '사업이 다섯째 단계를 채워 화덕 사업이 낙성한다. 잔불촌 굴뚝마다 연기가 오르고 마을 둘레에 화톳불이 늘어선다. 새로 다는 남명 깃발에 무엇을 넣을지 마을이 다투고, 보름이라 갈매가 화로 앞 걸상에 앉는 날이다.', 'ember_village', 50, '{mdq_17,ep_south_4}'::text[], null, 1549, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"project": "f:southern_remnant", "stage": 5}'::jsonb where quest_id = 'ep_south_5';
delete from public.world_quest_steps where quest_id = 'ep_south_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_5', 1, '깃발 다툼', '깃발 다툼', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "늦가을이었다. 잔불촌 골목마다 굴뚝 연기가 피어올랐다. 집집마다 화로를 새로 들였고, 마을 둘레 돌담을 따라 화톳불 자리가 줄지어 파여 있었다."}, {"s": null, "t": "큰 화로 앞 공터에서 마을 사람들이 둘로 갈려 목소리를 높이고 있었다. 공터 한가운데에 빈 깃대 자리 둘이 파여 있었고, 그 곁에 붉은 천 한 필이 펼쳐져 있었다."}, {"s": "q:sx_md_elder", "t": "남명 깃발이면 남명 문장을 넣어야지! 군부 문장 말일세. 장군님 칼자루에 새겨져 있던 그 문장."}, {"s": null, "t": "머루댁이 혀를 끌끌 차며 노인을 흘겨보았다."}, {"s": "q:sx_md_meoru", "t": "영감님, 그 문장 단 깃발 들고 나가서 나라가 망했어. 또 그걸 달자고?"}, {"s": null, "t": "노인이 지팡이로 땅을 탕 내리쳤다."}, {"s": "q:sx_md_elder", "t": "그럼 무얼 넣나! 빈 천을 달 텐가!"}, {"s": null, "t": "소이가 두 사람 사이에서 난처한 얼굴로 서 있었다. 나를 보자 소이가 반가운 듯 한 걸음 다가왔다."}, {"s": "southern_remnant:soi", "t": "조사원님, 마침 와 주셨사옵니다. 거점 사업이 다섯째 단계까지 다 찼사옵니다. 낙성 날이라 새 깃발을 달기로 하였는데, 깃발에 무엇을 넣을지로 이리되었사옵니다. 남명 분들 바탕 무늬도 오늘 그 깃발 무늬로 정해지옵니다.", "fac": "southern_remnant", "spec": 1, "grp": 1}, {"s": "southern_remnant:soi", "t": "조사원님, 마침 와 주셨사옵니다. 거점 사업이 다섯째 단계까지 다 찼사옵니다. 낙성 날이라 새 깃발을 달기로 하였는데, 깃발에 무엇을 넣을지로 이리되었사옵니다. 다른 땅 분이 보시기에는 우스우시겠사옵니다.", "fac_not": "southern_remnant", "spec": 2, "grp": 1}, {"s": null, "t": "쇠불이 대장간에서 나와 다툼을 듣다가 앞치마 끈을 고쳐 맸다. 쇠불이 망설이다 입을 열었다."}, {"s": "q:sn_soebul", "t": "저는 불씨를 넣었으면 해요. 어멈 화덕 불씨요. 망국 때부터 안 꺼진 거니까, 그게 남명이잖아요."}, {"s": null, "t": "노인이 쇠불을 돌아보며 버럭 소리를 질렀다."}, {"s": "q:sx_md_elder", "t": "불씨가 무슨 문장이야! 대장장이가 쇠나 두드리지!"}, {"s": null, "t": "쇠불이 움찔 물러섰다. 복례가 국자를 든 채 공동 부엌에서 나와 노인을 쏘아보았다."}, {"s": "q:sn_bokrye", "t": "영감님, 그 쇠나 두드리는 애가 영감님 집 화로를 두드려 줬소. 오늘 아침 그 화로에 밥 데워 드셨지?"}, {"s": null, "t": "노인이 헛기침을 하며 고개를 돌렸다. 소이가 한숨을 쉬고 빈 깃대 자리를 보았다."}, {"s": "southern_remnant:soi", "t": "무엇을 넣든 깃대부터 세워야 하옵니다. 화로 앞에 하나, 마을 어귀에 하나이옵니다. 오늘 저녁에는 갈매가 관성대에서 내려오니, 깃발은 그때 정하면 되겠사옵니다."}, {"s": "southern_remnant:soi", "t": "조사원님, 깃대로 쓸 부적목을 다듬어 주시겠사옵니까? 둘이옵니다. 쇠불이 깃대 끝 쇠갓을 두드리는 동안이면 되옵니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_5', 2, '갈매의 한 표', '가공 부적목을(를) 만든다, 가공 부적목을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "craft", "items": ["lumber"], "n": 2}], "give": {"lumber": 2}}'::jsonb, '[{"s": null, "t": "다듬은 가공 부적목 둘을 넘기자 쇠불이 깃대 끝에 쇠갓을 씌웠다. 마을 장정들이 깃대 하나를 화로 앞에, 하나를 마을 어귀에 세웠다. 깃대는 아직 비어 있었다."}, {"s": null, "t": "해 질 녘 마을 어귀에서 아이들이 소리를 질렀다. 갈매가 서하람의 손을 잡고 새 길을 따라 걸어오고 있었다."}, {"s": "q:md_child", "t": "갈매 누나 왔다! 하람 형도 왔다!"}, {"s": null, "t": "갈매가 어귀에 서서 빈 깃대를 올려다보았다. 공터에 펼쳐진 붉은 천과 둘로 갈린 사람들도 보았다. 갈매가 미간을 찌푸렸다."}, {"s": "southern_remnant:galmae", "t": "이게 다 뭐야. 왜 다들 화났어?"}, {"s": null, "t": "머루댁과 노인이 동시에 입을 열었다. 둘의 말이 뒤엉켜 무슨 소리인지 알 수가 없었다. 갈매가 손을 번쩍 들어 둘을 멈춰 세웠다."}, {"s": "southern_remnant:galmae", "t": "한 명씩. 아니, 둘 다 하지 마. {이름}, 네가 말해."}, {"s": null, "t": "나는 깃발에 군부 문장을 넣을지 불씨를 넣을지로 다투는 중이라고 했다. 갈매가 그 말을 듣고 한참 빈 깃대를 올려다보았다."}, {"s": null, "t": "서하람이 갈매의 소매를 살짝 당겼다. 서하람은 깃대 쪽으로 얼굴을 들고 있었다."}, {"s": "q:r71_seoharam", "t": "갈매 씨, 장군님이 칼을 어떻게 하라고 하셨는지 기억나요? 쇠불 씨가 그랬잖아요."}, {"s": null, "t": "쇠불이 그 말에 고개를 들었다. 갈매가 쇠불을 돌아보자, 쇠불이 앞치마 끈을 꽉 쥐고 대답했다."}, {"s": "q:sn_soebul", "t": "장군님이 그러셨어요. 나라는 칼로 지켜지지 않았다고. 남은 건 밭을 가는 손이라고요."}, {"s": null, "t": "공터가 조용해졌다. 노인이 헛기침을 하다 말고 입을 다물었다. 갈매가 붉은 천 앞에 쪼그려 앉아 천을 손바닥으로 쓸었다."}, {"s": "southern_remnant:galmae", "t": "할배 칼은 대장간 벽에 걸려 있어. 그걸로 됐어. 깃발엔 불씨를 넣어. 어멈 불씨. 할배가 칠십 해 동안 그 화로 앞에 앉아 있었던 것도 결국 불 때문이잖아."}, {"s": null, "t": "노인이 한참 깃대를 올려다보다가 지팡이로 땅을 톡 쳤다."}, {"s": "q:sx_md_elder", "t": "……장군님이 그리 말씀하셨다면야. 불씨로 하세. 그 대신 바느질은 머루댁이 하게. 내가 하면 불씨가 아니라 숯덩이가 될 테니."}, {"s": null, "t": "머루댁이 혀를 끌끌 차며 바늘을 꺼내 들었다. 마을 사람들 사이에서 웃음이 터졌다. 복례가 공동 부엌에서 국수 솥을 내다 걸었다."}, {"s": "q:sn_bokrye", "t": "낙성은 내일이오. 오늘 밤은 다들 화로 곁에서 자구려. 깃발은 밤새 짓고, 떡은 새벽에 찔 거요."}, {"s": null, "t": "그날 밤 큰 화로 앞 걸상에는 갈매가 앉았다. 보름이라 갈매가 앉는 날이었다. 갈매가 부지깽이로 숯을 고르자, 마을 사람들이 화로를 빙 둘러앉았다. 서하람이 갈매 발치에 담요를 펴고 앉으며 나를 돌아보았다."}, {"s": "q:r71_seoharam", "t": "{이름} 님도 여기 앉으세요. 화로 곁이요. 오늘 밤은 다들 여기서 잔대요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_south_5', 3, '깃발에 든 불씨', '잔불촌에서 쉰다', '{"at": ["ember_village"], "tasks": [{"t": "rest", "r": ["ember_village"], "n": 1}]}'::jsonb, '[{"s": null, "t": "화로 곁에서 하룻밤을 자고 나니 새벽녘이었다. 공동 부엌 화덕에서 떡 찌는 김이 무럭무럭 올랐다. 머루댁이 밤새 지은 깃발을 두 손으로 받쳐 들고 공터로 나왔다."}, {"s": null, "t": "붉은 바탕 한가운데에 불씨 하나가 수놓여 있었다. 불씨 둘레로 작은 불씨들이 둥글게 번져 나가는 무늬였다. 불이 나눠질수록 늘어나는 모양이었다."}, {"s": "q:sx_md_meoru", "t": "불씨 무늬야. 어멈 말대로 나누면 늘어나게 놨어. 밤을 꼬박 새웠더니 손가락이 다 불씨 같아."}, {"s": null, "t": "쇠불이 깃발을 깃대 줄에 매고 천천히 끌어 올렸다. 깃발이 깃대 끝에 닿는 순간 아침 바람이 불어왔다. 깃발이 펄럭 펼쳐졌다. 마을 어귀 깃대에도 같은 깃발이 올라갔다."}, {"s": null, "t": "돌담을 따라 파 둔 화톳불 자리에 아이들이 불을 하나씩 붙이며 뛰어다녔다. 화톳불이 마을을 빙 둘러 이어졌고, 굴뚝마다 연기가 깃발 쪽으로 기울며 올라갔다."}, {"s": null, "t": "서하람이 갈매의 소매를 잡고 고개를 들었다. 깃발 펄럭이는 소리를 듣는 얼굴이었다."}, {"s": "q:r71_seoharam", "t": "갈매 씨, 지금 어때요?"}, {"s": null, "t": "갈매가 깃발을 올려다보며 하나씩 짚어 말했다."}, {"s": "southern_remnant:galmae", "t": "연기가 많아. 굴뚝마다 다 올라와. 화톳불이 마을을 한 바퀴 둘렀어. 깃발은 빨개. 불씨가 한가운데 하나, 둘레에 잔뜩."}, {"s": null, "t": "서하람이 고개를 갸웃하며 물었다."}, {"s": "q:r71_seoharam", "t": "예뻐요?"}, {"s": null, "t": "갈매가 한참 깃발을 올려다보다 마지못해 대답했다."}, {"s": "southern_remnant:galmae", "t": "……예뻐."}, {"s": null, "t": "서하람이 입꼬리를 올리며 속삭였다."}, {"s": "q:r71_seoharam", "t": "그건 관측이 아니라 감상이네요."}, {"s": null, "t": "갈매가 서하람의 이마를 손가락으로 톡 튕겼다. 서하람이 웃음을 참으며 이마를 문질렀다."}, {"s": null, "t": "복례가 김이 오르는 떡 상자를 들고 나와 사람들에게 하나씩 나눠 주었다. 내 손에도 떡이 쥐여졌다. 뜨끈한 떡에서 쌀 냄새가 올라왔다."}, {"s": "q:sn_bokrye", "t": "낙성 떡이오. 몫을 넘겨준 사람들한테 돌리는 떡이지. 주괴 하나, 숯 한 덩이가 모여 화덕이 되고 대장간이 되고 길이 됐소. 그 몫을 낸 사람들이 다 먹어야 셈이 맞지."}, {"s": null, "t": "소이가 깃발 아래에 서서 화덕지기 노래를 불렀다. 마을 사람들이 둘째 소절부터 따라 불렀다. 「불 지키는 이 혼자 앉지 마오」 하는 대목에서 노래 소리가 가장 커졌다."}, {"s": null, "t": "노래가 끝나자 갈매가 걸상에서 일어섰다. 갈매가 걸상 앞에 서서 마을 사람들을 둘러보았다."}, {"s": "southern_remnant:galmae", "t": "다음 보름까지 이 걸상엔 누가 앉아?"}, {"s": null, "t": "아이들이 앞다투어 손을 들었다. 머루댁이 아이들 손을 하나씩 내려 주고 제 손을 들었다. 쇠불이 쭈뼛거리다 머루댁 뒤에서 손을 반쯤 들었다."}, {"s": "southern_remnant:galmae", "t": "머루댁 사흘, 쇠불 사흘, 어멈 사흘. 나머지는 영감님. 애들은 어른 무릎에 앉아. 혼자 앉지 말고."}, {"s": null, "t": "노인이 머루댁 흉내를 내며 혀를 끌끌 찼다."}, {"s": "q:sx_md_elder", "t": "내가 제일 길구먼. 늙은이 셈이 제일 넉넉하네."}, {"s": null, "t": "공터에 웃음이 와르르 터졌다. 갈매가 떡을 한 입 베어 물고 내 옆에 와 섰다. 펄럭이는 불씨 무늬 깃발을 올려다보며 갈매가 퉁명스럽게 말했다."}, {"s": "southern_remnant:galmae", "t": "할배 화로 연기가 오늘은 혼자 안 올라가. 굴뚝 연기랑 같이 올라가. {이름}, 다음 보름에도 와. 떡은 없어도 국수는 있어."}]'::jsonb, '{"gil": 400, "items": {"proj_rice_cake": 3}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_clerk', 'side', '뒷이야기·야행국 본부 정청', '서기관의 빈 책상', '명등청이 대청을 새로 꾸미며 옛 서기관 책상들을 치운다. 서당에서 아이들 글을 가르치는 연서희가 제 책상과 그 옆 출납관 책상을 정리하러 대청에 와서, 윤도한이 비워 둔 출납 장부 맨 끝 칸에 처음으로 한 줄을 적는다.', 'hq_yard', 50, '{mq_nine_gates,mdq_17,ep_x_doorkeeper}'::text[], null, 1550, '[]'::jsonb, true, null, null)
