update public.world_quests set open_req = null where quest_id = 'ep_x_clerk';
delete from public.world_quest_steps where quest_id = 'ep_x_clerk' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_clerk', 1, '깃발 일곱 아래', '깃발 일곱 아래', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "정청 대청 기둥마다 일곱 세력의 깃발이 걸려 있었다. 서리들이 낡은 책상을 마당으로 내가고 새 책상을 들여오느라, 대청 바닥에 끌린 자국이 어지러웠다."}, {"s": null, "t": "문수가 명단을 들고 대청 한가운데 서 있었다. 책상 하나가 나갈 때마다 명단에 줄을 그었는데, 맨 끝 두 줄에서 붓이 멈춰 있었다."}, {"s": "q:dh_munsu", "t": "조사원님, 마침 오셨거든요. 명등청에서 일곱 세력 분들 앉으실 자리를 만든대요. 옛 서기관 책상은 다 창고로 가고요. 근데 저 두 개가 문제거든요."}, {"s": null, "t": "문수가 붓 끝으로 창가 쪽을 가리켰다. 나란히 놓인 책상 둘이 먼지를 뒤집어쓰고 있었다. 하나는 붉은 인장 일 때 연서희가 앉던 책상이었고, 그 옆은 출납관 책상이었다."}, {"s": "q:dh_munsu", "t": "연 서기관님 책상엔 아직 물건이 그대로거든요. 서당으로 가시면서 안 치우셨어요. 옆 책상은요… 아무도 못 만지겠대요. 서리들이 그 의자에 앉으면 등이 서늘하대요."}, {"s": null, "t": "나는 윤도한이 맡긴 말을 떠올렸다. 연서희를 만나러 서당에 가 보겠다고 하자, 문수가 반가운 얼굴로 담장 문을 가리켰다."}, {"s": null, "t": "서당은 대청 뒤 담장 문 너머에 있었다. 창호지 너머로 아이들이 글자를 소리 내어 읽는 소리가 새어 나왔다. 마루에는 먹을 묻힌 한지가 빨래처럼 널려 있었다."}, {"s": null, "t": "연서희는 아이들 사이를 오가며 붓 쥔 손을 고쳐 잡아 주고 있었다. 걷어 올린 소매 아래 팔목에 먹 자국이 점점이 묻어 있었다. 연서희가 나를 보고 붓을 든 채 눈을 크게 떴다."}, {"s": "q:m_yeon", "t": "{이름} 님! 웬일이에요? 설마 목도리 빌리러 온 거 아니죠? 그건 이제 안 빌려줘요. 돌려받는 데 석 달 걸렸잖아요."}, {"s": null, "t": "나는 목도리가 아니라 말을 전하러 왔다고 했다. 봉연 아홉째 문 앞에서 들은 말을 그대로 옮겼다. 맨 끝 장, 운임 한 줄, 셈은 맞아야 한다는 말까지 옮겼다."}, {"s": null, "t": "연서희의 붓이 허공에서 멈췄다. 연서희는 한참 나를 보다가 웃음을 터뜨렸다. 웃음 끝에 눈가가 젖어 들었다."}, {"s": "q:m_yeon", "t": "운임이요? 문 안쪽에 갇혀서 한다는 말이 운임이에요? …그 사람다워요. 정말 그 사람다워요."}, {"s": null, "t": "연서희는 소매 끝으로 눈가를 훔치고 아이들 쪽을 돌아보았다. 아이 하나가 붓을 거꾸로 쥐고 있었다. 연서희가 다가가 붓을 바로 쥐여 주었다."}, {"s": "q:m_yeon", "t": "저 아직 봉연에 한 번도 못 내려갔어요. 문 앞에 서면 또 「출납관님」 하고 부를 것 같아서요. 그 사람은 이제 출납관이 아닌데."}, {"s": "q:m_yeon", "t": "책상은 오늘 저녁에 정리할게요. 애들 보내고요. 그 전에 하나만 부탁해도 돼요? 애들이 명등제 이름 쓰기 연습을 하느라 한지를 다 써 버렸어요. 부르는 이 칸에 제 이름을 적는 연습이요. 하루에 서른 번씩 쓰겠다고 우겨서요."}, {"s": null, "t": "마루 끝의 아이 하나가 마지막 한지를 들어 보였다. 앞뒤로 빽빽하게 이름이 적혀 더 쓸 자리가 없었다."}, {"s": "q:md_child", "t": "선생님, 이제 뒷면도 꽉 찼어요. 손바닥에 써도 돼요?"}, {"s": null, "t": "연서희가 아이의 이마를 손가락으로 톡 밀고 나를 돌아보았다."}, {"s": "q:m_yeon", "t": "손바닥은 안 돼. 엄마들이 나한테 와서 따진단 말이야. …{이름} 님, 다섯 장이면 오늘 수업은 버텨요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_clerk', 2, '비워 둔 자리', '한지을(를) 만든다, 한지을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "craft", "items": ["hp_hanji"], "n": 5}], "give": {"hp_hanji": 5}}'::jsonb, '[{"s": null, "t": "한지 다섯 장을 마루에 내려놓자 아이들이 우르르 몰려들었다. 연서희가 한 장씩 반으로 접어 나눠 주었다. 아이들은 받자마자 엎드려 이름을 적기 시작했다."}, {"s": null, "t": "창가 맨 앞자리 하나만 비어 있었다. 책상 위에는 붓 한 자루가 가지런히 놓여 있었다. 연서희가 그 자리를 손바닥으로 한 번 쓸었다."}, {"s": "q:m_yeon", "t": "다온이 자리예요. 흑련으로 따라가 버린 뒤로 비워 뒀어요. 그 애는 월하 씨 손을 놓을 생각이 없나 봐요. 대신 서신은 꼬박꼬박 와요."}, {"s": "q:m_yeon", "t": "맞춤법은 제가 빨간 먹으로 고쳐서 돌려보내요. 그럼 다음 서신에 「선생님 빨간 글씨 무서워요」라고 반듯하게 써 와요. 그건 안 틀려요."}, {"s": null, "t": "마루 끝에서 아까 그 아이가 손을 번쩍 들었다. 아이는 한지를 들고 쪼르르 내 앞으로 달려왔다."}, {"s": "q:md_child", "t": "조사원님은 이름이 뭐예요? 부르는 이 칸에 아무 이름이나 하나 적어 보래요. 선생님 이름은 다들 벌써 썼어요."}, {"s": null, "t": "나는 아이 앞에 쪼그려 앉아 내 이름을 한 글자씩 천천히 말해 주었다. 아이는 혀끝을 내밀고 한지 귀퉁이에 내 이름을 적었다. 마지막 획이 삐뚤게 미끄러졌다. 연서희가 아이 어깨 너머로 한지를 들여다보며 웃었다."}, {"s": "q:m_yeon", "t": "다온이도 처음엔 {이름} 님 이름을 그렇게 썼대요. 희수 서리가 그러더라고요. 마지막 획만 늘 미끄러졌다고."}, {"s": null, "t": "해가 기울자 아이들이 하나둘 돌아갔다. 연서희는 마루를 다 닦고 나서야 앞치마를 풀었다. 우리는 담장 문을 지나 대청으로 갔다."}, {"s": null, "t": "연서희가 먼저 제 책상 서랍을 열었다. 서랍 안에서 손때 묻은 붓과 마른 대나무 잎 몇 장이 나왔다. 맨 아래에는 낯익은 목도리 하나가 개켜져 있었다."}, {"s": "q:m_yeon", "t": "여기 있었네. 석 달 만에 돌려받은 그 목도리요. 다시는 안 빌려주려고 서랍 맨 밑에 숨겨 뒀었나 봐요."}, {"s": null, "t": "연서희가 목도리를 꺼내 내 목에 둘둘 감았다. 나는 빌려주는 거냐고 물었다. 연서희가 매듭을 꽉 당기며 고개를 저었다."}, {"s": "q:m_yeon", "t": "아뇨. 드리는 거예요. 그럼 돌려받을 일이 없잖아요."}, {"s": null, "t": "연서희가 옆 출납관 책상 앞에 섰다. 의자에 앉으려다 말고 의자 다리를 내려다보았다. 다리 하나가 짧아 의자가 기우뚱거렸고, 책상도 한쪽 귀가 내려앉아 있었다."}, {"s": null, "t": "문수가 기둥 뒤에서 고개를 내밀었다. 손에 든 명단이 바들바들 떨렸다."}, {"s": "q:dh_munsu", "t": "그 책상요, 고치느니 버리는 게 낫다고들 하거든요. 일 년 동안 아무도 손을 안 댔거든요."}, {"s": null, "t": "연서희가 책상 모서리를 두 손으로 짚었다. 내려앉은 귀가 손바닥 아래에서 삐걱 소리를 냈다."}, {"s": "q:m_yeon", "t": "버리지 말아요. 고쳐서 그대로 둬요. 명등청에도 셈 맞추는 자리 하나는 있어야죠. …{이름} 님, 이 다리 좀 손봐 줄래요? 장부를 펴려면 책상이 반듯해야 해요. 그 사람은 책상이 기우는 걸 못 참았거든요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_clerk', 3, '맨 끝 칸', '자율 활동을 끝까지 마친다', '{"at": ["hq_yard"], "tasks": [{"t": "idle", "n": 1, "k": "maintenance"}]}'::jsonb, '[{"s": null, "t": "책상 다리에 덧댄 나무가 꼭 맞자 책상이 반듯하게 섰다. 의자도 더는 기우뚱거리지 않았다. 대청에는 등잔 하나만 남아 있었고, 서리들은 모두 돌아가고 없었다."}, {"s": null, "t": "연서희가 품에서 출납 장부를 꺼냈다. 출납관이 맡기고 간 그 장부였다. 연서희는 출납관 의자에 앉아 장부를 맨 끝 장까지 넘겼다. 맨 끝 장은 깨끗하게 비어 있었다."}, {"s": "q:m_yeon", "t": "그 사람이 물속으로 내려간 날 이 장을 펴 놓고 한참 앉아 있었어요. 아무것도 못 적었어요. 뭘 적어야 할지 몰라서요."}, {"s": null, "t": "연서희가 붓에 먹을 찍었다. 첫 칸에 날짜를 적고, 그 옆에 「구중 봉연 왕복 운임 · 조사원 {이름} · 출납관이 달아 둠」이라고 적었다. 글씨는 획마다 끝까지 눌러 쓴 것이었다."}, {"s": null, "t": "연서희는 붓을 내려놓으려다 다시 들었다. 그 아래 줄에 「윤도한 · 구중 봉연 아홉째 문 안쪽 · 셈 맞음」이라고 한 줄을 더 적었다."}, {"s": "q:m_yeon", "t": "이제 셈이 맞네요. 처음으로요."}, {"s": null, "t": "연서희는 장부를 펼쳐 둔 채 대청 바닥을 내려다보았다. 대청 아래로는 장서각이 있었고, 그 아래에 정리소가 있었다. 연서희가 숨을 한 번 고르고 아주 작게 불렀다."}, {"s": "q:m_yeon", "t": "…윤도한 씨."}, {"s": null, "t": "연서희의 입김이 흩어지지 않고 금빛 실로 엉겼다. 실은 등잔 불빛 속에서 한 번 맴돌더니, 대청 마룻널 틈으로 스르르 빠져 내려갔다."}, {"s": null, "t": "연서희가 제 입을 손으로 막았다. 마룻널 틈을 내려다보는 눈이 동그래졌다."}, {"s": "q:m_yeon", "t": "직함 말고 이름으로 부른 건 처음이에요. 십 년을 같이 일했는데요."}, {"s": null, "t": "그때 장서각 쪽 계단에서 우당탕 소리가 났다. 문수가 등잔을 든 채 숨을 헐떡이며 대청으로 뛰어 올라왔다."}, {"s": "q:dh_munsu", "t": "연 서기관님! 조사원님! 방금 정리소 도랑에서요, 문지기님이 물으셨거든요! 방금 위에서 누가 자기 이름을 불렀냐고요! 가슴께가 따뜻하다고요!"}, {"s": null, "t": "연서희가 웃음을 터뜨렸다. 웃다가 장부 위로 고개를 숙였다. 어깨가 한참 들썩였다. 문수가 어쩔 줄 몰라 나를 돌아보았다."}, {"s": null, "t": "나는 문수에게 연서희가 불렀다고 전해 달라고 했다. 운임도 장부에 달아 두었다고 했다. 문수가 고개를 세차게 끄덕이고 다시 계단으로 달려갔다."}, {"s": null, "t": "연서희는 한참 뒤에 고개를 들었다. 장부를 덮어 출납관 책상 서랍에 넣고, 제 책상에서 붓과 대나무 잎만 챙겼다."}, {"s": "q:m_yeon", "t": "제 책상은 서당으로 가져갈래요. 다온이 자리 옆에 두면 애들이 덜 무서워할 거예요. 출납관 책상은 여기 그대로 두고요. 장부는 저녁마다 제가 와서 맞출게요."}, {"s": "q:m_yeon", "t": "낮에는 애들 칸 나누는 걸 가르치고, 밤에는 {이름} 님 운임을 맞추고요. 바뀐 건 그거 하나예요. 나머지는 다 그대로예요."}, {"s": null, "t": "연서희가 등잔 심지를 낮추며 내 목의 목도리를 한 번 더 여며 주었다. 아까보다 매듭이 반듯했다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_doorkeeper', 'side', '뒷이야기·정리소', '문 안쪽의 말벗', '정리소 마른 먹 도랑으로 문지기 윤도한이 날짜를 묻는다. 아홉째 문 앞 등잔의 흰 불씨가 작아졌다는 말에, 동지가 아닌 날 봉연에 내려가 등잔에 기름을 붓고 문 너머의 말벗이 된다.', 'jeongni_vault', 50, '{mq_nine_gates,mdq_17}'::text[], null, 1551, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'ep_x_doorkeeper';
delete from public.world_quest_steps where quest_id = 'ep_x_doorkeeper' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_doorkeeper', 1, '도랑으로 묻는 날짜', '도랑으로 묻는 날짜', '{"at": ["jeongni_vault"]}'::jsonb, '[{"s": null, "t": "정리소 돌방은 조용했다. 가늠 저울이 서 있던 자리에는 받침 자국만 네모나게 남아 있었고, 먹 도랑 바닥의 먹은 검은 유리처럼 굳어 있었다."}, {"s": null, "t": "서리 문수가 도랑 가에 쪼그려 앉아 있었다. 등잔을 무릎 곁에 내려놓고 한쪽 귀를 도랑 바닥으로 기울인 채였다."}, {"s": null, "t": "내 발소리를 듣자 문수가 화들짝 놀라 엉덩방아를 찧었다. 문수는 바닥을 짚고 일어나며 손을 내저었다."}, {"s": "q:dh_munsu", "t": "아, 조사원님! 깜짝 놀랐거든요. 엿듣던 거 아니에요. 이제 이걸 듣는 게 제 일이거든요."}, {"s": null, "t": "나는 문수의 팔을 잡아 일으켜 주고 무엇을 듣고 있었느냐고 물었다. 문수가 바지에 묻은 먹 가루를 털며 도랑 끝 어두운 쪽을 가리켰다."}, {"s": "q:dh_munsu", "t": "문지기님이요. 구중 봉연 아홉째 문 안쪽의 윤도한 님이요. 도랑이 마른 뒤로 그 아래 소리가 여기까지 올라오거든요. 사흘에 한 번쯤 말을 거세요. 첫마디는 늘 똑같고요."}, {"s": null, "t": "문수의 말이 끝나기도 전에 도랑 깊은 데서 똑, 똑 돌을 두드리는 소리가 올라왔다. 이어 낮고 또박또박한 목소리가 도랑을 타고 들려왔다."}, {"s": "q:m_yun", "t": "거기 누구 계십니까. 오늘이 며칠입니까. 문 안쪽에서는 날을 세기가 어렵습니다. 해도 달도 안 보이니까요."}, {"s": null, "t": "나는 도랑 가에 무릎을 꿇고 앉아 오늘 날짜를 말해 주었다. 도랑 아래가 잠깐 조용하더니, 웃음 섞인 숨소리가 올라왔다."}, {"s": "q:m_yun", "t": "그 목소리는 조사원 님이시군요. 장부 귀퉁이에 적어 두겠습니다. 그런데 문수 서리가 그저께 일러 준 날짜와 하루가 어긋납니다. 어느 쪽이 맞습니까."}, {"s": null, "t": "문수의 얼굴이 새빨개졌다. 문수는 손가락을 하나씩 꼽아 보다가 두 손으로 얼굴을 덮어 버렸다."}, {"s": "q:dh_munsu", "t": "제가 틀렸거든요. 그저께 사흘 치를 한꺼번에 말씀드리다가 하루를 빼먹었거든요. 문지기님, 죄송해요!"}, {"s": null, "t": "도랑 아래에서 이번에는 소리 내어 웃는 소리가 났다. 웃음이 그치자 목소리가 조금 가라앉았다."}, {"s": "q:m_yun", "t": "괜찮습니다. 셈이 하루쯤 틀리는 건 장부에서 늘 있는 일이지요. 그보다 여쭐 것이 있습니다. 문 앞 바위 틈 등잔 말입니다. 남명 정찰대장께서 두고 가신 흰 불씨요."}, {"s": "q:m_yun", "t": "요즘 그 불빛이 문틈으로 덜 들어옵니다. 안에서 제가 이름을 불러도 문을 메운 먹 때문에 소리가 반쯤만 나가는 모양입니다. 등잔 기름도 바닥이 났을 겁니다. 정찰대장께서는 동지에나 오실 테고요."}, {"s": null, "t": "문수가 손을 들었다 내렸다 했다. 도랑 끝의 어둠과 내 얼굴을 번갈아 보는 눈이 불안하게 흔들렸다."}, {"s": "q:dh_munsu", "t": "제가 내려가 봐야 하는데요… 봉연은 너무 깊거든요. 박쥐도 많고요. 저 전에 거기 박쥐한테 머리카락을 한 움큼 뜯긴 적이 있거든요."}, {"s": null, "t": "나는 내가 다녀오겠다고 했다. 문수가 안도의 숨을 길게 내쉬었다. 도랑 아래의 목소리는 한 박자 늦게 돌아왔다."}, {"s": "q:m_yun", "t": "와 주신다면 고맙지요. 등잔 기름은 등롱 어유가 좋습니다. 연기가 적어서 문틈 먹을 그을리지 않습니다. 두 병이면 동지까지 넉넉할 겁니다."}, {"s": "q:m_yun", "t": "그리고… 오시거든 잠깐 앉았다 가십시오. 문틈의 두 분은 서로만 부르시고 저와는 말을 안 섞으십니다. 말벗이 좀 그립습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_doorkeeper', 2, '쌀알만 한 흰 불씨', '등롱 어유을(를) 만든다, 구중 봉연에 간다, 등롱 어유을(를) 넘긴다', '{"at": ["sealed_abyss"], "tasks": [{"t": "craft", "items": ["lantern_oil"], "n": 2}, {"t": "travel", "r": ["sealed_abyss"], "n": 1}], "give": {"lantern_oil": 2}}'::jsonb, '[{"s": null, "t": "구중 봉연은 내려갈수록 서늘했다. 천장에서 늘어진 사슬은 꼼짝하지 않았고, 아래 물길의 물은 소리 없이 고여 있었다."}, {"s": null, "t": "아홉째 문 앞에 이르자 문틈을 메운 먹이 보였다. 먹은 단단히 굳어 있었지만 손바닥을 대 보니 미지근했다."}, {"s": null, "t": "문 옆 바위 틈의 작은 등잔에서 흰 불씨 하나가 쌀알만 하게 떨고 있었다. 등잔 접시는 바싹 말라, 심지 끝만 겨우 불씨를 붙들고 있었다."}, {"s": null, "t": "내가 등잔 곁에 무릎을 꿇자 천장 어둠에서 박쥐 떼가 푸드덕푸드덕 쏟아져 내려왔다. 박쥐들이 불씨 둘레를 빙빙 돌며 날개바람을 일으켰다."}, {"s": null, "t": "불씨가 날개바람에 납작하게 눌렸다가 바들바들 다시 일어섰다. 문 너머에서 누군가 문에 손바닥을 대는 소리가 났다."}, {"s": "q:m_yun", "t": "조사원 님이십니까. 그 소리는 박쥐 떼지요. 불빛이 흔들리면 저것들이 몰려듭니다. 밝은 것만 보면 꺼뜨리고 싶어 하는 놈들이라서요."}, {"s": null, "t": "나는 기름부터 붓고 싶은데 박쥐가 등잔을 덮친다고 했다. 문 너머에서 장부를 넘기는 듯한 사락 소리가 났다."}, {"s": "q:m_yun", "t": "그럼 먼저 쫓으십시오. 저는 여기서 세겠습니다. 몇 마리를 쫓으시는지. 셈은 제가 잘합니다."}, {"s": null, "t": "나는 웃음을 참으며 등잔 앞을 막아섰다. 문 너머에서 헛기침이 한 번 들렸다."}, {"s": "q:m_yun", "t": "웃으신 것도 압니다. 숨소리가 달라지거든요. 문 안쪽에 오래 있으면 귀만 밝아집니다."}, {"s": null, "t": "박쥐 한 마리가 등잔 위로 휙 내리꽂혔다. 나는 손바닥으로 불씨를 감싸며 몸을 숙였다. 문 너머의 목소리가 조금 빨라졌다."}, {"s": "q:m_yun", "t": "그 불씨는 남명 장군님 화로에서 덜어 온 것이라 들었습니다. 장군님은 구등대에서 한 번 뵈었지요. 그날 「등잔 밑이 어둡다, 바깥만 보지 마라」 하셨습니다."}, {"s": null, "t": "목소리가 거기서 잠깐 멎었다. 다시 이어진 목소리는 조금 작았다."}, {"s": "q:m_yun", "t": "그때는 그 말씀이 저를 두고 하신 줄 알고 등이 서늘했습니다. 그분 불씨가 이제 제 문 앞을 밝힌다니, 셈이 묘하게 맞습니다. 꺼뜨리지 말아 주십시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_doorkeeper', 3, '문틈의 두 목소리', '봉연 박쥐 떼을(를) 물리친다, 등롱 어유을(를) 넘긴다', '{"at": ["sealed_abyss"], "tasks": [{"t": "win", "m": ["x_sealed_abyss_1"], "n": 6}], "give": {"lantern_oil": 2}}'::jsonb, '[{"s": null, "t": "마지막 박쥐 떼가 천장 틈으로 달아나자 봉연이 다시 조용해졌다. 문 너머에서 기다렸다는 듯 목소리가 들렸다."}, {"s": "q:m_yun", "t": "여섯입니다. 날개 소리로 셌습니다. 셈이 맞습니까."}, {"s": null, "t": "나는 맞다고 했다. 등롱 어유 병을 기울여 등잔 접시에 천천히 부었다. 심지가 기름을 빨아올리자 불씨가 바르르 떨다가 곧게 섰다."}, {"s": null, "t": "불씨는 곧게 섰지만 여전히 작았다. 기름 냄새만 문 앞에 고소하게 퍼졌다."}, {"s": "q:m_yun", "t": "기름만으로는 안 하얘집니다. 그 불은 곁에서 누가 이름을 불러 줘야 밝아집니다. 제가 안에서 아무리 불러도 문틈이 반만 들어 주니까요."}, {"s": null, "t": "나는 문에 가까이 다가앉았다. 문 너머 사람에게 들리도록 「윤도한」 하고 또박또박 불렀다."}, {"s": null, "t": "내 입김이 흩어지지 않고 금빛 실로 엉겼다. 실은 문틈의 먹 사이로 스며들 듯 빨려 들어갔다."}, {"s": null, "t": "같은 순간 바위 틈의 불씨가 화르르 부풀며 하얗게 빛났다. 흰빛이 문틈의 먹을 비추자 굳은 먹 위로 글자 몇 획이 꼬물꼬물 떠올랐다가 가라앉았다."}, {"s": null, "t": "문 너머가 한참 조용했다. 이윽고 들려온 목소리에는 웃음도 셈도 섞여 있지 않았다."}, {"s": "q:m_yun", "t": "…가슴께가 따뜻합니다. 흑련 사람들은 저를 무명이라 불렀고, 정청 사람들은 출납관이라 불렀습니다. 이름으로 불린 게 언제였는지 기억이 안 납니다."}, {"s": null, "t": "나는 문 앞에 등을 기대고 앉았다. 연서희가 정청 서당에서 아이들 글을 가르친다고 말해 주었다. 문 너머에서 숨을 길게 내쉬는 소리가 났다."}, {"s": "q:m_yun", "t": "서당이요. 잘 어울립니다. 칸 나누는 법 하나는 제가 가르쳤으니, 아이들은 칸을 반듯하게 긋겠군요."}, {"s": "q:m_yun", "t": "서희 씨한테 맡긴 출납 장부가 있습니다. 맨 끝 장은 비워 두고 왔습니다. 서희 씨가 적을 자리로요. 혹시 아직도 비어 있거든, 오늘 조사원 님이 내려오신 길 운임을 한 줄 달아 두라고 전해 주십시오. 셈은 맞아야지요."}, {"s": null, "t": "나는 꼭 전하겠다고 했다. 우리는 그 뒤로 한참 이런저런 이야기를 했다. 윤도한은 바깥 장날 쌀값을 물었고, 나는 아는 대로 대답했다."}, {"s": null, "t": "밤이 깊었을 무렵이었다. 문 아래 굳은 먹 쪽에서 아주 작은 소리가 났다. 누군가 「…경현아」 하고 부르자, 조금 뒤에 「…예」 하는 대답이 이어졌다. 그런 소리가 들린 것 같았다."}, {"s": null, "t": "나는 숨을 죽이고 문 아래를 내려다보았다. 굳은 먹은 아무 일 없다는 듯 미지근하기만 했다."}, {"s": "q:m_yun", "t": "들으셨습니까. 밤마다 저럽니다. 저는 그 소리는 세지 않습니다. 셀 것이 아니라서요."}, {"s": null, "t": "등잔 불씨는 이제 엄지손톱만큼 하얗게 타고 있었다. 나는 일어나 옷자락의 먹 가루를 털었다. 문 너머에서도 누군가 일어서는 소리가 났다."}, {"s": "q:m_yun", "t": "또 오십시오, 조사원 님. 다음엔 문수 서리한테 날짜를 틀리지 말라고 단단히 일러 두시고요. 장부 귀퉁이가 두 날짜로 지저분해졌습니다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_hongmae', 'side', '뒷이야기·묵창 나루', '주막에 남은 잔', '묵창 주막 선반 맨 끝에 바닥 글씨가 번진 잔 하나가 열다섯 해째 놓여 있다. 첫 명등제 뒤 어느 아침, 주모 홍매댁은 그 잔 주인의 얼굴이 떠오른다. 국 두 그릇을 시켜 한 그릇을 싸 가던 젊은 조사원, 서율이었다.', 'mukchang_ferry', 50, '{mkq_5,mdq_17}'::text[], null, 1552, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'ep_x_hongmae';
delete from public.world_quest_steps where quest_id = 'ep_x_hongmae' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_hongmae', 1, '주인 모를 잔', '주인 모를 잔', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "이른 아침 묵창 주막은 손님 없이 조용했다. 주모 홍매댁이 먹물 묻은 앞치마로 선반의 잔을 하나씩 훔치고 있었다."}, {"s": null, "t": "선반에는 단골들이 맡겨 둔 잔이 줄지어 있었다. 잔 바닥마다 주인이 칼끝으로 긁어 둔 표식이 있었다. 물고기나 국자, 지붕 모양 같은 그림이 많았다. 홍매댁은 맨 끝 잔 앞에서 손을 멈췄다. 그 잔 바닥에만 글자가 긁혀 있었는데, 먹이 번진 듯 흐려 있었다."}, {"s": null, "t": "홍매댁이 나를 보고 반갑게 손짓했다. 그 잔을 두 손으로 받쳐 들고 평상으로 걸어왔다."}, {"s": "q:ug_hongmae", "t": "어머, 조사원님. 마침 잘 오셨어요. 이 잔 좀 보세요. 열다섯 해째 이 선반 끝에 있던 잔이에요. 주인이 누군지 몰라서 버리지도 못했어요."}, {"s": "q:ug_hongmae", "t": "저 손님이 흘린 말은 한 마디도 안 잊는 사람이잖아요. 이 잔 주인이 한 말도 다 기억했어요. 그런데 그 말을 한 얼굴이 하얬어요. 누가 한 말인지가 통 안 떠오르는 거예요."}, {"s": null, "t": "홍매댁이 잔 바닥을 엄지로 쓸었다. 번진 글씨 위에서 엄지가 오래 머물렀다."}, {"s": "q:ug_hongmae", "t": "그런데 명등제 지나고 며칠 뒤 아침에, 이 잔을 닦다가 갑자기 얼굴이 떠올랐어요. 등도에서 월하 씨가 「서율」 줄을 불렀다고 들은 다음 날이었어요."}, {"s": "q:ug_hongmae", "t": "젊은 조사원 양반이었어요. 먹비 안 오는 저녁마다 와서 국 두 그릇을 시켰어요. 한 그릇은 여기서 먹고, 한 그릇은 뚝배기에 담아 싸 갔어요."}, {"s": null, "t": "홍매댁이 그 사람의 말투를 흉내 내듯 목소리를 낮췄다. 열다섯 해 전 말을 어제 들은 것처럼 또박또박 옮겼다."}, {"s": "q:ug_hongmae", "t": "「한 그릇은 싸 갈게요. 누이가 식은 국은 안 먹어서요. 뛰어가면 안 식어요.」 그렇게 말하고 정말 뒷문으로 뛰어나갔어요. 바로 뒷집인데도요."}, {"s": "q:ug_hongmae", "t": "마지막으로 온 날은 혼자 왔어요. 국을 한 그릇만 시키고는 반도 안 먹었어요. 그리고 이 잔을 저한테 맡겼어요. 「돌아와서 마실게요. 외상은 다음에 갚을게요.」 그 뒤로 안 왔어요."}, {"s": null, "t": "나는 그 사람이 누구인지 알았다. 아홉 칸 뜰 매듭 안쪽에서 내가 이름을 불러 보낸 사람이었다. 홍매댁도 그것을 아는 얼굴이었다."}, {"s": "q:ug_hongmae", "t": "조사원님이 그 양반을 이름으로 보내 줬다면서요. 그래서 부탁드리는 거예요. 그 양반이 늘 시키던 국을 두 그릇만 끓여 줄래요? 부엌 솥은 묵창댁 언니 장국으로 다 찼고, 저는 술상만 닦던 손이라 국을 못 끓여요."}, {"s": "q:ug_hongmae", "t": "그리고 사실은… 그 양반 이름을 아는 손이 끓이는 게 맞을 것 같아서요. 저는 열다섯 해 동안 그 이름도 모르고 잔만 닦았으니까요."}, {"s": null, "t": "홍매댁이 평상 끝에 놓인 차림표를 가리켰다. 먹물 묻은 손가락이 「이름 새김 탕」 줄에서 멈췄다."}, {"s": "q:ug_hongmae", "t": "이거요. 그 양반은 늘 이것만 먹었어요. 국 위에 파를 이름 모양으로 얹어 주는 탕이라, 누이가 좋아한다고요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_hongmae', 2, '형 잔', '이름 새김 탕을(를) 만든다, 이름 새김 탕을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "craft", "items": ["name_carving_soup"], "n": 2}], "give": {"name_carving_soup": 2}}'::jsonb, '[{"s": null, "t": "이름 새김 탕 두 그릇을 평상에 내려놓자 김이 모락모락 피어올랐다. 홍매댁이 한 그릇을 맡긴 잔 옆에 놓고, 잔에는 데운 술을 따랐다."}, {"s": null, "t": "그때 주막 처마 밑에서 엽전 튕기는 소리가 났다. 월하가 기둥에 기대어 오른손으로 엽전을 굴리고 있었다. 월하의 눈길이 평상 위의 잔에 가서 멎었다."}, {"s": null, "t": "엽전이 월하의 손끝에서 미끄러져 평상 밑으로 굴러갔다. 월하는 엽전을 줍지도 않고 평상으로 걸어왔다."}, {"s": "q:mk_wolha", "t": "…그거 형 잔이네. 서율 형. 바닥에 「율」 자 긁은 거, 형이 칼끝으로 긁었어. 나는 옆에서 서하 몫으로 「하」 자도 긁어 달라고 졸랐고."}, {"s": null, "t": "홍매댁이 월하를 보았다. 손님 말을 잊지 않는 눈이 무언가를 맞추듯 가늘어졌다."}, {"s": "q:ug_hongmae", "t": "어머, 그럼 그때 그 양반 뒤를 졸졸 따라다니던 꼬맹이가 월하 씨예요? 국 싸 가는 뚝배기를 늘 들어 주겠다고 떼쓰던 애요?"}, {"s": null, "t": "월하가 웃으려다 말았다. 대신 평상에 걸터앉아 탕 그릇을 내려다보았다. 파를 얹은 모양이 이름 글자를 닮아 있었다."}, {"s": "q:mk_wolha", "t": "형은 국을 싸 가면 첫 숟가락은 늘 서하한테 줬어요. 나는 마지막 숟가락. 국물만 남은 거. 그래도 그게 제일 맛있었어요."}, {"s": null, "t": "월하가 품에서 엽전 꾸러미를 꺼내 평상에 올려놓았다. 아홉 손가락으로 꾸러미 끈을 풀다가 엽전 몇 닢을 바닥에 떨어뜨렸다."}, {"s": "q:mk_wolha", "t": "형 외상, 내가 갚을게요. 얼마예요. 열다섯 해면 이자도 꽤 붙었겠네."}, {"s": null, "t": "홍매댁이 엽전 꾸러미를 월하 쪽으로 도로 밀었다. 앞치마로 평상을 한 번 훔치고 고개를 저었다."}, {"s": "q:ug_hongmae", "t": "남이 대신 갚는 외상은 외상이 아니에요. 주막 셈법이 그래요. 월하 씨가 이름 장사꾼이라도 이건 못 깎아요."}, {"s": null, "t": "월하가 엽전 꾸러미를 도로 품에 넣으며 어깨를 으쓱했다."}, {"s": "q:mk_wolha", "t": "깎으려던 게 아니라 얹으려던 건데. 주모님 셈이 더 무섭네."}, {"s": null, "t": "홍매댁이 잔과 탕 그릇을 보자기에 싸기 시작했다. 보자기 매듭을 지으며 주막 문 쪽을 돌아보았다."}, {"s": "q:ug_hongmae", "t": "오늘 오후는 술청 문 닫을래요. 부엌은 언니가 지키면 되니까요. 이 잔이랑 국, 사당에 있는 그 양반 위패 앞에 직접 갖다 놓을 거예요. 열다섯 해 동안 술청을 하루도 안 비웠는데요."}, {"s": null, "t": "월하가 바닥에 떨어진 엽전을 주워 들고 일어섰다. 벌판 쪽 하늘을 올려다보며 눈살을 찌푸렸다."}, {"s": "q:mk_wolha", "t": "그 사당, 요즘 빈칸 까마귀들이 꼬여요. 위패 글자를 쪼아 간대요. 형 위패 글자를 까마귀가 물어 가면 그건 정말 못 참지. {이름}, 우리보다 먼저 가서 좀 쫓아 줘요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_hongmae', 3, '이름으로 갚는 외상', '빈칸 벌판에 간다, 빈칸 까마귀 떼을(를) 물리친다', '{"at": ["blank_field"], "tasks": [{"t": "travel", "r": ["blank_field"], "n": 1}, {"t": "win", "m": ["mk_field_2"], "n": 6}]}'::jsonb, '[{"s": null, "t": "까마귀 떼가 깍깍 울며 벌판 너머로 흩어졌다. 이름 없는 사당 맨 끝에 위패 셋이 나란히 서 있었다. 「서하」, 「서율」, 「이랑」이었다. 다온이 덧쓴 먹이 아직 진했다."}, {"s": null, "t": "해가 기울 무렵 홍매댁과 월하가 보자기를 들고 사당에 들어섰다. 홍매댁은 「서율」 위패 앞에 무릎을 꿇고 앉아 보자기를 풀었다."}, {"s": null, "t": "홍매댁이 탕 그릇을 위패 앞에 놓았다. 그 곁에 맡긴 잔을 놓고 잔 바닥이 위패 쪽을 보게 돌려놓았다."}, {"s": "q:ug_hongmae", "t": "국 왔어요. 식기 전에 드세요. 오늘은 싸 갈 그릇도 같이 왔어요."}, {"s": null, "t": "홍매댁은 두 번째 그릇을 「서하」 위패 앞에 놓았다. 손이 위패 앞에서 한참 떨어지지 않았다."}, {"s": null, "t": "벌판 위로 어둠이 내려앉았다. 홍매댁이 손을 모으고 위패를 올려다보았다. 입술을 몇 번 달싹이다가 불렀다."}, {"s": "q:ug_hongmae", "t": "조사원 양반."}, {"s": null, "t": "홍매댁의 입김은 그냥 흩어졌다. 홍매댁이 흩어진 입김을 멍하니 보았다. 월하가 홍매댁 곁에 쪼그려 앉아 낮게 말했다."}, {"s": "q:mk_wolha", "t": "호칭은 안 닿아요, 주모님. 나도 아까 혼자 「형」 하고 불러 봤는데 안 닿더라고요. 이름으로 불러야 해요."}, {"s": null, "t": "홍매댁이 숨을 고르고 다시 불렀다. 열다섯 해 만에 처음으로 그 손님의 이름을 불렀다."}, {"s": "q:ug_hongmae", "t": "…서율 씨."}, {"s": null, "t": "홍매댁의 입김이 금빛 실로 엉겨 위패에 닿았다. 위패에 적힌 「서율」 두 글자가 잠깐 따뜻한 빛깔로 물들었다."}, {"s": null, "t": "월하도 따라 불렀다. 월하의 금빛 실은 홍매댁의 것보다 굵었다. 실 두 가닥이 위패 앞에서 한 가닥으로 꼬였다."}, {"s": null, "t": "홍매댁이 앞치마로 눈가를 꾹꾹 눌렀다. 품에서 주막 외상 장부를 꺼내 맨 끝 장을 펼쳤다. 붓에 먹을 찍어 한 줄을 적었다. 「서율 · 국 한 그릇 · 갚음」이었다."}, {"s": null, "t": "나는 누가 갚았느냐고 물었다. 홍매댁이 장부를 덮으며 웃었다. 눈이 아직 젖어 있었다."}, {"s": "q:ug_hongmae", "t": "열다섯 해 동안 제가 이 잔을 못 버렸잖아요. 그게 이자예요. 그리고 오늘 제가 그 양반 이름을 불렀으니까, 그걸로 다 갚은 거예요. 주막 셈법이 그래요."}, {"s": null, "t": "월하가 위패 앞에 쪼그려 앉은 채 코를 한 번 훌쩍였다. 금세 능청스러운 얼굴로 돌아왔다."}, {"s": "q:mk_wolha", "t": "주모님 셈법은 장사꾼 셈법보다 후하네. 다음에 내 외상도 그렇게 쳐 줘요."}, {"s": null, "t": "홍매댁이 앞치마로 눈가를 마저 훔치고 월하를 흘겨보았다."}, {"s": "q:ug_hongmae", "t": "월하 씨 외상은 엽전으로 받아요."}, {"s": null, "t": "월하가 소리 내어 웃었다. 웃다가 엽전을 떨어뜨렸고, 이번에는 홍매댁이 주워 월하의 손에 쥐여 주었다."}, {"s": null, "t": "홍매댁은 잔을 다시 보자기에 쌌다. 탕 그릇 둘은 위패 앞에 그대로 두었다."}, {"s": "q:ug_hongmae", "t": "잔은 주막 선반에 도로 둘래요. 맨 끝 자리에요. 누가 이 잔 주인을 물어보면 제가 다 얘기해 줘야죠. 손님 말은 안 잊으니까요. 이번엔 얼굴까지요."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_lighthouse', 'side', '뒷이야기·구등대 군도', '아홉째 등대', '마지막 등대지기 도화가 꺼진 등대 여덟에 등대지기들의 이름을 하나씩 걸고 싶어 한다. 거둬진 동료들의 이름은 일지에서도 기억에서도 바래 있었다. 그 이름을 하나도 빠짐없이 아는 사람은, 그 등대들을 끄게 만든 문지기 윤도한뿐이었다.', 'nine_lighthouse', 50, '{mq_nine_gates,mdq_17}'::text[], null, 1553, '[]'::jsonb, true, null, null)
