update public.world_quests set open_req = null where quest_id = 'ep_x_lighthouse';
delete from public.world_quest_steps where quest_id = 'ep_x_lighthouse' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_lighthouse', 1, '호칭으로는 안 닿는 이름', '호칭으로는 안 닿는 이름', '{"at": ["nine_lighthouse"]}'::jsonb, '[{"s": null, "t": "청파의 배가 안개를 헤치고 군도의 가장 바깥 섬에 닿았다. 청파는 노를 뱃전에 걸치고 쿨럭쿨럭 쇳소리 섞인 기침을 했다."}, {"s": "q:sn_cheongpa", "t": "다 왔어요, {이름} 님. 저 등대가 아홉째예요. 군도에서 혼자 켜져 있는 거요. 저는 달마다 여기 기름을 실어 와요. 오늘은 짐이 하나 더 많네요. {이름} 님요."}, {"s": null, "t": "등대 꼭대기에서 푸른 불이 낮게 돌고 있었다. 섬 둘레 바다 위로 꺼진 등대 여덟이 검은 기둥처럼 서 있었다."}, {"s": null, "t": "등대 아래 돌계단에 도화가 앉아 있었다. 무릎 위에 낡은 책 여덟 권을 쌓아 놓고 한 권씩 넘기고 있었다. 손바닥에는 기름통 끈에 쓸린 자국이 여전했다."}, {"s": null, "t": "도화가 우리를 보고 일어섰다. 책 더미가 무릎에서 미끄러지려 하자 두 팔로 끌어안았다."}, {"s": "q:m_dohwa", "t": "조사원 님! 청파 씨가 모셔 온다더니 정말 오셨네요. 앉으세요. 기름 냄새는 좀 참으시고요."}, {"s": null, "t": "나는 도화 곁에 앉아 그 책들이 무엇이냐고 물었다. 도화가 맨 위 책을 펼쳐 보였다. 날마다 한 줄씩 기름 쓴 양과 바람 방향이 적혀 있었다."}, {"s": "q:m_dohwa", "t": "꺼진 등대 여덟에서 하나씩 가져온 등대 일지예요. 등대지기는 밤마다 맨 끝에 제 이름을 적어요. 그런데 보세요."}, {"s": null, "t": "일지 맨 끝 줄마다 이름 자리가 먹물을 엎지른 것처럼 번져 있었다. 기름 양과 바람 방향은 또렷한데 이름만 읽을 수가 없었다."}, {"s": "q:m_dohwa", "t": "명등제 이야기는 청파 씨한테 들었어요. 동짓밤에 다들 등롱을 들고 맡은 이름을 불렀다고요. 저는 그날 혼자 여기서 할머니만 불렀어요. 그러다 꺼진 등대들이 보여서… 저기에도 이름을 하나씩 걸어 주고 싶었어요."}, {"s": "q:m_dohwa", "t": "근데 이름이 하나도 생각이 안 나요. 같이 기름통을 지던 언니 오빠들인데, 얼굴 자리가 하얘요. 「셋째 등대 언니」 하고 불러 봤는데 입김이 그냥 흩어졌어요."}, {"s": null, "t": "도화가 일지 한 권을 품에 끌어안았다. 책장 사이에서 마른 귤껍질 한 조각이 떨어졌다. 도화가 그것을 주워 손바닥에 올려놓았다."}, {"s": "q:m_dohwa", "t": "셋째 등대 언니는 기름통에 늘 귤껍질을 넣었어요. 그을음 냄새가 싫다고요. 그런 건 다 기억나는데, 이름만요."}, {"s": null, "t": "나는 그 등대지기 여덟의 이름을 아는 사람이 하나 있다고 말했다. 등잔 밑의 일이 드러나던 날, 연화원 연못가에서 그 사람이 직접 한 말이 떠올랐다. 그 사람은 그날 「밤마다 그 이름들을 몰래 불렀지요」라고 했었다."}, {"s": null, "t": "도화의 얼굴에서 핏기가 가셨다. 손바닥 위의 귤껍질이 바들바들 떨렸다."}, {"s": "q:m_dohwa", "t": "…출납관이요. 명령서를 위조라고 했던 그 사람이요. 그 사람이 우리 등대를 끄게 했잖아요."}, {"s": null, "t": "청파가 뱃전에서 일어나려다 기침을 했다. 기침을 삼키고 도화 쪽으로 몸을 돌렸다."}, {"s": "q:sn_cheongpa", "t": "그분 지금 봉연 아홉째 문 안쪽에 계세요. 동지마다 문 안에서 이름을 부르신대요. 진짜로요. 제가 그 문 앞까지 배를 대 봤거든요."}, {"s": null, "t": "도화는 오래 아무 말도 하지 않았다. 바다 쪽 꺼진 등대들을 하나씩 세듯이 바라보았다. 이윽고 일지 여덟 권을 내 무릎에 올려놓았다."}, {"s": "q:m_dohwa", "t": "저는 못 가겠어요. 그 사람 목소리를 들으면 소리를 지를 것 같아요. 조사원 님이 대신 물어봐 주세요. 여덟 사람 이름이요. 틀리지 않게요."}, {"s": "q:m_dohwa", "t": "일지도 가져가세요. 그 사람이 정말 아는지, 이걸 보고 맞춰 보게요. 할머니가 그러셨어요. 등대는 누가 시켜서 켜는 게 아니라고요. 이번엔 제가 정해서 켜고 싶어요. 등롱은 넷까지는 제가 지을 수 있어요. 할머니한테 배웠거든요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_lighthouse', 2, '틀리지 않게', '구중 봉연에 간다, 구중 봉연을(를) 살핀다', '{"at": ["sealed_abyss"], "tasks": [{"t": "travel", "r": ["sealed_abyss"], "n": 1}, {"t": "search", "r": ["sealed_abyss"], "n": 2}]}'::jsonb, '[{"s": null, "t": "아홉째 문 앞 바위 틈 등잔에서 흰 불씨가 타고 있었다. 나는 등잔 곁에 일지 여덟 권을 내려놓고 문을 두드렸다."}, {"s": null, "t": "한참 뒤에 문 너머에서 장부를 덮는 소리가 났다. 이어 낯익은 목소리가 들렸다."}, {"s": "q:m_yun", "t": "조사원 님이시군요. 오늘은 발소리가 무겁습니다. 무엇을 들고 오셨습니까."}, {"s": null, "t": "나는 구등대 군도의 등대지기 도화가 보낸 일지라고 했다. 꺼진 등대 여덟에 그 등대지기들의 이름을 걸고 싶어 한다고 전했다. 문 너머가 조용해졌다."}, {"s": null, "t": "그 침묵은 길었다. 나는 등잔 불씨가 세 번쯤 흔들릴 때까지 기다렸다. 이윽고 문틈에 입을 대는 듯 목소리가 가까워졌다."}, {"s": "q:m_yun", "t": "…셋째 등대부터 말씀드리겠습니다. 첫째 등대가 아니라 셋째부터입니다. 그 사람이 가장 먼저 불을 껐으니까요. 받아 적으십시오."}, {"s": null, "t": "윤도한은 이름 여덟을 하나씩 불렀다. 한 이름을 부를 때마다 그 사람이 어느 등대를 지켰는지, 무엇을 좋아했는지를 한 줄씩 덧붙였다. 기름통에 귤껍질을 넣던 셋째 등대지기도 그 안에 있었다."}, {"s": null, "t": "나는 일지를 한 권씩 펴서 그 이름을 번진 자리 곁에 받아 적었다. 이름을 적은 자리마다 번졌던 먹이 아주 조금 옅어지는 것 같았다."}, {"s": "q:m_yun", "t": "다 적으셨습니까. 여덟입니다. 열다섯 해 동안 밤마다 불렀으니 틀릴 리는 없습니다. 틀렸다면 제 셈이 틀린 겁니다."}, {"s": null, "t": "나는 하나도 막히지 않았다고 했다. 문 너머에서 깊은 숨소리가 났다."}, {"s": "q:m_yun", "t": "그 아가씨한테 미안하다는 말은 전하지 마십시오. 그 말로는 셈이 안 맞습니다. 여덟을 끈 손이 미안하다는 한마디로 갚을 수 있는 게 아니니까요."}, {"s": "q:m_yun", "t": "대신 이름을 하나도 틀리지 않게 드렸다고만 전해 주십시오. 제가 그 사람들한테 해 줄 수 있었던 건 그것 하나뿐이었습니다."}, {"s": null, "t": "나는 일지를 다시 품에 안고 일어섰다. 문 너머에서 한마디가 더 따라왔다."}, {"s": "q:m_yun", "t": "등롱은 명등 등롱이 좋습니다. 이름 종이를 붙이고 부르면 기름 없이 탑니다. 바닷바람에도 안 꺼지지요. 등대 여덟이니 여덟이 있어야 할 텐데, 혼자 다 지으시려면 손이 모자라실 겁니다."}, {"s": null, "t": "나는 도화가 넷은 직접 짓겠다고 했다고 전했다. 문 너머에서 짧게 웃는 소리가 났다."}, {"s": "q:m_yun", "t": "그럼 넷이군요. 셈이 맞습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_lighthouse', 3, '하나는 기름으로, 여덟은 이름으로', '명등 등롱을(를) 만든다, 명등 등롱을(를) 넘긴다', '{"at": ["nine_lighthouse"], "tasks": [{"t": "craft", "items": ["myeongdeung_lamp"], "n": 4}], "give": {"myeongdeung_lamp": 4}}'::jsonb, '[{"s": null, "t": "해가 질 무렵 아홉째 등대 아래에 등롱 여덟이 나란히 놓였다. 넷은 도화가 지은 것이었고 넷은 내가 지은 것이었다. 도화는 내가 받아 적어 온 일지를 한 권씩 펴 들었다."}, {"s": null, "t": "도화는 번진 자리 곁의 이름을 오래 들여다보았다. 셋째 등대 일지에서 손가락이 멈췄다."}, {"s": "q:m_dohwa", "t": "…맞아요. 이 이름이에요. 이 언니 이름이에요. 이걸 왜 잊었지. 날마다 불렀는데."}, {"s": null, "t": "도화의 목소리가 떨렸다. 나는 윤도한이 전해 달라던 말을 그대로 전했다. 미안하다는 말 대신, 이름을 하나도 틀리지 않게 드렸다는 말이었다."}, {"s": null, "t": "도화는 일지를 꼭 쥐고 바다 쪽을 보았다. 한참 뒤에 코를 훌쩍이며 고개를 끄덕였다."}, {"s": "q:m_dohwa", "t": "미안하다고 했으면 화가 났을 거예요. 이건… 화를 못 내겠네요. 이름을 다 줬으니까요."}, {"s": null, "t": "청파가 노를 저어 등롱을 하나씩 꺼진 등대로 실어 날랐다. 나는 등대 난간마다 등롱을 걸고 이름 종이를 붙였다. 도화가 종이마다 일지에서 옮겨 적은 이름을 확인했다."}, {"s": null, "t": "여덟째 등롱을 걸고 돌아오니 바다는 완전히 어두워져 있었다. 우리 셋은 아홉째 등대 꼭대기 난간에 나란히 섰다. 군도의 꺼진 등대 여덟이 어둠 속에 검게 서 있었다."}, {"s": null, "t": "도화가 난간을 두 손으로 붙잡았다. 숨을 크게 들이마시고 첫 이름을 바다를 향해 불렀다."}, {"s": null, "t": "도화의 입김이 흩어지지 않고 금빛 실로 엉겼다. 실은 밤바다 위로 길게 뻗어 나가 셋째 등대 난간의 등롱에 닿았다. 기름 한 방울 붓지 않은 등롱에 화르르 불이 붙었다."}, {"s": null, "t": "도화가 소리를 지르듯 다음 이름을 불렀다. 둘째 실이 바다를 건너갔고, 또 하나의 등롱이 켜졌다. 도화는 울면서 이름을 불렀고, 부를 때마다 바다 위에 불이 하나씩 늘었다."}, {"s": null, "t": "여덟째 등롱에 불이 붙자 도화가 난간에 이마를 댔다. 군도 둘레 밤바다가 등롱 불빛으로 노랗게 물들어 있었다. 아홉 등대에 모두 불이 들어온 것은 몇 해 만이었다."}, {"s": "q:sn_cheongpa", "t": "다 켜졌어요…! 도화 씨, 다 켜졌어요! 배에서 보면 길이 다 보여요!"}, {"s": null, "t": "청파가 소리치다 기침을 터뜨렸다. 도화가 물통을 건네며 청파의 등을 두드렸다. 그 사이에 첫째로 켠 등롱의 불이 조금 낮아졌다."}, {"s": null, "t": "나는 그 등롱 쪽을 보며 셋째 등대지기의 이름을 불렀다. 내 입김이 바다를 건너가자 낮아지던 불이 다시 일어섰다."}, {"s": "q:m_dohwa", "t": "맞다, 계속 불러 줘야 타는 거죠. 그럼 돌아가면서 불러요. 조사원 님이 셋, 청파 씨가 둘, 제가 셋이요. 동틀 때까지요."}, {"s": null, "t": "우리는 그 밤 내내 돌아가며 이름을 불렀다. 청파는 숨이 차면 손을 들었고, 그때마다 도화가 청파 몫의 이름을 받아 불렀다. 도화는 중간에 할머니 이름도 한 번 불렀다."}, {"s": null, "t": "동이 틀 무렵 도화가 난간에 기대어 등롱 불빛을 하나씩 세었다. 목소리가 쉬어 있었다."}, {"s": "q:m_dohwa", "t": "아홉 다 켜졌네요. 하나는 기름으로, 여덟은 이름으로요. 할머니가 보셨으면 기름 아꼈다고 좋아하셨을 거예요."}, {"s": "q:m_dohwa", "t": "동지에는 제가 봉연에도 들를게요. 청파 씨 배 타고요. 그 사람 이름도 한 번 불러 줄까 봐요. 미워도요. 이름을 다 준 사람이니까요."}, {"s": null, "t": "청파가 쉰 목으로 웃으며 노를 들어 보였다. 동쪽 바다 끝이 하얘지고 있었다. 등롱 불빛은 아침빛 속에서도 한동안 꺼지지 않았다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_mukho', 'side', '뒷이야기·반요촌', '하루 한 글자', '명등청이 반요촌 주민 명부를 받겠다는 답을 보낸다. 다만 바깥 이름은 그 이름을 아는 사람이 손으로 새로 적어야 한다. 하루에 한 글자씩 바깥 이름을 잊는 촌장 묵호의 줄을 누가 적을 것인가.', 'banyo_village', 50, '{gq_5,mdq_17}'::text[], null, 1554, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'ep_x_mukho';
delete from public.world_quest_steps where quest_id = 'ep_x_mukho' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_mukho', 1, '봉연 물길로 온 답장', '봉연 물길로 온 답장', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 큰 집 문간에서 똑, 똑 망치 소리가 났다. 묵호가 쪼그려 앉아 문패를 고쳐 달고 있었다. 위 칸의 바깥 이름은 첫 글자가 또 번져 있었다."}, {"s": null, "t": "묵호는 나를 보더니 망치를 내려놓았다. 무릎을 짚고 일어서다 휘청해서, 나는 노인의 팔을 붙잡았다."}, {"s": "q:g_mukho", "t": "허, 또 자네 팔이구먼. 왔는가. 이 첫 글자 말일세. 그때 수정을 녹여 돌아온 글자인데 사흘을 못 가더군. 오늘 아침엔 둘째 글자도 흐려졌네."}, {"s": null, "t": "묵호가 문패 위 칸을 손가락으로 짚었다. 먹이 번진 자리에서 손가락이 오래 머물렀다."}, {"s": "q:g_mukho", "t": "잊는 건 하루 한 글자야. 늘 그래 왔지. 그래도 오늘은 기다리던 소식이 있어서 그런지 덜 서운하구먼. 여울이 선창에서 올 걸세."}, {"s": null, "t": "선창 쪽에서 여울이 젖은 봉투 하나를 들고 걸어왔다. 봉연 물길 나룻배에 실려 온 것이었다. 여울은 문간 앞에서 봉투를 뜯고 소리 내어 읽었다."}, {"s": "q:mk_hisu", "t": "「반요촌 길잡이 여울 님께. 이번에 보내 주신 반요촌 주민 명부를 받았습니다. 앞서 정청이 『받지 않음』으로 돌려보낸 것들도, 서신방에 누가 한 장씩 베껴 둔 것이 있어 함께 찾았습니다. 명등청 명부에 반요촌 장을 따로 엮겠습니다. 줄마다 바깥 이름, 섬 이름, 사는 곳, 그리고 끝에 부르는 이 칸을 두겠습니다.」"}, {"s": "q:mk_hisu", "t": "「다만 바깥 이름은 귀허 이송 명부에서 옮기지 않겠습니다. 줄이 그어진 글자를 그대로 옮기면 줄까지 따라오는 것 같아서요. 그 이름을 아는 분이 손으로 새로 적어 보내 주세요. 명등청 서리 희수.」"}, {"s": null, "t": "여울이 편지를 접었다. 편지를 쥔 손이 아주 조금 떨렸다. 묵호는 그 손을 보지 않은 척 문패 쪽으로 고개를 돌렸다."}, {"s": "q:g_mukho", "t": "아는 사람이 적어야 한다라. 내 바깥 이름을 제일 잘 아는 사람은 나였는데, 이제 첫 글자도 가물가물하네."}, {"s": "q:g_mukho", "t": "저잣거리 망각 수정을 녹이면 잊은 게 잠깐 돌아오지. 그때처럼 수정을 녹여 놓고 내 손으로 적어 보겠네. 바깥 종이 한 장에 적을 동안만 붙들면 되니까."}, {"s": null, "t": "나는 수정을 구해 오겠다고 했다. 묵호가 고맙다며 내 손등을 두드렸다. 그 곁에서 여울은 편지만 내려다보고 있었다."}, {"s": null, "t": "약 상자를 멘 단이가 마당 끝에서 쪼르르 달려왔다. 단이는 내 소매를 붙잡고 저잣거리 쪽을 가리켰다."}, {"s": "q:g_dani", "t": "저잣거리 가요? 거기 좌판 밑에 전당포 거미가 줄을 쳐 놨어요. 수정이 굴러가면 거미줄에 걸려서 못 꺼내요. 거미부터 쫓아야 해요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_mukho', 2, '번지는 손', '달 없는 저잣거리에서 망각 수정을(를) 모은다, 전당포 거미을(를) 물리친다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["oblivion_crystal"], "r": ["moonless_market"], "n": 3}, {"t": "win", "m": ["gw_market_4"], "n": 5}]}'::jsonb, '[{"s": null, "t": "거미줄에 걸린 수정을 떼어 내 반요촌으로 돌아왔다. 묵호는 화로 곁에 앉아 기다리고 있었다. 화로 곁에 섬에서 뜬 거친 종이 한 장과 붓이 놓여 있었다."}, {"s": null, "t": "묵호가 수정 하나를 화로에 넣었다. 수정이 지글지글 녹으며 푸른 김이 피어올랐다. 김이 문패에 닿자 위 칸의 번진 첫 글자가 또렷해졌다."}, {"s": "q:g_mukho", "t": "됐네. 이 글자야. 이제 잊기 전에 적어야지."}, {"s": null, "t": "묵호가 붓을 들었다. 첫 획은 반듯했다. 둘째 글자를 쓰려는 순간 붓끝의 먹이 종이 결을 따라 번져 나갔다. 섬 종이가 눅눅해 먹을 빨아들인 것이었다."}, {"s": null, "t": "묵호는 종이를 뒤집어 다시 썼다. 이번에는 종이 탓이 아니었다. 노인의 손이 지나간 자리마다 글자가 물에 젖은 듯 번졌다."}, {"s": "q:g_mukho", "t": "…허. 내 손으로는 안 되는구먼. 내 이름이 번져 있으니 손도 번지는 게지."}, {"s": null, "t": "단이가 약 상자에서 붓 한 자루를 꺼내 내밀었다. 눈을 반짝이며 묵호 곁에 바짝 다가앉았다."}, {"s": "q:g_dani", "t": "제가 써 드릴게요! 촌장 할아버지가 불러 주시면요. 근데 받침 있는 글자는 다 똑같아 보여서… 틀려도 돼요?"}, {"s": null, "t": "묵호가 단이의 머리에 주름진 손을 얹었다. 웃는 얼굴이었지만 고개는 저었다."}, {"s": "q:g_mukho", "t": "틀리면 남의 이름이 되지, 단이야. 마음만 받겠네."}, {"s": null, "t": "나는 수정에 비친 글자를 보고 내가 베껴 적어도 되느냐고 물었다. 묵호가 고개를 저었다. 꾸짖는 얼굴은 아니었다."}, {"s": "q:g_mukho", "t": "자네는 내 바깥 이름을 모르지 않나. 비친 걸 베끼는 건 아는 게 아닐세. 그 서리 아가씨 말이 그 뜻이겠지."}, {"s": null, "t": "묵호의 눈길이 화로 건너편으로 갔다. 여울이 거기 앉아 불만 보고 있었다. 여울은 손목의 비늘을 엄지로 쉬지 않고 문지르고 있었다."}, {"s": "q:g_mukho", "t": "여울. 자네는 알지. 이송 명부에 반듯하게 적은 게 자네였으니."}, {"s": null, "t": "여울이 고개를 들었다. 얼굴이 하얗게 질려 있었다."}, {"s": "q:g_yeoul", "t": "제가 그 이름에 줄을 그었어요, 촌장님. 그 손으로 또 적으라고요? 이번엔 명부 맨 위에요?"}, {"s": null, "t": "묵호는 화를 내지 않았다. 화로 불빛 너머로 여울의 손을 가만히 보았다."}, {"s": "q:g_mukho", "t": "그 손이니까 하는 말일세. 줄을 그은 손이 아니면 그 이름을 그렇게 또렷하게 기억할 사람이 없네."}, {"s": null, "t": "여울은 대답하지 못했다. 자리에서 일어나 선창 쪽으로 걸어가 버렸다. 단이가 따라가려 하자 묵호가 아이의 손목을 가만히 잡았다."}, {"s": "q:g_mukho", "t": "두게. 그건 그 사람이 정할 일이야. 내가 시키면 또 시켜서 적는 게 되네."}, {"s": "q:g_mukho", "t": "자네한테는 다른 부탁을 하겠네. 섬 종이는 습해서 먹이 번지네. 바깥 명부에 들어갈 줄이니 바깥 종이에 적어야지. 정제 황지 두 장이면 되겠네. 한 장은 여벌일세. 누가 적든."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_mukho', 3, '부르는 건 하루 한 번', '정제 황지을(를) 만든다, 정제 황지을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["fine_paper"], "n": 2}], "give": {"fine_paper": 2}}'::jsonb, '[{"s": null, "t": "밤이 깊어 마을 끝 화로 앞에서 배웅 노래가 끝났다. 여울은 화로 곁에 무릎을 세우고 혼자 앉아 있었다. 나는 정제 황지 두 장을 들고 그 곁에 앉았다."}, {"s": null, "t": "여울은 종이를 보고도 한참 손을 내밀지 않았다. 장작 하나를 불 속에 밀어 넣었다. 탁, 불똥이 튀었다."}, {"s": "q:g_yeoul", "t": "그 이름 다 기억해. 획 하나까지. 적을 때 손이 하나도 안 떨렸거든. 그래서 더 잘 기억나."}, {"s": "q:g_yeoul", "t": "그때는 그 이름에 줄을 긋는 게 일이었어. 오늘은 그 이름을 지키는 줄을 쓰래. 같은 손으로. …웃기지."}, {"s": null, "t": "나는 웃기지 않다고 했다. 그때 그 이름을 반듯하게 적었기 때문에, 오늘 그 이름이 아직 남아 있는 것이라고 했다. 촌장님도 그 말을 했었다고 덧붙였다."}, {"s": null, "t": "여울이 나를 오래 보았다. 이윽고 손을 내밀어 종이 한 장을 받았다. 화로 불빛 쪽으로 무릎을 당겨 앉았다."}, {"s": null, "t": "묵호가 언제부터인지 화로 건너편에 와 앉아 있었다. 단이가 그 무릎에 기대어 졸고 있었다. 여울은 묵호를 보지 않고 붓을 들었다."}, {"s": null, "t": "여울은 위 칸에 묵호의 바깥 이름을 적었다. 처음 보는 세 글자였다. 획마다 반듯했고, 번지지 않았다. 그 아래 칸에 「묵호」를 적고, 사는 곳 칸에 「반요촌 큰 집」이라고 적었다."}, {"s": null, "t": "마지막 칸 앞에서 붓이 멈췄다. 부르는 이 칸이었다. 여울은 숨을 한 번 고르고 그 칸에 「여울」이라고 제 이름을 적었다."}, {"s": "q:g_yeoul", "t": "줄을 그은 사람이 부르는 사람이 되면, 셈이 맞을까요. 촌장님."}, {"s": null, "t": "묵호는 대답 대신 고개를 끄덕였다. 여울이 붓을 내려놓고 화로 너머의 노인을 똑바로 보았다. 이어 방금 적은 바깥 이름을 소리 내어 불렀다."}, {"s": null, "t": "여울의 입김이 금빛 실로 엉겨 화로 위를 건너갔다. 실이 묵호의 가슴께에 닿았다. 묵호가 한 박자 늦게 고개를 들었다. 남의 이름을 듣는 사람처럼 잠깐 두리번거렸다."}, {"s": null, "t": "여울이 한 번 더 불렀다. 이번에는 묵호가 바로 돌아보았다. 노인의 짓무른 눈가가 화롯불에 번들거렸다."}, {"s": "q:g_mukho", "t": "…그래. 그게 내 이름이었어. 이렇게 부르는 소리였어."}, {"s": null, "t": "묵호가 일어나 문간으로 걸어가 문패를 올려다보았다. 위 칸의 첫 글자와 둘째 글자가 또렷하게 돌아와 있었다."}, {"s": "q:g_mukho", "t": "잊는 건 하루 한 글자. 부르는 건 하루 한 번. 그러면 셈이 맞겠구먼."}, {"s": null, "t": "여울이 무릎을 짚고 일어나 묵호 곁으로 걸어갔다. 손목의 비늘을 문지르던 손이 멈춰 있었다."}, {"s": "q:g_yeoul", "t": "날마다 부를게요, 촌장님. 아침마다요. 문패 고치시기 전에요."}, {"s": null, "t": "단이가 졸린 눈을 비비며 일어나 화로 곁의 남은 종이를 끌어당겼다. 단이는 종이 귀퉁이를 손가락으로 톡톡 두드렸다."}, {"s": "q:g_dani", "t": "저도 줄 하나 만들어 주세요. 저는 이름이 하나뿐이라 위 칸은 비워도 돼요. 근데 부르는 이 칸에는요… {이름} 님 이름 적어 주세요. 바깥 이름이 하나도 안 번진 사람이니까요."}, {"s": null, "t": "여울이 웃으며 남은 종이에 단이의 줄을 그어 주었다. 나는 단이의 부르는 이 칸에 내 이름을 또박또박 적었다. 단이가 그 종이를 두 손으로 들고 화로 불빛에 비춰 보았다. 여울이 두 장을 겹쳐 들고 선창 쪽을 보았다."}, {"s": "q:g_yeoul", "t": "둘 다 봉연 물길 배에 실어 보낼게. 이번엔 받아 줄 거야. 받아 주지 않아도 또 보내겠지만."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_pine', 'side', '뒷이야기·본부 객사', '느티나무 아래 송화차', '손이 굳어 배를 타지 못하는 기록관 모가람이, 도제조 백운서가 좋아하던 송화차를 무덤에 올려 달라고 한다. 겁 많은 서리 문수와, 무덤 앞의 일을 모두 받아 적어 오기로 한 곽두칠이 함께 등도 관아 뒤뜰 느티나무를 찾는다.', 'hq_dorm', 50, '{mdq_17}'::text[], null, 1555, '[]'::jsonb, true, null, null)
