update public.world_quests set open_req = null where quest_id = 'ep_x_pine';
delete from public.world_quest_steps where quest_id = 'ep_x_pine' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_pine', 1, '받아쓰기 쉬는 시간', '받아쓰기 쉬는 시간', '{"at": ["hq_dorm"]}'::jsonb, '[{"s": null, "t": "객사 작은 방 창가에 기록관 모가람이 앉아 있었다. 굳은 두 손을 무릎 위에 포개 놓은 채였다. 그 앞에서 곽두칠이 붓을 들고 받아 적고 있었다. 곽두칠의 발밑 그림자가 등잔 불빛에 또렷했다."}, {"s": "night_office:mo", "t": "…그해 동지 사본 일곱째 장, 넷째 줄이요. 아, 조사원님! 마침 잘 오셨어요. 두칠 씨, 우리 좀 쉬어요. 손가락에 쥐 나겠어요."}, {"s": null, "t": "곽두칠이 붓을 내려놓고 손가락을 하나씩 폈다. 먹이 묻은 손끝을 내려다보더니 고개를 저었다."}, {"s": "q:md_gwak_duchil", "t": "쥐는 안 났습니다. 기록관님이 쉬자고 하시면 쉬는 겁니다."}, {"s": null, "t": "모가람이 쿡쿡 웃었다. 굳은 손등으로 창밖을 가리켰다. 객사 뒤뜰 너머로 정청 뒷산 소나무들이 보였다."}, {"s": "night_office:mo", "t": "송화 날리는 걸 보니까 생각이 났어요. 도제조님이요. 옛 장부에 그분이 송화 넣은 차를 좋아하셨다고 적혀 있었잖아요. 조사원님이 한 번 우려 드렸고요. 그때 「송화차로구먼」 하셨다면서요."}, {"s": "night_office:mo", "t": "그분 묻힌 지가 꽤 됐는데, 저는 아직 무덤에 한 번도 못 가 봤어요. 손이 이래서 배를 못 타거든요. 수로 배는 흔들려서 뱃전을 붙잡아야 하는데 손가락이 안 굽어요."}, {"s": null, "t": "모가람이 굳은 손을 들어 보였다. 손가락 마디가 굽지 않고 뻣뻣하게 펴져 있었다. 모가람은 웃고 있었지만 눈은 웃지 않았다."}, {"s": "night_office:mo", "t": "그래서 부탁이에요. 송화차 두 잔만 우려서 그 느티나무 아래 올려 주세요. 그리고 두칠 씨가 같이 가 줘요. 무덤 앞에서 있었던 일을 하나도 빼지 말고 다 적어 와요. 제가 그걸 듣고 거기 간 셈 칠게요."}, {"s": null, "t": "곽두칠이 붓을 쥔 채 얼어붙었다. 그림자가 등잔 불빛 아래에서 조금 흔들렸다."}, {"s": "q:md_gwak_duchil", "t": "제가… 도제조님 무덤에요. 저는 정청 서가에 불을 놓은 사람입니다. 그분 앞에 서도 되는지 모르겠습니다."}, {"s": null, "t": "모가람이 굳은 손을 곽두칠의 팔에 가만히 얹었다."}, {"s": "night_office:mo", "t": "그러니까 두칠 씨가 가야죠. 저는 그 불에 손을 데었고 두칠 씨는 그 불을 놓았잖아요. 둘 다 그분한테 할 말이 있는데, 하나는 못 가니까 하나라도 가야죠."}, {"s": null, "t": "그때 방문이 벌컥 열렸다. 서리 문수가 서류 뭉치를 안고 들어오다 우리 셋을 보고 멈춰 섰다."}, {"s": "q:dh_munsu", "t": "기록관님, 사본 묶음 가져왔거든요. …근데 분위기가 왜 이래요? 저 뭐 잘못 들어온 거예요?"}, {"s": null, "t": "모가람이 문수를 보고 반가운 얼굴로 굳은 손을 흔들었다."}, {"s": "night_office:mo", "t": "아뇨, 딱 맞게 들어왔어요. 문수 서리, 등도 관아 터 가 봤죠? 길 좀 알려 줘요. 아니다, 같이 가 줘요."}, {"s": null, "t": "문수의 얼굴이 하얗게 질렸다. 서류 뭉치가 품에서 미끄러질 뻔했다."}, {"s": "q:dh_munsu", "t": "등도요? 저 거기 한 번도 안 가 봤거든요! 거기 아직 먹 묻은 것들이 어슬렁거린다던데요! 저는 정청 서리거든요, 정청에 있어야…"}, {"s": null, "t": "곽두칠이 문수 쪽을 보았다. 아주 조금 웃은 것 같았다. 곽두칠은 다시 붓을 들어 종이 귀퉁이에 무언가를 적었다."}, {"s": "q:dh_munsu", "t": "지금 뭐 적으세요?"}, {"s": null, "t": "곽두칠이 붓을 든 채 문수를 올려다보았다. 표정은 진지했다."}, {"s": "q:md_gwak_duchil", "t": "「서리 문수, 등도에 한 번도 안 가 봤다고 함.」 기록관님이 하나도 빼지 말라고 하셨습니다."}, {"s": null, "t": "모가람이 소리 내어 웃었다. 웃음이 가라앉자 굳은 손등으로 창밖 소나무를 다시 가리켰다."}, {"s": "night_office:mo", "t": "송화는 잿빛 들녘 끝 소나무에서 따면 돼요. 찻잎도 그 둘레에 나고요. 송화만 우리면 맛이 엷으니까, 그때처럼 밤빛 차로 덖어 주세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_pine', 2, '입에 대 주는 찻잔', '잿빛 들녘에서 채집한다, 밤빛 차을(를) 만든다, 밤빛 차을(를) 넘긴다', '{"at": ["hq_dorm"], "tasks": [{"t": "gather", "r": ["field_outskirts"], "n": 3}, {"t": "craft", "items": ["night_tea"], "n": 2}], "give": {"night_tea": 2}}'::jsonb, '[{"s": null, "t": "송화를 넣고 덖은 밤빛 차 두 잔을 들고 객사 작은 방으로 돌아왔다. 차에서 솔 향과 등 기름 냄새가 함께 피어올랐다. 모가람이 눈을 감고 그 냄새를 맡았다."}, {"s": "night_office:mo", "t": "이 냄새예요. 그분 방 앞을 지나가면 이 냄새가 났어요. 문은 늘 닫혀 있었는데 냄새는 새어 나왔어요."}, {"s": null, "t": "나는 찻잔 하나를 들어 모가람의 입에 대 주었다. 모가람이 한 모금 마시고 오래 입에 머금었다가 삼켰다."}, {"s": "night_office:mo", "t": "맛이 됐어요. 도제조님이 「송화차로구먼」 하실 맛이에요. 이거 올리고 오시면 돼요."}, {"s": null, "t": "모가람이 곽두칠 쪽으로 몸을 돌렸다. 곽두칠은 이미 붓에 먹을 찍어 들고 있었다."}, {"s": "night_office:mo", "t": "두칠 씨, 제 말 받아 적어요. 무덤 앞에서 두칠 씨가 읽어 줘요. 「서른 해 동안 봉인 서가를 지킨 기록관 모가람이 아룁니다.」"}, {"s": "night_office:mo", "t": "「알면서 적지 않았던 걸 이제 말로 다 남기는 중입니다. 열한 해 치 남았어요. 다 끝나면 그때는 배를 타는 법을 배워서 직접 가겠습니다. 손이 안 굽어도요.」"}, {"s": null, "t": "곽두칠의 붓이 멈추지 않고 따라갔다. 마지막 글자를 적은 곽두칠이 종이를 들어 모가람에게 보였다. 모가람이 고개를 끄덕였다."}, {"s": null, "t": "문수는 방 구석에 쪼그려 앉아 제 몫의 할 말을 손가락으로 세고 있었다. 문수가 고개를 들어 모가람을 보았다."}, {"s": "q:dh_munsu", "t": "기록관님, 저는 무덤 앞에서 뭐라고 해야 해요? 도제조님이랑은 문 앞에서 「심지가 밝아지셨어요」 하고 알린 것밖에 말을 해 본 적이 없거든요."}, {"s": null, "t": "모가람이 문수 쪽으로 고개를 돌리고 웃었다."}, {"s": "night_office:mo", "t": "하고 싶은 말을 하면 돼요. 두칠 씨가 다 적을 거니까요."}, {"s": null, "t": "문수가 곽두칠의 붓을 보더니 두 손으로 제 입을 막았다. 곽두칠이 붓을 들어 종이 귀퉁이에 또 무언가를 적었다."}, {"s": "q:dh_munsu", "t": "그것도 적으세요?! 제가 입 막은 것도요?!"}, {"s": null, "t": "곽두칠이 붓을 멈추지 않고 고개만 끄덕였다."}, {"s": "q:md_gwak_duchil", "t": "적었습니다."}, {"s": null, "t": "모가람이 웃다가 창밖으로 시선을 돌렸다. 관아 터 쪽 하늘은 보이지 않았지만, 모가람은 그쪽을 한참 바라보았다."}, {"s": "night_office:mo", "t": "수로 선착에서 내리면 관아 터까지 걸어가야 해요. 두칠 씨, 찻잔은 두칠 씨가 들어요. 조사원님은 앞에 서 주시고요. 문수 서리는 가운데요. 제일 안전한 자리니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_pine', 3, '받아 적은 그림자', '꺼진 관아 터에 간다, 밤빛 차을(를) 넘긴다', '{"at": ["dark_yamen"], "tasks": [{"t": "travel", "r": ["dark_yamen"], "n": 1}], "give": {"night_tea": 2}}'::jsonb, '[{"s": null, "t": "꺼진 관아 터에 밤이 내려와 있었다. 처마마다 걸린 등롱이 노란 불빛으로 마당을 비추었다. 마당 한가운데 구리 화로에서 흰 불씨 하나가 조용히 타고 있었다."}, {"s": null, "t": "문수는 수로 선착에서부터 내 등 뒤에 바싹 붙어 걸었다. 화로의 흰 불빛을 보고서야 문수가 어깨에서 힘을 뺐다."}, {"s": "q:dh_munsu", "t": "저 불은 남명 정찰대장님이 두고 가신 거죠? 저거 보니까 좀 덜 무섭거든요. 사람 사는 데 같아서요."}, {"s": null, "t": "관아 뒤뜰로 돌아가자 오래된 느티나무가 보였다. 가지가 마당 담장 너머까지 뻗어 있었다. 그 아래 작은 둔덕 하나가 있었다. 둔덕 위로 풀이 돋아 있었다."}, {"s": null, "t": "곽두칠이 찻잔 둘을 든 채 둔덕 앞에서 걸음을 멈췄다. 한참 서 있다가 무릎을 꿇고 찻잔 하나를 둔덕 앞에 내려놓았다. 나머지 한 잔은 들고 있었다."}, {"s": "q:md_gwak_duchil", "t": "기록관님이 한 잔은 무덤에, 한 잔은 저희가 나눠 마시라고 하셨습니다. 혼자 드시는 차는 맛이 없다고요."}, {"s": null, "t": "곽두칠이 품에서 종이를 꺼내 폈다. 모가람의 말을 받아 적은 종이였다. 곽두칠은 목소리를 가다듬고 둔덕을 향해 또박또박 읽었다."}, {"s": "q:md_gwak_duchil", "t": "「서른 해 동안 봉인 서가를 지킨 기록관 모가람이 아룁니다. 알면서 적지 않았던 걸 이제 말로 다 남기는 중입니다. 열한 해 치 남았어요. 다 끝나면 그때는 배를 타는 법을 배워서 직접 가겠습니다. 손이 안 굽어도요.」"}, {"s": null, "t": "곽두칠은 종이를 접고 나서도 일어서지 않았다. 둔덕 앞에 무릎을 꿇은 채로, 이번에는 종이를 보지 않고 말했다."}, {"s": "q:md_gwak_duchil", "t": "정청 서가에 불을 놓은 사람은 저였습니다. 그 불에 기록관님 손이 굳었습니다. 그날 도제조님 방 문틈 불빛은 떨리지 않았습니다. 저는 그게 무서웠습니다. 이제는… 그 불빛이 그리운 것 같습니다."}, {"s": null, "t": "곽두칠이 고개를 숙였다. 화로 불빛이 그 등 위로 비쳐, 둔덕 위에 곽두칠의 그림자가 길게 드리워졌다."}, {"s": null, "t": "문수가 내 소매를 잡아당겼다. 문수는 둔덕 앞으로 한 걸음 나섰다가 다시 물러났다. 입술을 몇 번 달싹이다가 겨우 입을 열었다."}, {"s": "q:dh_munsu", "t": "도제조 어르신. 저 문수거든요. 문 앞에서 맨날 심지 밝아지셨다고 알리던 서리요. 그때 제가 너무 크게 소리 질러서 죄송했거든요. 그래도 그 소리 들으시고 문 열어 주셔서… 고마웠거든요."}, {"s": null, "t": "문수의 입김은 그냥 흩어졌다. 「어르신」은 호칭이었다. 문수가 흩어진 입김을 보고 울상이 되었다."}, {"s": "q:dh_munsu", "t": "왜 안 나와요? 저 진심이었거든요!"}, {"s": null, "t": "나는 이름으로 불러야 닿는다고 했다. 문수가 화들짝 놀라 손을 내저었다."}, {"s": "q:dh_munsu", "t": "도제조님 함자를요? 제가요? 그건 너무 무례하잖아요!"}, {"s": null, "t": "곽두칠이 고개를 들고 문수를 보았다. 그러고는 둔덕을 향해 먼저 「백운서」 하고 불렀다."}, {"s": null, "t": "곽두칠의 입김이 금빛 실로 엉겨 둔덕 위에 내려앉았다. 실은 풀잎 사이로 스며들어 느티나무 뿌리 쪽으로 흘러갔다."}, {"s": "q:md_gwak_duchil", "t": "마지막 날 다들 이렇게 불렀다고 들었습니다. 무례가 아니라, 그게 그분이 바라신 거라고요. 정청에는 그분 이름을 부를 사람이 없다고 하셨답니다."}, {"s": null, "t": "문수가 코를 훌쩍였다. 두 손을 모으고 눈을 질끈 감았다. 아주 작게, 그래도 끝까지 「백운서」 하고 불렀다."}, {"s": null, "t": "문수의 실이 곽두칠의 실 곁에 나란히 내려앉았다. 나도 따라 불렀다. 실 세 가닥이 둔덕 위에서 한 가닥으로 꼬여 느티나무 뿌리로 스며들었다."}, {"s": null, "t": "우리는 둔덕 앞에 둘러앉아 남은 한 잔을 돌려 마셨다. 문수는 한 모금 마시고 너무 뜨겁다며 혀를 내밀었다. 곽두칠은 그것도 종이에 적었다."}, {"s": null, "t": "곽두칠이 붓을 내려놓고 둔덕 위를 내려다보았다. 화로 불빛 아래 곽두칠의 그림자가 둔덕 위에 또렷하게 앉아 있었다."}, {"s": "q:md_gwak_duchil", "t": "「도제조님 무덤 위에 곽두칠의 그림자가 같이 앉았음.」 이것도 적겠습니다. 기록관님이 들으시면 좋아하실 겁니다. 한때는 이 그림자가 없었으니까요."}, {"s": null, "t": "느티나무 가지가 밤바람에 흔들렸다. 등도에 돌아온 바람이었다. 문수가 그 바람에 몸을 움츠리면서도 둔덕 곁을 떠나지 않았다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_sawol', 'side', '뒷이야기·백골 장터', '무녀가 아닌 두 사람', '백 년 치 다발을 해마다 갈라 묶던 단비가 붉은 인장 일이 있던 해의 다발에서 「사월」이라는 이름을 찾는다. 바쳐지지 않은 산 사람의 이름이었다. 무녀를 그만둔 두 사람이 적사 황무지 사당 아래에서 다시 만나, 축문 없는 액막이를 함께 지낸다.', 'bone_market', 50, '{mq_nine_gates,mde_danbi_2}'::text[], null, 1556, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'ep_x_sawol';
delete from public.world_quest_steps where quest_id = 'ep_x_sawol' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_sawol', 1, '끝줄의 이름', '끝줄의 이름', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "백골 장터 어귀에 엿판이 하나 서 있었다. 판자에 「앵두 엿」이라고 크게 적혀 있었고, 단비가 그 앞에서 오른손으로 엿을 잘라 팔고 있었다."}, {"s": null, "t": "여운비는 단비의 오른쪽에 걸상을 놓고 앉아 장부를 적고 있었다. 손님이 엿을 사 갈 때마다 여운비가 호송 짐을 세듯 큰 소리로 셈을 불렀다."}, {"s": "north_league:yeo", "t": "엿 열두 짐… 아니, 열두 가락이오. 남은 것은 서른 가락. 이상 없소."}, {"s": null, "t": "엿을 사러 온 아이가 여운비의 하얗게 바랜 오른 눈을 보고 슬금슬금 뒷걸음질 쳤다. 단비가 웃으며 아이 손에 엿을 하나 더 쥐여 주었다."}, {"s": "red_moon_cult:danbi", "t": "무서워하지 마. 이 언니는 장부만 적어. 칼은 엿 자를 때만 뽑아. …{이름} 님! 마침 잘 오셨어요. 보여 드릴 게 있어요."}, {"s": null, "t": "단비가 엿판 밑에서 끈으로 묶은 종이 한 장을 꺼냈다. 오른쪽 위 모서리가 반듯하게 접혀 있었다. 단비는 종이를 펴 내 앞에 내밀었다."}, {"s": "red_moon_cult:danbi", "t": "교주님 다발을 해마다 갈라 묶다가 찾았어요. 붉은 인장 일이 있던 해 다발이에요. 월식성 서약에 바칠 이름 이백셋이요. 그런데 맨 끝 줄을 보세요."}, {"s": null, "t": "맨 끝 줄에 「사월」 두 글자가 적혀 있었다. 그 곁에 작은 글씨로 「무녀 · 달아남 · 대신할 것 없음」이라고 덧붙어 있었다."}, {"s": null, "t": "나는 그 이름을 알았다. 적사 황무지 바위 틈에서 바들바들 떨던 아이였다. 단비의 얼굴에서 늘 걸려 있던 웃음이 조금 내려앉았다."}, {"s": "red_moon_cult:danbi", "t": "이건 살아 있는 사람 이름이에요. 교주님이 사들인 이름도 아니고, 누가 판 이름도 아니에요. 우리가 동짓밤마다 부를 다발에 살아 있는 사람 이름이 섞여 있으면 안 되잖아요."}, {"s": "red_moon_cult:danbi", "t": "사월이 찾기 내기 기억나세요? 그때는 {이름} 님이 이겼죠. 이번엔 잡으러 가는 거 아니에요. 돌려주러 가는 거예요. 근데 사월이가 어디 있는지를 몰라요."}, {"s": null, "t": "그때 장터 공터 쪽에서 쿵, 쿵 무거운 발소리가 다가왔다. 대호법 사마겸이 다발 궤짝을 어깨에 메고 걸어오고 있었다. 사마겸은 엿판 앞에서 걸음을 멈추고 단비가 든 종이를 내려다보았다."}, {"s": "red_moon_cult:sama", "t": "정청 조사원. 그 종이를 기어이 찾아냈군. 그 아이는 내가 기른 아이다. 이름이 그 다발에 들어간 것도 안다.", "fac_not": "red_moon_cult", "spec": 2, "grp": 1}, {"s": "red_moon_cult:sama", "t": "교도. 그 종이를 기어이 찾아냈군. 그 아이는 내가 기른 아이다. 이름이 그 다발에 들어간 것도 안다.", "fac": "red_moon_cult", "spec": 1, "grp": 1}, {"s": null, "t": "사마겸이 궤짝을 내려놓고 품에서 깎다 만 무 한 토막을 꺼냈다. 무를 엄지로 문지르는 손이 생각보다 조심스러웠다."}, {"s": "red_moon_cult:sama", "t": "사월이는 해마다 이맘때면 성에서 아이들을 데리고 내려온다. 적사 황무지 어귀 사당으로. 무녀가 안 가니 저라도 가야 한다더군. 저도 이제 무녀가 아니면서."}, {"s": "red_moon_cult:sama", "t": "가거든 이걸 줘라. 그 애는 어릴 때 무만 깎아 주면 울음을 그쳤다. 내가 주면 안 받을 테니 네가 줘라."}, {"s": null, "t": "단비가 무를 받아 들고 사마겸을 올려다보았다. 사마겸은 헛기침을 하고 궤짝을 다시 어깨에 멨다."}, {"s": null, "t": "여운비가 장부를 덮고 일어섰다. 고개를 돌려 오른 뺨을 장터 바깥 바람 쪽으로 내밀었다."}, {"s": "north_league:yeo", "t": "황무지 바람이 서쪽에서 세게 부오. 모래가 날리면 길목에 전갈이 올라오지. 내 눈은 하나뿐이라 모래바람 속에서는 앞이 좁소. 당신이 앞에 서시오. 나는 단비 오른쪽에 서겠소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_sawol', 2, '바위 틈의 아이들', '적사 황무지을(를) 살핀다, 붉은 전갈을(를) 물리친다', '{"at": ["red_plain"], "tasks": [{"t": "search", "r": ["red_plain"], "n": 2}, {"t": "win", "m": ["g_red_plain"], "n": 6}]}'::jsonb, '[{"s": null, "t": "붉은 전갈들을 쫓아내고 바위 언덕을 두 번 돌고 나서야 낯익은 바위 틈이 보였다. 붉은 인장 일 때 사월이 숨어 있던 바로 그 틈이었다."}, {"s": null, "t": "바위 틈 그늘에 젊은 여자 하나와 아이 셋이 물통을 돌려 마시고 있었다. 아이들 손목마다 낡은 붉은 실이 감겨 있었다."}, {"s": null, "t": "여자가 고개를 들다가 단비와 눈이 마주쳤다. 물통이 손에서 미끄러져 모래 위로 굴렀다. 여자가 아이들을 제 등 뒤로 끌어당겼다. 어깨가 바들바들 떨렸다."}, {"s": "q:m_sawol", "t": "…단비 언니."}, {"s": null, "t": "단비가 그 자리에서 걸음을 멈췄다. 한 걸음도 더 다가가지 않고 모래 위에 털썩 주저앉았다. 오른손에 든 종이를 앞으로 내밀었다."}, {"s": "red_moon_cult:danbi", "t": "잡으러 온 거 아니야. 진짜야. 이거 돌려주러 왔어. 그리고… 이건 대호법님이 주래. 무야."}, {"s": null, "t": "사월의 시선이 무 토막에 가서 멈췄다. 떨리던 어깨가 조금 가라앉았다. 사월은 아이들을 그늘에 앉혀 두고 천천히 다가와 종이를 받았다."}, {"s": null, "t": "사월이 종이 맨 끝 줄을 오래 내려다보았다. 이윽고 품에서 꼬깃꼬깃한 종이 한 장을 꺼냈다. 같은 명단이었다. 맨 끝 줄의 「사월」 두 글자도 똑같았다."}, {"s": "q:m_sawol", "t": "저도 하나 갖고 있어요. {이름} 님이 다시 제 손에 쥐여 준 거요. 버리지도 못하고 태우지도 못했어요. 그럼 정말 지워질 것 같아서요."}, {"s": null, "t": "단비가 모래를 한 줌 쥐었다 놓았다. 웃는 얼굴이 아니었다."}, {"s": "red_moon_cult:danbi", "t": "그때 사월이 잡히면 교주님 앞에 끌고 갈 생각이었어. 내기에서 이기면 엿을 한 항아리 받기로 했었거든. 미안해. 엿 한 항아리에 너를 걸었어."}, {"s": null, "t": "사월이 단비를 보다가 단비의 왼손에 눈길이 멎었다. 손끝이 먹빛으로 굳어 있었다. 사월이 놀라 입을 벌렸다."}, {"s": "q:m_sawol", "t": "언니 손이 왜 그래요? 그리고 아까부터 오른쪽으로만 고개를 돌려요. 귀도… 다쳤어요?"}, {"s": null, "t": "단비가 먹빛 왼손을 들어 보였다. 웃으려 했지만 입꼬리가 끝까지 올라가지 않았다."}, {"s": "red_moon_cult:danbi", "t": "서약 값을 내 이름으로 치렀어. 남의 이름 말고. 반쪽만 가져가더라. 왼쪽 귀랑 왼손. 덕분에 축문이 안 들려. 이제 무녀 아니야. 엿 장수야."}, {"s": null, "t": "사월의 눈이 동그래졌다. 사월은 한참 단비를 보다가, 갑자기 웃음을 터뜨렸다. 웃음 끝에 눈물이 맺혔다."}, {"s": "q:m_sawol", "t": "저도 무녀 아니에요. 축문 끝을 배우기 전에 도망쳤거든요. 그래서 오늘 아이들 액막이를 어떻게 하나 걱정하던 참이었어요. 붉은 실은 감을 줄 아는데 외울 축문이 없어서요."}, {"s": null, "t": "아이 하나가 그늘에서 쪼르르 달려 나와 사월의 치마폭을 잡았다. 아이는 단비를 경계하는 눈으로 보았다."}, {"s": "q:md_child", "t": "사월 언니, 이 사람도 무녀예요? 액막이 해 줘요?"}, {"s": null, "t": "여운비가 단비 오른쪽에 서서 그 모습을 내려다보았다. 볼에 닿는 바람을 읽듯 잠깐 고개를 기울였다."}, {"s": "north_league:yeo", "t": "무녀가 없는 액막이라. 북령에서는 그런 걸 해 본 적이 없소. 조사원, 당신은 어떻게 생각하오."}, {"s": null, "t": "나는 축문 대신 아이들 이름을 불러 주자고 했다. 실은 사월이 감고, 이름은 단비가 부르자고 했다. 밤이 되면 부르는 이름이 금빛으로 닿을 거라고 했다."}, {"s": null, "t": "단비와 사월이 동시에 나를 돌아보았다. 둘이 서로를 보더니 똑같이 웃었다."}, {"s": "q:m_sawol", "t": "그거 좋다. 붉은 실은 원래 이름을 묶는 실이었대요. 서약에 쓰기 전에는요. 근데 아이들 실이 다 낡아서 새 실이 있어야 해요. 하나에 일곱 번 감으려면 넉넉해야 하고요."}, {"s": null, "t": "단비가 손가락을 꼽으며 아이들과 사월과 여운비를 차례로 가리켰다."}, {"s": "red_moon_cult:danbi", "t": "저 아이 셋에, 사월이 너, 그리고 나랑 대장님 몫까지. 여섯 타래요. {이름} 님, 부적실 좀 지어 줄래요? 저는 오른손밖에 못 써서 실이 자꾸 엉켜요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_sawol', 3, '일곱 번, 바로 감기', '부적실을(를) 만든다, 부적실을(를) 넘긴다', '{"at": ["red_plain"], "tasks": [{"t": "craft", "items": ["talisman_thread"], "n": 6}], "give": {"talisman_thread": 6}}'::jsonb, '[{"s": null, "t": "해가 진 뒤 우리는 황무지 어귀 사당 앞에 모였다. 사당 아래 비탈의 흙집에서 엿 고는 단내가 올라왔다. 언년이 솥 앞에서 주걱을 든 채 이쪽을 올려다보았다."}, {"s": "q:sx_md_eonnyeon", "t": "방울 무녀 왔구먼. 올해는 방울 대신 엿을 들고 왔냐. 애들 이마에 엿 바르지 마라. 개미 꼬인다."}, {"s": null, "t": "단비가 웃으며 언년에게 손을 흔들었다. 사월은 사당 계단에 아이 셋을 나란히 앉혔다. 사월의 손에는 내가 지어 온 부적실이 감겨 있었다."}, {"s": null, "t": "사월이 첫 아이의 손목을 잡았다. 붉은 실을 한 바퀴씩 천천히 감았다. 손끝이 익숙했다. 일곱 번째 매듭이 단단히 묶이자 사월이 단비를 돌아보았다. 단비가 아이 앞에 쪼그려 앉아 오른쪽 귀를 아이 쪽으로 기울였다."}, {"s": "red_moon_cult:danbi", "t": "이름이 뭐야? 크게 말해 줘. 언니는 오른쪽 귀로만 들려."}, {"s": null, "t": "아이가 제 이름을 크게 외쳤다. 단비가 그 이름을 받아 또박또박 불렀다. 단비의 입김이 흩어지지 않고 금빛 실로 엉겨 아이의 가슴께에 가 닿았다."}, {"s": null, "t": "아이가 제 가슴을 손으로 덮고 눈을 크게 떴다. 다른 아이 둘이 앞다투어 손목을 내밀었다."}, {"s": "q:md_child", "t": "따뜻해! 사월 언니, 여기가 따뜻해요! 나도, 나도 빨리 감아 줘요!"}, {"s": null, "t": "사월이 아이들 손목에 차례로 실을 감았고, 단비가 차례로 이름을 불렀다. 여운비는 사당 기둥에 기대어 아이들 숫자를 셌다. 셈이 끝날 때마다 여운비가 고개를 끄덕였다."}, {"s": null, "t": "아이들 실을 다 감고 나자 사월이 단비 앞에 섰다. 단비의 먹빛 왼손을 두 손으로 받쳐 들었다."}, {"s": "q:m_sawol", "t": "언니 손도 감을게요. 이 손은 이제 남의 이름 안 쥐잖아요. 이름을 묶는 실이 있어야죠."}, {"s": null, "t": "단비가 머뭇거리다 왼손을 내밀었다. 사월이 굳은 손목에 실을 일곱 번 감았다. 매듭을 짓고 나서 사월이 나를 돌아보며 웃었다."}, {"s": "q:m_sawol", "t": "이번에도 바로 돌렸어요, {이름} 님. 하루도 안 늘어요."}, {"s": null, "t": "월식성 아래 바위에서 사월이 내 손목에 실을 감아 주던 날이 떠올랐다. 나는 웃으며 고개를 끄덕였다."}, {"s": null, "t": "단비의 손목 매듭까지 다 지어지자 나는 사월 쪽으로 돌아섰다. 붉은 인장 일 때 그랬던 것처럼 「사월」 하고 또박또박 불렀다."}, {"s": null, "t": "금빛 실 한 가닥이 사월의 가슴께에 닿았다. 사월이 가슴에 손을 얹고 눈을 감았다."}, {"s": "q:m_sawol", "t": "…네. 사월이에요. 그때도 그랬는데, 지금도 누가 불러 주니까 제 이름 같아요."}, {"s": null, "t": "사월이 눈을 뜨고 단비를 보았다. 입술을 몇 번 달싹이다가 수줍게 불렀다."}, {"s": "q:m_sawol", "t": "단비 언니."}, {"s": null, "t": "사월의 입김은 그냥 흩어졌다. 단비가 그 입김이 흩어진 자리를 보다가 웃음을 터뜨렸다."}, {"s": "red_moon_cult:danbi", "t": "「언니」는 안 닿아. 호칭이잖아. 그냥 단비라고 불러 봐. 그래야 내 오른쪽 귀에도 들어오지."}, {"s": null, "t": "사월이 숨을 고르고 「단비」 하고 다시 불렀다. 이번에는 금빛 실이 단비의 가슴께에 똑바로 가 닿았다. 단비가 오른쪽 귀를 사월 쪽으로 기울인 채 한참 가만히 서 있었다."}, {"s": null, "t": "사월은 명단 두 장을 겹쳐 남은 붉은 실로 묶었다. 단비가 그것을 받아 사당 기둥 못에 걸었다. 기둥에는 아이들이 해마다 이마를 닦은 자국이 거뭇하게 남아 있었다."}, {"s": "red_moon_cult:danbi", "t": "이건 부를 다발 말고 여기 두자. 산 사람 이름은 산 사람 곁에. 해마다 애들 실 감으러 올 때 같이 보면 되잖아."}, {"s": null, "t": "비탈 아래에서 언년이 주걱으로 솥 테두리를 탁 두드렸다. 엿이 다 됐다는 소리였다. 아이들이 앞다투어 비탈을 뛰어 내려갔고, 사월과 단비가 그 뒤를 나란히 따라갔다. 여운비는 단비의 오른쪽에 서서 걸었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_seoha', 'side', '뒷이야기·묵창 나루', '둘째 줄의 아이', '첫 명등제에서 둘째 줄 「서하」를 맡아 부른 다온은 그날 제 입김이 가늘었던 것이 마음에 걸린다. 얼굴도 목소리도 모르는 아이를 제대로 부르려고, 다온은 서하가 어떤 아이였는지 하나씩 모은다.', 'mukchang_ferry', 50, '{mke_daon_3,mdq_17,ep_x_hongmae}'::text[], null, 1557, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'ep_x_seoha';
delete from public.world_quest_steps where quest_id = 'ep_x_seoha' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_seoha', 1, '가는 실', '가는 실', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "묵창 주막 뒤 다온네 집 마당에서 다온이 공책을 펴 놓고 엎드려 있었다. 다온은 월하를 따라 며칠 나루 집에 와 있었다. 월하는 마루 끝에 걸터앉아 엽전을 굴리고 있었다."}, {"s": null, "t": "다온이 나를 보고 벌떡 일어났다. 공책 한 장을 펼쳐 내 앞에 내밀었다."}, {"s": "q:mk_daon", "t": "{이름} 님, 이거 보세요. 서하 누나 장이에요. 근데 적은 게 이것밖에 없어요."}, {"s": null, "t": "공책 한 장 맨 위에 「서하 · 둘째 줄」이라고 적혀 있었다. 그 아래는 텅 비어 있었다."}, {"s": "q:mk_daon", "t": "명등제 때 제가 서하 누나 줄을 불렀잖아요. 그때 아저씨는 서율 아저씨 줄을 불렀고요. 근데 아저씨 입김은 굵은 실이었는데, 제 건 머리카락처럼 가늘었어요."}, {"s": "q:mk_daon", "t": "구슬 누나가 그랬어요. 실은 그 이름을 얼마나 아느냐에 따라 굵어진대요. 저는 서하 누나 얼굴도 몰라요. 이 집에 살면서도요. 그래서 내년엔 굵게 부르고 싶어요."}, {"s": null, "t": "마루 끝에서 엽전 소리가 멈췄다. 월하가 엽전을 손바닥에 쥔 채 딴 데를 보았다."}, {"s": "q:mk_wolha", "t": "꼬맹아. 그런 건 서리님한테 물어. 명부에 다 있을 거야. 나이, 사는 데."}, {"s": null, "t": "다온이 공책을 끌어안고 월하 앞으로 걸어갔다. 마루 앞에서 발을 탁 굴렀다."}, {"s": "q:mk_daon", "t": "명부엔 나이랑 집만 있잖아요. 아저씨는 서하 누나랑 같이 놀았잖아요. 아저씨가 제일 많이 알잖아요."}, {"s": null, "t": "월하는 한참 대답하지 않았다. 엽전을 튕기려다 그만두고 손을 무릎에 내려놓았다. 이윽고 선창 쪽을 턱으로 가리켰다."}, {"s": "q:mk_wolha", "t": "…서율 형이 서하를 업고 저 선창 끝에 앉아서 낚시를 했어. 서하는 고기가 물면 박수를 쳤고. 그러고는 꼭 울었어. 놓아주라고."}, {"s": "q:mk_wolha", "t": "놓아주기 전에 고기마다 이름을 지어 줬어. 「꼬리 큰 애」, 「입 삐죽한 애」. 그렇게 부르고 나서야 물에 넣어 줬지. 다음에 또 만나면 알아보려고."}, {"s": null, "t": "다온의 눈이 동그래졌다. 공책에 「고기마다 이름 지어 줌 · 놓아줌」이라고 또박또박 적었다. 그러고는 내 소매를 잡아끌었다."}, {"s": "q:mk_daon", "t": "{이름} 님, 우리도 그거 해요. 선창에서요. 제가 서하 누나처럼 해 보면 조금은 알 것 같아요. 고기는 {이름} 님이 낚고, 이름은 제가 지을게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_seoha', 2, '놓아준 고기', '묵창 나루에서 낚시를 한다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "fish", "r": ["mukchang_ferry"], "n": 3}]}'::jsonb, '[{"s": null, "t": "선창 끝에서 세 번 줄을 던져 세 번 고기를 낚았다. 다온은 고기가 올라올 때마다 손뼉을 치고 이름을 지어 주었다. 「먹 묻은 애」, 「눈 큰 애」, 「나 보고 웃은 애」였다."}, {"s": null, "t": "다온은 이름을 다 지어 준 뒤 고기를 한 마리씩 물에 넣어 주었다. 고기가 물속으로 사라질 때마다 이름을 한 번 더 불렀다."}, {"s": "q:mk_daon", "t": "또 와. 먹 묻은 애. 다음엔 알아볼게."}, {"s": null, "t": "월하가 선창 말뚝에 기대어 그 모습을 보고 있었다. 늘 능청스럽던 얼굴이 조금 풀어져 있었다."}, {"s": "q:mk_wolha", "t": "똑같네. 서하도 꼭 그렇게 「또 와」 했어. 물에 대고 손까지 흔들고."}, {"s": null, "t": "월하가 엽전을 한 번 튕겼다가 받았다. 받은 엽전을 손바닥에 쥔 채 말을 이었다. 이번에는 다온이 묻지 않았는데도 먼저 꺼낸 말이었다."}, {"s": "q:mk_wolha", "t": "서하는 나를 진짜 이름으로 불렀어. 그때는 월하라는 호칭도 없었으니까. 그 이름은 지금 흑련 장부에 맡겨 둬서 꺼낼 수가 없지만."}, {"s": null, "t": "다온이 월하를 올려다보았다. 아저씨 이름을 서하 누나는 알았느냐고 묻는 얼굴이었다. 월하가 다온의 머리를 손바닥으로 꾹 눌렀다."}, {"s": "q:mk_wolha", "t": "그거 말고 하나 더 있다. 서하가 뭘 묻어 둔 데가 있어. 벌판 어귀 늙은 말뚝 밑에. 「보물」이라고 우기면서 나랑 형한테도 안 보여 줬지. 나는 한 번도 안 파 봤어."}, {"s": null, "t": "다온이 공책을 펼친 채 월하 쪽으로 몸을 바짝 기울였다."}, {"s": "q:mk_daon", "t": "왜요? 궁금하지 않았어요?"}, {"s": null, "t": "월하가 엽전을 손바닥에서 굴리며 강물 쪽을 보았다."}, {"s": "q:mk_wolha", "t": "궁금했지. 근데 열댓 살에 거둠꾼이 된 놈이 그걸 파면, 그날로 장사를 못 할 것 같았어."}, {"s": null, "t": "그때 강둑길로 희수가 명부 한 권을 안고 걸어왔다. 다온을 보고 걸음을 서둘렀다. 희수는 명부를 펴서 한 줄을 손가락으로 짚어 보였다."}, {"s": "q:mk_hisu", "t": "다온아. 명등청 첫 명부 둘째 줄이야. 네가 부르는 이 칸에 이름을 적은 줄. 거기 적힌 대로 옮겨 왔어."}, {"s": null, "t": "줄에는 「서하 · 일곱 살 · 묵창 나루 주막 뒷집」이라고 적혀 있었다. 부르는 이 칸에는 다온의 삐뚤빼뚤한 이름이 있었다."}, {"s": "q:mk_daon", "t": "주막 뒷집… 여기잖아요. 우리 집이요. 일곱 살이요? 그럼 그때는 저보다 어렸네요. 그래도 누나예요. 저보다 먼저 이 집에 살았으니까요."}, {"s": null, "t": "다온이 그 줄을 공책에 옮겨 적었다. 혀끝을 내밀고 한 글자도 빼지 않았다. 다 적고 나서 다온이 나를 올려다보았다."}, {"s": "q:mk_daon", "t": "{이름} 님, 그 말뚝 밑에 뭐가 있는지 찾아 주세요. 아저씨는 못 판대요. 저는 벌판 가면 서리님이 혼내요. 그러니까 {이름} 님이요."}, {"s": null, "t": "희수가 다온의 머리를 쓰다듬으며 나를 보았다. 혼낼 거라는 말을 부정하지 않았다."}, {"s": "q:mk_hisu", "t": "조사원, 벌판 어귀 말뚝은 여러 개예요. 서하가 놀던 데라면 강둑에서 가까운 쪽일 거예요. 잘 살펴보세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_seoha', 3, '보물', '빈칸 벌판에 간다, 빈칸 벌판에서 실마리를 찾는다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "travel", "r": ["blank_field"], "n": 1}, {"t": "clue", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "강둑에서 가장 가까운 늙은 말뚝 밑을 파자 작은 옹기 단지 하나가 나왔다. 뚜껑을 기름종이로 꽁꽁 싸매 두어 안은 젖지 않았다. 나는 그 단지를 들고 나루로 돌아왔다."}, {"s": null, "t": "해가 진 선창에서 다온과 월하와 희수가 기다리고 있었다. 내가 단지를 내려놓자 다온이 숨을 죽이고 기름종이를 풀었다."}, {"s": null, "t": "단지 안에는 조개껍데기 세 개와 접은 종이배 하나, 그리고 접힌 그림 한 장이 들어 있었다. 다온이 그림을 펼쳤다."}, {"s": null, "t": "선창 끝에 앉은 아이 셋을 그린 그림이었다. 그림 아래에 서툰 글씨로 이름표가 붙어 있었다. 큰 아이 밑에는 「오라버니」, 작은 아이 밑에는 「나」라고 적혀 있었다."}, {"s": null, "t": "셋째 아이 밑의 글씨만 먹비에 젖은 듯 번져 있었다. 엽전 비슷한 동그라미를 손에 든 아이였다."}, {"s": null, "t": "월하가 그 번진 글씨를 내려다보았다. 한참 말이 없다가, 피식 웃음을 터뜨렸다."}, {"s": "q:mk_wolha", "t": "다행이네. 먹비가 일을 했어. 저게 읽혔으면 오늘 장부고에 큰일 날 뻔했다."}, {"s": null, "t": "다온이 그림을 들어 월하의 얼굴 앞에 바짝 들이댔다."}, {"s": "q:mk_daon", "t": "아저씨, 이거 아저씨예요? 이 동그라미, 엽전이에요?"}, {"s": null, "t": "월하는 대답하지 않았다. 대신 오른손 검지로 그림 속 셋째 아이의 손을 가만히 짚었다. 다온은 그 손가락과, 두 마디가 없는 월하의 왼손 새끼손가락을 번갈아 오래 보았다."}, {"s": null, "t": "다온은 그림과 조개껍데기와 종이배를 공책 곁에 나란히 놓았다. 공책의 서하 장이 이제 빼곡했다. 일곱 살, 주막 뒷집, 고기마다 이름을 지어 준 아이, 첫 숟가락을 받던 아이, 그림을 그려 묻어 둔 아이였다."}, {"s": null, "t": "밤이 내려앉은 선창 끝에 다온이 섰다. 서율이 서하를 업고 앉았다던 그 자리였다. 다온이 공책을 가슴에 안고 숨을 크게 들이마셨다."}, {"s": "q:mk_daon", "t": "서하 누나. 묵창 나루 주막 뒷집 서하 누나. 고기마다 이름 지어 주던 서하 누나."}, {"s": null, "t": "다온의 입김이 금빛 실로 엉겼다. 명등제 날 밤보다 훨씬 굵은 실이었다. 실은 선창 끝 물 위로 길게 풀려 나가며 반짝였다."}, {"s": null, "t": "다온이 입을 벌린 채 실을 바라보았다. 희수가 다온 곁에 서서 같은 이름을 불렀고, 나도 따라 불렀다. 세 가닥이 물 위에서 하나로 꼬였다."}, {"s": null, "t": "월하는 맨 마지막에 불렀다. 월하의 실이 닿자 꼬인 실이 한층 밝아졌다. 월하가 손에 쥐고 있던 엽전을 떨어뜨렸다. 엽전이 선창 바닥을 데구루루 굴렀다."}, {"s": null, "t": "다온이 쪼르르 달려가 엽전을 주웠다. 엽전을 월하의 손바닥에 쥐여 주고 그 손을 두 손으로 꼭 감쌌다."}, {"s": "q:mk_daon", "t": "아저씨, 오늘은 제가 서하 누나 대신 주워 드린 거예요. 서하 누나도 아저씨 엽전 주워 줬죠? 그림에 다 있어요."}, {"s": null, "t": "월하는 그 말에 대답하지 못하고 고개를 돌렸다. 강둑 위로 별이 하나둘 돋았다. 다온이 공책 서하 장 맨 아래에 「내년엔 더 굵게」라고 한 줄을 더 적었다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_solnae', 'side', '뒷이야기·야행국 본부 정청', '솔내', '경현의 장부를 밤마다 한 장씩 읽던 한설이 마지막 장에 이른다. 솔내 사람들의 이름이 집 차례대로 적혀 있지만, 명등청 명부에 적을 「사는 고을」 칸을 채울 지도가 없다. 한설은 여운비를 길잡이로 청해 서리솔 고개 너머 솔내 옛터를 찾아간다.', 'hq_yard', 50, '{mdq_17,mde_unbi_2}'::text[], null, 1558, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'ep_x_solnae';
