insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_solnae', 1, '지도에 없는 고을', '지도에 없는 고을', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "명등청 감찰관 방에 늦도록 등잔이 켜져 있었다. 한설이 책상 앞에 앉아 장부 한 권의 마지막 장을 펴 놓고 있었다. 모서리가 하나도 접히지 않은 장부였다."}, {"s": null, "t": "한설은 붓을 들지 않았다. 장부 위 이름 하나하나를 손가락으로 짚어 내려가며 읽고 있었다. 나는 문간에서 기다렸다가 한설이 고개를 들자 안으로 들어갔다."}, {"s": "night_office:han", "t": "왔나, 조사원. 앉아라. 그 사람 장부를 밤마다 한 장씩 읽었다. 어젯밤에 마지막 장까지 왔다."}, {"s": null, "t": "한설이 장부를 내 쪽으로 돌렸다. 마지막 장에 이름이 마흔 줄 넘게 적혀 있었다. 이름 곁마다 작은 글씨가 붙어 있었다. 「우물 위 첫 집」, 「느릅나무 집」, 「훈장 댁」 같은 말이었다."}, {"s": "night_office:han", "t": "이름을 집 차례대로 적었다. 고을 길을 따라 걷듯이. 그 사람은 솔내를 지도처럼 외우고 있었던 거다."}, {"s": "night_office:han", "t": "희수 서리가 물어 왔다. 명등청 명부에 이 이름들을 올리려면 사는 고을 칸에 무엇을 적어야 하느냐고. 솔내는 어느 지도에도 없다. 백십 년 전에 하룻밤 사이에 없어졌으니까."}, {"s": null, "t": "한설이 붓을 집어 들었다가 천천히 닦기 시작했다. 붓은 이미 깨끗했다. 한설은 그 붓을 오래 닦았다."}, {"s": "night_office:han", "t": "지도에 없는 고을은 내가 가서 보고 적겠다. 이 장은 그 자리에서 한 번 읽어야 할 것 같다. 땅 위에 사는 사람이 그 고을 이름을 불러 준 적이 백십 년 동안 한 번도 없었다."}, {"s": null, "t": "문간에서 서리 문수가 서류 뭉치를 떨어뜨렸다. 문수는 서류를 주울 생각도 못 하고 한설을 보았다."}, {"s": "q:dh_munsu", "t": "감찰관님이 정청을 사흘이나 비우신다고요? 명등청 생긴 뒤로 하루 비우신 날도 손에 꼽거든요! 그럼 그동안 일곱 세력 공문은요? 저 혼자요?"}, {"s": null, "t": "한설이 붓을 내려놓고 문수를 돌아보았다. 목소리는 짧았다."}, {"s": "night_office:han", "t": "사흘이다, 문수 서리. 공문은 쌓아 두면 된다. 쌓인 건 내가 돌아와서 읽는다."}, {"s": null, "t": "그때 방문 밖에서 발소리가 났다. 여운비가 문간에 서 있었다. 오른 눈은 하얗게 바래 있었고, 칼자루 끝에는 짧게 다시 맨 붉은 술이 달려 있었다."}, {"s": "north_league:yeo", "t": "감찰관의 서신을 받고 왔소. 단비가 엿을 싸 주었소. 감찰관은 밤새 아무것도 안 먹는다고 하더이다. 장부는 단비 혼자 적겠다고 했소. 짐 수를 틀리면 내가 돌아가서 고치기로 했소."}, {"s": null, "t": "여운비가 한설의 책상에 엿 꾸러미를 내려놓았다. 이어 품에서 누렇게 바랜 종이 한 장을 꺼냈다. 북령 호송 장부의 낱장이었다."}, {"s": "north_league:yeo", "t": "우리 집안 사당에서 찾았소. 증조할아버지께서 적으신 호송 장부요. 「솔내. 옷가지 마흔두 짐을 거둠. 서리솔 고개 셋째 굽이 아래 골짜기, 소나무 밑에 묻음.」 길은 여기 있소."}, {"s": null, "t": "한설이 그 낱장을 오래 내려다보았다. 증조할아버지라는 말에서 한설의 눈길이 여운비에게로 올라갔다."}, {"s": "night_office:han", "t": "네 증조할아버지께서 옷가지를 거두신 데라고 들었다. 길잡이를 부탁해도 되겠나. 앞을 서 달라는 건 아니다. 길만 알려 다오."}, {"s": null, "t": "여운비가 칼자루 끝의 붉은 술을 손가락으로 한 번 쓸고 나를 돌아보았다."}, {"s": "north_league:yeo", "t": "앞은 조사원이 서시오. 나는 뒤에서 볼로 바람을 읽겠소. 셋째 굽이라면 골짜기 바람이 위로 치오. 볼로도 알 수 있소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_solnae', 2, '마흔두 집터', '서리솔 고개에 간다, 서리솔 고개에 원정을 다녀온다', '{"at": ["frost_pine_pass"], "tasks": [{"t": "travel", "r": ["frost_pine_pass"], "n": 1}, {"t": "expedition", "r": ["frost_pine_pass"], "n": 1}]}'::jsonb, '[{"s": null, "t": "서리솔 고개 셋째 굽이 아래 골짜기는 소나무가 빽빽했다. 원정 끝에 골짜기 바닥에 닿자, 솔잎 덮인 땅 위로 네모난 돌 무더기가 줄지어 드러났다. 집터의 주춧돌이었다."}, {"s": null, "t": "주춧돌 사이로 백 년 넘게 자란 소나무들이 서 있었다. 집터는 골짜기를 따라 위아래로 길게 이어졌다. 군데군데 둥근 돌테가 땅에 박혀 있었다. 우물이었다."}, {"s": null, "t": "우물 돌테 안쪽에 검은 띠가 둥글게 배어 있었다. 물은 한 방울도 없었다. 검은 물이 솟았다가 빠진 자국이었다."}, {"s": null, "t": "한설이 장부를 펴 들고 집터 하나하나를 짚어 걸었다. 「우물 위 첫 집」에서 시작해 아래로 내려갔다. 장부의 차례와 집터의 차례가 하나도 어긋나지 않았다."}, {"s": "night_office:han", "t": "맞다. 하나도 안 틀렸다. 그 사람은 열 살 때 본 고을을 백 년 동안 이렇게 들고 다녔다."}, {"s": null, "t": "골짜기 중간쯤의 집터에서 한설이 걸음을 멈췄다. 장부에 「훈장 댁」이라고 적힌 자리였다. 주춧돌 곁에 금 간 장독 하나가 반쯤 흙에 묻혀 있었다."}, {"s": null, "t": "장독 뚜껑은 깨지지 않고 그대로였다. 뚜껑 위에 솔잎이 수북이 쌓여 있었다. 한설이 그 앞에 무릎을 꿇었다."}, {"s": null, "t": "한설은 아무 말도 하지 않았다. 소매로 뚜껑 위의 솔잎을 천천히 쓸어 냈다. 붓을 닦을 때처럼 같은 자리를 몇 번이고 쓸었다."}, {"s": null, "t": "나는 한설 곁에 가만히 앉아 있었다. 여운비는 집터 아래쪽 굽이의 큰 소나무 밑에 서 있었다. 그 밑에 넓적한 돌 하나가 놓인 둔덕이 있었다."}, {"s": "north_league:yeo", "t": "여기요. 옷가지를 묻은 자리요. 돌에 「솔내」 두 글자가 긁혀 있소. 증조할아버지 글씨 같소. 북령 호송 장부 글씨와 획이 같소."}, {"s": null, "t": "여운비가 돌 앞에 한쪽 무릎을 꿇었다. 고개를 숙인 채 한참 일어서지 않았다."}, {"s": "north_league:yeo", "t": "증조할아버지께서 옷가지를 거두실 때 무슨 마음이셨는지 이제 조금 알겠소. 사람이 하나도 없는 고을에서 옷만 마흔두 짐을 지셨으니. 그래도 버리지 않고 묻어 주셨소."}, {"s": null, "t": "해가 골짜기 위로 넘어가자 소나무 사이가 금세 어둑해졌다. 솔숲 어딘가에서 살쾡이 울음이 날카롭게 울렸다. 여운비가 고개를 들고 오른 뺨을 골짜기 위쪽으로 내밀었다."}, {"s": "north_league:yeo", "t": "바람을 따라 살쾡이 냄새가 내려오오. 여럿이오. 집터에 등을 밝히면 몰려들 거요. 감찰관이 이름을 다 읽으려면 밤새 걸릴 테니, 먼저 쫓아 두는 게 좋겠소."}, {"s": null, "t": "한설이 장독 뚜껑에서 손을 떼고 일어섰다. 무릎에 솔잎이 붙어 있었다."}, {"s": "night_office:han", "t": "오늘 밤은 여기서 보내겠다. 이 장은 해가 진 뒤에 읽어야 닿는다. 조사원, 살쾡이를 부탁한다. 나는 집터를 한 바퀴 더 돌겠다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_solnae', 3, '위에서 부르는 솔내', '솔숲 살쾡이을(를) 물리친다, 서리솔 고개에서 쉰다', '{"at": ["frost_pine_pass"], "tasks": [{"t": "win", "m": ["r220_pine_4"], "n": 6}, {"t": "rest", "r": ["frost_pine_pass"], "n": 1}]}'::jsonb, '[{"s": null, "t": "살쾡이들을 쫓아내고 집터로 돌아오니 골짜기에 밤이 내려와 있었다. 소나무 가지 사이로 별이 보였다. 여운비가 「우물 위 첫 집」 주춧돌 곁에 등을 하나 밝혀 두었다."}, {"s": null, "t": "한설이 등 곁에 서서 장부를 펼쳤다. 숨을 한 번 고르고 첫 이름을 불렀다. 우물 위 첫 집 사람의 이름이었다."}, {"s": null, "t": "한설의 입김이 흩어지지 않고 금빛 실로 엉겼다. 실은 허공에서 잠깐 머뭇거리다가, 주춧돌 사이 땅으로 스르르 스며들었다. 실이 스며든 자리의 솔잎이 잠깐 금빛으로 물들었다."}, {"s": null, "t": "한설은 다음 집터로 걸어가 다음 이름을 불렀다. 집터마다 서서 그 집 사람들의 이름을 차례대로 불렀다. 실이 스며들 때마다 골짜기 땅에 작은 빛이 하나씩 남았다."}, {"s": null, "t": "나는 등을 들고 한설의 걸음을 따라 집터를 밝혔다. 여운비는 내 뒤에서 걸으며 한설이 부른 이름을 낮은 목소리로 따라 불렀다. 여운비의 실도 같은 자리로 스며들었다."}, {"s": null, "t": "한설이 「훈장 댁」 앞에 이르렀다. 장독 곁에 서서 훈장 어른의 이름과 아이들의 이름을 불렀다. 마지막으로 남은 이름 앞에서 한설의 목소리가 한 번 걸렸다."}, {"s": "night_office:han", "t": "…연실. 솔내 훈장 댁 막내딸 연실."}, {"s": null, "t": "금빛 실이 장독 뚜껑 위에 내려앉았다. 실은 스며들지 않고 뚜껑 둘레를 한 바퀴 감았다. 장독 뚜껑 틈으로 금빛이 아주 조금 새어 들어갔다."}, {"s": null, "t": "장부 맨 끝줄에는 한설이 제 손으로 적어 넣은 이름이 하나 더 있었다. 한설은 그 줄을 오래 내려다보았다. 그러고는 장독을 향해 똑바로 불렀다."}, {"s": "night_office:han", "t": "경현."}, {"s": null, "t": "한설의 입김이 장독 위로 건너갔다. 먼저 감겨 있던 실 곁에 새 실이 나란히 감겼다. 두 실이 장독 둘레에서 한 가닥으로 꼬였다."}, {"s": null, "t": "한설은 장부를 덮고 장독 앞에 한참 서 있었다. 화가 날 때처럼 말이 없었지만, 화가 난 얼굴은 아니었다."}, {"s": "night_office:han", "t": "장독 뚜껑을 열면 안에 아무것도 없겠지. 그래도 이 뚜껑은 안 열겠다. 그 밤 이 뚜껑이 열리지 않았던 동안만큼은 그 사람이 살아 있었으니까."}, {"s": null, "t": "한설이 품에서 명등청 명부 낱장을 꺼냈다. 희수가 사는 고을 칸만 비워 보낸 종이였다. 한설은 장독 뚜껑 위에 종이를 펴고 그 칸에 「솔내 · 서리솔 고개 셋째 굽이 아래」라고 적었다."}, {"s": "night_office:han", "t": "이제 지도에 있다. 땅 위에 사는 사람이 적었으니까."}, {"s": null, "t": "여운비가 고개를 들어 골짜기 위쪽으로 뺨을 내밀었다. 소나무 가지가 쏴아 소리를 내며 흔들렸다."}, {"s": "north_league:yeo", "t": "골짜기 바람이 위로 부오. 아래서 올라오는 바람이오. 백 년 넘게 이 골짜기에서 위로 부는 바람이 있었을 텐데, 아무도 그걸 읽어 주지 않았구려."}, {"s": null, "t": "한설이 나를 돌아보았다. 등불 아래에서 늘 단호하던 얼굴이 조금 풀어져 있었다."}, {"s": "night_office:han", "t": "조사원. 동짓밤엔 정청에서 이 장을 읽겠다. 그래도 해마다 한 번은 여기 와서 읽겠다. 명등청 일이 아무리 쌓여도. 그때 너도 와라. 등 들 사람이 있어야 한다."}, {"s": null, "t": "나는 그러겠다고 했다. 골짜기 땅에 스며든 금빛이 동이 틀 때까지 꺼지지 않았다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('ep_x_yeoul', 'side', '뒷이야기·반요촌', '길잡이의 비늘', '반요촌 주민 명부를 받아 읽던 명등청 서리 하나가 봉연 물길을 타고 섬에 들어왔다가 잿빛 갈대숲에서 길을 잃는다. 일곱 해 전 여울에게 정화 부적 세 장을 붙여 주던 옛 동료였다. 갈대숲이 흉내 내는 「여울」 소리 사이에서, 길잡이가 진짜 목소리를 찾아간다.', 'banyo_village', 50, '{gq_5,mdq_17,ep_x_mukho}'::text[], null, 1559, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'ep_x_yeoul';
delete from public.world_quest_steps where quest_id = 'ep_x_yeoul' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_yeoul', 1, '사방에서 부르는 이름', '사방에서 부르는 이름', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 선창에서 여울이 나룻배에 종이 꾸러미를 싣고 있었다. 명등청에 보낼 반요촌 장이었다. 여울은 꾸러미 끈을 두 번 묶고 세 번째로 다시 묶었다."}, {"s": "q:g_yeoul", "t": "왔어? 이거 봉연 물길로 보내는 중이야. 끈을 몇 번 묶었는지 모르겠어. 이번엔 받아 줄 걸 아니까 손이 더 떨려."}, {"s": null, "t": "그때 갈대숲 쪽 둑길에서 단이가 약 상자를 덜컹거리며 뛰어왔다. 숨을 헉헉 몰아쉬며 갈대숲을 가리켰다."}, {"s": "q:g_dani", "t": "여울 언니! 갈대숲에서 누가 언니 이름을 불러요! 바깥 냄새 나는 목소리예요! 쉰 목소리로 「여울아」 하고요!"}, {"s": null, "t": "여울의 손에서 꾸러미 끈이 스르르 풀렸다. 여울이 갈대숲 쪽으로 고개를 돌린 순간, 바람도 없는데 갈대가 사락사락 흔들렸다."}, {"s": null, "t": "갈대숲 여기저기에서 「여울아, 여울아」 하는 같은 소리가 일어났다. 처음에는 한 목소리였는데, 곧 열이 되고 스물이 되었다. 갈대 물귀신들이 그 목소리를 흉내 내고 있었다."}, {"s": null, "t": "여울이 비늘 덮인 왼 손목을 오른손으로 꽉 움켜쥐었다. 얼굴이 하얗게 질려 있었다."}, {"s": "q:g_yeoul", "t": "바깥 사람이 갈대숲에 들어왔어. 이름을 크게 부르면서. 저것들이 그 목소리를 따라 하고 있어. 내 이름이라서 더 신이 났어. 반쯤 번진 이름은 저것들이 제일 좋아하거든."}, {"s": null, "t": "나는 누가 들어왔을 것 같으냐고 물었다. 여울은 대답하지 못하고 입술을 깨물었다."}, {"s": "q:g_yeoul", "t": "…모르겠어. 바깥에서 날 「여울아」라고 부르던 사람은 하나뿐이었는데. 그 사람일 리가 없어."}, {"s": null, "t": "여울이 선창 말뚝에 걸어 둔 등을 내려 들었다. 길잡이가 갈대숲에 들어갈 때 드는 등이었다."}, {"s": "q:g_yeoul", "t": "길잡이는 나야. 바깥 사람이 갈대숲에서 길을 잃으면 내가 데리고 나와야 해. 근데 지금 들어가면 사방에서 내 이름이 불려. 어느 게 진짜 목소린지 못 가려."}, {"s": "q:g_yeoul", "t": "같이 가 줘. 흉내 내는 놈들부터 치워 줘. 소리가 줄어들면, 진짜 목소리는 내가 찾을게. 그건 길잡이가 잘해."}, {"s": null, "t": "단이가 따라오겠다고 약 상자 끈을 고쳐 멨다. 여울이 단이의 어깨를 잡아 선창 쪽으로 돌려세웠다."}, {"s": "q:g_yeoul", "t": "너는 여기서 촌장님 모시고 기다려. 물에 젖은 사람을 데리고 나올 거야. 고약이랑 마른 옷을 챙겨 둬."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_yeoul', 2, '숨소리', '잿빛 갈대숲에 간다, 갈대 물귀신을(를) 물리친다', '{"at": ["ash_reeds"], "tasks": [{"t": "travel", "r": ["ash_reeds"], "n": 1}, {"t": "win", "m": ["gw_reed_1"], "n": 6}]}'::jsonb, '[{"s": null, "t": "흉내 내던 물귀신들이 하나둘 쓰러지자 「여울아」 소리가 잦아들었다. 갈대숲에 소리가 셋쯤 남았다. 여울이 등을 높이 들고 귀를 기울였다."}, {"s": null, "t": "여울은 오른쪽 소리 쪽으로 고개를 돌렸다가 저었다. 왼쪽 소리에도 저었다. 마지막 소리 쪽에서 여울의 고개가 멈췄다."}, {"s": "q:g_yeoul", "t": "저거야. 저 목소리는 숨을 쉬어. 부르고 나서 숨을 들이마셔. 물귀신은 숨을 안 쉬거든. 길잡이는 이걸로 가려내."}, {"s": null, "t": "여울은 갈대를 헤치고 그쪽으로 뛰었다. 나는 등 뒤를 지키며 따라갔다. 잿물이 고인 갈대 둔덕에 사내 하나가 무릎까지 빠져 있었다."}, {"s": null, "t": "사내는 남빛 서리 관복 위에 낡은 조사원 겉옷을 걸치고 있었다. 한 손에 누렇게 바랜 부적 한 장을 쥐고 있었다. 잿물에서 다리를 빼려 할수록 몸이 더 깊이 빨려 들었다."}, {"s": null, "t": "여울이 그 자리에 우뚝 멈춰 섰다. 등을 든 손이 떨려 불빛이 흔들렸다."}, {"s": "q:g_yeoul", "t": "…기산 선배."}, {"s": null, "t": "사내가 고개를 들었다. 지친 얼굴에 잿가루가 묻어 있었다. 사내의 눈이 여울의 얼굴에서 비늘 덮인 손목으로 내려갔다가 다시 얼굴로 올라왔다."}, {"s": "q:sx_x_gisan", "t": "여울아. 진짜 너냐. 아까부터 네 목소리가 사방에서 대답을 해서, 다 따라가다 보니 여기까지 빠졌네."}, {"s": null, "t": "여울이 등을 내게 넘기고 둔덕으로 뛰어들었다. 나는 등을 말뚝에 걸고 사내의 다른 팔을 붙잡았다. 여울과 내가 동시에 잡아당기자 잿물이 철벅 소리를 내며 사내의 다리를 놓아주었다."}, {"s": null, "t": "사내는 둔덕에 주저앉아 숨을 몰아쉬었다. 손끝이 바들바들 떨렸다. 그 손에 쥔 부적은 젖지 않고 그대로였다."}, {"s": null, "t": "여울은 저도 모르게 왼 손목을 소매 속으로 감추었다. 기산이 그 손을 보고 떨리는 손을 내밀었다. 여울은 한참 망설이다 소매를 걷어 손목을 내주었다."}, {"s": null, "t": "기산이 비늘 위를 손바닥으로 가만히 덮었다. 덮은 손이 오래 움직이지 않았다."}, {"s": "q:sx_x_gisan", "t": "차갑지가 않구먼. 그날은 얼음 같았는데. 부적을 세 장이나 붙여도 계속 차가웠지."}, {"s": null, "t": "기산이 쥐고 있던 부적을 여울의 손바닥에 올려놓았다. 일곱 해 동안 품에 넣고 다닌 듯 귀퉁이가 닳아 둥글었다."}, {"s": "q:sx_x_gisan", "t": "네 번째 부적이네. 그날 이걸 꺼내다가 손이 떨려서 못 붙였지. 네가 내 손을 잡아 내렸고. 그 뒤로 이걸 버리지를 못했어."}, {"s": null, "t": "여울이 부적을 내려다보았다. 입술이 몇 번 달싹였지만 말이 나오지 않았다. 여울이 고개를 숙이자 어깨가 들썩였다."}, {"s": "q:g_yeoul", "t": "…그걸 아직 갖고 있었어요, 선배? 바보같이."}, {"s": null, "t": "기산의 입술이 새파랗게 질려 있었다. 이가 딱딱 부딪는 소리가 났다. 갈대숲의 찬 잿물에 오래 잠겨 있었던 탓이었다. 여울이 기산의 어깨를 붙들고 나를 돌아보았다."}, {"s": "q:g_yeoul", "t": "놀라고 얼어서 그래. 갈대숲에 홀렸던 사람은 한참 떨어. 안신탕 한 그릇이면 가라앉아. 너 지을 줄 알지? 선배는 내가 업고 갈게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('ep_x_yeoul', 3, '마중 방울', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 1}], "give": {"calm_brew": 1}}'::jsonb, '[{"s": null, "t": "동트기 전 반요촌 선창이었다. 기산은 단이가 챙겨 둔 마른 옷을 입고 안신탕 사발을 두 손으로 감싸 쥐고 있었다. 떨림이 조금씩 가라앉았다."}, {"s": null, "t": "단이는 기산의 무릎에 반요 고약을 발라 주고, 젖은 신을 화롯가에 세워 말리며 낯선 손님을 힐끔힐끔 쳐다보았다. 기산이 단이와 눈이 마주치자 어색하게 웃었다."}, {"s": "q:sx_x_gisan", "t": "고약 고맙네, 꼬마 의원. 무릎이 안 시리구먼."}, {"s": null, "t": "단이가 신을 내려놓고 허리에 손을 올렸다. 볼이 뾰로통하게 부풀었다."}, {"s": "q:g_dani", "t": "꼬마 의원 아니에요. 단이예요. 엄마가 의무관이었어요. 이 상자 엄마 거예요."}, {"s": null, "t": "기산이 사발을 내려놓고 여울을 보았다. 여울은 선창 말뚝에 기대 서서 손목의 비늘을 엄지로 문지르고 있었다."}, {"s": "q:sx_x_gisan", "t": "정청 서신방에서 반요촌 명부를 받는 게 내 일이었네. 명부가 올 때마다 「받지 않음」 도장을 찍어 돌려보냈지. 위에서 그러라고 했으니까. 명등청이 되고 나서도 나는 그 방에 그대로 앉아 있네."}, {"s": "q:sx_x_gisan", "t": "그래도 글씨를 보면 알았어. 네 글씨였거든. 반듯해서. 그래서 돌려보내기 전에 한 장씩 베껴 두었네. 이번에 명등청이 받는다길래, 베껴 둔 걸 들고 직접 왔지. 도장 찍은 손으로 사과는 못 하겠고, 그냥 얼굴이라도 보려고."}, {"s": null, "t": "여울이 말뚝에서 몸을 떼고 기산 앞으로 다가왔다. 품에서 네 번째 부적을 꺼내 들었다."}, {"s": "q:g_yeoul", "t": "이건 이제 안 붙여도 돼요. 섬에선 비늘이 더 안 번져요. 반요촌 사람들이 날마다 서로 불러 주고요. 대신 이건 문패에 꽂아 둘게요. 바깥 이름이랑 섬 이름 사이에요."}, {"s": null, "t": "기산이 고개를 끄덕였다. 떨리던 손끝이 그제야 멎었다. 나룻배가 물결에 흔들리며 선창 말뚝을 톡톡 두드렸다."}, {"s": "q:sx_x_gisan", "t": "또 와도 되겠나. 다음엔 갈대숲에서 네 이름을 안 부르고 들어오겠네. 부르면 저것들이 또 신이 날 테니."}, {"s": null, "t": "단이가 약 상자를 뒤적이더니 작은 방울 하나를 꺼냈다. 단이는 방울을 기산 앞에 내밀었다."}, {"s": "q:g_dani", "t": "그럼 갈대숲 어귀 말뚝에 이걸 달아 둘게요. 아저씨가 오면 이걸 흔들어요. 물귀신은 사람 목소리만 흉내 내요. 방울 소리는 못 내요. 그 소리가 나면 여울 언니가 마중 나갈 거예요."}, {"s": null, "t": "여울이 단이의 머리를 쓰다듬고 기산을 돌아보았다. 손목의 비늘을 문지르던 손이 멈춰 있었다."}, {"s": "q:g_yeoul", "t": "길잡이가 마중 나갈게요, 선배. 그게 제 일이에요. 일곱 해 동안 내보내기만 했으니까, 이제 맞이하는 것도 해 봐야죠."}, {"s": null, "t": "기산이 나룻배에 올랐다. 배가 선창을 떠나려 할 때 기산이 뱃전을 붙잡고 돌아보았다. 하늘은 아직 어두웠다."}, {"s": "q:sx_x_gisan", "t": "여울아."}, {"s": null, "t": "기산의 입김이 금빛 실로 엉겨 선창 위로 건너왔다. 실이 여울의 가슴께에 닿았다. 갈대숲 쪽에서는 아무 소리도 따라 하지 않았다."}, {"s": null, "t": "여울이 가슴께에 손을 얹었다. 배가 물길로 멀어지는 동안 마을 쪽에서 노래 한 소절이 들려왔다. 배웅 노래와 가락이 비슷했지만 끝 소절이 달랐다. 반요촌 사람들이 짓고 있던 맞이하는 노래였다."}, {"s": "q:g_yeoul", "t": "저 노래, 아직 다 못 지었대. 다음에 선배 올 때까지 마저 지어 놓으라고 해야겠다."}]'::jsonb, '{"gil": 400}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;


select public.world_quest_label_refresh();

update public.world_patch_notes set body = body || $N$

## 3.1.0

- Lv50 뒤 「뒷이야기」 보조 퀘스트 60편이 생겼습니다. 경험치는 없고, 홍인사부터 명등기까지 나온 인물들이 결말 뒤 어떻게 지내는지, 세력 거점과 먼 땅 사람들이 어떻게 사는지를 보여 줍니다. 일지 › 보조 퀘스트의 「뒷이야기」 칸에 모여 있습니다.
- 세력 거점 사업(일곱 곳)과 공동 사업(반요촌·묵창 나루·등도)이 한 단계씩 찰 때마다 그 거점의 뒷이야기가 하나씩 열립니다. 1~5단계마다 하나, 세력과 상관없이 누구나 받을 수 있습니다. 아직 열리지 않은 이야기는 일지에서 몇 단계에 열리는지 보입니다.
- 이야기 뒤 10편은 홍인사·요인록·묵적록·명등기의 앞 이야기를 마치면 열립니다.
- 상시 의뢰가 의뢰 창을 처음 열기 전에 한 토벌·채집·탐색도 셉니다(그날 한국 시각 0시부터).$N$
 where note_id = '3.0.0' and position('## 3.1.0' in body) = 0;


insert into public.world_app_meta(key, value, changed_at) values ('db_version', '20261120000000', now())
on conflict (key) do update set value = excluded.value, changed_at = excluded.changed_at;
